        public MainForm()
        {
            InitializeComponent();

            // 开启双缓冲，防止动画闪烁
            this.DoubleBuffered = true;
            typeof(Panel).InvokeMember("DoubleBuffered",
                System.Reflection.BindingFlags.SetProperty | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic,
                null, _sideNavPanel, new object[] { true });

            // 设置窗体图标
            var iconPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "app.ico");
            if (File.Exists(iconPath))
            {
                this.Icon = new Icon(iconPath);
            }
            Log("Application started");

            // 记录首次运行时间
            RecordFirstRunDate();

            // 确保注册信息已保存到INF文件
            EnsureRegistrationSaved();

            // 检查试用期
            CheckTrialPeriod();

            // 检查是否过期
            CheckExpiration();

            // 检查Python环境
            CheckPythonEnvironment();

            // 如果没有注册记录，弹出注册框
            CheckAndShowRegistration();
        }

        public void UpdateRegistrationStatus()
        {
            CheckTrialPeriod();

            // 更新菜单文本
            var settings = ConfigService.LoadAll();
            if (settings.IsRegistered)
            {
                _registerMenuItem.Text = "激活软件";
            }
            else
            {
                _registerMenuItem.Text = "注册软件";
            }
        }

        /// <summary>
        /// 应用字体设置到日志窗口和状态栏（根据DPI自动缩放）
        /// </summary>
        public void ApplyFontSettings()
        {
            float dpiScale = GetDpiScaleFactor();

            if (_logTextBox != null && !_logTextBox.IsDisposed)
            {
                float scaledLogSize = _featureSettings.LogFontSize * dpiScale;
                _logTextBox.Font = new Font(_featureSettings.LogFontName, scaledLogSize);
            }
            if (_trialLabel != null)
            {
                float scaledStatusSize = _featureSettings.StatusFontSize * dpiScale;
                _trialLabel.Font = new Font(_featureSettings.StatusFontName, scaledStatusSize);
            }
        }

        /// <summary>
        /// 根据屏幕分辨率智能设置窗体大小（100%缩放下保证1024x768基础尺寸）
        /// </summary>
        private void SetSmartClientSize()
        {
            Rectangle screenArea = Screen.PrimaryScreen?.WorkingArea ?? new Rectangle(0, 0, 1920, 1080);

            // 计算目标尺寸：屏幕的80%
            int targetWidth = (int)(screenArea.Width * 0.8);
            int targetHeight = (int)(screenArea.Height * 0.85);

            // 保底尺寸（确保在100%缩放下有足够空间）
            int baseWidth = 1024;
            int baseHeight = 768;

            // 取较大值，但不超过屏幕的90%
            int finalWidth = Math.Min(Math.Max(targetWidth, baseWidth), (int)(screenArea.Width * 0.9));
            int finalHeight = Math.Min(Math.Max(targetHeight, baseHeight), (int)(screenArea.Height * 0.9));

            this.ClientSize = new Size(finalWidth, finalHeight);
        }

        /// <summary>
        /// 获取当前DPI缩放比例（100%缩放返回1.0，150%返回1.5，175%返回1.75）
        /// </summary>
        private float GetDpiScaleFactor()
        {
            using (Graphics g = this.CreateGraphics())
            {
                return g.DpiX / 96f;
            }
        }

        /// <summary>
        /// <summary>
        /// 加载侧边栏图标（从Icon文件夹加载PNG，如果不存在则使用内置图标）
        /// </summary>
        private Image GetSidebarIcon(string iconName)
        {
            var iconPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Icon", iconName + ".png");
            if (File.Exists(iconPath))
            {
                try
                {
                    var img = Image.FromFile(iconPath);
                    return ColorizeImage(img, Color.White);
                }
                catch { }
            }
            return GetBuiltInIcon(iconName);
        }

        /// <summary>
        /// 获取内置图标图像（Segoe MDL2 Assets）
        /// </summary>
        private Image GetBuiltInIcon(string iconName)
        {
            var iconChar = GetBuiltInIconChar(iconName);
            if (string.IsNullOrEmpty(iconChar)) return new Bitmap(32, 32);

            try
            {
                var bmp = new Bitmap(32, 32);
                using (var g = Graphics.FromImage(bmp))
                {
                    g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
                    g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                    using (var font = new Font("Segoe MDL2 Assets", 18, FontStyle.Regular))
                    using (var brush = new SolidBrush(Color.White))
                    {
                        var size = g.MeasureString(iconChar, font);
                        float x = (32 - size.Width) / 2;
                        float y = (32 - size.Height) / 2;
                        g.DrawString(iconChar, font, brush, x, y);
                    }
                }
                return bmp;
            }
            catch
            {
                return new Bitmap(32, 32);
            }
        }

        /// <summary>
        /// 获取内置图标字符（Segoe MDL2 Assets）
        /// </summary>
        private string GetBuiltInIconChar(string iconName)
        {
            var iconMap = new Dictionary<string, string>
            {
                { "file-earmark-arrow-up", "\uE8D4" },    // Upload
                { "arrow-left-right", "\uE8AB" },         // Sync
                { "download", "\uE896" },                   // Download
                { "envelope-paper-fill", "\uE8B3" },        // Mail
                { "people-fill", "\uE716" },                // People
                { "cloud-check-fill", "\uE8FB" },          // Cloud Done
                { "hdd-stack-fill", "\uEDA2" },             // HDD Stack
                { "list", "\uE700" },                       // List
                { "terminal-fill", "\uE756" }               // Terminal
            };

            return iconMap.TryGetValue(iconName, out var iconChar) ? iconChar : "";
        }

        /// <summary>
        /// 初始化侧边栏图标列表
        /// </summary>
        private void InitializeSideNavIcons()
        {
            _sideNavImageList = new ImageList
            {
                ImageSize = new Size(32, 32),
                ColorDepth = ColorDepth.Depth32Bit
            };

            // 图标顺序与按钮顺序一致
            var iconNames = new[] {
                "file-earmark-arrow-up",   // 转换为PST
                "envelope-paper-fill",      // 邮件提取
                "people-fill",              // 单用户同步（O365)
                "arrow-left-right",         // 批量用户同步（O365）
                "cloud-check-fill",         // O365百宝箱
                "hdd-stack-fill"            // 本地EX百宝箱
            };

            foreach (var iconName in iconNames)
            {
                var img = GetSidebarIcon(iconName);
                _sideNavImageList.Images.Add(img);
            }
        }

        /// <summary>
        /// 将图标着色为指定颜色（用于在深色背景上显示白色图标）
        /// </summary>
        private Image ColorizeImage(Image source, Color targetColor)
        {
            if (source == null) return null;
            var bmp = new Bitmap(source.Width, source.Height);
            using (var g = Graphics.FromImage(bmp))
            {
                g.DrawImage(source, 0, 0);
            }
            // 遍历所有像素，将非透明像素改为目标颜色
            for (int x = 0; x < bmp.Width; x++)
            {
                for (int y = 0; y < bmp.Height; y++)
                {
                    var pixel = bmp.GetPixel(x, y);
                    if (pixel.A > 0)
                    {
                        bmp.SetPixel(x, y, Color.FromArgb(pixel.A, targetColor));
                    }
                }
            }
            return bmp;
        }

        /// <summary>
        /// 确保注册信息已保存到INF文件，避免更新时丢失
        /// </summary>
        private void EnsureRegistrationSaved()
        {
            try
            {
                var settings = ConfigService.LoadAll();
                if (settings.IsRegistered)
                {
                    // 如果已注册，确保信息保存到registration.inf
                    ConfigService.SaveRegistration(settings);
                    Log("注册信息已保存到INF文件");
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Warning(ex, "保存注册信息失败");
            }
        }

        /// <summary>
        /// 如果没有订单记录也没有激活记录，弹出注册框
        /// </summary>
        private async void CheckAndShowRegistration()
        {
            try
            {
                var settings = ConfigService.LoadAll();

                // 优先从注册表加载注册信息（快速启动）
                if (RegistryService.HasRegistrationRecord())
                {
                    RegistryService.LoadRegistration(settings);
                    ConfigService.SaveRegistration(settings);
                    UpdateRegistrationStatus();
                    Log("从注册表加载注册信息成功，剩余天数：" + settings.RegisterRemainingDays);
                    return;
                }

                // 注册表没有记录，向服务器查询
                var regService = new RegistrationService();
                var currentMac = regService.GetPhysicalMacAddress();

                var result = await regService.CheckRegistrationStatusAsync(
                    "小铭邮件百宝箱",
                    settings.RegisteredUserEmail);

                if (result.Success)
                {
                    // 服务器返回成功，更新本地注册信息
                    settings.RegisteredMacAddress = currentMac;
                    settings.RegisterRemainingDays = result.RemainingDays;
                    settings.RegisterExpireDate = result.ExpireDate;
                    if (DateTime.TryParse(result.InstallDate, out var installDate))
                        settings.RegisterDate = installDate;
                    settings.IsRegistered = true;

                    // 如果是已购买激活，保存激活码
                    if (result.IsActivated && !string.IsNullOrEmpty(result.ActivationCode))
                    {
                        settings.RegisterSerialNumber = result.ActivationCode;
                    }

                    // 保存到注册表和INF文件
                    RegistryService.SaveRegistration(settings);
                    ConfigService.SaveRegistration(settings);
                    UpdateRegistrationStatus();
                    Log("注册状态检查成功，剩余天数：" + result.RemainingDays);
                }
                else
                {
                    // 服务器返回未注册/无订单记录，弹出注册框
                    Log("服务器返回无注册记录：" + result.Message);
                    ShowRegistrationFormAndExitIfCancelled();
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Warning(ex, "检查注册状态失败");
                // 检查失败时也弹出注册框
                ShowRegistrationFormAndExitIfCancelled();
            }
        }

        private void ShowRegistrationFormAndExitIfCancelled()
        {
            using (var regForm = new RegistrationForm())
            {
                if (regForm.ShowDialog() != DialogResult.OK)
                {
                    // 用户取消注册，退出程序
                    Environment.Exit(0);
                }
            }
        }

        private void RecordFirstRunDate()
        {
            var settings = ConfigService.LoadAll();
            if (!settings.FirstRunDate.HasValue)
            {
                settings.FirstRunDate = DateTime.Now;
                ConfigService.SaveAll(settings);
                RegistryService.SaveRegistration(settings);
                Log("首次运行日期已记录: " + settings.FirstRunDate.Value.ToString("yyyy-MM-dd HH:mm:ss"));
            }
        }

        private void CheckTrialPeriod()
        {
            var settings = ConfigService.LoadAll();
            if (settings.IsRegistered && settings.RegisterRemainingDays.HasValue)
            {
                int remainingDays = settings.RegisterRemainingDays.Value;

                // 如果服务器返回的剩余天数为0或不合理，尝试从过期日期计算
                if (remainingDays <= 0 && !string.IsNullOrEmpty(settings.RegisterExpireDate))
                {
                    if (DateTime.TryParse(settings.RegisterExpireDate, out DateTime expireDate))
                    {
                        remainingDays = (int)Math.Max(0, (expireDate - DateTime.Now).TotalDays);
                    }
                }

                bool isOfficial = !string.IsNullOrEmpty(settings.RegisterSerialNumber);
                if (isOfficial)
                {
                    _trialLabel.Text = $"订阅版 | 剩余 {remainingDays} 天";
                    _trialLabel.ForeColor = remainingDays <= 7 ? Color.Orange : Color.Green;
                }
                else
                {
                    _trialLabel.Text = $"试用版 | 剩余 {remainingDays} 天";
                    _trialLabel.ForeColor = remainingDays <= 7 ? Color.Red : Color.Orange;
                }
            }
            else
            {
                _trialLabel.Text = "未授权";
                _trialLabel.ForeColor = Color.Red;
            }
        }

        /// <summary>
        /// 检查授权是否过期，过期则弹出激活框（无法关闭）
        /// </summary>
        private void CheckExpiration()
        {
            var settings = ConfigService.LoadAll();
            if (settings.IsRegistered && settings.RegisterRemainingDays.HasValue && settings.RegisterRemainingDays.Value <= 0)
            {
                ShowExpirationDialog();
            }
        }

        private void ShowExpirationDialog()
        {
            var result = MessageBox.Show(
                "您的订阅已过期！\n\n请购买授权并激活后继续使用。\n\n点击\"确定\"前往激活界面。",
                "订阅已过期",
                MessageBoxButtons.OKCancel,
                MessageBoxIcon.Warning);

            if (result == DialogResult.OK)
            {
                // 打开注册激活界面
                using (var regForm = new RegistrationForm())
                {
                    if (regForm.ShowDialog() != DialogResult.OK)
                    {
                        // 用户取消，返回注册界面重新检查
                        ShowExpirationDialog();
                        return;
                    }
                }

                // 激活成功后，重新检查
                var settings = ConfigService.LoadAll();
                if (settings.RegisterRemainingDays.HasValue && settings.RegisterRemainingDays.Value > 0)
                {
                    UpdateRegistrationStatus();
                    MessageBox.Show("激活成功！", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                else
                {
                    // 仍然过期，再次弹出
                    ShowExpirationDialog();
                }
            }
            else
            {
                // 用户取消，退出程序
                Application.Exit();
            }
        }

        private bool CheckPythonEnvironment()
        {
            try
            {
                var exeDir = AppDomain.CurrentDomain.BaseDirectory;
                var checkScript = Path.Combine(exeDir, "script", "check_env.py");

                if (!File.Exists(checkScript))
                {
                    MessageBox.Show("环境检查脚本不存在，请重新安装程序", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return false;
                }

                var pythonExe = Program.GetPythonExecutable();
                if (string.IsNullOrEmpty(pythonExe))
                {
                    MessageBox.Show("Python环境未找到，请重新安装程序", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return false;
                }

                var startInfo = Program.CreatePythonStartInfo(pythonExe, $"\"{checkScript}\"");

                using (var process = System.Diagnostics.Process.Start(startInfo))
                {
                    if (process != null)
                    {
                        process.WaitForExit(30000);
                        var output = process.StandardOutput.ReadToEnd();
                        var error = process.StandardError.ReadToEnd();

                        Log("Environment check output: " + output);
                        if (!string.IsNullOrEmpty(error))
                            Log("Environment check error: " + error);

                        if (process.ExitCode != 0)
                        {
                            Log("Python环境检查失败，将使用内置Python环境: " + output);
                            return false;
                        }
                    }
                }
                return true;
            }
            catch (Exception ex)
            {
                Log("无法启动Python环境: " + ex.Message);
                return false;
            }
        }

        private void Log(string message, string pstLogType = null, string mailPickLogType = null)
        {
            var logPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs", "mailconverter.log");
            var logEntry = $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {message}\n";
            // 使用UTF-8编码写入日志，解决中文乱码问题
            File.AppendAllText(logPath, logEntry, System.Text.Encoding.UTF8);

            // 如果指定了PST日志类型，也写入PST转换日志
            if (!string.IsNullOrEmpty(pstLogType))
            {
                TransferPstLogService.Log(pstLogType, message);
            }

            // 如果指定了邮件提取日志类型，也写入邮件提取日志
            if (!string.IsNullOrEmpty(mailPickLogType))
            {
                MailPickLogService.Log(mailPickLogType, message);
            }

            // 同时显示到UI
            if (_logTextBox != null && !_logTextBox.IsDisposed)
            {
                if (_logTextBox.InvokeRequired)
                {
                    _logTextBox.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText(logEntry);
                    }));
                }
                else
                {
                    _logTextBox.AppendText(logEntry);
                }
            }
        }

        // 切换日志显示
        private void ToggleLogView()
        {
            if (_logTextBox != null)
            {
                _logTextBox.Visible = !_logTextBox.Visible;
            }
        }

        // 切换PST转换日志类型并显示对应日志
        private void SwitchPstLog(string logType)
        {
            _currentPstLogType = logType;
            TransferPstLogService.SetCurrentLogType(logType);

            // 读取并显示对应日志
            var logContent = TransferPstLogService.ReadLog(logType);
            if (_logTextBox != null && !_logTextBox.IsDisposed)
            {
                if (_logTextBox.InvokeRequired)
                {
                    _logTextBox.Invoke(new Action(() =>
                    {
                        _logTextBox.Text = logContent;
                        _logTextBox.SelectionStart = _logTextBox.Text.Length;
                        _logTextBox.ScrollToCaret();
                    }));
                }
                else
                {
                    _logTextBox.Text = logContent;
                    _logTextBox.SelectionStart = _logTextBox.Text.Length;
                    _logTextBox.ScrollToCaret();
                }
            }
        }

        // 切换邮件提取日志类型并显示对应日志
        private void SwitchMailPickLog(string logType)
        {
            _currentMailPickLogType = logType;
