        private async void CheckRegistrationStatus_Click(object sender, EventArgs e)
        {
            var settings = ConfigService.LoadAll();
            if (string.IsNullOrEmpty(settings.RegisteredMacAddress))
            {
                MessageBox.Show("您尚未注册本软件。", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            try
            {
                var regService = new RegistrationService();
                var result = await regService.CheckRegistrationStatusAsync(
                    "小铭邮件百宝箱",
                    settings.RegisteredUserEmail);

                if (result.Success)
                {
                    // 更新本地注册信息
                    settings.RegisterRemainingDays = result.RemainingDays;
                    settings.RegisterExpireDate = result.ExpireDate;
                    if (DateTime.TryParse(result.InstallDate, out var installDate))
                        settings.RegisterDate = installDate;

                    // 如果是已购买激活，保存激活码
                    if (result.IsActivated && !string.IsNullOrEmpty(result.ActivationCode))
                    {
                        settings.RegisterSerialNumber = result.ActivationCode;
                    }

                    ConfigService.SaveAll(settings);

                    // 刷新状态显示
                    UpdateRegistrationStatus();

                    var versionType = result.IsActivated ? "已授权" : (string.IsNullOrEmpty(settings.RegisterSerialNumber) ? "试用版" : "订阅版");
                    MessageBox.Show(
                        $"{versionType}\n剩余天数：{result.RemainingDays} 天\n到期日期：{result.ExpireDate}",
                        "注册状态",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information);
                }
                else
                {
                    // 服务器返回未注册或过期，使用本地数据重新注册
                    var reRegResult = await regService.RegisterAsync(
                        "小铭邮件百宝箱",
                        "1.1.0",
                        settings.RegisteredUserName,
                        settings.RegisteredUserEmail,
                        settings.RegisteredOrganization,
                        settings.RegisteredMacAddress);

                    if (reRegResult.Success)
                    {
                        settings.RegisterRemainingDays = reRegResult.RemainingDays;
                        settings.RegisterExpireDate = reRegResult.ExpireDate;
                        if (DateTime.TryParse(reRegResult.InstallDate, out var installDate))
                            settings.RegisterDate = installDate;
                        settings.IsRegistered = true;
                        ConfigService.SaveAll(settings);
                        UpdateRegistrationStatus();
                        MessageBox.Show("注册状态已恢复，剩余天数：" + reRegResult.RemainingDays + " 天", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    else
                    {
                        MessageBox.Show("检查注册状态失败：" + result.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Error(ex, "检查注册状态异常");
                MessageBox.Show("检查注册状态异常：" + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

