        /// <summary>
        /// 创建侧边栏导航按钮（使用手动位置定位）
        /// </summary>
        /// <param name="panelIndexMap">面板索引映射，用于按钮点击时显示对应面板。如果为null，则使用默认的ShowContentPanel方式。</param>
        private void CreateSideNavButtons(Dictionary<int, Control> panelIndexMap = null)
        {
            int y = 40; // 从顶部开始（避开菜单按钮）
            int buttonHeight = 45;
            int spacing = 5;
            Button firstButton = null;

            // 按顺序添加按钮（从上到下），图标索引与InitializeSideNavIcons中的顺序一致
            // 使用ShowPanel直接显示对应的面板容器
            if (_featureSettings.Feature_ToPst)
            {
                var btn = CreateNavButton("转换为PST", y, 0);
                if (panelIndexMap != null && panelIndexMap.ContainsKey(0))
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowPanel(panelIndexMap[0]); };
                else
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowContentPanel(0); };
                _sideNavPanel.Controls.Add(btn);
                firstButton = firstButton ?? btn;
                y += buttonHeight + spacing;
            }

            if (_featureSettings.Feature_Extract)
            {
                var btn = CreateNavButton("邮件提取", y, 1);
                if (panelIndexMap != null && panelIndexMap.ContainsKey(1))
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowPanel(panelIndexMap[1]); };
                else
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowContentPanel(1); };
                _sideNavPanel.Controls.Add(btn);
                firstButton = firstButton ?? btn;
                y += buttonHeight + spacing;
            }

            if (_featureSettings.Feature_SingleUserSync)
            {
                var btn = CreateNavButton("单用户同步（O365)", y, 2);
                if (panelIndexMap != null && panelIndexMap.ContainsKey(2))
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowPanel(panelIndexMap[2]); };
                else
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowContentPanel(2); };
                _sideNavPanel.Controls.Add(btn);
                firstButton = firstButton ?? btn;
                y += buttonHeight + spacing;
            }

            if (_featureSettings.Feature_BatchSync)
            {
                var btn = CreateNavButton("批量用户同步（O365）", y, 3);
                if (panelIndexMap != null && panelIndexMap.ContainsKey(3))
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowPanel(panelIndexMap[3]); };
                else
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowContentPanel(3); };
                _sideNavPanel.Controls.Add(btn);
                firstButton = firstButton ?? btn;
                y += buttonHeight + spacing;
            }

            if (_featureSettings.Feature_O365Toolkit)
            {
                var btn = CreateNavButton("O365百宝箱", y, 4);
                if (panelIndexMap != null && panelIndexMap.ContainsKey(4))
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowPanel(panelIndexMap[4]); };
                else
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowContentPanel(4); };
                _sideNavPanel.Controls.Add(btn);
                firstButton = firstButton ?? btn;
                y += buttonHeight + spacing;
            }

            if (_featureSettings.Feature_OnPremiseToolkit)
            {
                var btn = CreateNavButton("本地EX百宝箱", y, 5);
                if (panelIndexMap != null && panelIndexMap.ContainsKey(5))
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowPanel(panelIndexMap[5]); };
                else
                    btn.Click += (s, e) => { SetSelectedNavButton(btn); ShowContentPanel(5); };
                _sideNavPanel.Controls.Add(btn);
                firstButton = firstButton ?? btn;
                y += buttonHeight + spacing;
            }

            // 设置第一个按钮为选中状态
            if (firstButton != null)
            {
                SetSelectedNavButton(firstButton);
            }
        }

        private Button CreateNavButton(string text, int y, int iconIndex = -1)
        {
            var btn = new Button
            {
                Text = text,
                Location = new Point(0, y),
                Size = new Size(SIDENAV_EXPANDED_WIDTH - 5, 45),
                FlatStyle = FlatStyle.Flat,
                ForeColor = Color.White,
                BackColor = NAV_DEFAULT_BG,
                TextAlign = ContentAlignment.MiddleLeft,
                ImageAlign = ContentAlignment.MiddleLeft,
                Padding = new Padding(20, 0, 0, 0),
                FlatAppearance = { BorderSize = 0 },
                Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right,
                AutoEllipsis = true,
                Font = new Font("Microsoft YaHei", 9f)
            };

            // 强制文字在图标后面，绝不允许重叠
            btn.TextImageRelation = TextImageRelation.ImageBeforeText;

            if (iconIndex >= 0 && _sideNavImageList != null)
            {
                btn.ImageList = _sideNavImageList;
                btn.ImageIndex = iconIndex;
            }

            return btn;
        }

        private void SetSelectedNavButton(Button selectedButton)
        {
            // 恢复之前选中的按钮样式
            if (_currentSelectedNavButton != null)
            {
                _currentSelectedNavButton.BackColor = NAV_DEFAULT_BG;
                _currentSelectedNavButton.FlatAppearance.MouseOverBackColor = NAV_HOVER_BG;
            }

            // 设置新的选中按钮样式
            _currentSelectedNavButton = selectedButton;
            _currentSelectedNavButton.BackColor = NAV_SELECTED_BG;
            _currentSelectedNavButton.FlatAppearance.MouseOverBackColor = NAV_SELECTED_BG;
        }

        private void ShowContentPanel(int index)
        {
            // 隐藏所有容器面板
            foreach (Control ctrl in _mainContentPanel.Controls)
            {
                ctrl.Visible = false;
            }

            // 显示指定索引的容器
            int visibleIndex = 0;
            foreach (Control ctrl in _mainContentPanel.Controls)
            {
                if (index == visibleIndex)
                {
                    ctrl.Visible = true;
                    break;
                }
                visibleIndex++;
            }
        }

        private void ShowPanel(Control panel)
        {
            // 隐藏所有容器面板
            foreach (Control ctrl in _mainContentPanel.Controls)
            {
                ctrl.Visible = false;
            }
            // 显示指定的面板
            if (panel != null)
            {
                panel.Visible = true;
            }
        }

        private void BtnMenuToggle_Click(object sender, EventArgs e)
        {
            if (_sideNavAnimTimer.Enabled) return; // 动画进行中不重复触发
            _sideNavAnimTimer.Start();
        }

        private void SideNavAnimTimer_Tick(object sender, EventArgs e)
        {
            if (_isSideNavCollapsed)
            {
                // 展开动画
                _sideNavPanel.Width += SIDENAV_ANIM_STEP;
                if (_sideNavPanel.Width >= SIDENAV_EXPANDED_WIDTH)
                {
                    _sideNavPanel.Width = SIDENAV_EXPANDED_WIDTH;
                    _sideNavAnimTimer.Stop();
                    _isSideNavCollapsed = false;
                    RestoreNavButtonTexts();
                    this.Refresh(); // 刷新窗体
                }
            }
            else
            {
                // 收缩动画
                _sideNavPanel.Width -= SIDENAV_ANIM_STEP;
                if (_sideNavPanel.Width <= SIDENAV_COLLAPSED_WIDTH)
                {
                    _sideNavPanel.Width = SIDENAV_COLLAPSED_WIDTH;
                    _sideNavAnimTimer.Stop();
                    _isSideNavCollapsed = true;
                    HideNavButtonTexts();
                    this.Refresh(); // 刷新窗体
                }
            }
        }

        private void HideNavButtonTexts()
        {
            foreach (Control ctrl in _sideNavPanel.Controls)
            {
                if (ctrl is Button btn && btn != _btnMenuToggle)
                {
                    btn.Text = "";
                    btn.TextAlign = ContentAlignment.MiddleCenter;
                    btn.Padding = new Padding(0);
                }
            }
        }

        private void RestoreNavButtonTexts()
        {
            var buttons = _sideNavPanel.Controls.OfType<Button>().Where(b => b != _btnMenuToggle).ToList();
            // 按添加顺序设置（与显示顺序一致）
            if (buttons.Count >= 1) buttons[0].Text = "转换为PST";
            if (buttons.Count >= 2) buttons[1].Text = "邮件提取";
            if (buttons.Count >= 3) buttons[2].Text = "单用户同步（O365)";
            if (buttons.Count >= 4) buttons[3].Text = "批量用户同步（O365）";
            if (buttons.Count >= 5) buttons[4].Text = "O365百宝箱";
            if (buttons.Count >= 6) buttons[5].Text = "本地EX百宝箱";

            foreach (Control ctrl in _sideNavPanel.Controls)
            {
                if (ctrl is Button btn && btn != _btnMenuToggle)
                {
                    btn.TextImageRelation = TextImageRelation.ImageBeforeText;
                    btn.TextAlign = ContentAlignment.MiddleLeft;
                    btn.ImageAlign = ContentAlignment.MiddleLeft;
                    btn.Padding = new Padding(20, 0, 0, 0);
                    btn.AutoEllipsis = true;
                }
            }
        }

