            #region Event Handlers
            // Validate SAS URL
            btnValidateSas.MouseDown += (s, e) =>
            {
                Program.PurviewLogger.Information("[PurView] 验证按钮 MouseDown 触发");
            };
            btnValidateSas.Click += async (s, e) =>
            {
                Program.PurviewLogger.Information("[PurView] 验证按钮 Click 事件触发, btnValidateSas.Enabled={Enabled}", btnValidateSas.Enabled);
                string sasUrl;
                try
                {
                    sasUrl = txtSasUrl.Text.Trim();
                }
                catch (Exception ex)
                {
                    Program.PurviewLogger.Error(ex, "[PurView] 获取 SAS URL 失败");
                    lblSasStatus.Text = "错误: 无法获取 SAS URL";
                    lblSasStatus.ForeColor = Color.Red;
                    return;
                }

                Program.PurviewLogger.Information("[PurView] SAS URL 长度: {Len}", sasUrl.Length);

                if (string.IsNullOrEmpty(sasUrl))
                {
                    lblSasStatus.Text = "请输入 SAS URL";
                    lblSasStatus.ForeColor = Color.Red;
                    return;
                }

                lblSasStatus.Text = "验证中...";
                lblSasStatus.ForeColor = Color.Orange;

                try
                {
                    var azureService = new AzureStorageService();
                    azureService.ConnectWithSasUrl(sasUrl);
                    var result = await azureService.ValidateSasUrlAsync();

                    lblSasStatus.Text = result;
                    if (result.Contains("成功"))
                    {
                        lblSasStatus.ForeColor = Color.Green;
                        // 验证成功后，如果文件列表不为空则显示上传按钮
                        btnStartUpload.Visible = gridPstFiles.RowCount > 0;
                    }
                    else
                    {
                        lblSasStatus.ForeColor = Color.Red;
                    }
                }
                catch (Exception ex)
                {
                    Program.PurviewLogger.Error(ex, "[PurView] 验证异常");
                    lblSasStatus.Text = "验证异常: " + ex.Message;
                    lblSasStatus.ForeColor = Color.Red;
                }
            };

            // Load Folder
            btnLoadFolder.Click += (s, e) =>
            {
                using (var fbd = new FolderBrowserDialog())
                {
                    if (fbd.ShowDialog() == DialogResult.OK)
                    {
                        gridPstFiles.Rows.Clear();
                        var files = Directory.GetFiles(fbd.SelectedPath, "*.pst");

                        foreach (var file in files)
                        {
                            var fileName = Path.GetFileName(file);
                            var emailName = Path.GetFileNameWithoutExtension(fileName); // 去掉.pst后缀
                            gridPstFiles.Rows.Add(fileName, emailName, false, "待上传");
                            gridPstFiles.Rows[gridPstFiles.RowCount - 1].Tag = file;
                        }

                        lblStatus.Text = $"已载入 {files.Length} 个 PST 文件";
                        lblStatus.ForeColor = Color.Gray;

                        // 如果 SAS 已验证且文件列表不为空，则显示上传按钮
                        btnStartUpload.Visible = files.Length > 0 && lblSasStatus.Text.Contains("成功");
                    }
                }
            };

            // Select All
            btnSelectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridPstFiles.Rows)
                {
                    row.Cells["Select"].Value = true;
                }
            };

            // Deselect All
            btnDeselectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridPstFiles.Rows)
                {
                    row.Cells["Select"].Value = false;
                }
            };

            // Start Upload with AzCopy
            btnStartUpload.Click += (s, e) =>
            {
                var sasUrl = txtSasUrl.Text.Trim();

                if (string.IsNullOrEmpty(sasUrl))
                {
                    lblStatus.Text = "请输入 SAS URL";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                if (!AzureStorageService.IsAzCopyAvailable())
                {
                    lblStatus.Text = "请先安装 AzCopy";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                // 收集选中的文件
                var selectedFiles = new List<Tuple<string, string>>(); // localPath, blobName
                foreach (DataGridViewRow row in gridPstFiles.Rows)
                {
                    if (row.Cells["Select"].Value != null && (bool)row.Cells["Select"].Value)
                    {
                        var localPath = row.Tag?.ToString();
                        var blobName = row.Cells["FileName"].Value?.ToString();

                        if (!string.IsNullOrEmpty(localPath) && !string.IsNullOrEmpty(blobName))
                        {
                            selectedFiles.Add(Tuple.Create(localPath, blobName));
                        }
                    }
                }

                if (selectedFiles.Count == 0)
                {
                    lblStatus.Text = "请选择要上传的 PST 文件";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                // 禁用按钮
                btnStartUpload.Enabled = false;
                btnLoadFolder.Enabled = false;
                btnCancelMigration.Enabled = true;
                progressUpload.Style = ProgressBarStyle.Marquee;

                Task.Run(() =>
                {
                    var azureService = new AzureStorageService();
                    azureService.ConnectWithSasUrl(sasUrl);

                    int successCount = 0;
                    int failCount = 0;
                    int total = selectedFiles.Count;
                    var uploadedFiles = new List<Tuple<string, string>>(); // (fileName, targetEmail)

                    for (int i = 0; i < selectedFiles.Count; i++)
                    {
                        var file = selectedFiles[i];

                        // 获取目标邮箱
                        string targetEmail = "";
                        this.Invoke(new Action(() =>
                        {
                            foreach (DataGridViewRow row in gridPstFiles.Rows)
                            {
                                if (row.Cells["FileName"].Value?.ToString() == file.Item2)
                                {
                                    targetEmail = row.Cells["TargetEmail"].Value?.ToString() ?? "";
                                    break;
                                }
                            }
                        }));

                        this.Invoke(new Action(() =>
                        {
                            int percent = ((i + 1) * 100) / total;
                            lblProgressPercent.Text = percent + "%";
                            lblStatus.Text = $"正在上传: {file.Item2} ({i + 1}/{total})";
                        }));

                        // 更新状态为上传中
                        this.Invoke(new Action(() =>
                        {
                            foreach (DataGridViewRow row in gridPstFiles.Rows)
                            {
                                if (row.Cells["FileName"].Value?.ToString() == file.Item2)
                                {
                                    row.Cells["Status"].Value = "上传中...";
                                    break;
                                }
                            }
                        }));

                        // 使用 AzCopy 上传
                        bool success = azureService.UploadWithAzCopyAsync(file.Item1, file.Item2,
                            (p, m) => this.Invoke(new Action(() =>
                            {
                                lblProgressDetail.Text = m;
                            }))).Result;

                        this.Invoke(new Action(() =>
                        {
                            foreach (DataGridViewRow row in gridPstFiles.Rows)
                            {
                                if (row.Cells["FileName"].Value?.ToString() == file.Item2)
                                {
                                    row.Cells["Status"].Value = success ? "已上传" : "上传失败";
                                    row.Cells["Select"].Value = false;
                                    break;
                                }
                            }
                        }));

                        if (success)
                        {
                            successCount++;
                            uploadedFiles.Add(Tuple.Create(file.Item2, targetEmail));
                        }
                        else
                            failCount++;
                    }

                    // 写入上传记录 CSV
                    if (uploadedFiles.Count > 0)
                    {
                        try
                        {
                            var settings = ConfigService.LoadAll();
                            var outputDir = string.IsNullOrEmpty(settings.PurviewOutputPath)
                                ? Program.PurviewLogDirectory
                                : settings.PurviewOutputPath;

                            if (!Directory.Exists(outputDir))
                                Directory.CreateDirectory(outputDir);

                            var csvPath = Path.Combine(outputDir, $"uploaded_{DateTime.Now:yyyyMMdd_HHmmss}.csv");
                            // Purview CSV 格式: Workload,FilePath,Name,Mailbox,IsArchive,TargetRootFolder,ContentCodePage,SPFileContainer,SPManifestContainer,SPSiteUrl
                            // 10列数据 = 9个逗号
                            var csvLines = new List<string> { "Workload,FilePath,Name,Mailbox,IsArchive,TargetRootFolder,ContentCodePage,SPFileContainer,SPManifestContainer,SPSiteUrl" };
                            foreach (var uploaded in uploadedFiles)
                            {
                                // 格式: Exchange,,文件名.pst,邮箱,FALSE,/,,,,
                                csvLines.Add(string.Format("Exchange,,{0},{1},FALSE,/,,,,", uploaded.Item1, uploaded.Item2));
                            }
                            File.WriteAllLines(csvPath, csvLines, new System.Text.UTF8Encoding(false));
                            Program.PurviewLogger.Information("[PurView] 上传记录已保存: {Path}", csvPath);
                        }
                        catch (Exception ex)
                        {
                            Program.PurviewLogger.Error(ex, "[PurView] 保存上传记录失败");
                        }
                    }

                    // 完成
                    this.Invoke(new Action(() =>
                    {
                        btnStartUpload.Enabled = true;
                        btnLoadFolder.Enabled = true;
                        btnCancelMigration.Enabled = false;
                        progressUpload.Style = ProgressBarStyle.Continuous;
                        progressUpload.Value = 100;
                        lblProgressPercent.Text = "100%";

                        if (failCount > 0)
                        {
                            lblProgressPercent.ForeColor = Color.Red;
                            lblStatus.Text = $"上传完成: 成功 {successCount}, 失败 {failCount}";
                            lblStatus.ForeColor = Color.Red;

                            // 弹出错误提示
                            var errorMsg = $"PST 文件上传失败！\n\n可能原因：\n1. 文件被其他程序锁定（如 Outlook）\n2. 文件路径不存在或为空\n3. SAS URL 权限不足\n\n请检查：\n- 文件是否正在被其他程序使用\n- 关闭 Outlook 后重试\n- 查看 AzCopy 日志: C:\\Users\\{Environment.UserName}\\.azcopy\\*.log";
                            MessageBox.Show(errorMsg, "上传失败", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }
                        else
                        {
                            lblProgressPercent.ForeColor = Color.Green;
                            lblStatus.Text = $"上传完成: 成功 {successCount}";
                            lblStatus.ForeColor = Color.Green;
                        }

                        lblProgressDetail.Text = $"成功: {successCount} 个\n失败: {failCount} 个";
                    }));

                    Serilog.Log.Information("PST 上传完成: 成功 {Success}, 失败 {Fail}", successCount, failCount);
                });
            };

            // Cancel
            btnCancelMigration.Click += (s, e) =>
            {
                lblStatus.Text = "取消操作...";
                lblStatus.ForeColor = Color.Orange;
                btnStartUpload.Enabled = true;
                btnLoadFolder.Enabled = true;
                btnCancelMigration.Enabled = false;
                progressUpload.Style = ProgressBarStyle.Continuous;
            };
            #endregion

            #region Add Controls to Panel
            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblSasUrl);
            panel.Controls.Add(txtSasUrl);
            panel.Controls.Add(lblSasUrlHint);
            panel.Controls.Add(btnValidateSas);
            panel.Controls.Add(lblSasStatus);
            panel.Controls.Add(lblFileList);
            panel.Controls.Add(gridPstFiles);
            panel.Controls.Add(btnLoadFolder);
            panel.Controls.Add(btnSelectAll);
            panel.Controls.Add(btnDeselectAll);
            panel.Controls.Add(lblProgressTitle);
            panel.Controls.Add(lblProgressPercent);
            panel.Controls.Add(lblProgressDetail);
            panel.Controls.Add(progressUpload);
            panel.Controls.Add(btnStartUpload);
            panel.Controls.Add(btnViewStatus);
            panel.Controls.Add(btnCancelMigration);
            panel.Controls.Add(lblStatus);
            #endregion

            return panel;
        }

