        private void UpdateExtractMethod()
        {
            // WSL方案只支持EML格式，隐藏MSG选项
            if (cmbExtractMethod != null && cmbExtractMethod.SelectedIndex == 1)
            {
                // WSL方案
                if (cmbExtractFormat != null && cmbExtractFormat.Items.Count > 1)
                {
                    cmbExtractFormat.Items.RemoveAt(1); // 移除MSG格式
                }
                if (cmbExtractFormat != null && cmbExtractFormat.SelectedIndex != 0)
                {
                    cmbExtractFormat.SelectedIndex = 0; // 强制选择EML
                }
            }
            else
            {
                // Outlook方案，恢复MSG选项
                if (cmbExtractFormat != null && cmbExtractFormat.Items.Count == 1)
                {
                    cmbExtractFormat.Items.Add("MSG格式");
                }
            }
            UpdateExtractButton();
        }

        private void UpdateExtractButton()
        {
            if (cmbExtractMethod == null || cmbExtractFormat == null || btnExtract == null)
                return;

            bool isOutlook = cmbExtractMethod.SelectedIndex == 0;
            string format = cmbExtractFormat.SelectedIndex == 0 ? "EML" : "MSG";

            if (isOutlook)
            {
                btnExtract.Text = $"提取为{format}";
            }
            else
            {
                btnExtract.Text = "提取(WSL)";
            }
        }

