            chkImapSsl.Checked = true;
            panel.Controls.Add(chkImapSsl);
            yPos += 30;

            // 测试连接按钮
            btnImapTest = new Button();
            btnImapTest.Location = new Point(120, yPos);
            btnImapTest.Size = new Size(100, 28);
            btnImapTest.Text = "测试连接";
            btnImapTest.Click += BtnImapTest_Click;
            panel.Controls.Add(btnImapTest);

            lblImapStatus = new Label();
            lblImapStatus.Location = new Point(230, yPos + 5);
            lblImapStatus.Size = new Size(250, 20);
            lblImapStatus.ForeColor = Color.Gray;
            panel.Controls.Add(lblImapStatus);
            yPos += 40;

            // 分隔线
            var separator1 = new Label
            {
                Text = "",
                Location = new Point(20, yPos),
