        private void BtnExcelAddFiles_Click(object sender, EventArgs e)
        {
            using (var dialog = new OpenFileDialog())
            {
                dialog.Filter = "Excel/CSV文件|*.xlsx;*.xls;*.csv|Excel文件|*.xlsx;*.xls|CSV文件|*.csv";
                dialog.Title = "选择Excel或CSV文件";
                dialog.Multiselect = true;

                if (dialog.ShowDialog() == DialogResult.OK)
                {
                    foreach (var file in dialog.FileNames)
                    {
                        if (!lstExcelFiles.Items.Contains(file))
                        {
                            lstExcelFiles.Items.Add(file);
                        }
                    }
                }
            }
        }

        private void BtnExcelBrowse_Click(object sender, EventArgs e)
        {
            using (var dialog = new FolderBrowserDialog())
            {
                dialog.Description = "选择输出目录";
                if (dialog.ShowDialog() == DialogResult.OK)
                {
                    txtExcelOutputDir.Text = dialog.SelectedPath;
                }
            }
        }

        private async void BtnExcelImport_Click(object sender, EventArgs e)
        {
            if (lstExcelFiles.Items.Count == 0)
            {
                MessageBox.Show("请至少选择一个文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtExcelOutputDir.Text))
            {
                MessageBox.Show("请选择输出目录", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtExcelFileName.Text))
            {
                MessageBox.Show("请输入文件名", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            string outputPath = Path.Combine(txtExcelOutputDir.Text, txtExcelFileName.Text);
            if (!outputPath.EndsWith(".pst", StringComparison.OrdinalIgnoreCase))
            {
                outputPath += ".pst";
            }

            if (isExcelImporting) return;

            isExcelImporting = true;
            btnExcelImport.Enabled = false;
            btnExcelImport.Text = "导入中...";
            lblStatus.Text = "正在导入...";
            _statusProgressBar.Minimum = 0;
            _statusProgressBar.Maximum = 100;
            _statusProgressBar.Value = 0;

            try
            {
                _excelImportService = new ExcelCsvImportService();
                _excelImportService.SetCallbacks(
                    msg => this.Invoke(new Action(() => {
                        lblExcelStatus.Text = msg;
                        Log("[ExcelImport] " + msg);
                    })),
                    (current, total) => this.Invoke(new Action(() => {
                        _statusProgressBar.Value = (int)((double)current / total * 100);
                        lblStatus.Text = $"正在导入: {current}/{total}";
                    }))
                );

                string[] files = new string[lstExcelFiles.Items.Count];
                lstExcelFiles.Items.CopyTo(files, 0);

                await Task.Run(() => _excelImportService.ImportToPstAsync(
                    files,
                    outputPath,
                    txtExcelSubjectPrefix.Text
                ));

                lblStatus.Text = "导入完成!";
                _statusProgressBar.Value = 100;
                MessageBox.Show("导入完成！", "成功", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                lblStatus.Text = "导入失败: " + ex.Message;
                MessageBox.Show("导入失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Log("[ExcelImport ERROR] " + ex.Message);
            }
            finally
            {
                isExcelImporting = false;
                btnExcelImport.Enabled = true;
                btnExcelImport.Text = "开始导入";
            }
        }

