        private void BtnImapAccountsFile_Click(object sender, EventArgs e)
        {
            using (var dialog = new OpenFileDialog())
            {
                dialog.Filter = "Excel/CSV文件|*.xlsx;*.xls;*.csv";
                dialog.Title = "选择账户配置文件";

                if (dialog.ShowDialog() == DialogResult.OK)
                {
                    txtImapAccountsFile.Text = dialog.FileName;
                    LoadImapAccounts(dialog.FileName);
                }
            }
        }

        private void LoadImapAccounts(string filePath)
        {
            lstImapAccounts.Items.Clear();

            try
            {
                string ext = Path.GetExtension(filePath).ToLower();
                var accounts = new List<ImapAccount>();

                if (ext == ".xlsx" || ext == ".xls")
                {
                    accounts = LoadAccountsFromExcel(filePath);
                }
                else if (ext == ".csv")
                {
                    accounts = LoadAccountsFromCsv(filePath);
                }

                foreach (var account in accounts)
                {
                    lstImapAccounts.Items.Add($"{account.Email} -> {account.PstFilePath}");
                }

                lblImapSyncStatus.Text = $"已加载 {accounts.Count} 个账户";
            }
            catch (Exception ex)
            {
                MessageBox.Show("加载账户失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private List<ImapAccount> LoadAccountsFromExcel(string filePath)
        {
            var accounts = new List<ImapAccount>();

            using (var workbook = new ClosedXML.Excel.XLWorkbook(filePath))
            {
                var worksheet = workbook.Worksheets.First();

                var headerRow = worksheet.Row(1);
                var headers = new List<string>();
                foreach (var cell in headerRow.CellsUsed())
                {
                    headers.Add(cell.GetValue<string>().Trim().ToLower());
                }

                // 找列索引
                int emailIdx = -1, pwdIdx = -1, pstIdx = -1, nameIdx = -1;
                for (int i = 0; i < headers.Count; i++)
                {
                    if (headers[i].Contains("email") || headers[i].Contains("邮箱"))
                        emailIdx = i;
                    if (headers[i].Contains("password") || headers[i].Contains("密码") || headers[i].Contains("pwd"))
                        pwdIdx = i;
                    if (headers[i].Contains("pst") || headers[i].Contains("path") || headers[i].Contains("路径"))
                        pstIdx = i;
                    if (headers[i].Contains("name") || headers[i].Contains("名称") || headers[i].Contains("display"))
                        nameIdx = i;
                }

                if (emailIdx < 0 || pwdIdx < 0 || pstIdx < 0)
                {
                    throw new Exception("Excel文件必须包含Email、Password、PstPath列");
                }

                var rows = worksheet.RowsUsed().Skip(1);
                foreach (var row in rows)
                {
                    var email = row.Cell(emailIdx + 1).GetValue<string>().Trim();
                    var pwd = row.Cell(pwdIdx + 1).GetValue<string>().Trim();
                    var pst = row.Cell(pstIdx + 1).GetValue<string>().Trim();

                    if (!string.IsNullOrWhiteSpace(email) && !string.IsNullOrWhiteSpace(pwd))
                    {
                        var account = new ImapAccount
                        {
                            Email = email,
                            Password = pwd,
                            PstFilePath = pst,
                            DisplayName = nameIdx >= 0 ? row.Cell(nameIdx + 1).GetValue<string>().Trim() : email
                        };

                        accounts.Add(account);
                    }
                }
            }

            return accounts;
        }

        private List<ImapAccount> LoadAccountsFromCsv(string filePath)
        {
            var accounts = new List<ImapAccount>();

            try
            {
                // 尝试不同编码
                System.Text.Encoding encoding = System.Text.Encoding.UTF8;
                var bom = new byte[4];
                using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                {
                    fs.Read(bom, 0, 4);
                    if (bom[0] == 0xEF && bom[1] == 0xBB && bom[2] == 0xBF)
                        encoding = System.Text.Encoding.UTF8;
                    else if (bom[0] == 0xFF && bom[1] == 0xFE)
                        encoding = System.Text.Encoding.Unicode;
                    else if (bom[0] == 0xFE && bom[1] == 0xFF)
                        encoding = System.Text.Encoding.BigEndianUnicode;
                }

                using (var reader = new System.IO.StreamReader(filePath, encoding))
                {
                    var config = new CsvHelper.Configuration.CsvConfiguration(System.Globalization.CultureInfo.InvariantCulture)
                    {
                        HasHeaderRecord = true,
                        MissingFieldFound = null,
                        BadDataFound = null
                    };

                    using (var csv = new CsvHelper.CsvReader(reader, config))
                    {
                        csv.Read();
                        csv.ReadHeader();
                        var headers = csv.HeaderRecord;

                    // 找列索引
                    int emailIdx = -1, pwdIdx = -1, pstIdx = -1, nameIdx = -1;
                    for (int i = 0; i < headers.Length; i++)
                    {
                        string h = headers[i].ToLower();
                        if (h.Contains("email") || h.Contains("邮箱"))
                            emailIdx = i;
                        if (h.Contains("password") || h.Contains("密码") || h.Contains("pwd"))
                            pwdIdx = i;
                        if (h.Contains("pst") || h.Contains("path") || h.Contains("路径"))
                            pstIdx = i;
                        if (h.Contains("name") || h.Contains("名称") || h.Contains("display"))
                            nameIdx = i;
                    }

                    while (csv.Read())
                    {
                        var email = csv.GetField(emailIdx)?.Trim() ?? "";
                        var pwd = csv.GetField(pwdIdx)?.Trim() ?? "";
                        var pst = csv.GetField(pstIdx)?.Trim() ?? "";

                        if (!string.IsNullOrWhiteSpace(email) && !string.IsNullOrWhiteSpace(pwd))
                        {
                            var account = new ImapAccount
                            {
                                Email = email,
                                Password = pwd,
                                PstFilePath = pst,
                                DisplayName = nameIdx >= 0 ? csv.GetField(nameIdx)?.Trim() ?? email : email
                            };

                            accounts.Add(account);
                        }
                    }
                }
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Error(ex, "LoadAccountsFromCsv failed: " + filePath);
                throw new Exception("CSV解析失败: " + ex.Message);
            }

            return accounts;
        }

        private async void BtnImapSyncStart_Click(object sender, EventArgs e)
        {
            if (lstImapAccounts.Items.Count == 0)
            {
                MessageBox.Show("请先加载账户文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (isImapSyncing) return;

            isImapSyncing = true;
            btnImapSyncStart.Enabled = false;
            btnImapSyncStart.Text = "同步中...";
            lblStatus.Text = "正在多线程同步...";
            _statusProgressBar.Minimum = 0;
            _statusProgressBar.Maximum = lstImapAccounts.Items.Count;
            _statusProgressBar.Value = 0;

            try
            {
                // 重新加载账户
                var accounts = new List<ImapAccount>();
                string ext = Path.GetExtension(txtImapAccountsFile.Text).ToLower();
                if (ext == ".xlsx" || ext == ".xls")
                    accounts = LoadAccountsFromExcel(txtImapAccountsFile.Text);
                else
                    accounts = LoadAccountsFromCsv(txtImapAccountsFile.Text);

                // 应用全局服务器设置到没有指定服务器的账户
                string globalHost = txtMultiImapHost.Text?.Trim() ?? "";
                int globalPort = (int)numMultiImapPort.Value;
                bool globalSsl = chkMultiImapSsl.Checked;
                foreach (var account in accounts)
                {
                    if (string.IsNullOrEmpty(account.Host) && !string.IsNullOrEmpty(globalHost))
                    {
                        account.Host = globalHost;
                        account.Port = globalPort;
                        account.UseSsl = globalSsl;
                    }
                }

                _multiImapService = new MultiThreadImapService();
                _multiImapService.SetCallbacks(
                    msg => this.Invoke(new Action(() => {
                        lblImapSyncStatus.Text = msg;
                        Log("[MultiImap] " + msg, "IMAPMULTI2PST");
                    })),
                    (progress) => this.Invoke(new Action(() => {
                        if (progress.TotalAccounts > 0)
                            _statusProgressBar.Value = progress.CompletedAccounts;
                        lblStatus.Text = $"[{progress.CompletedAccounts}/{progress.TotalAccounts}] {progress.CurrentEmail}";
                        if (!string.IsNullOrEmpty(progress.CurrentFolder))
                        {
                            lblMultiImapCurrentFolder.Text = $"当前文件夹: {progress.CurrentFolder}";
                            lblImapSyncStatus.Text = $"已投递: {progress.FolderEmailCount}封";
                        }
                    }))
                );

                int daysBack = chkDaysLimit.Checked ? (int)numDaysBack.Value : 0;

                await Task.Run(() => _multiImapService.SyncAccountsAsync(
                    accounts,
                    (int)numImapParallel.Value,
                    (int)numImapMaxPerAccount.Value,
                    daysBack
                ));

                lblStatus.Text = "同步完成!";
                _statusProgressBar.Value = _statusProgressBar.Maximum;
                MessageBox.Show("全部账户同步完成！", "成功", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                lblStatus.Text = "同步失败: " + ex.Message;
                MessageBox.Show("同步失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Log("[MultiImap ERROR] " + ex.Message, "IMAPMULTI2PST");
            }
            finally
            {
                isImapSyncing = false;
                btnImapSyncStart.Enabled = true;
                btnImapSyncStart.Text = "开始同步";
            }
        }

