        private void UpdateO365AuthUI()
        {
            bool isOAuth = cmbO365AuthType.SelectedIndex == 0; // 现在 OAuth 2.0 是唯一选项

            // 邮箱两种模式都需要
            if (txtO365Email != null) txtO365Email.Visible = true;
            if (lblO365Email != null) lblO365Email.Visible = true;

            // 用户名密码专用 - 隐藏
            if (txtO365Password != null) txtO365Password.Visible = !isOAuth;
            if (txtO365Domain != null) txtO365Domain.Visible = !isOAuth;
            if (lblO365Pwd != null) lblO365Pwd.Visible = !isOAuth;
            if (lblO365Dom != null) lblO365Dom.Visible = !isOAuth;

            // 测试连接按钮 - 用户名密码模式显示
            if (btnO365Test != null) btnO365Test.Visible = !isOAuth;

            // OAuth 专用 - 显示
            if (txtO365ClientId != null) txtO365ClientId.Visible = isOAuth;
            if (btnO365OAuthLogin != null) btnO365OAuthLogin.Visible = isOAuth;
            if (lblO365ClientId != null) lblO365ClientId.Visible = isOAuth;
            if (txtO365TenantId != null) txtO365TenantId.Visible = isOAuth;
            if (lblO365TenantId != null) lblO365TenantId.Visible = isOAuth;

            // 查找租户提示标签
            ShowTenantHint(isOAuth);
        }

        private void ShowTenantHint(bool show)
        {
            FindControlAndShow(this, "lblTenantHint", show);
            FindControlAndShow(this, "btnO365CloseListener", show);
        }

        private void CloseO365Listener()
        {
            try
            {
                if (_o365Listener != null && _o365Listener.IsListening)
                {
                    _o365Listener.Stop();
                    _o365Listener.Close();
                    _o365Listener = null;
                    lblO365Status.Text = "监听端口已关闭";
                    lblO365Status.ForeColor = Color.Gray;
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Warning(ex, "关闭监听器失败");
            }
        }

        private void FindControlAndShow(Control parent, string name, bool visible)
        {
            foreach (Control ctrl in parent.Controls)
            {
                if (ctrl.Name == name)
                {
                    ctrl.Visible = visible;
                    return;
                }
                if (ctrl.HasChildren)
                {
                    FindControlAndShow(ctrl, name, visible);
                }
            }
        }

        private async void BtnO365OAuthLogin_Click(object sender, EventArgs e)
        {
            try
            {
                // 根据sender的Tag确定是哪个页签
                var btn = sender as Button;
                string panelName = btn?.Tag?.ToString() == "PST" ? "PSTO365Panel" : "EMLO365Panel";
                var panel = this.Controls.Find(panelName, true).FirstOrDefault() as Panel;

                // 查找页签中的控件
                var txtClientId = panel?.Controls.Find("txtO365ClientId", true).FirstOrDefault() as TextBox;
                var txtTenantId = panel?.Controls.Find("txtO365TenantId", true).FirstOrDefault() as TextBox;
                var txtEmail = panel?.Controls.Find("txtO365AdminAccount", true).FirstOrDefault() as TextBox;
                var lblStatus = panel?.Controls.Find("lblO365Status", true).FirstOrDefault() as Label;

                lblStatus.Text = "正在打开浏览器进行 OAuth2 登录...";
                lblStatus.ForeColor = Color.Blue;

                string clientId = txtClientId?.Text?.Trim() ?? "";
                string email = txtEmail?.Text?.Trim() ?? "";

                if (string.IsNullOrEmpty(clientId))
                {
                    MessageBox.Show("请输入 Azure AD 应用的 Client ID", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (string.IsNullOrEmpty(email))
                {
                    MessageBox.Show("请输入目标邮箱地址", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                // Start local HTTP server to receive OAuth callback
                // 先关闭之前的监听器（如果存在）
                CloseO365Listener();

                // 启动新的监听器
                _o365Listener = new System.Net.HttpListener();
                _o365Listener.Prefixes.Add("http://localhost:5555/");
                _o365Listener.Start();

                // Build OAuth URL
                string redirectUri = Uri.EscapeDataString("http://localhost:5555/");
                // 使用 Microsoft Graph 委托权限 (Mail.ReadWrite)
                // 之前用 EWS.AccessAsUser.All 会让 token 的 aud=outlook.office365.com，
                // 调 Graph API 时会报 "Invalid audience"。
                string scope = Uri.EscapeDataString("https://graph.microsoft.com/Mail.ReadWrite");

                // 获取租户 ID，如果为空则使用 common
                string tenantId = txtTenantId?.Text?.Trim();
                string tenant = string.IsNullOrEmpty(tenantId) ? "common" : tenantId;

                string authUrl = $"https://login.microsoftonline.com/{tenant}/oauth2/v2.0/authorize?" +
                    $"client_id={clientId}" +
                    $"&response_type=code" +
                    $"&redirect_uri={redirectUri}" +
                    $"&scope={scope}" +
                    $"&response_mode=query" +
                    $"&login_hint={Uri.EscapeDataString(email)}";

                Serilog.Log.Information("OAuth URL tenant: {Tenant}", tenant);

                // Open browser
                System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
                {
                    FileName = authUrl,
                    UseShellExecute = true
                });

                // Wait for callback
                lblStatus.Text = "请在浏览器中完成登录，然后等待...";

                var context = await _o365Listener.GetContextAsync();
                var request = context.Request;
                var response = context.Response;

                // 调试：记录请求的完整 URL
                string requestUrl = request.Url?.ToString() ?? "null";
                Serilog.Log.Information("OAuth callback URL: {Url}", requestUrl);

                string authCode = request.QueryString["code"];
                string error = request.QueryString["error"];

                // 调试信息
                Serilog.Log.Information("Auth code: {Code}, Error: {Error}", authCode ?? "null", error ?? "null");

                // 返回简单页面告知用户
                string responseHtml;
                if (authCode != null)
                {
                    responseHtml = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"></head><body><h1>Login successful! Please close this window and return to the application.</h1></body></html>";
                }
                else if (!string.IsNullOrEmpty(error))
                {
                    responseHtml = $"<!DOCTYPE html><html><head><meta charset=\"utf-8\"></head><body><h1>Login failed: {error}</h1></body></html>";
                }
                else
                {
                    responseHtml = $"<!DOCTYPE html><html><head><meta charset=\"utf-8\"></head><body><h1>Login failed. Request URL: {requestUrl}</h1></body></html>";
                }

                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(responseHtml);
                response.ContentType = "text/html";
                response.ContentLength64 = buffer.Length;
                response.OutputStream.Write(buffer, 0, buffer.Length);
                response.Close();

                if (!string.IsNullOrEmpty(error))
                {
                    lblStatus.Text = "OAuth2 授权失败: " + error;
                    lblStatus.ForeColor = Color.Red;
                    _o365Listener.Stop();
                    _o365Listener.Close();
                    return;
                }

                if (string.IsNullOrEmpty(authCode))
                {
                    lblStatus.Text = "未获取到授权码";
                    lblStatus.ForeColor = Color.Red;
                    _o365Listener.Stop();
                    _o365Listener.Close();
                    return;
                }

                lblStatus.Text = "正在获取访问令牌...";

                // Exchange code for token
                using (var httpClient = new System.Net.Http.HttpClient())
                {
                    var tokenRequest = new System.Net.Http.FormUrlEncodedContent(new Dictionary<string, string>
                    {
                        {"client_id", clientId},
                        {"code", authCode},
                        {"redirect_uri", "http://localhost:5555/"},
                        {"grant_type", "authorization_code"},
                        {"scope", "https://graph.microsoft.com/Mail.ReadWrite"}
                    });

                    // 使用相同的租户 ID 获取令牌
                    string tId = txtTenantId?.Text?.Trim();
                    string tName = string.IsNullOrEmpty(tId) ? "common" : tId;
                    var tokenResponse = await httpClient.PostAsync($"https://login.microsoftonline.com/{tName}/oauth2/v2.0/token", tokenRequest);
                    var tokenContent = await tokenResponse.Content.ReadAsStringAsync();

                    if (!tokenResponse.IsSuccessStatusCode)
                    {
                        lblStatus.Text = "获取令牌失败: " + tokenContent;
                        lblStatus.ForeColor = Color.Red;
                        _o365Listener.Stop();
                        _o365Listener.Close();
                        return;
                    }

                    // Manually parse JSON to extract access_token
                    string accessToken = null;
                    int startIdx = tokenContent.IndexOf("\"access_token\":\"");
                    if (startIdx >= 0)
                    {
                        startIdx += 16; // length of "access_token":"
                        int endIdx = tokenContent.IndexOf("\"", startIdx);
                        if (endIdx > startIdx)
                        {
                            accessToken = tokenContent.Substring(startIdx, endIdx - startIdx);
                        }
                    }

                    if (!string.IsNullOrEmpty(accessToken))
                    {
                        _office365AccessToken = accessToken;
                        _isO365OAuthConnected = true;
                        _office365OAuthEmail = email;

                        lblStatus.Text = "OAuth2 登录成功! 正在加载文件夹...";
                        lblStatus.ForeColor = Color.Green;

                        // 加载文件夹列表
                        LoadO365Folders(email, accessToken);

                        btn.Text = "已连接";
                        btn.Enabled = false;
                    }
                    else
                    {
                        lblStatus.Text = "令牌响应格式错误: " + tokenContent;
                        lblStatus.ForeColor = Color.Red;
                    }
                }

                _o365Listener.Stop();
                _o365Listener.Close();
            }
            catch (Exception ex)
            {
                var lblStatus = this.Controls.Find("lblO365Status", true).FirstOrDefault() as Label;
                lblStatus.Text = "OAuth2 登录失败: " + ex.Message;
                lblStatus.ForeColor = Color.Red;
                Serilog.Log.Error(ex, "OAuth2 login failed");
            }
        }

        /// <summary>
        /// 将权限ID转换为可读的权限名称
        /// </summary>
        private List<string> GetConfiguredPermissionNames(HashSet<string> permissionIds)
        {
            var names = new List<string>();
            // Microsoft Graph 应用程序权限ID到名称的映射
            var permissionMap = new Dictionary<string, string>
            {
                { "df021288-bdef-4463-88db-98f22de89214", "User.Read.All" },
                { "45b7d09e-4c90-4c85-a0c5-8f0b4894f5bd", "User.ReadBasic.All" },
                { "1190152b-106b-462e-8f13-4a7f5d2bb0a0", "User.ReadWrite.All" },
                { "a82b7c70-6505-4f60-a2b9-6f0d2a3f82db", "Directory.Read.All" },
                { "ec15cda2-0cbe-4050-a6b6-f47dd8bd3d7e", "Directory.ReadWrite.All" },
                { "741c2c88-e08e-4986-b2da-2e2c6c9b4c22", "Mail.Read" },
                { "b52a9531-4d29-4146-9f98-d2a4c3d9a1d4", "Mail.ReadWrite" },
                { "a4b6b51b-347a-4658-8e91-c1f85dfcfe06", "Mail.Send" },
                { "2b351c46-62b6-4913-9d7e-8fee39d4bb62", "Calendars.Read" },
                { "4e9dd4cc-fd7e-47d6-8a8f-5a7b82c5c97c", "Contacts.Read" },
                { "aa4ab2db-0532-4b8f-b2b7-a9d5cd3a7b25", "Group.Read.All" },
                { "a2f83395-4a79-4096-ba89-2901b89e2b23", "Group.ReadWrite.All" }
            };

            foreach (var id in permissionIds)
            {
                if (permissionMap.ContainsKey(id))
                {
                    names.Add(permissionMap[id]);
                }
                else
                {
                    names.Add($"ID:{id.Substring(0, 8)}");
                }
            }
            return names;
        }

