                Location = new Point(190, 175),
                Size = new Size(90, 30),
                Text = "刷新权限",
                Name = "btnRefreshPermissions"
            };

            // 登录状态显示（移到刷新权限右边）
            var lblLoginStatus = new Label { Text = "未登录", Location = new Point(290, 180), AutoSize = true, ForeColor = Color.Gray, Name = "lblLoginStatus" };

            // 配置路径说明（移到右上角）
            var lblPermissionNote = new Label
            {
                Text = "配置路径：Azure AD → 应用注册 → 你的应用 → API权限",
                Location = new Point(450, 15),
                Size = new Size(250, 25),
                ForeColor = Color.Gray,
                Font = new Font("Microsoft Sans Serif", 10F)
            };

            // 权限状态显示（给更多空间）
            var lblPermissionStatus = new Label
            {
                Text = "点击'刷新权限'查看API权限配置",
                Location = new Point(20, 340),
                Size = new Size(550, 40),
                ForeColor = Color.Gray,
                Name = "lblPermissionStatus"
            };

            // API权限配置标题
            var lblRequiredTitle = new Label
            {
                Text = "API权限配置:",
                Location = new Point(20, 205),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold),
                ForeColor = Color.Black
            };

            // 预设权限列表
            var requiredPermissions = new List<(string Id, string Name)>
            {
                ("df021288-bdef-4463-88db-98f22de89214", "User.Read.All"),
                ("45b7d09e-4c90-4c85-a0c5-8f0b4894f5bd", "User.ReadBasic.All"),
                ("1190152b-106b-462e-8f13-4a7f5d2bb0a0", "User.ReadWrite.All"),
                ("a82b7c70-6505-4f60-a2b9-6f0d2a3f82db", "Directory.Read.All"),
                ("ec15cda2-0cbe-4050-a6b6-f47dd8bd3d7e", "Directory.ReadWrite.All"),
                ("741c2c88-e08e-4986-b2da-2e2c6c9b4c22", "Mail.Read"),
                ("b52a9531-4d29-4146-9f98-d2a4c3d9a1d4", "Mail.ReadWrite"),
                ("a4b6b51b-347a-4658-8e91-c1f85dfcfe06", "Mail.Send"),
                ("2b351c46-62b6-4913-9d7e-8fee39d4bb62", "Calendars.Read"),
                ("4e9dd4cc-fd7e-47d6-8a8f-5a7b82c5c97c", "Contacts.Read"),
                ("aa4ab2db-0532-4b8f-b2b7-a9d5cd3a7b25", "Group.Read.All"),
                ("a2f83395-4a79-4096-ba89-2901b89e2b23", "Group.ReadWrite.All")
