            int labelWidth = 180;
            int rowSpacing = 25;
            int startY = 240;  // API权限配置标题下20px
            for (int i = 0; i < requiredPermissions.Count; i++)
            {
                var row = i / permPerRow;
                var col = i % permPerRow;
