            // 刷新权限的逻辑
            void RefreshPermissions()
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblPermissionStatus.Text = "请先登录";
                    lblPermissionStatus.ForeColor = Color.Red;
                    return;
                }

                lblPermissionStatus.Text = "正在获取权限信息...";
                lblPermissionStatus.ForeColor = Color.Blue;

                Task.Run(() =>
                {
                    try
                    {
                        // 获取 Graph API 访问令牌
                        var accessToken = _exchangeOnlineService.GraphAccessToken;
                        if (string.IsNullOrEmpty(accessToken))
                        {
                            accessToken = _exchangeOnlineService.AccessToken;
                        }

                        Serilog.Log.Information("刷新权限: accessToken={Token}", accessToken?.Substring(0, 20) + "...");

                        if (!string.IsNullOrEmpty(accessToken))
                        {
                            // 方法1: 解析JWT Token中的权限
                            var tokenPermissions = new List<string>();
                            var appRolesList = new List<string>();
                            var scopesList = new List<string>();

                            try
                            {
                                var handler = new System.IdentityModel.Tokens.Jwt.JwtSecurityTokenHandler();
                                var jwtToken = handler.ReadJwtToken(accessToken);

                                // 应用程序权限在 "roles" claim 中
                                appRolesList = jwtToken.Claims
                                    .Where(c => c.Type == "roles")
                                    .Select(c => c.Value).ToList();

                                // 委托权限在 "scp" (scope) claim 中
                                scopesList = jwtToken.Claims
                                    .Where(c => c.Type == "scp")
                                    .SelectMany(c => c.Value.Split(' ')).ToList();

                                tokenPermissions.AddRange(appRolesList);
                                tokenPermissions.AddRange(scopesList);

                                // 记录Token中的权限到登录日志（记录即可，UI显示用tokenPermissions）
                                Program.LoginLogger.Information("Token权限 - 应用程序权限(Roles): {Roles}", string.Join(", ", appRolesList));
                                Program.LoginLogger.Information("Token权限 - 委托权限(Scopes): {Scopes}", string.Join(", ", scopesList));

                                Serilog.Log.Information("JWT解析 - 应用程序权限: {Roles}", string.Join(", ", appRolesList));
                                Serilog.Log.Information("JWT解析 - 委托权限: {Scopes}", string.Join(", ", scopesList));
                            }
                            catch (Exception ex)
                            {
                                // JWT解析失败，记录详细信息
                                Serilog.Log.Error(ex, "JWT解析失败，Token可能无效");
                                Program.LoginLogger.Error(ex, "JWT解析失败");

                                // 尝试打印Token前50字符用于调试
                                Serilog.Log.Warning("Token前缀: {Prefix}", accessToken.Substring(0, Math.Min(50, accessToken.Length)));
                            }

                            // 方法2: 获取应用配置的权限
                            var clientId = txtClientId.Text;
                            Serilog.Log.Information("查询应用: clientId={ClientId}", clientId);

                            using (var httpClient = new System.Net.Http.HttpClient())
                            {
                                httpClient.DefaultRequestHeaders.Authorization =
                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                // 通过 appId 查询应用程序
                                var appResponse = httpClient.GetAsync(
                                    $"https://graph.microsoft.com/v1.0/applications(appId='{clientId}')?$select=id,displayName,requiredResourceAccess").Result;

                                Serilog.Log.Information("应用查询结果: StatusCode={StatusCode}", appResponse.StatusCode);

                                if (appResponse.IsSuccessStatusCode)
                                {
                                    var appJson = appResponse.Content.ReadAsStringAsync().Result;
                                    Serilog.Log.Information("应用信息: {Json}", appJson.Substring(0, Math.Min(500, appJson.Length)));
                                    var appDoc = System.Text.Json.JsonDocument.Parse(appJson);

                                    if (appDoc.RootElement.TryGetProperty("id", out _))
                                    {
                                        var appDisplayName = appDoc.RootElement.TryGetProperty("displayName", out var nameProp) ? nameProp.GetString() : "未知";
                                        var requiredResources = appDoc.RootElement.GetProperty("requiredResourceAccess");

                                        // 收集所有配置的权限名称（使用ID转名称映射）
                                        var configuredPermissions = new HashSet<string>();
                                        var permissionIdToName = new Dictionary<string, string>
                                        {
                                            { "df021288-bdef-4463-88db-98f22de89214", "User.Read.All" },
                                            { "45b7d09e-4c90-4c85-a0c5-8f0b4894f5bd", "User.ReadBasic.All" },
                                            { "1190152b-106b-462e-8f13-4a7f5d2bb0a0", "User.ReadWrite.All" },
                                            { "a82b7c70-6505-4f60-a2b9-6f0d2a3f82db", "Directory.Read.All" },
                                            { "ec15cda2-0cbe-4050-a6b6-f47dd8bd3d7e", "Directory.ReadWrite.All" },
                                            { "741c2c88-e08e-4986-b2da-2e2c6c9b4c22", "Mail.Read" },
                                            { "b52a9531-4d29-4146-9f98-d2a4c3d9a1d4", "Mail.ReadWrite" },
                                            { "a4b6b51b-347a-4658-8e91-c1f85dfcfe06", "Mail.Send" },
                                            { "2b351c46-62b6-4913-9d7e-8fee39d4bb62", "Calendars.Read" },
                                            { "4e9dd4cc-fd7e-47d6-8a8f-5a7b82c5c97c", "Contacts.Read" },
                                            { "aa4ab2db-0532-4b8f-b2b7-a9d5cd3a7b25", "Group.Read.All" },
                                            { "a2f83395-4a79-4096-ba89-2901b89e2b23", "Group.ReadWrite.All" }
                                        };
                                        foreach (var resource in requiredResources.EnumerateArray())
                                        {
                                            var resourceAppId = resource.GetProperty("resourceAppId").GetString();
                                            if (resourceAppId == "00000003-0000-0000-c000-000000000000")
                                            {
                                                var roles = resource.GetProperty("resourceAccess");
                                                foreach (var role in roles.EnumerateArray())
                                                {
                                                    var roleType = role.GetProperty("type").GetString();
                                                    if (roleType == "role")
                                                    {
                                                        var roleId = role.GetProperty("id").GetString();
                                                        // 转换为名称
                                                        if (permissionIdToName.ContainsKey(roleId))
                                                        {
                                                            configuredPermissions.Add(permissionIdToName[roleId]);
                                                        }
                                                    }
                                                }
                                            }
                                        }

                                        this.Invoke(new Action(() =>
                                        {
                                            // 构建权限状态文本
                                            var statusText = $"应用 '{appDisplayName}' 已配置的API权限:\n";
                                            statusText += $"  • 已配置 {configuredPermissions.Count} 个权限\n";

                                            // 显示实际权限名称（从Token权限中匹配）
                                            var matchedPerms = new List<string>();
                                            foreach (var permName in requiredPermissions.Select(p => p.Name))
                                            {
                                                if (tokenPermissions.Contains(permName))
                                                {
                                                    matchedPerms.Add(permName);
                                                }
                                            }

                                            if (matchedPerms.Count > 0)
                                            {
                                                statusText += $"  (已配置: {string.Join(", ", matchedPerms.Take(3))}";
                                                if (matchedPerms.Count > 3) statusText += "...";
                                                statusText += ")";
                                            }

                                            lblPermissionStatus.Text = statusText;
                                            lblPermissionStatus.ForeColor = matchedPerms.Count > 0 ? Color.Green : Color.Orange;

                                            // 更新横向权限标签的颜色（按Token权限匹配）
                                            foreach (var lbl in permLabels)
                                            {
                                                var permName = lbl.Name.Replace("lblPerm_", "");
                                                var isConfigured = tokenPermissions.Contains(permName);
                                                lbl.Text = isConfigured ? "● " + permName : "○ " + permName;
                                                lbl.ForeColor = isConfigured ? Color.Green : Color.Red;
                                            }
                                        }));
                                    }
                                    else
                                    {
                                        this.Invoke(new Action(() =>
                                        {
                                            lblPermissionStatus.Text = "未找到应用程序信息";
                                            lblPermissionStatus.ForeColor = Color.Orange;
                                        }));
                                    }
                                }
                                else
                                {
                                    var errorContent = appResponse.Content.ReadAsStringAsync().Result;
                                    this.Invoke(new Action(() =>
                                    {
                                        lblPermissionStatus.Text = $"获取权限失败: {appResponse.StatusCode}";
                                        lblPermissionStatus.ForeColor = Color.Red;
                                    }));
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblPermissionStatus.Text = $"获取权限失败: {ex.Message}";
                            lblPermissionStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            }

            btnRefreshPermissions.Click += (s, e) => RefreshPermissions();

            // 登录成功后自动刷新权限
            btnLogin.Click += (s, e) =>
            {
                if (cmbPstAccounts.SelectedItem == null || string.IsNullOrWhiteSpace(txtTenantId.Text) ||
                    string.IsNullOrWhiteSpace(txtClientId.Text) || string.IsNullOrWhiteSpace(txtClientSecret.Text))
                {
                    lblLoginStatus.Text = "请选择账户并填写完整信息";
                    lblLoginStatus.ForeColor = Color.Red;
                    return;
                }

                try
                {
                    var accountName = cmbPstAccounts.SelectedItem.ToString();
                    _exchangeOnlineService = new Office365ImportService();

                    if (_exchangeOnlineService.ConnectWithClientSecret(txtTenantId.Text, txtClientId.Text, txtClientSecret.Text, accountName))
                    {
                        _isExchangeOnlineLoggedIn = true;
                        _exchangeOnlineCurrentAccount = accountName;
                        lblLoginStatus.Text = $"已登录: {accountName}";
                        lblLoginStatus.ForeColor = Color.Green;

                        // 记录登录成功日志
                        Program.LoginLogger.Information("登录成功: Account={Account}, TenantId={TenantId}", accountName, txtTenantId.Text);

                        // 登录成功后自动刷新权限
                        RefreshPermissions();
                    }
                    else
                    {
                        lblLoginStatus.Text = "登录失败";
                        lblLoginStatus.ForeColor = Color.Red;

                        // 记录登录失败日志
                        Program.LoginLogger.Warning("登录失败: Account={Account}, TenantId={TenantId}", accountName, txtTenantId.Text);
                    }
                }
                catch (Exception ex)
                {
                    lblLoginStatus.Text = $"登录失败: {ex.Message}";
                    lblLoginStatus.ForeColor = Color.Red;

                    // 记录登录异常日志
                    var currentAccount = cmbPstAccounts.SelectedItem?.ToString() ?? "未知";
                    Program.LoginLogger.Error(ex, "登录异常: Account={Account}", currentAccount);
                }
            };
            void LoadPstAccountFields(string name)
            {
                var account = savedSettings.PstAccounts.Find(a => a.Name == name);
                if (account != null)
                {
                    txtTenantId.Text = account.TenantId;
                    txtClientId.Text = account.ClientId;
                    txtClientSecret.Text = account.ClientSecret;
                }
            }

            // 加载第一个账户的设置
            if (savedSettings.PstAccounts.Count > 0)
            {
                LoadPstAccountFields(savedSettings.PstAccounts[0].Name);
            }

            cmbPstAccounts.SelectedIndexChanged += (s, e) =>
            {
                if (cmbPstAccounts.SelectedItem != null)
                {
                    LoadPstAccountFields(cmbPstAccounts.SelectedItem.ToString());
                }
            };

            // 登录按钮点击事件
            btnLogin.Click += (s, e) =>
            {
                if (cmbPstAccounts.SelectedItem == null || string.IsNullOrWhiteSpace(txtTenantId.Text) ||
                    string.IsNullOrWhiteSpace(txtClientId.Text) || string.IsNullOrWhiteSpace(txtClientSecret.Text))
                {
                    lblLoginStatus.Text = "请选择账户并填写完整信息";
                    lblLoginStatus.ForeColor = Color.Red;
                    return;
                }

                try
                {
                    var accountName = cmbPstAccounts.SelectedItem.ToString();
                    _exchangeOnlineService = new Office365ImportService();

                    if (_exchangeOnlineService.ConnectWithClientSecret(txtTenantId.Text, txtClientId.Text, txtClientSecret.Text, accountName))
                    {
                        _isExchangeOnlineLoggedIn = true;
                        _exchangeOnlineCurrentAccount = accountName;
                        lblLoginStatus.Text = $"已登录: {accountName}";
                        lblLoginStatus.ForeColor = Color.Green;

                        // 登录成功后获取应用的API权限并显示
                        Task.Run(() =>
                        {
                            try
                            {
                                // 获取访问令牌
                                var accessToken = _exchangeOnlineService.GraphAccessToken;
                                if (string.IsNullOrEmpty(accessToken))
                                {
                                    accessToken = _exchangeOnlineService.AccessToken;
                                }

                                if (!string.IsNullOrEmpty(accessToken))
                                {
                                    using (var httpClient = new System.Net.Http.HttpClient())
                                    {
                                        httpClient.DefaultRequestHeaders.Authorization =
                                            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                        // 获取应用信息
                                        var appResponse = httpClient.GetAsync(
                                            $"https://graph.microsoft.com/v1.0/applications?$filter=displayName eq '{accountName}'&$select=id,displayName,requiredResourceAccess").Result;

                                        if (appResponse.IsSuccessStatusCode)
                                        {
                                            var appJson = appResponse.Content.ReadAsStringAsync().Result;
                                            var appDoc = System.Text.Json.JsonDocument.Parse(appJson);
                                            var apps = appDoc.RootElement.GetProperty("value");

                                            if (apps.GetArrayLength() > 0)
                                            {
                                                var app = apps[0];
                                                var appId = app.GetProperty("id").GetString();
                                                var appDisplayName = app.GetProperty("displayName").GetString();

                                                // 获取所需的权限列表
                                                var requiredResources = app.GetProperty("requiredResourceAccess");
                                                var permissionsInfo = new List<string>();

                                                foreach (var resource in requiredResources.EnumerateArray())
                                                {
                                                    var resourceAppId = resource.GetProperty("resourceAppId").GetString();

                                                    // Microsoft Graph 的 appId 是 00000003-0000-0000-c000-000000000000
                                                    if (resourceAppId == "00000003-0000-0000-c000-000000000000")
                                                    {
                                                        var roles = resource.GetProperty("resourceAccess");
                                                        foreach (var role in roles.EnumerateArray())
                                                        {
                                                            var roleId = role.GetProperty("id").GetString();
                                                            var roleType = role.GetProperty("type").GetString();

                                                            if (roleType == "role")
                                                            {
                                                                // 查询具体权限名称
                                                                permissionsInfo.Add(roleId);
                                                            }
                                                        }
                                                    }
                                                }

                                                // 显示权限信息
                                                this.Invoke(new Action(() =>
                                                {
                                                    lblPermissionStatus.Text = "✓ 已配置所需权限";
                                                    lblPermissionStatus.ForeColor = Color.Green;
                                                }));
                                            }
                                        }
                                    }
                                }
                            }
                            catch
                            {
                                // 忽略权限查询错误
                            }
                        });
                    }
                    else
                    {
                        lblLoginStatus.Text = "登录失败";
                        lblLoginStatus.ForeColor = Color.Red;
                    }
                }
                catch (Exception ex)
                {
                    lblLoginStatus.Text = $"登录失败: {ex.Message}";
                    lblLoginStatus.ForeColor = Color.Red;
                }
            };

            // 说明文字
            var lblNote = new Label
            {
                Text = "说明：登录后可使用账户管理、组管理、邮件路由管理等功能。\n切换到其他主Tab会断开连接，需要重新登录。",
                Location = new Point(20, 170),
                Size = new Size(500, 40),
                ForeColor = Color.Gray
            };

            // 权限状态显示
            var lblPermissionTitle = new Label
            {
                Text = "API 权限配置:",
                Location = new Point(20, 220),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold),
                ForeColor = Color.Black
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblPstAccount);
            panel.Controls.Add(cmbPstAccounts);
            panel.Controls.Add(lblTenantId);
            panel.Controls.Add(txtTenantId);
            panel.Controls.Add(lblClientId);
            panel.Controls.Add(txtClientId);
            panel.Controls.Add(lblClientSecret);
            panel.Controls.Add(txtClientSecret);
            panel.Controls.Add(lblLoginStatus);
            panel.Controls.Add(btnLogin);
            panel.Controls.Add(btnRefreshPermissions);
            panel.Controls.Add(lblRequiredTitle);
            panel.Controls.Add(lblPermissionStatus);
            panel.Controls.Add(lblPermissionNote);
            foreach (var lbl in permLabels)
            {
                panel.Controls.Add(lbl);
            }

            return panel;
        }

