            var btnEnableUser = new Button
            {
                Location = new Point(440, 280),
                Size = new Size(100, 30),
                Text = "启用账户",
                BackColor = Color.Green,
                ForeColor = Color.White,
                Name = "btnEnableUser"
            };

            var btnDisableUser = new Button
            {
                Location = new Point(550, 280),
                Size = new Size(100, 30),
                Text = "禁用账户",
                BackColor = Color.Red,
                ForeColor = Color.White,
                Name = "btnDisableUser"
            };

            var btnViewApps = new Button
            {
                Location = new Point(440, 320),
                Size = new Size(100, 30),
                Text = "查看应用",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnViewApps"
            };

            // 状态显示
            var lblStatus = new Label
            {
                Location = new Point(440, 330),
                Size = new Size(250, 30),
                ForeColor = Color.Gray,
                Name = "lblUserStatus"
            };

            // 为加载用户按钮添加事件
            btnLoadUsers.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在账户管理登录";
                    lblStatus.ForeColor = Color.Red;
                    Program.AccountManagementLogger.Warning("加载用户列表失败: 未登录");
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                lblStatus.Text = "正在加载用户列表...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel("正在加载用户列表...");
                Program.AccountManagementLogger.Information("开始加载用户列表");

                Task.Run(() =>
                {
                    try
                    {
                        LogToPanel("调用Graph API获取用户列表...");
                        Program.AccountManagementLogger.Information("调用Graph API获取用户列表");

                        var users = _exchangeOnlineService.GraphClient.Users
                            .GetAsync(requestConfiguration =>
                            {
                                requestConfiguration.QueryParameters.Filter = "userType eq 'Member'";
                                requestConfiguration.QueryParameters.Select = new[] { "displayName", "mail", "userPrincipalName", "accountEnabled", "assignedLicenses" };
                                requestConfiguration.QueryParameters.Top = 500;
                            });

                        var usersResult = users.Result;

                        this.Invoke(new Action(() =>
                        {
                            gridAccounts.Rows.Clear();
                            if (usersResult?.Value != null)
                            {
                                foreach (var user in usersResult.Value)
                                {
                                    var displayName = user.DisplayName ?? user.Mail ?? user.UserPrincipalName;
                                    var email = user.Mail ?? user.UserPrincipalName;
                                    var status = (user.AccountEnabled == true) ? "已启用" : "已禁用";
                                    var license = user.AssignedLicenses != null && user.AssignedLicenses.Any()
                                        ? $"{user.AssignedLicenses.Count}个授权"
                                        : "未授权";
                                    gridAccounts.Rows.Add(displayName, email, status, license);
                                }
                                lblStatus.Text = $"共加载 {usersResult.Value.Count} 个用户";
                                LogToPanel($"加载完成，共 {usersResult.Value.Count} 个用户");
                            }
                            else
                            {
                                lblStatus.Text = "未找到用户";
                                LogToPanel("未找到用户");
                            }
                            lblStatus.ForeColor = Color.Green;
                        }));
                    }
                    catch (Exception ex)
                    {
                        var errorMsg = ex.Message;
                        Serilog.Log.Error(ex, "加载用户列表失败");
                        Program.AccountManagementLogger.Error(ex, "加载用户列表失败");
                        LogToPanel($"错误: {errorMsg}");
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {errorMsg}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            // 加载应用按钮
            btnLoadApps.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在账户管理登录";
                    lblStatus.ForeColor = Color.Red;
                    Program.AccountManagementLogger.Warning("加载应用列表失败: 未登录");
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                lblStatus.Text = "正在加载应用列表...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel("正在加载应用列表...");
                Program.AccountManagementLogger.Information("开始加载应用列表");

                Task.Run(() =>
                {
                    try
                    {
                        LogToPanel("调用Graph API获取应用列表...");
                        Program.AccountManagementLogger.Information("调用Graph API获取应用列表");

                        var apps = _exchangeOnlineService.GraphClient.Applications
                            .GetAsync(requestConfiguration =>
                            {
                                requestConfiguration.QueryParameters.Select = new[] { "displayName", "appId", "publisherDomain", "createdDateTime" };
                                requestConfiguration.QueryParameters.Top = 500;
                            });

                        var appsResult = apps.Result;

                        this.Invoke(new Action(() =>
                        {
                            gridAccounts.Rows.Clear();
                            if (appsResult?.Value != null)
                            {
                                foreach (var app in appsResult.Value)
                                {
                                    var displayName = app.DisplayName ?? "未命名";
                                    var appId = app.AppId?.ToString() ?? "";
                                    var publisher = app.PublisherDomain ?? "未知";
                                    gridAccounts.Rows.Add(displayName, appId, "应用", publisher, "");
                                }
                                lblStatus.Text = $"共加载 {appsResult.Value.Count} 个应用";
                                LogToPanel($"加载完成，共 {appsResult.Value.Count} 个应用");
                            }
                            else
                            {
                                lblStatus.Text = "未找到应用";
                                LogToPanel("未找到应用");
                            }
                            lblStatus.ForeColor = Color.Green;
                        }));
                    }
                    catch (Exception ex)
                    {
                        var errorMsg = ex.Message;
                        Serilog.Log.Error(ex, "加载应用列表失败");
                        Program.AccountManagementLogger.Error(ex, "加载应用列表失败");
                        LogToPanel($"错误: {errorMsg}");
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {errorMsg}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            // 选中用户时显示详情
            gridAccounts.SelectionChanged += (s, e) =>
            {
                if (gridAccounts.SelectedRows.Count > 0)
                {
                    var row = gridAccounts.SelectedRows[0];
                    txtDetailName.Text = row.Cells["DisplayName"].Value?.ToString() ?? "";
                    txtDetailEmail.Text = row.Cells["Email"].Value?.ToString() ?? "";
                    txtDetailStatus.Text = row.Cells["Status"].Value?.ToString() ?? "";
                    txtDetailLicense.Text = "待查询";
                    lblStatus.Text = "";
                }
            };

            // 重置密码按钮
            btnResetPassword.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailEmail.Text))
                {
                    lblStatus.Text = "请先选择用户";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                // 弹出密码输入对话框
                var form = new Form
                {
                    Width = 400,
                    Height = 200,
                    FormBorderStyle = FormBorderStyle.FixedDialog,
                    Text = "重置密码 - " + txtDetailEmail.Text,
                    StartPosition = FormStartPosition.CenterParent,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var lblNewPwd = new Label { Text = "新密码:", Left = 20, Top = 20, Width = 60 };
                var txtNewPwd = new TextBox { Left = 90, Top = 18, Width = 250, UseSystemPasswordChar = true };
                var lblConfirmPwd = new Label { Text = "确认密码:", Left = 20, Top = 55, Width = 60 };
                var txtConfirmPwd = new TextBox { Left = 90, Top = 53, Width = 250, UseSystemPasswordChar = true };
                var btnOK = new Button { Text = "确定", Left = 200, Width = 80, Top = 100, DialogResult = DialogResult.OK };
                var btnCancel = new Button { Text = "取消", Left = 290, Width = 80, Top = 100, DialogResult = DialogResult.Cancel };

                form.Controls.AddRange(new Control[] { lblNewPwd, txtNewPwd, lblConfirmPwd, txtConfirmPwd, btnOK, btnCancel });
                form.AcceptButton = btnOK;
                form.CancelButton = btnCancel;

                if (form.ShowDialog() != DialogResult.OK)
                    return;

                var newPassword = txtNewPwd.Text;
                var confirmPassword = txtConfirmPwd.Text;

                if (string.IsNullOrWhiteSpace(newPassword))
                {
                    MessageBox.Show("请输入新密码", "错误", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (newPassword != confirmPassword)
                {
                    MessageBox.Show("两次输入的密码不一致", "错误", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                var userEmail = txtDetailEmail.Text;
                lblStatus.Text = "正在重置密码...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel($"正在重置用户 {userEmail} 的密码...");

                Task.Run(() =>
                {
                    try
                    {
                        // 使用Graph API重置密码
                        var userUpdate = new Microsoft.Graph.Models.User
                        {
                            PasswordProfile = new Microsoft.Graph.Models.PasswordProfile
                            {
                                Password = newPassword,
                                ForceChangePasswordNextSignIn = true
                            }
                        };

                        _exchangeOnlineService.GraphClient.Users[userEmail]
                            .PatchAsync(userUpdate)
                            .Wait();

                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = "密码已重置";
                            lblStatus.ForeColor = Color.Green;
                            LogToPanel($"密码已重置! 新密码: {newPassword}");
                            MessageBox.Show($"密码已重置!\n新密码: {newPassword}\n请妥善保管", "重置密码", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"重置失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                            LogToPanel($"错误: {ex.Message}");
                        }));
                    }
                });
            };

            // 分配授权按钮
            btnAssignLicense.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailEmail.Text))
                {
                    lblStatus.Text = "请先选择用户";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                var userEmail = txtDetailEmail.Text;
                lblStatus.Text = "正在获取授权信息...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel($"正在获取 {userEmail} 的授权信息...");

                Task.Run(() =>
                {
                    try
                    {
                        // 获取当前用户的授权信息
                        var user = _exchangeOnlineService.GraphClient.Users[userEmail]
                            .GetAsync(requestConfiguration => requestConfiguration.QueryParameters.Select = new[] { "assignedLicenses", "licenseAssignmentStates" })
                            .Result;

                        // 获取可用的授权列表
                        var subs = _exchangeOnlineService.GraphClient.SubscribedSkus.GetAsync().Result;

                        var availableLicenses = new List<(Guid? SkuId, string SkuPartNumber, int Total, int Used)>();
                        if (subs?.Value != null)
                        {
                            foreach (var sub in subs.Value)
                            {
                                var total = sub.PrepaidUnits?.Enabled ?? 0;
                                var used = sub.ConsumedUnits ?? 0;
                                availableLicenses.Add((sub.SkuId, sub.SkuPartNumber, total, used));
                            }
                        }

                        // 当前用户已分配的授权
                        var userLicenseIds = user.AssignedLicenses?.Select(l => l.SkuId).ToHashSet() ?? new HashSet<Guid?>();

                        this.Invoke(new Action(() =>
                        {
                            // 创建分配授权弹窗
                            var licenseForm = new Form
                            {
                                Width = 500,
                                Height = 450,
                                Text = $"分配授权 - {userEmail}",
                                StartPosition = FormStartPosition.CenterParent,
                                MaximizeBox = false,
                                MinimizeBox = false
                            };

                            var lblLicenseTitle = new Label
                            {
                                Text = "授权管理:",
                                Location = new Point(20, 15),
                                AutoSize = true,
                                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
                            };

                            var tabControl = new TabControl
                            {
                                Location = new Point(20, 40),
                                Size = new Size(440, 280)
                            };

                            // 分配授权页签
                            var tabAssign = new TabPage("分配授权");
                            var gridAssign = new DataGridView
                            {
                                Dock = DockStyle.Fill,
                                AllowUserToAddRows = false,
                                AllowUserToDeleteRows = false,
                                ReadOnly = false,
                                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                                MultiSelect = true,
                                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                                RowHeadersVisible = false,
                                BackgroundColor = Color.White,
                                BorderStyle = BorderStyle.FixedSingle
                            };
                            gridAssign.Columns.Add(new DataGridViewCheckBoxColumn { Name = "选择", Width = 40 });
                            gridAssign.Columns.Add(new DataGridViewTextBoxColumn { Name = "授权名称", Width = 220, ReadOnly = true });
                            gridAssign.Columns.Add(new DataGridViewTextBoxColumn { Name = "已分配/总量", Width = 100, ReadOnly = true });

                            // 解除授权页签
                            var tabRemove = new TabPage("解除授权");
                            var gridRemove = new DataGridView
                            {
                                Dock = DockStyle.Fill,
                                AllowUserToAddRows = false,
                                AllowUserToDeleteRows = false,
                                ReadOnly = false,
                                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                                MultiSelect = true,
                                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                                RowHeadersVisible = false,
                                BackgroundColor = Color.White,
                                BorderStyle = BorderStyle.FixedSingle
                            };
                            gridRemove.Columns.Add(new DataGridViewCheckBoxColumn { Name = "选择", Width = 40 });
                            gridRemove.Columns.Add(new DataGridViewTextBoxColumn { Name = "授权名称", Width = 220, ReadOnly = true });
                            gridRemove.Columns.Add(new DataGridViewTextBoxColumn { Name = "已分配/总量", Width = 100, ReadOnly = true });

                            // 填充分配授权列表（未分配的）
                            var unassignedLicenses = new List<(Guid? SkuId, string SkuPartNumber, int Total, int Used)>();
                            foreach (var lic in availableLicenses)
                            {
                                var isAssigned = userLicenseIds.Contains(lic.SkuId);
                                if (!isAssigned)
                                {
                                    unassignedLicenses.Add(lic);
                                    gridAssign.Rows.Add(false, lic.SkuPartNumber, $"{lic.Used}/{lic.Total}");
                                }
                            }

                            // 填充解除授权列表（已分配的）
                            var assignedLicenses = new List<(Guid? SkuId, string SkuPartNumber, int Total, int Used)>();
                            foreach (var lic in availableLicenses)
                            {
                                var isAssigned = userLicenseIds.Contains(lic.SkuId);
                                if (isAssigned)
                                {
                                    assignedLicenses.Add(lic);
                                    gridRemove.Rows.Add(false, lic.SkuPartNumber, $"{lic.Used}/{lic.Total}");
                                }
                            }

                            tabAssign.Controls.Add(gridAssign);
                            tabRemove.Controls.Add(gridRemove);
                            tabControl.Controls.Add(tabAssign);
                            tabControl.Controls.Add(tabRemove);

                            var lblInfo = new Label
                            {
                                Text = $"当前用户已有授权: {assignedLicenses.Count}，可分配授权: {unassignedLicenses.Count}",
                                Location = new Point(20, 330),
                                AutoSize = true,
                                ForeColor = Color.Gray
                            };

                            var btnAssign = new Button
                            {
                                Text = "分配选中",
                                Location = new Point(280, 350),
                                Size = new Size(80, 30),
                                BackColor = Color.FromArgb(0, 120, 215),
                                ForeColor = Color.White
                            };

                            var btnRemove = new Button
                            {
                                Text = "解除选中",
                                Location = new Point(370, 350),
                                Size = new Size(80, 30),
                                BackColor = Color.FromArgb(220, 53, 69),
                                ForeColor = Color.White
                            };

                            var btnClose = new Button
                            {
                                Text = "关闭",
                                Location = new Point(150, 350),
                                Size = new Size(60, 30)
                            };

                            // 分配授权按钮事件
                            btnAssign.Click += (sender, args) =>
                            {
                                var selectedSkus = new List<Guid?>();
                                for (int i = 0; i < gridAssign.Rows.Count; i++)
                                {
                                    if (Convert.ToBoolean(gridAssign.Rows[i].Cells["选择"].Value))
                                    {
                                        selectedSkus.Add(unassignedLicenses[i].SkuId);
                                    }
                                }

                                if (selectedSkus.Count == 0)
                                {
                                    MessageBox.Show("请至少选择一个授权", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                                    return;
                                }

                                var confirmMsg = $"确定要分配以下授权吗？\n{string.Join(", ", unassignedLicenses.Where((l, i) => selectedSkus.Contains(l.SkuId)).Select(l => l.SkuPartNumber))}";
                                if (MessageBox.Show(confirmMsg, "确认", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
                                {
                                    return;
                                }

                                LogToPanel($"正在为用户 {userEmail} 分配 {selectedSkus.Count} 个授权...");

                                Task.Run(() =>
                                {
                                    try
                                    {
                                        var accessToken = _exchangeOnlineService.GraphAccessToken;
                                        if (string.IsNullOrEmpty(accessToken))
                                        {
                                            throw new Exception("无法获取 Graph API 访问令牌");
                                        }

                                        using (var httpClient = new System.Net.Http.HttpClient())
                                        {
                                            httpClient.DefaultRequestHeaders.Authorization =
                                                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                            var requestBody = new Dictionary<string, object>
                                            {
                                                ["addLicenses"] = selectedSkus
                                                    .Where(x => x.HasValue)
                                                    .Select(x => new Dictionary<string, object>
                                                    {
                                                        ["disabledPlans"] = new List<string>(),
                                                        ["skuId"] = x.Value.ToString()
                                                    })
                                                    .ToList(),
                                                ["removeLicenses"] = new List<string>()
                                            };

                                            var jsonContent = System.Text.Json.JsonSerializer.Serialize(requestBody);
                                            var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                            var response = httpClient.PostAsync(
                                                $"https://graph.microsoft.com/v1.0/users/{userEmail}/assignLicense",
                                                httpContent).Result;

                                            if (!response.IsSuccessStatusCode)
                                            {
                                                var errorContent = response.Content.ReadAsStringAsync().Result;
                                                throw new Exception($"API调用失败: {response.StatusCode} - {errorContent}");
                                            }
                                        }

                                        this.Invoke(new Action(() =>
                                        {
                                            lblStatus.Text = "授权分配成功";
                                            lblStatus.ForeColor = Color.Green;
                                            LogToPanel("授权分配成功!");
                                            btnLoadUsers.PerformClick();
                                            licenseForm.Close();
                                        }));
                                    }
                                    catch (Exception ex)
                                    {
                                        Serilog.Log.Error(ex, "分配授权失败");
                                        this.Invoke(new Action(() =>
                                        {
                                            lblStatus.Text = $"分配失败: {ex.Message}";
                                            lblStatus.ForeColor = Color.Red;
                                            LogToPanel($"分配失败: {ex.Message}");
                                            MessageBox.Show($"分配失败: {ex.Message}", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                        }));
                                    }
                                });
                            };

                            // 解除授权按钮事件
                            btnRemove.Click += (sender, args) =>
                            {
                                var selectedSkus = new List<Guid?>();
                                for (int i = 0; i < gridRemove.Rows.Count; i++)
                                {
                                    if (Convert.ToBoolean(gridRemove.Rows[i].Cells["选择"].Value))
                                    {
                                        selectedSkus.Add(assignedLicenses[i].SkuId);
                                    }
                                }

                                if (selectedSkus.Count == 0)
                                {
                                    MessageBox.Show("请至少选择一个授权", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                                    return;
                                }

                                var confirmMsg = $"确定要解除以下授权吗？\n{string.Join(", ", assignedLicenses.Where((l, i) => selectedSkus.Contains(l.SkuId)).Select(l => l.SkuPartNumber))}";
                                if (MessageBox.Show(confirmMsg, "确认", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
                                {
                                    return;
                                }

                                LogToPanel($"正在为用户 {userEmail} 解除 {selectedSkus.Count} 个授权...");

                                Task.Run(() =>
                                {
                                    try
                                    {
                                        var accessToken = _exchangeOnlineService.GraphAccessToken;
                                        if (string.IsNullOrEmpty(accessToken))
                                        {
                                            throw new Exception("无法获取 Graph API 访问令牌");
                                        }

                                        using (var httpClient = new System.Net.Http.HttpClient())
                                        {
                                            httpClient.DefaultRequestHeaders.Authorization =
                                                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                            var requestBody = new Dictionary<string, object>
                                            {
                                                ["addLicenses"] = new List<object>(),
                                                ["removeLicenses"] = selectedSkus
                                                    .Where(x => x.HasValue)
                                                    .Select(x => x.Value.ToString())
                                                    .ToList()
                                            };

                                            var jsonContent = System.Text.Json.JsonSerializer.Serialize(requestBody);
                                            var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                            var response = httpClient.PostAsync(
                                                $"https://graph.microsoft.com/v1.0/users/{userEmail}/assignLicense",
                                                httpContent).Result;

                                            if (!response.IsSuccessStatusCode)
                                            {
                                                var errorContent = response.Content.ReadAsStringAsync().Result;
                                                throw new Exception($"API调用失败: {response.StatusCode} - {errorContent}");
                                            }
                                        }

                                        this.Invoke(new Action(() =>
                                        {
                                            lblStatus.Text = "授权解除成功";
                                            lblStatus.ForeColor = Color.Green;
                                            LogToPanel("授权解除成功!");
                                            btnLoadUsers.PerformClick();
                                            licenseForm.Close();
                                        }));
                                    }
                                    catch (Exception ex)
                                    {
                                        Serilog.Log.Error(ex, "解除授权失败");
                                        this.Invoke(new Action(() =>
                                        {
                                            lblStatus.Text = $"解除失败: {ex.Message}";
                                            lblStatus.ForeColor = Color.Red;
                                            LogToPanel($"解除失败: {ex.Message}");
                                            MessageBox.Show($"解除失败: {ex.Message}", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                        }));
                                    }
                                });
                            };

                            btnClose.Click += (sender, args) => licenseForm.Close();

                            licenseForm.Controls.AddRange(new Control[] { lblLicenseTitle, tabControl, lblInfo, btnAssign, btnRemove, btnClose });
                            licenseForm.ShowDialog();

                            lblStatus.Text = "授权分配完成";
                            lblStatus.ForeColor = Color.Green;
                            LogToPanel("授权分配完成");
                        }));
                    }
                    catch (Exception ex)
                    {
                        Serilog.Log.Error(ex, "获取授权列表失败");

                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"获取授权失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                            LogToPanel($"错误: {ex.Message}");
                            LogToPanel($"详细信息: {ex.ToString()}");
                        }));
                    }
                });
            };

            // 启用账户按钮
            btnEnableUser.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailEmail.Text))
                {
                    lblStatus.Text = "请先选择用户";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                if (txtDetailStatus.Text == "已启用")
                {
                    lblStatus.Text = "用户已启用";
                    lblStatus.ForeColor = Color.Gray;
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                var userEmail = txtDetailEmail.Text;
                lblStatus.Text = "正在启用账户...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel($"正在启用用户 {userEmail}...");

                Task.Run(() =>
                {
                    try
                    {
                        // 使用Graph API启用账户
                        var userUpdate = new Microsoft.Graph.Models.User
                        {
                            AccountEnabled = true
                        };

                        _exchangeOnlineService.GraphClient.Users[userEmail]
                            .PatchAsync(userUpdate)
                            .Wait();

                        this.Invoke(new Action(() =>
                        {
                            txtDetailStatus.Text = "已启用";
                            lblStatus.Text = "账户已启用";
                            lblStatus.ForeColor = Color.Green;
                            LogToPanel("账户已启用");
                            // 刷新用户列表
                            btnLoadUsers.PerformClick();
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"启用失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                            LogToPanel($"错误: {ex.Message}");
                        }));
                    }
                });
            };

            // 禁用账户按钮
            btnDisableUser.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailEmail.Text))
                {
                    lblStatus.Text = "请先选择用户";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                if (txtDetailStatus.Text == "已禁用")
                {
                    lblStatus.Text = "用户已禁用";
                    lblStatus.ForeColor = Color.Gray;
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                var userEmail = txtDetailEmail.Text;
                lblStatus.Text = "正在禁用账户...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel($"正在禁用用户 {userEmail}...");

                Task.Run(() =>
                {
                    try
                    {
                        // 确认对话框
                        var result = MessageBox.Show($"确定要禁用用户 {userEmail} 吗?", "确认禁用", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
                        if (result != DialogResult.Yes) return;

                        // 使用Graph API禁用账户
                        var userUpdate = new Microsoft.Graph.Models.User
                        {
                            AccountEnabled = false
                        };

                        _exchangeOnlineService.GraphClient.Users[userEmail]
                            .PatchAsync(userUpdate)
                            .Wait();

                        this.Invoke(new Action(() =>
                        {
                            txtDetailStatus.Text = "已禁用";
                            lblStatus.Text = "账户已禁用";
                            lblStatus.ForeColor = Color.Green;
                            LogToPanel("账户已禁用");
                            // 刷新用户列表
                            btnLoadUsers.PerformClick();
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"禁用失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                            LogToPanel($"错误: {ex.Message}");
                        }));
                    }
                });
            };

            // 查看用户应用按钮
            btnViewApps.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailEmail.Text))
                {
                    lblStatus.Text = "请先选择用户";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                void LogToPanel(string msg)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\n");
                    }));
                }

                var userEmail = txtDetailEmail.Text;
                lblStatus.Text = "正在获取用户应用列表...";
                lblStatus.ForeColor = Color.Blue;
                LogToPanel($"正在获取用户 {userEmail} 的应用列表...");
                Program.AccountManagementLogger.Information("开始获取用户应用列表: {UserEmail}", userEmail);

                Task.Run(() =>
                {
                    try
                    {
                        LogToPanel("调用Graph API获取licenseDetails...");
                        Program.AccountManagementLogger.Information("调用Graph API获取licenseDetails");

                        // 获取用户的许可证详情 (不指定Top)
                        var licenseDetailsTask = _exchangeOnlineService.GraphClient.Users[userEmail].LicenseDetails
                            .GetAsync();

                        try
                        {
                            licenseDetailsTask.Wait();
                        }
                        catch (AggregateException ae)
                        {
                            foreach (var ex in ae.InnerExceptions)
                            {
                                Program.AccountManagementLogger.Error(ex, "LicenseDetails API错误: {Message}", ex.Message);
                            }
                            throw;
                        }

                        var licenseResult = licenseDetailsTask.Result;

                        // 获取所有可用的订阅SKU (不指定Top，API不支持自定义分页大小)
                        LogToPanel("调用Graph API获取SubscribedSkus...");
                        var subscribedSkusTask = _exchangeOnlineService.GraphClient.SubscribedSkus
                            .GetAsync();

                        try
                        {
                            subscribedSkusTask.Wait();
                        }
                        catch (AggregateException ae2)
                        {
                            foreach (var ex in ae2.InnerExceptions)
                            {
                                Program.AccountManagementLogger.Error(ex, "SubscribedSkus API错误: {Message}", ex.Message);
                            }
                            throw;
                        }

                        var skuResult = subscribedSkusTask.Result;

                        this.Invoke(new Action(() =>
                        {
                            // 创建应用列表显示窗口
                            var appForm = new Form
                            {
                                Width = 700,
                                Height = 550,
                                Text = $"用户应用列表 - {userEmail}",
                                StartPosition = FormStartPosition.CenterParent,
                                MaximizeBox = true,
                                MinimizeBox = true
                            };

                            // 添加警告标签
                            var lblWarning = new Label
                            {
                                Text = "注意：用户状态可能会有滞后性，请稍后再来查看",
                                Location = new Point(10, 5),
                                AutoSize = true,
                                ForeColor = Color.Red,
                                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
                            };

                            var gridApps = new DataGridView
                            {
                                Dock = DockStyle.Fill,
                                AllowUserToAddRows = false,
                                AllowUserToDeleteRows = false,
                                ReadOnly = false,
                                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                                MultiSelect = false,
                                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                                RowHeadersVisible = false,
                                BackgroundColor = Color.White,
                                BorderStyle = BorderStyle.FixedSingle
                            };

                            // 添加复选框列
                            var chkColumn = new DataGridViewCheckBoxColumn
                            {
                                Name = "Enabled",
                                HeaderText = "启用",
                                Width = 50,
                                ValueType = typeof(bool)
                            };
                            gridApps.Columns.Add(chkColumn);
                            gridApps.Columns.Add(new DataGridViewTextBoxColumn { Name = "ServicePlanName", HeaderText = "服务计划", Width = 180, ReadOnly = true });
                            gridApps.Columns.Add(new DataGridViewTextBoxColumn { Name = "DisplayName", HeaderText = "显示名称", Width = 200, ReadOnly = true });
                            gridApps.Columns.Add(new DataGridViewTextBoxColumn { Name = "SkuName", HeaderText = "许可证", Width = 150, ReadOnly = true });
                            gridApps.Columns.Add(new DataGridViewTextBoxColumn { Name = "ProvisioningStatus", HeaderText = "当前状态", Width = 80, ReadOnly = true });

                            // 服务计划名称到显示名称的映射
                            var servicePlanNames = new Dictionary<string, string>
                            {
                                { "EXCHANGE_S", "Exchange Online (Plan 1)" },
                                { "EXCHANGE_S_ENTERPRISE", "Exchange Online (Plan 2)" },
                                { "EXCHANGE_S_FOUNDATION", "Exchange Online 基本" },
                                { "MCOSTANDARD", "Skype for Business Online" },
                                { "MCOEV", "Microsoft Teams 音频会议" },
                                { "MCOPSTN", "Microsoft Teams 通话套餐" },
                                { "SPOTIOT", "Microsoft Stream" },
                                { "PROJECTWORKMANAGEMENT", "Project Online" },
                                { "SHAREPOINTSTANDARD", "SharePoint Online (Plan 1)" },
                                { "SHAREPOINTENTERPRISE", "SharePoint Online (Plan 2)" },
                                { "SHAREPOINTWAC", "Office for the web" },
                                { "YAMMER_ENTERPRISE", "Yammer Enterprise" },
                                { "RMS_S_ENTERPRISE", "Azure RMS" },
                                { "OFFICE_FOR_WEB", "Office 网页版" },
                                { "TEAMS1", "Microsoft Teams" },
                                { "TEAMS_SWVOICE", "Teams 电话系统" },
                                { "INTUNE_A", "Intune" },
                                { "EMS", "企业移动性套件 E3" },
                                { "RMS_S_BASIC", "Azure 信息保护基础版" },
                                { "ADALLOM_S_STANDALONE", "Cloud App Security" },
                                { "API", "Graph API" },
                                { "POWERAPPS_VIRAL", "Power Apps" },
                                { "FLOW_VIRAL", "Power Automate" },
                                { "POWER_VIRTUAL_AGENTS", "Power Virtual Agents" },
                                { "MICROSOFTBOOKINGS", "Microsoft Bookings" },
                                { "KAIZALA_STANDALONE", "Kaizala" },
                                { "WHITEBOARD_FIRSTLINE1", "Whiteboard (First Release)" },
                                { "MIROVOICE", "音频会议" },
                                { "COMMUNICATIONS_DOE", "Teams 音频会议" },
                                { "BPOS_S_TODO", "To-Do" },
                                { "FORMS_PLAN_E3", "Microsoft Forms" },
                                { "STREAM_O365_E3", "Microsoft Stream" },
                                { "SWAY", "Sway" },
                                { "DESKLESS", "Frontline Worker" },
                                { "WINDOWSUPDATEFORBUSINESS_DEPLOYMENT_SERVICE", "Windows Update for Business" },
                                { "M365_TEAM_MEMBERS", "Microsoft 365 Team Members" },
                                { "MCOEAM_DOD", "Microsoft 365 GCC" }
                            };

                            // 创建用户当前启用的服务计划字典
                            var enabledPlans = new Dictionary<string, string>(); // servicePlanName -> skuId

                            if (licenseResult?.Value != null)
                            {
                                foreach (var license in licenseResult.Value)
                                {
                                    var skuId = license.SkuId?.ToString();
                                    if (license.ServicePlans != null)
                                    {
                                        foreach (var plan in license.ServicePlans)
                                        {
                                            if (plan.ProvisioningStatus == "Success")
                                            {
                                                enabledPlans[plan.ServicePlanName] = skuId;
                                            }
                                        }
                                    }
                                }
                            }

                            // 从SKU获取所有服务计划
                            if (skuResult?.Value != null)
                            {
                                foreach (var sku in skuResult.Value)
                                {
                                    var skuName = sku.SkuPartNumber ?? "未知";
                                    if (sku.ServicePlans != null)
                                    {
                                        foreach (var plan in sku.ServicePlans)
                                        {
                                            var isEnabled = enabledPlans.ContainsKey(plan.ServicePlanName);
                                            var displayName = servicePlanNames.ContainsKey(plan.ServicePlanName)
                                                ? servicePlanNames[plan.ServicePlanName]
                                                : plan.ServicePlanName;
                                            var statusText = isEnabled ? "已启用" : "未启用";
                                            gridApps.Rows.Add(isEnabled, plan.ServicePlanName, displayName, skuName, statusText);
                                        }
                                    }
                                }
                            }

                            var panelBottom = new Panel { Dock = DockStyle.Bottom, Height = 60 };

                            var lblCount = new Label
                            {
                                Text = $"共 {gridApps.Rows.Count} 个应用",
                                Location = new Point(10, 20),
                                AutoSize = true
                            };

                            var btnSave = new Button
                            {
                                Text = "保存修改",
                                Location = new Point(450, 15),
                                Size = new Size(100, 30),
                                BackColor = Color.FromArgb(0, 120, 215),
                                ForeColor = Color.White
                            };

                            var btnClose = new Button
                            {
                                Text = "关闭",
                                Location = new Point(560, 15),
                                Size = new Size(80, 30),
                                BackColor = Color.FromArgb(128, 128, 128),
                                ForeColor = Color.White
                            };

                            btnSave.Click += (sender, args) =>
                            {
                                // 收集修改后的服务计划
                                var plansToDisable = new List<string>();
                                var plansToEnable = new List<string>();

                                foreach (DataGridViewRow row in gridApps.Rows)
                                {
                                    var servicePlan = row.Cells["ServicePlanName"].Value?.ToString();
                                    var isChecked = row.Cells["Enabled"].Value != null && (bool)row.Cells["Enabled"].Value;
                                    var currentStatus = row.Cells["ProvisioningStatus"].Value?.ToString();
                                    var wasEnabled = currentStatus == "已启用";

                                    if (wasEnabled && !isChecked)
                                    {
                                        plansToDisable.Add(servicePlan);
                                    }
                                    else if (!wasEnabled && isChecked)
                                    {
                                        plansToEnable.Add(servicePlan);
                                    }
                                }

                                if (plansToDisable.Count == 0 && plansToEnable.Count == 0)
                                {
                                    MessageBox.Show("没有修改", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                    return;
                                }

                                var confirmMsg = "";
                                if (plansToEnable.Count > 0 && plansToDisable.Count > 0)
                                {
                                    confirmMsg = $"启用应用: {string.Join(", ", plansToEnable)}\n禁用应用: {string.Join(", ", plansToDisable)}";
                                }
                                else if (plansToEnable.Count > 0)
                                {
                                    confirmMsg = $"确定要启用以下应用吗？\n{string.Join(", ", plansToEnable)}";
                                }
                                else
                                {
                                    confirmMsg = $"确定要禁用以下应用吗？\n{string.Join(", ", plansToDisable)}";
                                }

                                var result = MessageBox.Show(confirmMsg, "确认修改", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
                                if (result != DialogResult.Yes)
                                    return;

                                LogToPanel($"正在修改用户应用...");
                                Program.AccountManagementLogger.Information("开始修改用户应用: {UserEmail}, 启用: {EnablePlans}, 禁用: {DisablePlans}",
                                    userEmail, string.Join(",", plansToEnable), string.Join(",", plansToDisable));

                                btnSave.Enabled = false;
                                btnSave.Text = "处理中...";

                                Task.Run(() =>
                                {
                                    try
                                    {
                                        // 获取 Graph API 访问令牌
                                        var accessToken = _exchangeOnlineService.GraphAccessToken;
                                        if (string.IsNullOrEmpty(accessToken))
                                        {
                                            throw new Exception("无法获取 Graph API 访问令牌");
                                        }

                                        // 获取所有SKU信息，建立服务计划到SKU的映射
                                        var allSkus = _exchangeOnlineService.GraphClient.SubscribedSkus.GetAsync().Result;
                                        var servicePlanToSku = new Dictionary<string, string>(); // servicePlanName -> skuId

                                        foreach (var sku in allSkus.Value)
                                        {
                                            if (sku.ServicePlans != null)
                                            {
                                                foreach (var plan in sku.ServicePlans)
                                                {
                                                    if (!servicePlanToSku.ContainsKey(plan.ServicePlanName))
                                                    {
                                                        servicePlanToSku[plan.ServicePlanName] = sku.SkuId.ToString();
                                                    }
                                                }
                                            }
                                        }

                                        // 获取用户当前的许可证详情（包括禁用的服务计划）
                                        var userLicenseDetails = _exchangeOnlineService.GraphClient.Users[userEmail].LicenseDetails.GetAsync().Result;

                                        // 构建当前许可证状态：SkuId -> 当前启用的服务计划列表 和 禁用的服务计划GUID
                                        var currentEnabledPlans = new Dictionary<string, HashSet<string>>(); // skuId -> enabledPlanNames
                                        var currentDisabledPlans = new Dictionary<string, HashSet<string>>(); // skuId -> disabledPlanGuids
                                        if (userLicenseDetails?.Value != null)
                                        {
                                            foreach (var lic in userLicenseDetails.Value)
                                            {
                                                var skuId = lic.SkuId?.ToString();
                                                if (skuId != null && lic.ServicePlans != null)
                                                {
                                                    var userEnabledPlans = new HashSet<string>();
                                                    var userDisabledPlanGuids = new HashSet<string>();
                                                    foreach (var sp in lic.ServicePlans)
                                                    {
                                                        if (sp.ProvisioningStatus == "Success")
                                                        {
                                                            userEnabledPlans.Add(sp.ServicePlanName);
                                                        }
                                                        else if (sp.ProvisioningStatus == "Disabled" && sp.ServicePlanId.HasValue)
                                                        {
                                                            userDisabledPlanGuids.Add(sp.ServicePlanId.Value.ToString());
                                                        }
                                                    }
                                                    currentEnabledPlans[skuId] = userEnabledPlans;
                                                    currentDisabledPlans[skuId] = userDisabledPlanGuids;
                                                }
                                            }
                                        }

                                        LogToPanel($"当前禁用的服务计划: {string.Join(", ", currentDisabledPlans.Select(kv => $"{kv.Key}:{string.Join(",", kv.Value)}"))}");

                                        var addLicenses = new List<Dictionary<string, object>>();

                                        LogToPanel($"开始处理启用请求: {string.Join(", ", plansToEnable)}");
                                        LogToPanel($"当前用户已有SKU: {string.Join(", ", currentEnabledPlans.Keys)}");

                                        // 处理启用的服务计划 - 只需要确保该SKU存在，不禁用要启用的计划
                                        foreach (var plan in plansToEnable)
                                        {
                                            LogToPanel($"处理启用计划: {plan}");
                                            if (servicePlanToSku.ContainsKey(plan))
                                            {
                                                var targetSkuId = servicePlanToSku[plan];
                                                LogToPanel($"计划 {plan} 对应的SKU: {targetSkuId}");

                                                // 检查该SKU是否已经在addLicenses中，避免重复添加
                                                var skuAlreadyAdded = addLicenses.Any(l => l["skuId"].ToString() == targetSkuId);
                                                if (skuAlreadyAdded)
                                                {
                                                    LogToPanel($"SKU {targetSkuId} 已存在于待处理列表，跳过");
                                                    continue; // 已处理过，跳过
                                                }

                                                // 获取该SKU的所有服务计划
                                                var skuAllPlans = new List<(string Name, string Guid)>();
                                                foreach (var sku in allSkus.Value)
                                                {
                                                    if (sku.SkuId.ToString() == targetSkuId && sku.ServicePlans != null)
                                                    {
                                                        foreach (var sp in sku.ServicePlans)
                                                        {
                                                            if (sp.ServicePlanId.HasValue)
                                                            {
                                                                skuAllPlans.Add((sp.ServicePlanName, sp.ServicePlanId.Value.ToString()));
                                                            }
                                                        }
                                                        break;
                                                    }
                                                }

                                                // 找到要启用的计划对应的GUID
                                                var planGuidToEnable = "";
                                                foreach (var (planName, planGuid) in skuAllPlans)
                                                {
                                                    if (planName == plan)
                                                    {
                                                        planGuidToEnable = planGuid;
                                                        break;
                                                    }
                                                }

                                                if (currentEnabledPlans.ContainsKey(targetSkuId))
                                                {
                                                    // SKU已存在 - 检查该服务计划是否在禁用列表中
                                                    var currentEnabled = currentEnabledPlans[targetSkuId];

                                                    // 如果该服务计划当前未启用，说明它在disabledPlans中
                                                    if (!currentEnabled.Contains(plan))
                                                    {
                                                        // 需要修改disabledPlans，移除要启用的计划
                                                        // 必须保留原有的disabledPlans列表，只移除要启用的计划
                                                        var disabledPlans = new List<string>();
                                                        if (currentDisabledPlans.ContainsKey(targetSkuId))
                                                        {
                                                            // 保留原有的disabledPlans，只移除要启用的计划
                                                            foreach (var disabledGuid in currentDisabledPlans[targetSkuId])
                                                            {
                                                                if (disabledGuid != planGuidToEnable)
                                                                {
                                                                    disabledPlans.Add(disabledGuid);
                                                                }
                                                            }
                                                        }

                                                        LogToPanel($"启用计划 {plan}，更新后的disabledPlans: {string.Join(",", disabledPlans)}");

                                                        // 无论disabledPlans是否为空，都需要添加许可证来更新状态
                                                        addLicenses.Add(new Dictionary<string, object>
                                                        {
                                                            ["skuId"] = targetSkuId,
                                                            ["disabledPlans"] = disabledPlans
                                                        });
                                                    }
                                                }
                                                else
                                                {
                                                    // SKU不存在，需要添加（不禁用任何服务计划）
                                                    addLicenses.Add(new Dictionary<string, object>
                                                    {
                                                        ["skuId"] = targetSkuId,
                                                        ["disabledPlans"] = new List<string>()
                                                    });
                                                }
                                            }
                                        }

                                        // 处理禁用的服务计划
                                        foreach (var plan in plansToDisable)
                                        {
                                            if (servicePlanToSku.ContainsKey(plan))
                                            {
                                                var targetSkuId = servicePlanToSku[plan];

                                                // 检查该SKU是否已经在addLicenses中，避免重复添加
                                                var skuAlreadyAdded = addLicenses.Any(l => l["skuId"].ToString() == targetSkuId);
                                                if (skuAlreadyAdded)
                                                {
                                                    continue; // 已处理过，跳过
                                                }

                                                if (currentEnabledPlans.ContainsKey(targetSkuId))
                                                {
                                                    // 用户已有该SKU，需要将该服务计划添加到disabledPlans
                                                    // 必须保留原有的disabledPlans列表，只添加要禁用的计划
                                                    var disabledPlans = new List<string>();
                                                    if (currentDisabledPlans.ContainsKey(targetSkuId))
                                                    {
                                                        // 保留原有的disabledPlans
                                                        foreach (var disabledGuid in currentDisabledPlans[targetSkuId])
                                                        {
                                                            disabledPlans.Add(disabledGuid);
                                                        }
                                                    }

                                                    // 找到要禁用的服务计划的GUID并添加到disabledPlans
                                                    var planGuid = "";
                                                    foreach (var sku in allSkus.Value)
                                                    {
                                                        if (sku.ServicePlans != null)
                                                        {
                                                            foreach (var sp in sku.ServicePlans)
                                                            {
                                                                if (sp.ServicePlanName == plan && sp.ServicePlanId.HasValue)
                                                                {
                                                                    planGuid = sp.ServicePlanId.Value.ToString();
                                                                    break;
                                                                }
                                                            }
                                                        }
                                                    }
                                                    if (!string.IsNullOrEmpty(planGuid) && !disabledPlans.Contains(planGuid))
                                                    {
                                                        disabledPlans.Add(planGuid);
                                                    }

                                                    LogToPanel($"禁用计划 {plan}，更新后的disabledPlans: {string.Join(",", disabledPlans)}");

                                                    addLicenses.Add(new Dictionary<string, object>
                                                    {
                                                        ["skuId"] = targetSkuId,
                                                        ["disabledPlans"] = disabledPlans
                                                    });
                                                }
                                                else
                                                {
                                                    // 用户没有该SKU，需要添加并禁用该服务计划
                                                    // 找到该服务计划的GUID
                                                    var planGuid = "";
                                                    foreach (var sku in allSkus.Value)
                                                    {
                                                        if (sku.ServicePlans != null)
                                                        {
                                                            foreach (var sp in sku.ServicePlans)
                                                            {
                                                                if (sp.ServicePlanName == plan && sp.ServicePlanId.HasValue)
                                                                {
                                                                    planGuid = sp.ServicePlanId.Value.ToString();
                                                                    break;
                                                                }
                                                            }
                                                        }
                                                    }
                                                    addLicenses.Add(new Dictionary<string, object>
                                                    {
                                                        ["skuId"] = targetSkuId,
                                                        ["disabledPlans"] = string.IsNullOrEmpty(planGuid) ? new List<string> { plan } : new List<string> { planGuid }
                                                    });
                                                }
                                            }
                                        }

                                        // 如果有修改，调用 API
                                        LogToPanel($"准备修改的SKU数量: {addLicenses.Count}");
                                        foreach (var lic in addLicenses)
                                        {
                                            var skuId = lic["skuId"].ToString();
                                            var disabledPlans = lic["disabledPlans"] as List<string>;
                                            LogToPanel($"  SKU: {skuId}, 禁用计划: {(disabledPlans != null ? string.Join(",", disabledPlans) : "无")}");
                                        }

                                        if (addLicenses.Count > 0)
                                        {
                                            using (var httpClient = new System.Net.Http.HttpClient())
                                            {
                                                httpClient.DefaultRequestHeaders.Authorization =
                                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                                var requestBody = new Dictionary<string, object>
                                                {
                                                    ["addLicenses"] = addLicenses,
                                                    ["removeLicenses"] = new List<string>()
                                                };

                                                var jsonContent = System.Text.Json.JsonSerializer.Serialize(requestBody);
                                                LogToPanel($"发送API请求: {jsonContent.Substring(0, Math.Min(500, jsonContent.Length))}...");
                                                var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                                LogToPanel("正在调用 assignLicense API...");

                                                var response = httpClient.PostAsync(
                                                    $"https://graph.microsoft.com/v1.0/users/{userEmail}/assignLicense",
                                                    httpContent).Result;

                                                LogToPanel($"API响应状态: {response.StatusCode}");

                                                if (!response.IsSuccessStatusCode)
                                                {
                                                    var errorContent = response.Content.ReadAsStringAsync().Result;
                                                    LogToPanel($"API错误响应: {errorContent}");
                                                    throw new Exception($"API调用失败: {response.StatusCode} - {errorContent}");
                                                }

                                                foreach (var plan in plansToEnable)
                                                    LogToPanel($"已启用: {plan}");
                                                foreach (var plan in plansToDisable)
                                                    LogToPanel($"已禁用: {plan}");
                                            }
                                        }

                                        this.Invoke(new Action(() =>
                                        {
                                            btnSave.Enabled = true;
                                            btnSave.Text = "保存修改";
                                            MessageBox.Show("应用修改成功", "成功", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                            LogToPanel("应用修改成功");
                                            lblStatus.Text = "应用修改成功";
                                            lblStatus.ForeColor = Color.Green;

                                            // 刷新当前窗口的数据
                                            gridApps.Rows.Clear();

                                            // 重新获取用户当前的应用状态
                                            var refreshLicenseTask = _exchangeOnlineService.GraphClient.Users[userEmail].LicenseDetails.GetAsync();
                                            refreshLicenseTask.Wait();
                                            var refreshLicenseResult = refreshLicenseTask.Result;

                                            var refreshEnabledPlans = new Dictionary<string, string>();
                                            if (refreshLicenseResult?.Value != null)
                                            {
                                                foreach (var license in refreshLicenseResult.Value)
                                                {
                                                    var skuId = license.SkuId?.ToString();
                                                    if (license.ServicePlans != null)
                                                    {
                                                        foreach (var plan in license.ServicePlans)
                                                        {
                                                            if (plan.ProvisioningStatus == "Success")
                                                            {
                                                                refreshEnabledPlans[plan.ServicePlanName] = skuId;
                                                            }
                                                        }
                                                    }
                                                }
                                            }

                                            // 重新加载所有服务计划
                                            foreach (var sku in skuResult.Value)
                                            {
                                                var skuName = sku.SkuPartNumber ?? "未知";
                                                if (sku.ServicePlans != null)
                                                {
                                                    foreach (var plan in sku.ServicePlans)
                                                    {
                                                        var isEnabled = refreshEnabledPlans.ContainsKey(plan.ServicePlanName);
                                                        var displayName = servicePlanNames.ContainsKey(plan.ServicePlanName)
                                                            ? servicePlanNames[plan.ServicePlanName]
                                                            : plan.ServicePlanName;
                                                        var statusText = isEnabled ? "已启用" : "未启用";
                                                        gridApps.Rows.Add(isEnabled, plan.ServicePlanName, displayName, skuName, statusText);
                                                    }
                                                }
                                            }

                                            lblCount.Text = $"共 {gridApps.Rows.Count} 个应用";
                                        }));
                                    }
                                    catch (Exception ex)
                                    {
                                        this.Invoke(new Action(() =>
                                        {
                                            btnSave.Enabled = true;
                                            btnSave.Text = "保存修改";
                                            MessageBox.Show($"修改失败: {ex.Message}", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                            LogToPanel($"修改失败: {ex.Message}");
                                            Program.AccountManagementLogger.Error(ex, "修改用户应用失败: {UserEmail}", userEmail);
                                        }));
                                    }
                                });
                            };

                            btnClose.Click += (sender, args) =>
                            {
                                appForm.Close();
                            };

                            panelBottom.Controls.Add(lblCount);
                            panelBottom.Controls.Add(btnSave);
                            panelBottom.Controls.Add(btnClose);

                            appForm.Controls.Add(lblWarning);
                            appForm.Controls.Add(gridApps);
                            appForm.Controls.Add(panelBottom);

                            appForm.Show();
                            LogToPanel($"成功获取用户应用列表，共 {gridApps.Rows.Count} 个应用");
                            lblStatus.Text = $"已获取 {gridApps.Rows.Count} 个应用";
                            lblStatus.ForeColor = Color.Green;
                        }));
                    }
                    catch (Exception ex)
                    {
                        var errorMsg = ex.Message;
                        Serilog.Log.Error(ex, "获取用户应用列表失败");
                        Program.AccountManagementLogger.Error(ex, "获取用户应用列表失败: {UserEmail}", userEmail);
                        LogToPanel($"错误: {errorMsg}");
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"获取失败: {errorMsg}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            // 添加控件到面板
            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblAccountList);
            panel.Controls.Add(gridAccounts);
            panel.Controls.Add(btnLoadUsers);
            panel.Controls.Add(btnLoadApps);
            panel.Controls.Add(lblUserDetail);
            panel.Controls.Add(lblDetailName);
            panel.Controls.Add(txtDetailName);
            panel.Controls.Add(lblDetailEmail);
            panel.Controls.Add(txtDetailEmail);
            panel.Controls.Add(lblDetailStatus);
            panel.Controls.Add(txtDetailStatus);
            panel.Controls.Add(lblDetailLicense);
            panel.Controls.Add(txtDetailLicense);
            panel.Controls.Add(lblActions);
            panel.Controls.Add(btnResetPassword);
            panel.Controls.Add(btnAssignLicense);
            panel.Controls.Add(btnEnableUser);
            panel.Controls.Add(btnDisableUser);
            panel.Controls.Add(btnViewApps);
            panel.Controls.Add(lblStatus);

            return panel;
        }

        // 根据ServicePlanId获取ServicePlanName
        private string GetServicePlanNameById(string planId, IEnumerable<Microsoft.Graph.Models.SubscribedSku> skus)
        {
            foreach (var sku in skus)
            {
                if (sku.ServicePlans != null)
                {
                    foreach (var sp in sku.ServicePlans)
                    {
                        if (sp.ServicePlanId.HasValue && sp.ServicePlanId.Value.ToString() == planId)
                        {
                            return sp.ServicePlanName;
                        }
                    }
                }
            }
            return null;
        }

