            };

            // 加载组按钮事件
            btnLoadGroups.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在账户管理登录";
                    lblStatus.ForeColor = Color.Red;
                    Program.GroupManagementLogger.Warning("加载组列表失败: 未登录");
                    return;
                }

                lblStatus.Text = "正在加载组列表...";
                lblStatus.ForeColor = Color.Blue;
                Program.GroupManagementLogger.Information("开始加载组列表");

                Task.Run(() =>
                {
                    try
                    {
                        var accessToken = _exchangeOnlineService.GraphAccessToken;
                        if (string.IsNullOrEmpty(accessToken))
                        {
                            accessToken = _exchangeOnlineService.AccessToken;
                        }

                        using (var httpClient = new System.Net.Http.HttpClient())
                        {
                            httpClient.DefaultRequestHeaders.Authorization =
                                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                            // 获取组列表
                            var groupsResponse = httpClient.GetAsync(
                                "https://graph.microsoft.com/v1.0/groups?$top=500&$select=id,displayName,description,groupTypes").Result;

                            if (groupsResponse.IsSuccessStatusCode)
                            {
                                var json = groupsResponse.Content.ReadAsStringAsync().Result;
                                var doc = System.Text.Json.JsonDocument.Parse(json);
                                var groups = doc.RootElement.GetProperty("value");

                                this.Invoke(new Action(() =>
                                {
                                    gridGroups.Rows.Clear();
                                    foreach (var group in groups.EnumerateArray())
                                    {
                                        var displayName = group.GetProperty("displayName").GetString() ?? "未知";
                                        var description = group.TryGetProperty("description", out var descProp) ? descProp.GetString() ?? "" : "";
                                        var groupTypes = group.GetProperty("groupTypes").GetArrayLength() > 0 ? "通讯组" : "安全组";

                                        gridGroups.Rows.Add(displayName, description, groupTypes);
                                    }
                                    lblStatus.Text = $"共加载 {groups.GetArrayLength()} 个组";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                                Program.GroupManagementLogger.Information("加载组列表成功: Count={Count}", groups.GetArrayLength());
                            }
                            else
                            {
                                this.Invoke(new Action(() =>
                                {
                                    lblStatus.Text = "加载组列表失败";
                                    lblStatus.ForeColor = Color.Red;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                        Program.GroupManagementLogger.Error(ex, "加载组列表失败");
                    }
                });
            };

            // 选择组时显示详情
            gridGroups.SelectionChanged += (s, e) =>
            {
                if (gridGroups.SelectedRows.Count > 0)
