                    var row = gridGroups.SelectedRows[0];
                    txtDetailName.Text = row.Cells["DisplayName"].Value?.ToString() ?? "";
                    txtDetailDesc.Text = row.Cells["Description"].Value?.ToString() ?? "";
                    txtDetailType.Text = row.Cells["GroupType"].Value?.ToString() ?? "";

                    // 获取组ID
                    var groupDisplayName = row.Cells["DisplayName"].Value?.ToString();
