                var gridMembers = new DataGridView
                {
                    Location = new Point(20, 40),
                    Size = new Size(430, 200),
                    AllowUserToAddRows = false,
                    ReadOnly = true,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    MultiSelect = false,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.FixedSingle
                };
                gridMembers.Columns.Add(new DataGridViewTextBoxColumn { Name = "DisplayName", HeaderText = "显示名称", Width = 200 });
                gridMembers.Columns.Add(new DataGridViewTextBoxColumn { Name = "Email", HeaderText = "邮箱", Width = 200 });

                var btnAddMember = new Button { Text = "添加成员", Location = new Point(20, 255), Size = new Size(100, 30) };
                var btnRemoveMember = new Button { Text = "移除成员", Location = new Point(130, 255), Size = new Size(100, 30) };
                var btnRefreshMembers = new Button { Text = "刷新", Location = new Point(240, 255), Size = new Size(80, 30) };
                var btnClose = new Button { Text = "关闭", Location = new Point(350, 255), Size = new Size(80, 30) };

                void LoadMembers()
                {
                    gridMembers.Rows.Clear();
                    Task.Run(() =>
                    {
                        try
                        {
                            var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                            using (var httpClient = new System.Net.Http.HttpClient())
                            {
                                httpClient.DefaultRequestHeaders.Authorization =
                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                var response = httpClient.GetAsync(
                                    $"https://graph.microsoft.com/v1.0/groups/{txtDetailId.Text}/members?$select=displayName,mail&$top=100").Result;

                                if (response.IsSuccessStatusCode)
                                {
                                    var json = response.Content.ReadAsStringAsync().Result;
                                    var doc = System.Text.Json.JsonDocument.Parse(json);
                                    var members = doc.RootElement.GetProperty("value");

                                    this.Invoke(new Action(() =>
                                    {
                                        foreach (var member in members.EnumerateArray())
                                        {
                                            var displayName = member.TryGetProperty("displayName", out var dn) ? dn.GetString() : "";
                                            var email = member.TryGetProperty("mail", out var m) ? m.GetString() : "";
                                            gridMembers.Rows.Add(displayName, email);
                                        }
                                    }));
                                }
                            }
                        }
                        catch { }
                    });
                }

                btnRefreshMembers.Click += (sender, args) => LoadMembers();
                btnAddMember.Click += (sender, args) =>
                {
                    // 先加载所有可用用户
                    var availableUsers = new List<(string DisplayName, string Email, string UserType)>();

                    Task.Run(() =>
                    {
                        try
                        {
                            var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                            using (var httpClient = new System.Net.Http.HttpClient())
                            {
                                httpClient.DefaultRequestHeaders.Authorization =
                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                // 获取所有用户（成员和来宾）
                                var response = httpClient.GetAsync("https://graph.microsoft.com/v1.0/users?$select=displayName,mail,userPrincipalName,userType&$top=500").Result;
                                if (response.IsSuccessStatusCode)
                                {
                                    var json = response.Content.ReadAsStringAsync().Result;
                                    var doc = System.Text.Json.JsonDocument.Parse(json);
                                    if (doc.RootElement.TryGetProperty("value", out var users))
                                    {
                                        foreach (var user in users.EnumerateArray())
                                        {
                                            var displayName = user.TryGetProperty("displayName", out var dn) ? dn.GetString() : "";
                                            var email = user.TryGetProperty("mail", out var mail) ? mail.GetString() :
                                                        (user.TryGetProperty("userPrincipalName", out var upn) ? upn.GetString() : "");
                                            var userType = user.TryGetProperty("userType", out var ut) ? ut.GetString() : "Member";

                                            if (!string.IsNullOrWhiteSpace(email))
                                            {
                                                availableUsers.Add((displayName ?? email, email, userType));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        catch { }
                    }).Wait();

                    var addForm = new Form
                    {
                        Width = 500,
                        Height = 400,
                        Text = "添加成员",
                        StartPosition = FormStartPosition.CenterParent,
                        MaximizeBox = false,
                        MinimizeBox = false
                    };

                    var labelTitle = new Label
                    {
                        Text = "选择要添加的成员:",
                        Left = 20,
                        Top = 15,
                        AutoSize = true,
                        Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
                    };

                    var usersGrid = new DataGridView
                    {
                        Left = 20,
                        Top = 40,
                        Width = 440,
                        Height = 250,
                        AllowUserToAddRows = false,
                        AllowUserToDeleteRows = false,
                        ReadOnly = false,
                        SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                        MultiSelect = true,
                        ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                        RowHeadersVisible = false,
                        BackgroundColor = Color.White,
                        BorderStyle = BorderStyle.FixedSingle
                    };

                    usersGrid.Columns.Add(new DataGridViewCheckBoxColumn { Name = "选择", Width = 40 });
                    usersGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = "显示名称", Width = 180, ReadOnly = true });
                    usersGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = "邮箱", Width = 180, ReadOnly = true });
                    usersGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = "类型", Width = 60, ReadOnly = true });

                    foreach (var user in availableUsers)
                    {
                        var userType = user.UserType == "Guest" ? "外部" : "内部";
                        usersGrid.Rows.Add(false, user.DisplayName, user.Email, userType);
                    }

                    var lblInfo = new Label
                    {
                        Text = $"共 {availableUsers.Count} 个用户",
                        Left = 20,
                        Top = 300,
                        AutoSize = true,
                        ForeColor = Color.Gray
                    };

                    var btnOk = new Button
                    {
                        Text = "添加选中",
                        Left = 280,
                        Top = 320,
                        Width = 90,
                        BackColor = Color.FromArgb(0, 120, 215),
                        ForeColor = Color.White
                    };

                    var btnCancel = new Button
                    {
                        Text = "取消",
                        Left = 380,
                        Top = 320,
                        Width = 80
                    };

                    addForm.Controls.AddRange(new Control[] { labelTitle, usersGrid, lblInfo, btnOk, btnCancel });
                    addForm.AcceptButton = btnOk;

                    btnOk.Click += (ev, btnEv) =>
                    {
                        var selectedUsers = new List<string>();
                        for (int i = 0; i < usersGrid.Rows.Count; i++)
                        {
                            if (Convert.ToBoolean(usersGrid.Rows[i].Cells["选择"].Value))
                            {
                                selectedUsers.Add(usersGrid.Rows[i].Cells["邮箱"].Value?.ToString());
                            }
                        }

                        if (selectedUsers.Count == 0)
                        {
                            MessageBox.Show("请至少选择一个成员", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            return;
                        }

                        addForm.DialogResult = DialogResult.OK;
                        addForm.Close();

                        // 添加选中的成员
                        Task.Run(() =>
                        {
                            int successCount = 0;
                            foreach (var userEmail in selectedUsers)
                            {
                                try
                                {
                                    var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                                    using (var httpClient = new System.Net.Http.HttpClient())
                                    {
                                        httpClient.DefaultRequestHeaders.Authorization =
                                            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                        // 先通过邮箱获取用户ID
                                        var userResponse = httpClient.GetAsync($"https://graph.microsoft.com/v1.0/users/{userEmail}").Result;
                                        if (!userResponse.IsSuccessStatusCode)
                                        {
                                            continue;
                                        }
                                        var userJson = userResponse.Content.ReadAsStringAsync().Result;
                                        var userDoc = System.Text.Json.JsonDocument.Parse(userJson);
                                        string userId = null;
                                        if (userDoc.RootElement.TryGetProperty("id", out var idElement))
                                        {
                                            userId = idElement.GetString();
                                        }

                                        if (string.IsNullOrEmpty(userId))
                                        {
                                            continue;
                                        }

                                        var body = new Dictionary<string, object> { ["@odata.id"] = $"https://graph.microsoft.com/v1.0/directoryObjects/{userId}" };
                                        var jsonContent = System.Text.Json.JsonSerializer.Serialize(body);
                                        var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                        var response = httpClient.PostAsync(
                                            $"https://graph.microsoft.com/v1.0/groups/{txtDetailId.Text}/members/$ref", httpContent).Result;

                                        if (response.IsSuccessStatusCode)
                                        {
                                            successCount++;
                                        }
                                    }
                                }
                                catch { }
                            }

                            this.Invoke(new Action(() =>
                            {
                                LoadMembers();
                                lblStatus.Text = $"成功添加 {successCount}/{selectedUsers.Count} 个成员";
                                lblStatus.ForeColor = successCount > 0 ? Color.Green : Color.Red;
                            }));
                        });
                    };

                    btnCancel.Click += (btnSender, btnEv) => addForm.Close();
                    addForm.ShowDialog();
                };

                btnRemoveMember.Click += (sender, args) =>
                {
                    if (gridMembers.SelectedRows.Count == 0)
                    {
                        MessageBox.Show("请选择要移除的成员", "提示");
                        return;
                    }
                    var memberEmail = gridMembers.SelectedRows[0].Cells["Email"].Value?.ToString();
                    if (string.IsNullOrWhiteSpace(memberEmail)) return;

                    var result = MessageBox.Show($"确定要移除成员 '{memberEmail}' 吗？", "确认", MessageBoxButtons.YesNo);
                    if (result != DialogResult.Yes) return;

                    Task.Run(() =>
                    {
                        try
                        {
                            var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                            using (var httpClient = new System.Net.Http.HttpClient())
                            {
                                httpClient.DefaultRequestHeaders.Authorization =
                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                // 先通过邮箱获取用户ID
                                var userResponse = httpClient.GetAsync($"https://graph.microsoft.com/v1.0/users/{memberEmail}").Result;
                                if (!userResponse.IsSuccessStatusCode)
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        lblStatus.Text = "获取用户ID失败";
                                        lblStatus.ForeColor = Color.Red;
                                    }));
                                    return;
                                }
                                var userJson = userResponse.Content.ReadAsStringAsync().Result;
                                var userDoc = System.Text.Json.JsonDocument.Parse(userJson);
                                string userId = null;
                                if (userDoc.RootElement.TryGetProperty("id", out var idElement))
                                {
                                    userId = idElement.GetString();
                                }

                                if (string.IsNullOrEmpty(userId))
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        lblStatus.Text = "无法获取用户ID";
                                        lblStatus.ForeColor = Color.Red;
                                    }));
                                    return;
                                }

                                var response = httpClient.DeleteAsync(
                                    $"https://graph.microsoft.com/v1.0/groups/{txtDetailId.Text}/members/{userId}/$ref").Result;

                                this.Invoke(new Action(() =>
                                {
                                    if (response.IsSuccessStatusCode)
                                    {
                                        LoadMembers();
                                        lblStatus.Text = "成员移除成功";
                                        lblStatus.ForeColor = Color.Green;
                                    }
                                    else
                                    {
                                        lblStatus.Text = "移除成员失败";
                                        lblStatus.ForeColor = Color.Red;
                                    }
                                }));
                            }
                        }
                        catch (Exception ex)
                        {
                            this.Invoke(new Action(() =>
                            {
                                lblStatus.Text = $"移除失败: {ex.Message}";
                                lblStatus.ForeColor = Color.Red;
                            }));
                        }
                    });
                };

                btnClose.Click += (sender, args) => membersForm.Close();

                membersForm.Controls.AddRange(new Control[] { lblMembers, gridMembers, btnAddMember, btnRemoveMember, btnRefreshMembers, btnClose });
                LoadMembers();
                membersForm.ShowDialog();
            };

            // 修改组信息按钮 (原重命名)
            btnRenameGroup.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailId.Text))
                {
                    lblStatus.Text = "请先选择一个组";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var editForm = new Form
                {
                    Width = 400,
                    Height = 250,
                    Text = "修改组信息",
                    StartPosition = FormStartPosition.CenterParent,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var lblNewName = new Label { Text = "显示名称:", Left = 20, Top = 20, Width = 80 };
                var txtNewName = new TextBox { Left = 110, Top = 18, Width = 250, Text = txtDetailName.Text };

                var lblNewDesc = new Label { Text = "描述:", Left = 20, Top = 55, Width = 80 };
                var txtNewDesc = new TextBox { Left = 110, Top = 53, Width = 250, Multiline = true, Height = 60, Text = txtDetailDesc.Text };

                var btnOk = new Button { Text = "保存", Left = 200, Top = 130, Width = 80, DialogResult = DialogResult.OK };
                var btnCancel = new Button { Text = "取消", Left = 290, Top = 130, Width = 80, DialogResult = DialogResult.Cancel };

                editForm.Controls.AddRange(new Control[] { lblNewName, txtNewName, lblNewDesc, txtNewDesc, btnOk, btnCancel });
                editForm.AcceptButton = btnOk;
                editForm.CancelButton = btnCancel;

                if (editForm.ShowDialog() == DialogResult.OK)
                {
                    lblStatus.Text = "正在更新组信息...";
                    lblStatus.ForeColor = Color.Blue;

                    Task.Run(() =>
                    {
                        try
                        {
                            var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                            using (var httpClient = new System.Net.Http.HttpClient())
                            {
                                httpClient.DefaultRequestHeaders.Authorization =
                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                var body = new Dictionary<string, object>
                                {
                                    ["displayName"] = txtNewName.Text,
                                    ["description"] = txtNewDesc.Text
                                };

                                var jsonContent = System.Text.Json.JsonSerializer.Serialize(body);
                                var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                var request = new System.Net.Http.HttpRequestMessage(
                                    new System.Net.Http.HttpMethod("PATCH"),
                                    $"https://graph.microsoft.com/v1.0/groups/{txtDetailId.Text}") { Content = httpContent };
                                var response = httpClient.SendAsync(request).Result;

                                if (response.IsSuccessStatusCode)
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        lblStatus.Text = "组信息更新成功";
                                        lblStatus.ForeColor = Color.Green;
                                        btnLoadGroups.PerformClick();
                                    }));
                                }
                                else
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        lblStatus.Text = $"更新失败: {response.StatusCode}";
                                        lblStatus.ForeColor = Color.Red;
                                    }));
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            this.Invoke(new Action(() =>
                            {
                                lblStatus.Text = $"更新失败: {ex.Message}";
                                lblStatus.ForeColor = Color.Red;
                            }));
                        }
                    });
                }
            };

            // 创建组按钮
            btnCreateGroup.Click += (s, e) =>
            {
                var createForm = new Form
                {
                    Width = 400,
                    Height = 250,
                    Text = "创建新组",
                    StartPosition = FormStartPosition.CenterParent,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var lblNewName = new Label { Text = "显示名称:", Left = 20, Top = 20, Width = 80 };
                var txtNewName = new TextBox { Left = 110, Top = 18, Width = 250 };

                var lblNewMailNick = new Label { Text = "邮件别名:", Left = 20, Top = 55, Width = 80 };
                var txtNewMailNick = new TextBox { Left = 110, Top = 53, Width = 250 };

                var lblNewDesc = new Label { Text = "描述:", Left = 20, Top = 90, Width = 80 };
                var txtNewDesc = new TextBox { Left = 110, Top = 88, Width = 250, Multiline = true, Height = 60 };

                var btnOk = new Button { Text = "创建", Left = 200, Top = 165, Width = 80, DialogResult = DialogResult.OK };
                var btnCancel = new Button { Text = "取消", Left = 290, Top = 165, Width = 80, DialogResult = DialogResult.Cancel };

                createForm.Height = 290;
                createForm.Controls.AddRange(new Control[] { lblNewName, txtNewName, lblNewMailNick, txtNewMailNick, lblNewDesc, txtNewDesc, btnOk, btnCancel });
                createForm.AcceptButton = btnOk;
                createForm.CancelButton = btnCancel;

                if (createForm.ShowDialog() == DialogResult.OK && !string.IsNullOrWhiteSpace(txtNewName.Text))
                {
                    lblStatus.Text = "正在创建组...";
                    lblStatus.ForeColor = Color.Blue;

                    // 先计算 mailNickname 用于日志
                    var mailNicknameForLog = txtNewMailNick.Text.Trim();
                    if (string.IsNullOrEmpty(mailNicknameForLog))
                    {
                        mailNicknameForLog = new string(txtNewName.Text.Where(c => char.IsLetterOrDigit(c) || c == '_' || c == '-').ToArray());
                        if (string.IsNullOrEmpty(mailNicknameForLog))
                        {
                            mailNicknameForLog = "group" + DateTime.Now.Ticks.ToString().Substring(8);
                        }
                    }
                    Program.GroupManagementLogger.Information("开始创建组: Name={Name}, MailNick={MailNick}, Description={Desc}", txtNewName.Text, mailNicknameForLog, txtNewDesc.Text);

                    Task.Run(() =>
                    {
                        try
                        {
                            var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                            using (var httpClient = new System.Net.Http.HttpClient())
                            {
                                httpClient.DefaultRequestHeaders.Authorization =
                                    new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                                var body = new Dictionary<string, object>
                                {
                                    ["displayName"] = txtNewName.Text,
                                    ["mailEnabled"] = false,
                                    ["securityEnabled"] = true
                                };

                                // 使用用户输入的 mailNickname，如果没有输入则自动生成
                                var mailNickname = txtNewMailNick.Text.Trim();
                                if (string.IsNullOrEmpty(mailNickname))
                                {
                                    mailNickname = new string(txtNewName.Text.Where(c => char.IsLetterOrDigit(c) || c == '_' || c == '-').ToArray());
                                    if (string.IsNullOrEmpty(mailNickname))
                                    {
                                        mailNickname = "group" + DateTime.Now.Ticks.ToString().Substring(8);
                                    }
                                }
                                body["mailNickname"] = mailNickname;

                                // 只在描述不为空时添加描述字段
                                if (!string.IsNullOrWhiteSpace(txtNewDesc.Text))
                                {
                                    body["description"] = txtNewDesc.Text;
                                }

                                var jsonContent = System.Text.Json.JsonSerializer.Serialize(body);
                                var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                var response = httpClient.PostAsync("https://graph.microsoft.com/v1.0/groups", httpContent).Result;

                                if (response.IsSuccessStatusCode)
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        lblStatus.Text = "组创建成功";
                                        lblStatus.ForeColor = Color.Green;
                                        btnLoadGroups.PerformClick();
                                    }));
                                    Program.GroupManagementLogger.Information("组创建成功: Name={Name}", txtNewName.Text);
                                }
                                else
                                {
                                    var error = response.Content.ReadAsStringAsync().Result;
                                    this.Invoke(new Action(() =>
                                    {
                                        lblStatus.Text = $"创建失败: {response.StatusCode}";
                                        lblStatus.ForeColor = Color.Red;
                                    }));
                                    Program.GroupManagementLogger.Error("组创建失败: Name={Name}, StatusCode={StatusCode}, Error={Error}", txtNewName.Text, response.StatusCode, error);
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            this.Invoke(new Action(() =>
                            {
                                lblStatus.Text = $"创建失败: {ex.Message}";
                                lblStatus.ForeColor = Color.Red;
                            }));
                            Program.GroupManagementLogger.Error(ex, "组创建异常: Name={Name}", txtNewName.Text);
                        }
                    });
                }
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblGroupList);
            btnDeleteGroup.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtDetailId.Text))
                {
                    lblStatus.Text = "请先选择一个组";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var result = MessageBox.Show($"确定要删除组 '{txtDetailName.Text}' 吗？", "确认删除", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
                if (result != DialogResult.Yes) return;

                lblStatus.Text = "正在删除组...";
                lblStatus.ForeColor = Color.Blue;
                Program.GroupManagementLogger.Information("开始删除组: Name={Name}, Id={Id}", txtDetailName.Text, txtDetailId.Text);

                Task.Run(() =>
                {
                    try
                    {
                        var accessToken = _exchangeOnlineService.GraphAccessToken ?? _exchangeOnlineService.AccessToken;
                        using (var httpClient = new System.Net.Http.HttpClient())
                        {
                            httpClient.DefaultRequestHeaders.Authorization =
                                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                            var response = httpClient.DeleteAsync($"https://graph.microsoft.com/v1.0/groups/{txtDetailId.Text}").Result;

                            if (response.IsSuccessStatusCode)
                            {
                                this.Invoke(new Action(() =>
                                {
                                    lblStatus.Text = "组删除成功";
                                    lblStatus.ForeColor = Color.Green;
                                    btnLoadGroups.PerformClick();
                                }));
                                Program.GroupManagementLogger.Information("组删除成功: Name={Name}", txtDetailName.Text);
                            }
                            else
                            {
                                var error = response.Content.ReadAsStringAsync().Result;
                                this.Invoke(new Action(() =>
                                {
                                    lblStatus.Text = $"删除失败: {response.StatusCode}";
                                    lblStatus.ForeColor = Color.Red;
                                }));
                                Program.GroupManagementLogger.Error("组删除失败: Name={Name}, StatusCode={StatusCode}", txtDetailName.Text, response.StatusCode);
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"删除失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                        Program.GroupManagementLogger.Error(ex, "组删除异常: Name={Name}", txtDetailName.Text);
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblGroupList);
            panel.Controls.Add(btnLoadGroups);
            panel.Controls.Add(gridGroups);
            panel.Controls.Add(lblGroupDetail);
            panel.Controls.Add(lblDetailName);
            panel.Controls.Add(txtDetailName);
            panel.Controls.Add(lblDetailDesc);
            panel.Controls.Add(txtDetailDesc);
            panel.Controls.Add(lblDetailType);
            panel.Controls.Add(txtDetailType);
            panel.Controls.Add(lblDetailId);
            panel.Controls.Add(txtDetailId);
            panel.Controls.Add(lblActions);
            panel.Controls.Add(btnCreateGroup);
            panel.Controls.Add(btnManageMembers);
            panel.Controls.Add(btnDeleteGroup);
            panel.Controls.Add(btnRenameGroup);
            panel.Controls.Add(lblStatus);

            return panel;
        }

        private Panel CreateAdminRoleManagementPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "Exchange Online 管理员角色管理",
                Location = new Point(20, 20),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 左侧：角色列表
            var lblRoleList = new Label { Text = "角色列表:", Location = new Point(20, 55), AutoSize = true };

            var btnLoadRoles = new Button
            {
                Location = new Point(90, 53),
                Size = new Size(100, 25),
                Text = "加载角色",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnLoadRoles"
            };

            var gridRoles = new DataGridView
            {
                Location = new Point(20, 85),
                Size = new Size(450, 320),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle,
                Name = "gridRoles"
            };

            gridRoles.Columns.Add(new DataGridViewTextBoxColumn { Name = "DisplayName", HeaderText = "角色名称", Width = 150 });
            gridRoles.Columns.Add(new DataGridViewTextBoxColumn { Name = "Description", HeaderText = "描述", Width = 180 });
            gridRoles.Columns.Add(new DataGridViewTextBoxColumn { Name = "RoleId", HeaderText = "ID", Width = 100 });

            // 右侧：角色详情面板
            var lblRoleDetail = new Label { Text = "角色详情:", Location = new Point(440, 55), AutoSize = true, Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold) };

            var lblDetailName = new Label { Text = "角色名称:", Location = new Point(440, 85), AutoSize = true };
            var txtDetailName = new TextBox { Location = new Point(530, 82), Size = new Size(250, 25), ReadOnly = true, Name = "txtRoleName" };

            var lblDetailDesc = new Label { Text = "描述:", Location = new Point(440, 120), AutoSize = true };
            var txtDetailDesc = new TextBox { Location = new Point(530, 117), Size = new Size(250, 60), Multiline = true, ReadOnly = true, Name = "txtRoleDesc" };

            var lblDetailId = new Label { Text = "ID:", Location = new Point(440, 190), AutoSize = true };
            var txtDetailId = new TextBox { Location = new Point(530, 187), Size = new Size(250, 25), ReadOnly = true, Name = "txtRoleId" };

            // 操作按钮
            var lblActions = new Label { Text = "操作:", Location = new Point(440, 230), AutoSize = true, Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold) };

            var btnManageMembers = new Button
            {
                Location = new Point(440, 255),
                Size = new Size(100, 30),
                Text = "管理成员",
                Name = "btnManageRoleMembers",
                Enabled = false
            };

            var btnAddMember = new Button
            {
                Location = new Point(550, 255),
                Size = new Size(100, 30),
                Text = "添加成员",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnAddRoleMember",
                Enabled = false
            };

            var btnRemoveMember = new Button
            {
                Location = new Point(660, 255),
                Size = new Size(100, 30),
                Text = "移除成员",
                BackColor = Color.Red,
                ForeColor = Color.White,
                Name = "btnRemoveRoleMember",
                Enabled = false
            };

            // 状态显示
            var lblStatus = new Label
            {
                Location = new Point(440, 300),
                Size = new Size(250, 30),
                ForeColor = Color.Gray,
                Name = "lblRoleStatus"
            };

            // 加载角色按钮事件
            btnLoadRoles.Click += (s, e) =>
            {
                // 检查是否通过 OAuth 登录（优先使用 OAuth 令牌）
                bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                bool useAppToken = _isExchangeOnlineLoggedIn && _exchangeOnlineService != null;

                if (!useOAuth && !useAppToken)
                {
                    lblStatus.Text = "请先在'单用户同步（O365)'或'Exchange Online 百宝箱'登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在加载角色列表...";
                lblStatus.ForeColor = Color.Blue;

                Task.Run(() =>
                {
                    try
                    {
                        // 确定使用哪个令牌和租户ID
                        string accessToken;
                        string tenantId;
                        if (useOAuth)
                        {
                            accessToken = _office365AccessToken;
                            // 从 OAuth 令牌中解析租户ID或使用已知租户
                            tenantId = _exchangeOnlineService?.TenantId ?? "common";
                            Program.GroupManagementLogger.Information("使用OAuth令牌加载角色: TenantId={TenantId}", tenantId);
                        }
                        else
                        {
                            tenantId = _exchangeOnlineService.TenantId;
                            // 使用 AccessToken (outlook.office365.com) 而不是 GraphAccessToken
                            accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                            Program.GroupManagementLogger.Information("使用应用令牌加载角色: TenantId={TenantId}", tenantId);
                        }

                        // 使用 PowerShell 获取 Exchange Online 角色组
                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                // 连接 Exchange Online
                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    throw new Exception(error.Exception?.Message ?? "连接 Exchange Online 失败");
                                }

                                ps.Commands.Clear();

                                // 获取角色组列表
                                ps.AddScript("Get-RoleGroup | Select-Object Name, DisplayName, Description, Id | ConvertTo-Json");
                                var result = ps.Invoke();

                                ps.Commands.Clear();

                                // 断开连接
                                ps.AddCommand("Disconnect-ExchangeOnline");
                                ps.AddParameter("Confirm", false);
                                ps.Invoke();

                                this.Invoke(new Action(() =>
                                {
                                    gridRoles.Rows.Clear();

                                    if (result.Count > 0)
                                    {
                                        var jsonStr = result[0].BaseObject?.ToString();
                                        if (!string.IsNullOrEmpty(jsonStr))
                                        {
                                            try
                                            {
                                                var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                                if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                                {
                                                    foreach (var role in doc.RootElement.EnumerateArray())
                                                    {
                                                        var name = role.TryGetProperty("Name", out var n) ? n.GetString() : "";
                                                        var displayName = role.TryGetProperty("DisplayName", out var dn) ? dn.GetString() : "";
                                                        var description = role.TryGetProperty("Description", out var desc) ? desc.GetString() : "";
                                                        var roleId = role.TryGetProperty("Id", out var id) ? id.GetString() : "";
                                                        // 优先使用 DisplayName，如果没有则使用 Name
                                                        var showName = !string.IsNullOrWhiteSpace(displayName) ? displayName : (!string.IsNullOrWhiteSpace(name) ? name : "(未命名)");
                                                        gridRoles.Rows.Add(showName, description ?? "", roleId);
                                                    }
                                                }
                                                else if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Object)
                                                {
                                                    // 单个角色组
                                                    var name = doc.RootElement.TryGetProperty("Name", out var n) ? n.GetString() : "";
                                                    var displayName = doc.RootElement.TryGetProperty("DisplayName", out var dn) ? dn.GetString() : "";
                                                    var description = doc.RootElement.TryGetProperty("Description", out var desc) ? desc.GetString() : "";
                                                    var roleId = doc.RootElement.TryGetProperty("Id", out var id) ? id.GetString() : "";
                                                    var showName = !string.IsNullOrWhiteSpace(displayName) ? displayName : (!string.IsNullOrWhiteSpace(name) ? name : "(未命名)");
                                                    gridRoles.Rows.Add(showName, description ?? "", roleId);
                                                }
                                            }
                                            catch { }
                                        }
                                    }

                                    lblStatus.Text = $"角色加载完成，共 {gridRoles.Rows.Count} 个角色";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            // 选中角色后显示详情
            gridRoles.SelectionChanged += (s, e) =>
            {
                if (gridRoles.SelectedRows.Count > 0)
                {
                    txtDetailName.Text = gridRoles.SelectedRows[0].Cells["DisplayName"].Value?.ToString();
                    txtDetailDesc.Text = gridRoles.SelectedRows[0].Cells["Description"].Value?.ToString();
                    txtDetailId.Text = gridRoles.SelectedRows[0].Cells["RoleId"].Value?.ToString();
                    btnManageMembers.Enabled = true;
                    btnAddMember.Enabled = true;
                    btnRemoveMember.Enabled = true;
                }
                else
                {
                    txtDetailName.Text = "";
                    txtDetailDesc.Text = "";
                    txtDetailId.Text = "";
                    btnManageMembers.Enabled = false;
                    btnAddMember.Enabled = false;
                    btnRemoveMember.Enabled = false;
                }
            };

            // 获取角色ID - 直接从Grid获取
            string getRoleId()
            {
                if (gridRoles.SelectedRows.Count > 0)
                {
                    return gridRoles.SelectedRows[0].Cells["RoleId"].Value?.ToString();
                }
                return null;
            };

            // 管理成员按钮 - 弹出对话框
            btnManageMembers.Click += (s, e) =>
            {
                if (gridRoles.SelectedRows.Count == 0) return;

                var roleName = gridRoles.SelectedRows[0].Cells["DisplayName"].Value?.ToString();
                var roleId = getRoleId();
                if (string.IsNullOrEmpty(roleId))
                {
                    lblStatus.Text = "无法获取角色ID";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var membersForm = new Form
                {
                    Width = 600,
                    Height = 450,
                    Text = $"角色成员管理 - {roleName}",
                    StartPosition = FormStartPosition.CenterParent,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var lblMembersTitle = new Label
                {
                    Text = "当前成员:",
                    Location = new Point(20, 15),
                    AutoSize = true,
                    Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
                };

                var gridMembers = new DataGridView
                {
                    Location = new Point(20, 40),
                    Size = new Size(540, 280),
                    AllowUserToAddRows = false,
                    AllowUserToDeleteRows = false,
                    ReadOnly = true,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    MultiSelect = true,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    RowHeadersVisible = false,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.FixedSingle
                };
                gridMembers.Columns.Add(new DataGridViewTextBoxColumn { Name = "DisplayName", HeaderText = "显示名称", Width = 200, ReadOnly = true });
                gridMembers.Columns.Add(new DataGridViewTextBoxColumn { Name = "Email", HeaderText = "邮箱", Width = 250, ReadOnly = true });

                var lblMemberCount = new Label
                {
                    Location = new Point(20, 330),
                    AutoSize = true,
                    ForeColor = Color.Gray
                };

                var btnRefreshMembers = new Button
                {
                    Text = "刷新",
                    Location = new Point(20, 350),
                    Size = new Size(80, 30)
                };

                var btnClose = new Button
                {
                    Text = "关闭",
                    Location = new Point(480, 350),
                    Size = new Size(80, 30)
                };

                // 加载成员方法
                Action loadRoleMembers = () =>
                {
                    lblMemberCount.Text = "正在加载...";
                    Task.Run(() =>
                    {
                        try
                        {
                            // 确定使用哪个令牌
                            string accessToken;
                            string tenantId;
                            bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                            if (useOAuth)
                            {
                                accessToken = _office365AccessToken;
                                tenantId = _exchangeOnlineService?.TenantId ?? "common";
                            }
                            else
                            {
                                accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                                tenantId = _exchangeOnlineService.TenantId;
                            }

                            // 使用 PowerShell 获取角色成员
                            using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                            {
                                runspace.Open();

                                using (var ps = System.Management.Automation.PowerShell.Create())
                                {
                                    ps.Runspace = runspace;

                                    // 连接 Exchange Online
                                    ps.AddCommand("Connect-ExchangeOnline");
                                    ps.AddParameter("AccessToken", accessToken);
                                    ps.AddParameter("Organization", tenantId);
                                    ps.AddParameter("ShowBanner", false);
                                    ps.AddParameter("ErrorAction", "Stop");
                                    ps.Invoke();

                                    if (ps.HadErrors)
                                    {
                                        var error = ps.Streams.Error[0];
                                        throw new Exception(error.Exception?.Message ?? "连接失败");
                                    }

                                    ps.Commands.Clear();

                                    // 获取角色组成员
                                    ps.AddScript($"Get-RoleGroupMember -Identity '{roleName}' -ErrorAction SilentlyContinue | ConvertTo-Json");
                                    var result = ps.Invoke();

                                    ps.Commands.Clear();

                                    // 断开连接
                                    ps.AddCommand("Disconnect-ExchangeOnline");
                                    ps.AddParameter("Confirm", false);
                                    ps.Invoke();

                                    this.Invoke(new Action(() =>
                                    {
                                        gridMembers.Rows.Clear();

                                        if (result.Count > 0)
                                        {
                                            var jsonStr = result[0].BaseObject?.ToString();
                                            if (!string.IsNullOrEmpty(jsonStr))
                                            {
                                                try
                                                {
                                                    var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                                    if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                                    {
                                                        foreach (var member in doc.RootElement.EnumerateArray())
                                                        {
                                                            var name = member.TryGetProperty("Name", out var n) ? n.GetString() : "";
                                                            var displayName = member.TryGetProperty("DisplayName", out var dn) ? dn.GetString() : "";
                                                            var email = member.TryGetProperty("WindowsLiveID", out var wl) ? wl.GetString() :
                                                                        (member.TryGetProperty("MicrosoftOnlineServicesID", out var ms) ? ms.GetString() : "");
                                                            gridMembers.Rows.Add(displayName ?? name, email);
                                                        }
                                                    }
                                                }
                                                catch { }
                                            }
                                        }

                                        lblMemberCount.Text = $"共 {gridMembers.Rows.Count} 个成员";
                                    }));
                                }
                            }
                        }
                        catch { }
                    });
                };

                btnRefreshMembers.Click += (sender, args) => loadRoleMembers();
                btnClose.Click += (sender, args) => membersForm.Close();

                membersForm.Controls.AddRange(new Control[] { lblMembersTitle, gridMembers, lblMemberCount, btnRefreshMembers, btnClose });
                membersForm.ShowDialog();
            };

            // 添加成员按钮 - 弹出对话框
            btnAddMember.Click += (s, e) =>
            {
                if (gridRoles.SelectedRows.Count == 0) return;

                var roleName = gridRoles.SelectedRows[0].Cells["DisplayName"].Value?.ToString();
                var roleId = getRoleId();
                if (string.IsNullOrEmpty(roleId))
                {
                    lblStatus.Text = "无法获取角色ID";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                // 确定使用哪个令牌
                string accessToken;
                bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                if (useOAuth)
                {
                    accessToken = _office365AccessToken;
                }
                else
                {
                    accessToken = _exchangeOnlineService.GraphAccessToken;
                }

                // 加载所有用户
                var availableUsers = new List<(string DisplayName, string Email)>();
                Task.Run(() =>
                {
                    try
                    {
                        using (var httpClient = new System.Net.Http.HttpClient())
                        {
                            httpClient.DefaultRequestHeaders.Authorization =
                                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                            var response = httpClient.GetAsync("https://graph.microsoft.com/v1.0/users?$select=displayName,mail,userPrincipalName&$top=500").Result;
                            if (response.IsSuccessStatusCode)
                            {
                                var json = response.Content.ReadAsStringAsync().Result;
                                var doc = System.Text.Json.JsonDocument.Parse(json);
                                if (doc.RootElement.TryGetProperty("value", out var users))
                                {
                                    foreach (var user in users.EnumerateArray())
                                    {
                                        var displayName = user.TryGetProperty("displayName", out var dn) ? dn.GetString() : "";
                                        var email = user.TryGetProperty("mail", out var m) ? m.GetString() :
                                                   (user.TryGetProperty("userPrincipalName", out var upn) ? upn.GetString() : "");
                                        if (!string.IsNullOrWhiteSpace(email))
                                        {
                                            availableUsers.Add((displayName ?? email, email));
                                        }
                                    }
                                }
                            }
                        }
                    }
                    catch { }
                }).Wait();

                var addForm = new Form
                {
                    Width = 500,
                    Height = 400,
                    Text = $"添加角色成员 - {roleName}",
                    StartPosition = FormStartPosition.CenterParent,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var lblSelectUser = new Label
                {
                    Text = "选择要添加的用户:",
                    Location = new Point(20, 15),
                    AutoSize = true,
                    Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
                };

                var gridUsers = new DataGridView
                {
                    Location = new Point(20, 40),
                    Size = new Size(440, 250),
                    AllowUserToAddRows = false,
                    AllowUserToDeleteRows = false,
                    ReadOnly = false,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    MultiSelect = true,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    RowHeadersVisible = false,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.FixedSingle
                };
                gridUsers.Columns.Add(new DataGridViewCheckBoxColumn { Name = "选择", Width = 40 });
                gridUsers.Columns.Add(new DataGridViewTextBoxColumn { Name = "显示名称", Width = 180, ReadOnly = true });
                gridUsers.Columns.Add(new DataGridViewTextBoxColumn { Name = "邮箱", Width = 200, ReadOnly = true });

                foreach (var user in availableUsers)
                {
                    gridUsers.Rows.Add(false, user.DisplayName, user.Email);
                }

                var lblInfo = new Label
                {
                    Text = $"共 {availableUsers.Count} 个用户",
                    Location = new Point(20, 300),
                    AutoSize = true,
                    ForeColor = Color.Gray
                };

                var btnConfirm = new Button
                {
                    Text = "添加选中",
                    Location = new Point(280, 320),
                    Size = new Size(90, 30),
                    BackColor = Color.FromArgb(0, 120, 215),
                    ForeColor = Color.White
                };

                var btnCancel = new Button
                {
                    Text = "取消",
                    Location = new Point(380, 320),
                    Size = new Size(80, 30)
                };

                btnConfirm.Click += (sender, args) =>
                {
                    var selectedUsers = new List<string>();
                    for (int i = 0; i < gridUsers.Rows.Count; i++)
                    {
                        if (Convert.ToBoolean(gridUsers.Rows[i].Cells["选择"].Value))
                        {
                            selectedUsers.Add(gridUsers.Rows[i].Cells["邮箱"].Value?.ToString());
                        }
                    }

                    if (selectedUsers.Count == 0)
                    {
                        MessageBox.Show("请至少选择一个用户", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }

                    addForm.DialogResult = DialogResult.OK;
                    addForm.Close();

                    // 确定使用哪个令牌
                    string accessTokenForAdd;
                    bool useOAuthAdd = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                    if (useOAuthAdd)
                    {
                        accessTokenForAdd = _office365AccessToken;
                    }
                    else
                    {
                        accessTokenForAdd = _exchangeOnlineService.GraphAccessToken;
                    }

                    Task.Run(() =>
                    {
                        var tenantId = _exchangeOnlineService?.TenantId ?? "common";
                        int successCount = 0;
                        foreach (var userEmail in selectedUsers)
                        {
                            try
                            {
                                using (var httpClient = new System.Net.Http.HttpClient())
                                {
                                    httpClient.DefaultRequestHeaders.Authorization =
                                        new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessTokenForAdd);

                                    // 获取用户ID
                                    var userResp = httpClient.GetAsync($"https://graph.microsoft.com/v1.0/users/{userEmail}").Result;
                                    if (!userResp.IsSuccessStatusCode) continue;

                                    var userJson = userResp.Content.ReadAsStringAsync().Result;
                                    var userDoc = System.Text.Json.JsonDocument.Parse(userJson);
                                    string userId = null;
                                    if (userDoc.RootElement.TryGetProperty("id", out var uid))
                                    {
                                        userId = uid.GetString();
                                    }
                                    if (string.IsNullOrEmpty(userId)) continue;

                                    // 添加到角色组
                                    var body = new Dictionary<string, object> { ["@odata.id"] = $"https://graph.microsoft.com/v1.0/directoryObjects/{userId}" };
                                    var jsonContent = System.Text.Json.JsonSerializer.Serialize(body);
                                    var httpContent = new System.Net.Http.StringContent(jsonContent, System.Text.Encoding.UTF8, "application/json");

                                    var response = httpClient.PostAsync($"https://graph.microsoft.com/v1.0/directoryRoles/{roleId}/members/$ref", httpContent).Result;
                                    if (response.IsSuccessStatusCode) successCount++;
                                }
                            }
                            catch { }
                        }

                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"成功添加 {successCount}/{selectedUsers.Count} 个成员";
                            lblStatus.ForeColor = successCount > 0 ? Color.Green : Color.Red;
                        }));
                    });
                };

                btnCancel.Click += (sender, args) => addForm.Close();
                addForm.Controls.AddRange(new Control[] { lblSelectUser, gridUsers, lblInfo, btnConfirm, btnCancel });
                addForm.ShowDialog();
            };

            // 移除成员按钮
            btnRemoveMember.Click += (s, e) =>
            {
                if (gridRoles.SelectedRows.Count == 0) return;

                var roleName = gridRoles.SelectedRows[0].Cells["DisplayName"].Value?.ToString();
                var roleId = getRoleId();
                if (string.IsNullOrEmpty(roleId))
                {
                    lblStatus.Text = "无法获取角色ID";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                // 确定使用哪个令牌
                string accessToken;
                bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                if (useOAuth)
                {
                    accessToken = _office365AccessToken;
                }
                else
                {
                    accessToken = _exchangeOnlineService.GraphAccessToken;
                }

                // 先加载成员列表供选择
                var currentMembers = new List<(string DisplayName, string Email, string Id)>();
                Task.Run(() =>
                {
                    try
                    {
                        using (var httpClient = new System.Net.Http.HttpClient())
                        {
                            httpClient.DefaultRequestHeaders.Authorization =
                                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);

                            var response = httpClient.GetAsync($"https://graph.microsoft.com/v1.0/directoryRoles/{roleId}/members").Result;
                            if (response.IsSuccessStatusCode)
                            {
                                var json = response.Content.ReadAsStringAsync().Result;
                                var doc = System.Text.Json.JsonDocument.Parse(json);
                                if (doc.RootElement.TryGetProperty("value", out var members))
                                {
                                    foreach (var member in members.EnumerateArray())
                                    {
                                        var displayName = member.TryGetProperty("displayName", out var dn) ? dn.GetString() : "";
                                        var mail = member.TryGetProperty("mail", out var m) ? m.GetString() :
                                                  (member.TryGetProperty("userPrincipalName", out var upn) ? upn.GetString() : "");
                                        var id = member.TryGetProperty("id", out var idProp) ? idProp.GetString() : "";
                                        currentMembers.Add((displayName ?? mail, mail, id));
                                    }
                                }
                            }
                        }
                    }
                    catch { }
                }).Wait();

                if (currentMembers.Count == 0)
                {
                    MessageBox.Show("该角色没有成员", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                var removeForm = new Form
                {
                    Width = 500,
                    Height = 400,
                    Text = $"移除角色成员 - {roleName}",
                    StartPosition = FormStartPosition.CenterParent,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var lblSelectMember = new Label
                {
                    Text = "选择要移除的成员:",
                    Location = new Point(20, 15),
                    AutoSize = true,
                    Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
                };

                var gridMembers = new DataGridView
                {
                    Location = new Point(20, 40),
                    Size = new Size(440, 250),
                    AllowUserToAddRows = false,
                    AllowUserToDeleteRows = false,
                    ReadOnly = false,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    MultiSelect = true,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    RowHeadersVisible = false,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.FixedSingle
                };
                gridMembers.Columns.Add(new DataGridViewCheckBoxColumn { Name = "选择", Width = 40 });
                gridMembers.Columns.Add(new DataGridViewTextBoxColumn { Name = "显示名称", Width = 180, ReadOnly = true });
                gridMembers.Columns.Add(new DataGridViewTextBoxColumn { Name = "邮箱", Width = 200, ReadOnly = true });

                foreach (var member in currentMembers)
                {
                    gridMembers.Rows.Add(false, member.DisplayName, member.Email);
                }

                var btnConfirmRemove = new Button
                {
                    Text = "移除选中",
                    Location = new Point(280, 320),
                    Size = new Size(90, 30),
                    BackColor = Color.Red,
                    ForeColor = Color.White
                };

                var btnCancelRemove = new Button
                {
                    Text = "取消",
                    Location = new Point(380, 320),
                    Size = new Size(80, 30)
                };

                btnConfirmRemove.Click += (sender, args) =>
                {
                    var selectedIndices = new List<int>();
                    for (int i = 0; i < gridMembers.Rows.Count; i++)
                    {
                        if (Convert.ToBoolean(gridMembers.Rows[i].Cells["选择"].Value))
                        {
                            selectedIndices.Add(i);
                        }
                    }

                    if (selectedIndices.Count == 0)
                    {
                        MessageBox.Show("请至少选择一个成员", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }

                    if (MessageBox.Show($"确定要移除 {selectedIndices.Count} 个成员吗？", "确认", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
                    {
                        return;
                    }

                    removeForm.DialogResult = DialogResult.OK;
                    removeForm.Close();

                    // 确定使用哪个令牌 (重新获取，因为之前的变量作用域已结束)
                    string accessTokenForRemove;
                    bool useOAuthRemove = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                    if (useOAuthRemove)
                    {
                        accessTokenForRemove = _office365AccessToken;
                    }
                    else
                    {
                        accessTokenForRemove = _exchangeOnlineService.GraphAccessToken;
                    }

                    Task.Run(() =>
                    {
                        int successCount = 0;
                        foreach (var idx in selectedIndices)
                        {
                            var memberId = currentMembers[idx].Id;
                            try
                            {
                                using (var httpClient = new System.Net.Http.HttpClient())
                                {
                                    httpClient.DefaultRequestHeaders.Authorization =
                                        new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessTokenForRemove);

                                    var response = httpClient.DeleteAsync($"https://graph.microsoft.com/v1.0/directoryRoles/{roleId}/members/{memberId}").Result;
                                    if (response.IsSuccessStatusCode) successCount++;
                                }
                            }
                            catch { }
                        }

                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"成功移除 {successCount}/{selectedIndices.Count} 个成员";
                            lblStatus.ForeColor = successCount > 0 ? Color.Green : Color.Red;
                        }));
                    });
                };

                btnCancelRemove.Click += (sender, args) => removeForm.Close();
                removeForm.Controls.AddRange(new Control[] { lblSelectMember, gridMembers, btnConfirmRemove, btnCancelRemove });
                removeForm.ShowDialog();
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblRoleList);
            panel.Controls.Add(btnLoadRoles);
            panel.Controls.Add(gridRoles);
            panel.Controls.Add(lblRoleDetail);
            panel.Controls.Add(lblDetailName);
            panel.Controls.Add(txtDetailName);
            panel.Controls.Add(lblDetailDesc);
            panel.Controls.Add(txtDetailDesc);
            panel.Controls.Add(lblDetailId);
            panel.Controls.Add(txtDetailId);
            panel.Controls.Add(lblActions);
            panel.Controls.Add(btnManageMembers);
            panel.Controls.Add(btnAddMember);
            panel.Controls.Add(btnRemoveMember);
            panel.Controls.Add(lblStatus);

            return panel;
        }

        private Panel CreateAppManagementPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "Office 365 应用程序管理",
                Location = new Point(20, 20),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 说明文字
            var lblNote = new Label
            {
                Text = "查看和管理Office 365中各种应用程序服务的状态",
                Location = new Point(20, 55),
                AutoSize = true,
                ForeColor = Color.Gray
            };

            // 加载服务状态按钮
            var btnLoadServices = new Button
            {
                Location = new Point(20, 90),
                Size = new Size(150, 35),
                Text = "加载服务状态",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnLoadServices"
            };

            // 状态显示
            var lblStatus = new Label
            {
                Location = new Point(180, 95),
                Size = new Size(300, 30),
                ForeColor = Color.Gray,
                Name = "lblAppStatus"
            };

            // 服务列表
            var lblServices = new Label
            {
                Text = "服务列表:",
                Location = new Point(20, 140),
                AutoSize = true
            };

            var lstServices = new ListBox
            {
                Location = new Point(20, 160),
                Size = new Size(550, 300),
                Font = new Font("Consolas", 10F),
                Name = "lstServices"
            };

            // 按钮点击事件
            btnLoadServices.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在加载服务状态...";
                lblStatus.ForeColor = Color.Blue;
                lstServices.Items.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        var services = new List<(string Name, string Status)>();

                        // 获取订阅信息
                        try
                        {
                            var subs = _exchangeOnlineService.GraphClient.SubscribedSkus.GetAsync().Result;
                            if (subs?.Value != null)
                            {
                                foreach (var sub in subs.Value)
                                {
                                    services.Add(($"订阅: {sub.SkuPartNumber}", $"已用: {sub.ConsumedUnits}"));
                                }
                            }
                        }
                        catch { services.Add(("订阅信息", "权限不足")); }

                        this.Invoke(new Action(() =>
                        {
                            lstServices.Items.Add("=== Office 365 服务状态 ===");
                            lstServices.Items.Add("");
                            foreach (var svc in services)
                            {
                                lstServices.Items.Add($"{svc.Name}: {svc.Status}");
                            }
                            lstServices.Items.Add("");
                            lstServices.Items.Add("注: 如显示权限不足，请在Azure AD添加Directory.Read.All权限");
                            lblStatus.Text = "加载完成";
                            lblStatus.ForeColor = Color.Green;
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(btnLoadServices);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblServices);
            panel.Controls.Add(lstServices);

            return panel;
        }

        private Panel CreateConnectorManagementPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "Exchange Online 连接器管理",
                Location = new Point(20, 20),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 说明文字
            var lblNote = new Label
            {
                Text = "查看和管理发送连接器和接收连接器",
                Location = new Point(20, 55),
                AutoSize = true,
                ForeColor = Color.Gray
            };

            // 加载连接器按钮
            var btnLoadConnectors = new Button
            {
                Location = new Point(20, 90),
                Size = new Size(150, 35),
                Text = "加载连接器",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnLoadConnectors"
            };

            // 状态显示
            var lblStatus = new Label
            {
                Location = new Point(180, 95),
                Size = new Size(300, 30),
                ForeColor = Color.Gray,
                Name = "lblConnectorStatus"
            };

            // 发送连接器标签
            var lblSendConnectors = new Label
            {
                Text = "发送连接器:",
                Location = new Point(20, 140),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 发送连接器表格
            var gridSendConnectors = new DataGridView
            {
                Location = new Point(20, 165),
                Size = new Size(750, 180),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle,
                Name = "gridSendConnectors"
            };

            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "Name", HeaderText = "名称", Width = 150 });
            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "Enabled", HeaderText = "启用", Width = 60 });
            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "Status", HeaderText = "状态", Width = 80 });
            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "SmartHosts", HeaderText = "智能主机", Width = 150 });
            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "SmartHostType", HeaderText = "智能主机类型", Width = 120 });
            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "MXRecord", HeaderText = "MX记录", Width = 100 });
            gridSendConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "BridgeheadServer", HeaderText = "桥接服务器", Width = 100 });

            // 接收连接器标签
            var lblReceiveConnectors = new Label
            {
                Text = "接收连接器:",
                Location = new Point(20, 360),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 接收连接器表格
            var gridReceiveConnectors = new DataGridView
            {
                Location = new Point(20, 385),
                Size = new Size(750, 200),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle,
                Name = "gridReceiveConnectors"
            };

            gridReceiveConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "Name", HeaderText = "名称", Width = 180 });
            gridReceiveConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "Enabled", HeaderText = "启用", Width = 60 });
            gridReceiveConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "Status", HeaderText = "状态", Width = 80 });
            gridReceiveConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "RemoteIPRanges", HeaderText = "远程IP范围", Width = 200 });
            gridReceiveConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "AuthMechanisms", HeaderText = "认证机制", Width = 150 });
            gridReceiveConnectors.Columns.Add(new DataGridViewTextBoxColumn { Name = "PermissionGroups", HeaderText = "权限组", Width = 120 });

            // 按钮点击事件
            btnLoadConnectors.Click += (s, e) =>
            {
                // 检查是否通过 OAuth 登录（优先使用 OAuth 令牌）
                bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                bool useAppToken = _isExchangeOnlineLoggedIn && _exchangeOnlineService != null;

                if (!useOAuth && !useAppToken)
                {
                    lblStatus.Text = "请先在'单用户同步（O365)'或'Exchange Online 百宝箱'登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在加载连接器...";
                lblStatus.ForeColor = Color.Blue;
                gridSendConnectors.Rows.Clear();
                gridReceiveConnectors.Rows.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        // 确定使用哪个令牌和租户ID
                        string accessToken;
                        string tenantId;
                        if (useOAuth)
                        {
                            accessToken = _office365AccessToken;
                            tenantId = _exchangeOnlineService?.TenantId ?? "common";
                        }
                        else
                        {
                            tenantId = _exchangeOnlineService.TenantId;
                            accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                        }

                        var logPath = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs", "O365Online", "Connector", $"Connector_{DateTime.Now:yyyyMMdd}.log");
                        var logDir = System.IO.Path.GetDirectoryName(logPath);
                        if (!System.IO.Directory.Exists(logDir))
                            System.IO.Directory.CreateDirectory(logDir);

                        void Log(string msg)
                        {
                            System.IO.File.AppendAllText(logPath, $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {msg}\n");
                        }

                        Log($"开始加载连接器. TenantId: {tenantId}, OAuth: {useOAuth}, AppToken: {useAppToken}");
                        Log($"Token长度: {accessToken?.Length ?? 0}");

                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                // 连接 Exchange Online
                                Log("正在连接 Exchange Online...");
                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    var errMsg = error.Exception?.Message ?? "连接 Exchange Online 失败";
                                    Log($"连接失败: {errMsg}");
                                    throw new Exception(errMsg);
                                }

                                Log("连接成功!");
                                ps.Commands.Clear();

                                // 设置本地模块路径并导入 Exchange Online 模块
                                Log("导入 Exchange Online 模块...");
                                var localModulePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "PowerShellModules", "ExchangeOnlineManagement", "3.9.2", "netFramework");
                                ps.AddScript($@"
                                    $env:PSModulePath = '{localModulePath}' + ';' + $env:PSModulePath
                                    Import-Module '{Path.Combine(localModulePath, "ExchangeOnlineManagement.psm1")}' -DisableNameChecking -ErrorAction Stop
                                    Get-Module -Name ExchangeOnlineManagement | Select-Object -ExpandProperty ExportedCommands
                                ");
                                var moduleResult = ps.Invoke();
                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    Log($"模块导入错误: {error.Exception?.Message}");
                                }
                                else
                                {
                                    Log($"已导入模块导出的命令数: {moduleResult.Count}");
                                }
                                ps.Commands.Clear();

                                // 列出所有ExchangeOnlineManagement模块的命令
                                Log("列出模块所有命令...");
                                ps.AddScript($@"
                                    $module = Get-Module -Name ExchangeOnlineManagement
                                    Write-Output ""=== Module Path: $($module.Path) ===""
                                    $allCommands = Get-Command -Module ExchangeOnlineManagement
                                    Write-Output ""=== Total Commands: $($allCommands.Count) ===""
                                    foreach ($cmd in $allCommands) {{
                                        Write-Output ""CMD: $($cmd.Name)""
                                    }}
                                ");
                                var sendResult = ps.Invoke();

                                // 输出详细日志
                                for (int i = 0; i < sendResult.Count; i++)
                                {
                                    Log($"发送连接器结果[{i}]: {sendResult[i]}");
                                }

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    Log($"获取发送连接器错误: {error.Exception?.Message}");
                                    var errorRecord = error.ToString();
                                    Log($"详细错误: {errorRecord}");
                                }

                                ps.Commands.Clear();

                                // 尝试通过Graph API (Beta)获取连接器信息
                                Log("尝试通过Graph API (Beta)获取连接器信息...");
                                try
                                {
                                    var graphTokenUrl = $"https://login.microsoftonline.com/{tenantId}/oauth2/v2.0/token";
                                    var graphScope = "https://graph.microsoft.com/.default";
                                    // 从已保存的配置中获取AppId和ClientSecret，如果没有则使用默认值
                                    var appId = "dfe93cc7-f090-45ab-a77a-f0ceef160649";
                                    var clientSecret = "";
                                    // 尝试从配置中读取
                                    try {
                                        var settingsPath = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "config", "o365_accounts.json");
                                        if (System.IO.File.Exists(settingsPath)) {
                                            var json = System.Text.Json.JsonDocument.Parse(System.IO.File.ReadAllText(settingsPath));
                                            if (json.RootElement.TryGetProperty("appId", out var a)) appId = a.GetString() ?? appId;
                                            if (json.RootElement.TryGetProperty("clientSecret", out var c)) clientSecret = c.GetString() ?? "";
                                        }
                                    } catch { }

                                    var graphPostData = $"client_id={Uri.EscapeDataString(appId)}&scope={Uri.EscapeDataString(graphScope)}&client_secret={Uri.EscapeDataString(clientSecret)}&grant_type=client_credentials";
                                    var graphClient = new System.Net.Http.HttpClient();
                                    var graphContent = new System.Net.Http.StringContent(graphPostData, System.Text.Encoding.UTF8, "application/x-www-form-urlencoded");
                                    var graphResponse = graphClient.PostAsync(graphTokenUrl, graphContent).Result;
                                    var graphResponseContent = graphResponse.Content.ReadAsStringAsync().Result;

                                    if (graphResponse.IsSuccessStatusCode)
                                    {
                                        using (var json = System.Text.Json.JsonDocument.Parse(graphResponseContent))
                                        {
                                            var graphToken = json.RootElement.GetProperty("access_token").GetString();
                                            Log($"获取到Graph Token, 长度: {graphToken?.Length ?? 0}");

                                            // 调用Graph Beta API获取发送连接器
                                            var outboundClient = new System.Net.Http.HttpClient();
                                            outboundClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", graphToken);
                                            var outboundUrl = "https://graph.microsoft.com/beta/admin/exchange/outboundConnectors";
                                            var outboundResponse = outboundClient.GetAsync(outboundUrl).Result;
                                            var outboundContent = outboundResponse.Content.ReadAsStringAsync().Result;
                                            Log($"Graph API发送连接器响应: {outboundContent}");

                                            // 调用Graph Beta API获取接收连接器
                                            var inboundClient = new System.Net.Http.HttpClient();
                                            inboundClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", graphToken);
                                            var inboundUrl = "https://graph.microsoft.com/beta/admin/exchange/inboundConnectors";
                                            var inboundResponse = inboundClient.GetAsync(inboundUrl).Result;
                                            var inboundContent = inboundResponse.Content.ReadAsStringAsync().Result;
                                            Log($"Graph API接收连接器响应: {inboundContent}");
                                        }
                                    }
                                    else
                                    {
                                        Log($"获取Graph Token失败: {graphResponseContent}");
                                    }
                                }
                                catch (Exception ex)
                                {
                                    Log($"Graph API调用错误: {ex.Message}");
                                }

                                ps.Commands.Clear();

                                // 获取接收连接器
                                Log("获取接收连接器...");
                                ps.AddScript(@"
                                    $module = Get-Module -Name ExchangeOnlineManagement
                                    if (-not $module) {
                                        Import-Module ExchangeOnlineManagement -DisableNameChecking
                                    }

                                    try {
                                        $connectors = Get-ReceiveConnector -ErrorAction Stop
                                        Write-Output ""Found $($connectors.Count) receive connectors""
                                        if ($connectors) {
                                            $connectors | Select-Object Name, Enabled, Status | ConvertTo-Json -Compress
                                        }
                                    } catch {
                                        Write-Output ""Error: $($_.Exception.Message)""
                                    }
                                ");
                                var receiveResult = ps.Invoke();

                                for (int i = 0; i < receiveResult.Count; i++)
                                {
                                    Log($"接收连接器结果[{i}]: {receiveResult[i]}");
                                }

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    Log($"获取接收连接器错误: {error.Exception?.Message}");
                                }

                                ps.Commands.Clear();

                                // 断开连接
                                ps.AddCommand("Disconnect-ExchangeOnline");
                                ps.AddParameter("Confirm", false);
                                ps.Invoke();

                                Log($"发送连接器结果数量: {sendResult.Count}");
                                Log($"接收连接器结果数量: {receiveResult.Count}");

                                // 处理发送连接器数据
                                var sendConnectors = new List<Dictionary<string, string>>();
                                if (sendResult.Count > 0)
                                {
                                    var jsonStr = sendResult[0].BaseObject?.ToString();
                                    if (!string.IsNullOrEmpty(jsonStr))
                                    {
                                        try
                                        {
                                            var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                            {
                                                foreach (var item in doc.RootElement.EnumerateArray())
                                                {
                                                    var dict = new Dictionary<string, string>();
                                                    foreach (var prop in item.EnumerateObject())
                                                    {
                                                        dict[prop.Name] = prop.Value.ToString();
                                                    }
                                                    sendConnectors.Add(dict);
                                                }
                                            }
                                        }
                                        catch { }
                                    }
                                }

                                // 处理接收连接器数据
                                var receiveConnectors = new List<Dictionary<string, string>>();
                                if (receiveResult.Count > 0)
                                {
                                    var jsonStr = receiveResult[0].BaseObject?.ToString();
                                    if (!string.IsNullOrEmpty(jsonStr))
                                    {
                                        try
                                        {
                                            var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                            {
                                                foreach (var item in doc.RootElement.EnumerateArray())
                                                {
                                                    var dict = new Dictionary<string, string>();
                                                    foreach (var prop in item.EnumerateObject())
                                                    {
                                                        dict[prop.Name] = prop.Value.ToString();
                                                    }
                                                    receiveConnectors.Add(dict);
                                                }
                                            }
                                        }
                                        catch { }
                                    }
                                }

                                this.Invoke(new Action(() =>
                                {
                                    // 填充发送连接器
                                    foreach (var conn in sendConnectors)
                                    {
                                        gridSendConnectors.Rows.Add(
                                            conn.TryGetValue("Name", out var name1) ? name1 : "",
                                            conn.TryGetValue("Enabled", out var enabled1) ? enabled1 : "",
                                            conn.TryGetValue("Status", out var status1) ? status1 : "",
                                            conn.TryGetValue("SmartHosts", out var sh) ? sh : "",
                                            conn.TryGetValue("SmartHostType", out var sht) ? sht : "",
                                            conn.TryGetValue("MXRecordSet", out var mx) ? mx : "",
                                            conn.TryGetValue("BridgeheadServer", out var bh) ? bh : ""
                                        );
                                    }

                                    // 填充接收连接器
                                    foreach (var conn in receiveConnectors)
                                    {
                                        gridReceiveConnectors.Rows.Add(
                                            conn.TryGetValue("Name", out var name2) ? name2 : "",
                                            conn.TryGetValue("Enabled", out var enabled2) ? enabled2 : "",
                                            conn.TryGetValue("Status", out var status2) ? status2 : "",
                                            conn.TryGetValue("RemoteIPRanges", out var r) ? r : "",
                                            conn.TryGetValue("AuthMechanisms", out var a) ? a : "",
                                            conn.TryGetValue("PermissionGroups", out var p) ? p : ""
                                        );
                                    }

                                    lblStatus.Text = $"发送连接器: {sendConnectors.Count}, 接收连接器: {receiveConnectors.Count}";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(btnLoadConnectors);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblSendConnectors);
            panel.Controls.Add(gridSendConnectors);
            panel.Controls.Add(lblReceiveConnectors);
            panel.Controls.Add(gridReceiveConnectors);

            return panel;
        }

        private Panel CreateMobileDeviceManagementPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "移动设备管理",
                Location = new Point(20, 20),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 说明文字
            var lblNote = new Label
            {
                Text = "查看与Office 365邮箱关联的移动设备列表",
                Location = new Point(20, 55),
                AutoSize = true,
                ForeColor = Color.Gray
            };

            // 加载设备按钮
            var btnLoadDevices = new Button
            {
                Location = new Point(20, 90),
                Size = new Size(150, 35),
                Text = "加载移动设备",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnLoadMobileDevices"
            };

            // 状态显示
            var lblStatus = new Label
            {
                Location = new Point(180, 95),
                Size = new Size(300, 30),
                ForeColor = Color.Gray,
                Name = "lblMobileDeviceStatus"
            };

            // 用户筛选器
            var lblUserFilter = new Label { Text = "用户筛选:", Location = new Point(500, 95), AutoSize = true };
            var cmbUserFilter = new ComboBox
            {
                Location = new Point(560, 92),
                Size = new Size(200, 25),
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbUserFilter.Items.Add("全部用户");
            cmbUserFilter.SelectedIndex = 0;

            // 设备列表表格
            var gridDevices = new DataGridView
            {
                Location = new Point(20, 140),
                Size = new Size(750, 350),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle,
                Name = "gridMobileDevices"
            };

            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "UserDisplayName", HeaderText = "用户显示名", Width = 120 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "UserPrincipalName", HeaderText = "用户UPN", Width = 180 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "DeviceType", HeaderText = "设备类型", Width = 80 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "DeviceModel", HeaderText = "设备型号", Width = 100 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "DeviceOS", HeaderText = "操作系统", Width = 100 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "DeviceVersion", HeaderText = "系统版本", Width = 80 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "LastSyncTime", HeaderText = "最后同步时间", Width = 140 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "IsRemoteWipeSupported", HeaderText = "支持远程擦除", Width = 80 });
            gridDevices.Columns.Add(new DataGridViewTextBoxColumn { Name = "ComplianceStatus", HeaderText = "合规状态", Width = 80 });

            // 按钮点击事件
            btnLoadDevices.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在'Exchange Online 百宝箱'登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在加载移动设备...";
                lblStatus.ForeColor = Color.Blue;
                gridDevices.Rows.Clear();

                _mobileDevicesList.Clear();
                _mobileDeviceUsers.Clear();

                Task.Run(() =>
                {
                    try
                    {

                        // 使用 Get-MobileDevice 获取移动设备
                        string accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                        string tenantId = _exchangeOnlineService.TenantId;

                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                // 连接 Exchange Online
                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    throw new Exception(error.Exception?.Message ?? "连接 Exchange Online 失败");
                                }

                                ps.Commands.Clear();

                                // 获取移动设备列表
                                ps.AddScript("Get-MobileDevice | Select-Object UserDisplayName, UserPrincipalName, DeviceType, DeviceModel, DeviceOS, DeviceVersion, LastSyncTime, IsRemoteWipeSupported, ComplianceStatus | ConvertTo-Json");
                                var result = ps.Invoke();

                                ps.Commands.Clear();

                                // 断开连接
                                ps.AddCommand("Disconnect-ExchangeOnline");
                                ps.AddParameter("Confirm", false);
                                ps.Invoke();

                                var devices = new List<Dictionary<string, string>>();
                                if (result.Count > 0)
                                {
                                    var jsonStr = result[0].BaseObject?.ToString();
                                    if (!string.IsNullOrEmpty(jsonStr))
                                    {
                                        try
                                        {
                                            var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                            {
                                                foreach (var item in doc.RootElement.EnumerateArray())
                                                {
                                                    var dict = new Dictionary<string, string>();
                                                    foreach (var prop in item.EnumerateObject())
                                                    {
                                                        dict[prop.Name] = prop.Value.ToString();
                                                    }
                                                    devices.Add(dict);
                                                }
                                            }
                                        }
                                        catch { }
                                    }
                                }

                                this.Invoke(new Action(() =>
                                {
                                    _mobileDevicesList.Clear();
                                    _mobileDeviceUsers.Clear();

                                    // 收集唯一用户名
                                    foreach (var dev in devices)
                                    {
                                        _mobileDevicesList.Add(dev);
                                        var userDisplayName = dev.TryGetValue("UserDisplayName", out var udn) ? udn : "";
                                        if (!string.IsNullOrEmpty(userDisplayName) && !_mobileDeviceUsers.Contains(userDisplayName))
                                        {
                                            _mobileDeviceUsers.Add(userDisplayName);
                                        }
                                    }

                                    // 填充筛选下拉框
                                    cmbUserFilter.Items.Clear();
                                    cmbUserFilter.Items.Add("全部用户");
                                    cmbUserFilter.Items.AddRange(_mobileDeviceUsers.OrderBy(u => u).ToArray());
                                    cmbUserFilter.SelectedIndex = 0;

                                    // 显示所有设备
                                    foreach (var dev in _mobileDevicesList)
                                    {
                                        var userDisplayName = dev.TryGetValue("UserDisplayName", out var udn) ? udn : "";
                                        var upn = dev.TryGetValue("UserPrincipalName", out var upnVal) ? upnVal : "";

                                        // 如果 UPN 为空，尝试用显示名构造
                                        if (string.IsNullOrEmpty(upn) && !string.IsNullOrEmpty(userDisplayName))
                                        {
                                            upn = userDisplayName;
                                        }

                                        gridDevices.Rows.Add(
                                            userDisplayName,
                                            upn,
                                            dev.TryGetValue("DeviceType", out var dt) ? dt : "",
                                            dev.TryGetValue("DeviceModel", out var dm) ? dm : "",
                                            dev.TryGetValue("DeviceOS", out var os) ? os : "",
                                            dev.TryGetValue("DeviceVersion", out var v) ? v : "",
                                            dev.TryGetValue("LastSyncTime", out var lst) ? lst : "",
                                            dev.TryGetValue("IsRemoteWipeSupported", out var irws) ? irws : "",
                                            dev.TryGetValue("ComplianceStatus", out var cs) ? cs : ""
                                        );
                                    }

                                    lblStatus.Text = $"已加载 {devices.Count} 个移动设备，共 {_mobileDeviceUsers.Count} 个用户";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"加载失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(btnLoadDevices);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblUserFilter);
            panel.Controls.Add(cmbUserFilter);
            panel.Controls.Add(gridDevices);

            // 用户筛选事件
            cmbUserFilter.SelectedIndexChanged += (s, e) =>
            {
                gridDevices.Rows.Clear();
                var selectedUser = cmbUserFilter.SelectedItem?.ToString();

                foreach (var dev in _mobileDevicesList)
                {
                    var userDisplayName = dev.TryGetValue("UserDisplayName", out var udn) ? udn : "";

                    if (selectedUser == "全部用户" || userDisplayName == selectedUser)
                    {
                        gridDevices.Rows.Add(
                            userDisplayName,
                            dev.TryGetValue("UserPrincipalName", out var upn) ? upn : "",
                            dev.TryGetValue("DeviceType", out var dt) ? dt : "",
                            dev.TryGetValue("DeviceModel", out var dm) ? dm : "",
                            dev.TryGetValue("DeviceOS", out var os) ? os : "",
                            dev.TryGetValue("DeviceVersion", out var v) ? v : "",
                            dev.TryGetValue("LastSyncTime", out var lst) ? lst : "",
                            dev.TryGetValue("IsRemoteWipeSupported", out var irws) ? irws : "",
                            dev.TryGetValue("ComplianceStatus", out var cs) ? cs : ""
                        );
                    }
                }
            };

            return panel;
        }

        private Panel CreateMailTrafficSearchPanel()
