            // 搜索按钮
            var btnSearch = new Button
            {
                Location = new Point(650, 125),
                Size = new Size(120, 30),
                Text = "搜索",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnSearchMailTraffic"
            };

            // 状态显示
