            {
                Location = new Point(20, 165),
                Size = new Size(300, 30),
                ForeColor = Color.Gray,
                Name = "lblMailTrafficStatus"
            };

            // 结果表格
            var gridTraffic = new DataGridView
            {
                Location = new Point(20, 200),
                Size = new Size(1050, 320),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle,
                Name = "gridMailTraffic",
                ScrollBars = ScrollBars.Both
            };

            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "Received", HeaderText = "时间", Width = 140 });
            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "SenderAddress", HeaderText = "发件人", Width = 170 });
            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "RecipientAddress", HeaderText = "收件人", Width = 170 });
            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "Subject", HeaderText = "主题", Width = 230 });
            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "Status", HeaderText = "状态", Width = 70 });
            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "TotalBytes", HeaderText = "大小", Width = 70 });
            gridTraffic.Columns.Add(new DataGridViewTextBoxColumn { Name = "MessageTraceId", HeaderText = "追踪ID", Width = 170 });

            // 右键菜单
            var contextMenu = new ContextMenuStrip();
            var menuTraceInfo = new ToolStripMenuItem("查看Trace信息");
            var menuHeaders = new ToolStripMenuItem("查看邮件头信息");
            var menuAnalyzeHeaders = new ToolStripMenuItem("分析邮件头安全性");
            var menuPasteHeaders = new ToolStripMenuItem("粘贴邮件头分析");

            // 邮件头分析函数
            void AnalyzeEmailHeaders(string headersText, RichTextBox txtOutput)
            {
                txtOutput.Clear();
                txtOutput.AppendText("=== 邮件头安全分析 ===\n\n");

                if (string.IsNullOrWhiteSpace(headersText))
                {
                    txtOutput.AppendText("未提供邮件头内容\n");
                    return;
                }

                var lines = headersText.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                var headersDict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                var receivedHeaders = new List<string>();
                string authResults = "";

                // 解析邮件头
                foreach (var line in lines)
                {
                    var colonIndex = line.IndexOf(':');
                    if (colonIndex > 0)
                    {
                        var name = line.Substring(0, colonIndex).Trim();
                        var value = line.Substring(colonIndex + 1).Trim();
                        headersDict[name] = value;

                        if (name.Equals("Received", StringComparison.OrdinalIgnoreCase))
                            receivedHeaders.Add(value);
                        if (name.Equals("Authentication-Results", StringComparison.OrdinalIgnoreCase))
                            authResults = value;
                    }
                }

                // 1. SPF/DKIM/DMARC 分析
                txtOutput.AppendText("【认证结果】\n");
                var spf = "未找到";
                var dkim = "未找到";
                var dmarc = "未找到";

                if (!string.IsNullOrEmpty(authResults))
                {
                    if (authResults.Contains("spf="))
                    {
                        var spfMatch = System.Text.RegularExpressions.Regex.Match(authResults, @"spf=(\w+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                        if (spfMatch.Success) spf = spfMatch.Groups[1].Value;
                    }
                    if (authResults.Contains("dkim="))
                    {
                        var dkimMatch = System.Text.RegularExpressions.Regex.Match(authResults, @"dkim=(\w+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                        if (dkimMatch.Success) dkim = dkimMatch.Groups[1].Value;
                    }
                    if (authResults.Contains("dmarc="))
                    {
                        var dmarcMatch = System.Text.RegularExpressions.Regex.Match(authResults, @"dmarc=(\w+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                        if (dmarcMatch.Success) dmarc = dmarcMatch.Groups[1].Value;
                    }
                }

                // SPF 状态
                var spfColor = spf.ToLower() == "pass" ? Color.Green : (spf.ToLower() == "fail" ? Color.Red : Color.Orange);
                txtOutput.SelectionColor = spfColor;
                txtOutput.AppendText($"  SPF: {spf}\n");
                txtOutput.SelectionColor = txtOutput.ForeColor;

                // DKIM 状态
                var dkimColor = dkim.ToLower() == "pass" ? Color.Green : (dkim.ToLower() == "fail" ? Color.Red : Color.Orange);
                txtOutput.SelectionColor = dkimColor;
                txtOutput.AppendText($"  DKIM: {dkim}\n");
                txtOutput.SelectionColor = txtOutput.ForeColor;

                // DMARC 状态
                var dmarcColor = dmarc.ToLower() == "pass" ? Color.Green : (dmarc.ToLower() == "fail" ? Color.Red : Color.Orange);
                txtOutput.SelectionColor = dmarcColor;
                txtOutput.AppendText($"  DMARC: {dmarc}\n");
                txtOutput.SelectionColor = txtOutput.ForeColor;

                // 2. 路由路径分析
                txtOutput.AppendText(string.Format("\n【邮件路由路径】(共 {0} 跳)\n", receivedHeaders.Count));
                for (int i = receivedHeaders.Count - 1; i >= 0; i--)
                {
                    txtOutput.AppendText(string.Format("  [{0}] {1}\n", receivedHeaders.Count - i, receivedHeaders[i]));
                }

                // 3. 发件人信息
                txtOutput.AppendText("\n【发件人信息】\n");
                if (headersDict.TryGetValue("From", out var from))
                    txtOutput.AppendText(string.Format("  From: {0}\n", from));
                if (headersDict.TryGetValue("Reply-To", out var replyTo))
                    txtOutput.AppendText(string.Format("  Reply-To: {0}\n", replyTo));
                if (headersDict.TryGetValue("Return-Path", out var returnPath))
                    txtOutput.AppendText(string.Format("  Return-Path: {0}\n", returnPath));
                if (headersDict.TryGetValue("X-Mailer", out var xMailer))
                    txtOutput.AppendText(string.Format("  X-Mailer: {0}\n", xMailer));

                // 4. 风险评估
                txtOutput.AppendText("\n【安全风险评估】\n");
                int riskLevel = 0;
                var risks = new List<string>();

                // 检查SPF
                if (spf.ToLower() == "fail")
                {
                    riskLevel++;
                    risks.Add("SPF 认证失败 - 发件服务器可能伪造");
                }

                // 检查DKIM
                if (dkim.ToLower() == "fail")
                {
                    riskLevel++;
                    risks.Add("DKIM 签名验证失败 - 邮件可能被篡改");
                }
                else if (dkim == "未找到")
                {
                    riskLevel++;
                    risks.Add("缺少 DKIM 签名 - 无法验证邮件完整性");
                }

                // 检查Return-Path与From一致性
                if (headersDict.TryGetValue("From", out var from2) && headersDict.TryGetValue("Return-Path", out var returnPath2))
                {
                    var fromDomain = ExtractDomain(from2);
                    var returnPathDomain = ExtractDomain(returnPath2);
                    if (!fromDomain.Equals(returnPathDomain, StringComparison.OrdinalIgnoreCase))
                    {
                        riskLevel += 2;
                        risks.Add("Return-Path 与 From 域名不一致 - 可能是伪造邮件");
                    }
                }

                // 检查可疑关键词
                var subject = headersDict.TryGetValue("Subject", out var sub) ? sub : "";
                var suspiciousKeywords = new[] { "紧急", "账户", "密码", "银行", "验证", "点击", "登录" };
                foreach (var kw in suspiciousKeywords)
                {
                    if (subject.Contains(kw))
                    {
                        riskLevel++;
                        risks.Add(string.Format("主题包含可疑关键词: {0}", kw));
                        break;
                    }
                }

                // 显示风险等级
                var riskColor = riskLevel == 0 ? Color.Green : (riskLevel <= 2 ? Color.Orange : Color.Red);
                txtOutput.SelectionColor = riskColor;
                txtOutput.AppendText(string.Format("  风险等级: {0}/10\n", Math.Min(riskLevel * 2, 10)));
                txtOutput.SelectionColor = txtOutput.ForeColor;

                if (risks.Count > 0)
                {
                    txtOutput.AppendText("  发现的问题:\n");
                    foreach (var risk in risks)
                    {
                        txtOutput.SelectionColor = Color.Red;
                        txtOutput.AppendText(string.Format("    ! {0}\n", risk));
                        txtOutput.SelectionColor = txtOutput.ForeColor;
                    }
                }
                else
                {
                    txtOutput.SelectionColor = Color.Green;
                    txtOutput.AppendText("  未发现明显风险\n");
                    txtOutput.SelectionColor = txtOutput.ForeColor;
                }

                // 5. 原始邮件头
                txtOutput.AppendText("\n【原始邮件头】\n");
                txtOutput.AppendText(headersText);
            }

            string ExtractDomain(string emailOrHeader)
            {
                if (string.IsNullOrEmpty(emailOrHeader)) return "";
                var match = System.Text.RegularExpressions.Regex.Match(emailOrHeader, @"@([^\s<>]+)");
                return match.Success ? match.Groups[1].Value : emailOrHeader;
            }

            // 查看Trace信息
            menuTraceInfo.Click += (s, e) =>
            {
                if (gridTraffic.SelectedRows.Count > 0)
                {
                    var row = gridTraffic.SelectedRows[0];
                    var traceId = row.Cells["MessageTraceId"].Value?.ToString() ?? "";
                    var sender = row.Cells["SenderAddress"].Value?.ToString() ?? "";
                    var recipient = row.Cells["RecipientAddress"].Value?.ToString() ?? "";
                    var subject = row.Cells["Subject"].Value?.ToString() ?? "";
                    var date = row.Cells["Received"].Value?.ToString() ?? "";

                    if (!string.IsNullOrEmpty(traceId))
                    {
                        var detailForm = new Form
                        {
                            Text = "邮件追踪详情",
                            Size = new Size(700, 450),
                            StartPosition = FormStartPosition.CenterParent
                        };

                        var txtDetail = new TextBox
                        {
                            Multiline = true,
                            Dock = DockStyle.Fill,
                            ScrollBars = ScrollBars.Vertical,
                            ReadOnly = true,
                            Font = new Font("Consolas", 9)
                        };

                        detailForm.Controls.Add(txtDetail);
                        detailForm.Load += async (ss, ee) =>
                        {
                            try
                            {
                                txtDetail.AppendText($"正在查询邮件追踪详情...\n");
                                txtDetail.AppendText($"追踪ID: {traceId}\n");
                                txtDetail.AppendText($"发件人: {sender}\n");
                                txtDetail.AppendText($"收件人: {recipient}\n");
                                txtDetail.AppendText($"主题: {subject}\n");
                                txtDetail.AppendText($"时间: {date}\n");
                                txtDetail.AppendText(new string('-', 50) + "\n\n");

                                var accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                                var tenantId = _exchangeOnlineService.TenantId;

                                using (var ps = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                                {
                                    ps.Open();

                                    var psCmd = System.Management.Automation.PowerShell.Create();
                                    psCmd.Runspace = ps;
                                    psCmd.AddCommand("Connect-ExchangeOnline");
                                    psCmd.AddParameter("AccessToken", accessToken);
                                    psCmd.AddParameter("Organization", tenantId);
                                    psCmd.AddParameter("ShowBanner", false);
                                    psCmd.AddParameter("ErrorAction", "Stop");
                                    psCmd.Invoke();

                                    if (psCmd.HadErrors)
                                    {
                                        var err = psCmd.Streams.Error[0].Exception?.Message ?? "连接失败";
                                        txtDetail.AppendText($"连接错误: {err}\n");
                                        return;
                                    }

                                    txtDetail.AppendText("已连接 Exchange Online，正在查询详情...\n\n");

                                    psCmd.Commands.Clear();
                                    psCmd.AddScript($"Get-MessageTraceDetailV2 -MessageTraceId '{traceId}' -RecipientAddress '{recipient}' | ConvertTo-Json -Depth 3");
                                    var result = psCmd.Invoke();

                                    if (psCmd.HadErrors)
                                    {
                                        var err = psCmd.Streams.Error[0].Exception?.Message ?? "查询失败";
                                        txtDetail.AppendText($"查询错误: {err}\n");
                                    }
                                    else if (result.Count > 0)
                                    {
                                        var jsonStr = result[0].BaseObject?.ToString();
                                        if (!string.IsNullOrEmpty(jsonStr))
                                        {
                                            try
                                            {
                                                var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                                txtDetail.AppendText("=== 邮件追踪详情 ===\n\n");

                                                string ParseDate(string jsonDate)
                                                {
                                                    if (string.IsNullOrEmpty(jsonDate)) return "";
                                                    if (jsonDate.StartsWith("/Date(") && jsonDate.EndsWith(")/"))
                                                    {
                                                        var ticksStr = jsonDate.Substring(6, jsonDate.Length - 8);
                                                        if (long.TryParse(ticksStr, out long ticks))
                                                        {
                                                            return new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc).AddMilliseconds(ticks).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss.fff");
                                                        }
                                                    }
                                                    return jsonDate;
                                                }

                                                if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                                {
                                                    int idx = 1;
                                                    foreach (var item in doc.RootElement.EnumerateArray())
                                                    {
                                                        var dateStr = item.TryGetProperty("Date", out var dateProp) ? ParseDate(dateProp.GetString() ?? "") : "";
                                                        var eventStr = item.TryGetProperty("Event", out var eventProp) ? eventProp.GetString() : "";
                                                        var detailStr = item.TryGetProperty("Detail", out var detailProp) ? detailProp.GetString() : "";
                                                        var messageIdStr = item.TryGetProperty("MessageId", out var msgIdProp) ? msgIdProp.GetString() : "";

                                                        txtDetail.AppendText($"[{idx}] {eventStr}\n");
                                                        txtDetail.AppendText($"    时间: {dateStr}\n");
                                                        if (!string.IsNullOrEmpty(detailStr))
                                                            txtDetail.AppendText($"    详情: {detailStr}\n");
                                                        if (!string.IsNullOrEmpty(messageIdStr))
                                                            txtDetail.AppendText($"    邮件ID: {messageIdStr}\n");
                                                        txtDetail.AppendText("\n");
                                                        idx++;
                                                    }
                                                }
                                                else
                                                {
                                                    foreach (var prop in doc.RootElement.EnumerateObject())
                                                    {
                                                        var val = prop.Value.GetRawText();
                                                        if (val.StartsWith("/Date("))
                                                            val = ParseDate(val);
                                                        txtDetail.AppendText($"{prop.Name}: {val}\n");
                                                    }
                                                }
                                            }
                                            catch (Exception ex)
                                            {
                                                txtDetail.AppendText($"解析异常: {ex.Message}\n原始内容:\n{ex}");
                                            }
                                        }
                                    }
                                    else
                                    {
                                        txtDetail.AppendText("未找到详情信息\n");
                                    }

                                    psCmd.Commands.Clear();
                                    psCmd.AddCommand("Disconnect-ExchangeOnline");
                                    psCmd.AddParameter("Confirm", false);
                                    psCmd.Invoke();
                                }
                            }
                            catch (Exception ex)
                            {
                                txtDetail.AppendText($"异常: {ex.Message}\n");
                            }
                        };

                        detailForm.ShowDialog();
                    }
                    else
                    {
                        MessageBox.Show("该记录没有追踪ID", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
            };

            // 查看邮件头信息
            menuHeaders.Click += async (s, e) =>
            {
                if (gridTraffic.SelectedRows.Count > 0)
                {
                    var row = gridTraffic.SelectedRows[0];
                    var sender = row.Cells["SenderAddress"].Value?.ToString() ?? "";
                    var recipient = row.Cells["RecipientAddress"].Value?.ToString() ?? "";
                    var subject = row.Cells["Subject"].Value?.ToString() ?? "";
                    var date = row.Cells["Received"].Value?.ToString() ?? "";

                    var headerForm = new Form
                    {
                        Text = "邮件头信息",
                        Size = new Size(800, 500),
                        StartPosition = FormStartPosition.CenterParent
                    };

                    var txtHeader = new TextBox
                    {
                        Multiline = true,
                        Dock = DockStyle.Fill,
                        ScrollBars = ScrollBars.Vertical,
                        ReadOnly = true,
                        Font = new Font("Consolas", 9)
                    };

                    headerForm.Controls.Add(txtHeader);
                    headerForm.Load += async (ss, ee) =>
                    {
                        try
                        {
                            txtHeader.AppendText($"正在获取邮件头信息...\n");
                            txtHeader.AppendText($"发件人: {sender}\n");
                            txtHeader.AppendText($"收件人: {recipient}\n");
                            txtHeader.AppendText($"主题: {subject}\n");
                            txtHeader.AppendText($"时间: {date}\n");
                            txtHeader.AppendText(new string('-', 50) + "\n\n");

                            var graphToken = _exchangeOnlineService?.GraphAccessToken;
                            if (string.IsNullOrEmpty(graphToken))
                            {
                                txtHeader.AppendText("错误: Graph 访问令牌不可用\n");
                                return;
                            }

                            var client = new System.Net.Http.HttpClient();
                            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", graphToken);
                            client.DefaultRequestHeaders.Accept.Add(new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue("application/json"));

                            var userEmails = new[] { recipient, sender };
                            object foundMessage = null;

                            foreach (var userEmail in userEmails)
                            {
                                var filterQuery = Uri.EscapeDataString($"from/emailAddress/address eq '{sender}' and subject eq '{subject}' and receivedDateTime ge {date.Split(' ')[0]}");
                                var graphUrl = $"https://graph.microsoft.com/v1.0/users/{Uri.EscapeDataString(userEmail)}/messages?$filter={filterQuery}&$select=internetMessageHeaders,internetMessageId,subject,from,toRecipients,receivedDateTime&$top=5";

                                var httpResponse = await client.GetAsync(graphUrl);
                                var response = await httpResponse.Content.ReadAsStringAsync();

                                if (httpResponse.IsSuccessStatusCode)
                                {
                                    var graphDoc = System.Text.Json.JsonDocument.Parse(response);
                                    if (graphDoc.RootElement.TryGetProperty("value", out var messages) && messages.GetArrayLength() > 0)
                                    {
                                        foundMessage = messages[0];
                                        txtHeader.AppendText($"查询用户: {userEmail} (组织内用户)\n\n");
                                        break;
                                    }
                                }
                            }

                            if (foundMessage != null)
                            {
                                var message = (System.Text.Json.JsonElement)foundMessage;
                                var messageId = message.TryGetProperty("internetMessageId", out var msgId) ? msgId.GetString() : "";
                                var receivedDateTime = message.TryGetProperty("receivedDateTime", out var rdt) ? rdt.GetString() : "";

                                txtHeader.AppendText($"邮件ID: {messageId}\n");
                                txtHeader.AppendText($"接收时间: {receivedDateTime}\n\n");
                                txtHeader.AppendText("=== Internet Message Headers ===\n\n");

                                if (message.TryGetProperty("internetMessageHeaders", out var headers))
                                {
                                    foreach (var header in headers.EnumerateArray())
                                    {
                                        var name = header.TryGetProperty("name", out var hName) ? hName.GetString() : "";
                                        var value = header.TryGetProperty("value", out var hValue) ? hValue.GetString() : "";
                                        txtHeader.AppendText($"{name}: {value}\n");
                                    }
                                }
                                else
                                {
                                    txtHeader.AppendText("未找到邮件头信息\n");
                                }
                            }
                            else
                            {
                                txtHeader.AppendText("未找到对应的邮件，请确认搜索条件\n");
                            }
                        }
                        catch (Exception ex)
                        {
                            txtHeader.AppendText($"异常: {ex.Message}\n{ex.StackTrace}");
                        }
                    };

                    headerForm.ShowDialog();
                }
            };

            // 分析邮件头安全性
            menuAnalyzeHeaders.Click += async (s, e) =>
            {
                if (gridTraffic.SelectedRows.Count > 0)
                {
                    var row = gridTraffic.SelectedRows[0];
                    var sender = row.Cells["SenderAddress"].Value?.ToString() ?? "";
                    var recipient = row.Cells["RecipientAddress"].Value?.ToString() ?? "";
                    var subject = row.Cells["Subject"].Value?.ToString() ?? "";
                    var date = row.Cells["Received"].Value?.ToString() ?? "";

                    var analyzeForm = new Form
                    {
                        Text = "邮件头安全分析",
                        Size = new Size(900, 600),
                        StartPosition = FormStartPosition.CenterParent
                    };

                    var txtAnalyze = new RichTextBox
                    {
                        Multiline = true,
                        Dock = DockStyle.Fill,
                        ScrollBars = RichTextBoxScrollBars.Vertical,
                        ReadOnly = true,
                        Font = new Font("Consolas", 9)
                    };

                    analyzeForm.Controls.Add(txtAnalyze);
                    analyzeForm.Load += async (ss, ee) =>
                    {
                        try
                        {
                            txtAnalyze.AppendText($"正在获取并分析邮件头...\n");
                            txtAnalyze.AppendText($"发件人: {sender}\n");
                            txtAnalyze.AppendText($"收件人: {recipient}\n");
                            txtAnalyze.AppendText($"主题: {subject}\n");
                            txtAnalyze.AppendText($"时间: {date}\n");
                            txtAnalyze.AppendText(new string('-', 50) + "\n\n");

                            var graphToken = _exchangeOnlineService?.GraphAccessToken;
                            if (string.IsNullOrEmpty(graphToken))
                            {
                                txtAnalyze.AppendText("错误: Graph 访问令牌不可用\n");
                                return;
                            }

                            var client = new System.Net.Http.HttpClient();
                            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", graphToken);
                            client.DefaultRequestHeaders.Accept.Add(new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue("application/json"));

                            var userEmails = new[] { recipient, sender };
                            string headersText = null;

                            foreach (var userEmail in userEmails)
                            {
                                var filterQuery = Uri.EscapeDataString($"from/emailAddress/address eq '{sender}' and subject eq '{subject}' and receivedDateTime ge {date.Split(' ')[0]}");
                                var graphUrl = $"https://graph.microsoft.com/v1.0/users/{Uri.EscapeDataString(userEmail)}/messages?$filter={filterQuery}&$select=internetMessageHeaders&$top=1";

                                var httpResponse = await client.GetAsync(graphUrl);
                                var response = await httpResponse.Content.ReadAsStringAsync();

                                if (httpResponse.IsSuccessStatusCode)
                                {
                                    var graphDoc = System.Text.Json.JsonDocument.Parse(response);
                                    if (graphDoc.RootElement.TryGetProperty("value", out var messages) && messages.GetArrayLength() > 0)
                                    {
                                        var message = messages[0];
                                        if (message.TryGetProperty("internetMessageHeaders", out var headers))
                                        {
                                            var sb = new System.Text.StringBuilder();
                                            foreach (var header in headers.EnumerateArray())
                                            {
                                                var name = header.TryGetProperty("name", out var hName) ? hName.GetString() : "";
                                                var value = header.TryGetProperty("value", out var hValue) ? hValue.GetString() : "";
                                                sb.AppendLine(string.Format("{0}: {1}", name, value));
                                            }
                                            headersText = sb.ToString();
                                            txtAnalyze.AppendText("已获取邮件头，开始分析...\n\n");
                                            break;
                                        }
                                    }
                                }
                            }

                            if (!string.IsNullOrEmpty(headersText))
                            {
                                AnalyzeEmailHeaders(headersText, txtAnalyze);
                            }
                            else
                            {
                                txtAnalyze.AppendText("未找到邮件头信息\n");
                            }
                        }
                        catch (Exception ex)
                        {
                            txtAnalyze.AppendText($"异常: {ex.Message}\n{ex.StackTrace}");
                        }
                    };

                    analyzeForm.ShowDialog();
                }
            };

            // 粘贴邮件头分析
            menuPasteHeaders.Click += (s, e) =>
            {
                var pasteForm = new Form
                {
                    Text = "粘贴邮件头分析",
                    Size = new Size(900, 600),
                    StartPosition = FormStartPosition.CenterParent
                };

                var lblInput = new Label { Text = "请粘贴邮件头内容:", Location = new Point(10, 10), AutoSize = true };
                var txtInput = new TextBox
                {
                    Location = new Point(10, 35),
                    Size = new Size(pasteForm.Width - 30, 200),
                    Multiline = true,
                    ScrollBars = ScrollBars.Vertical
                };

                var btnAnalyze = new Button { Text = "分析", Location = new Point(10, 245), Size = new Size(100, 30) };
                var txtOutput = new RichTextBox
                {
                    Location = new Point(10, 280),
                    Size = new Size(pasteForm.Width - 30, pasteForm.Height - 320),
                    Multiline = true,
                    ScrollBars = RichTextBoxScrollBars.Vertical,
                    ReadOnly = true,
                    Font = new Font("Consolas", 9)
                };

                btnAnalyze.Click += (ss, ee) =>
                {
                    AnalyzeEmailHeaders(txtInput.Text, txtOutput);
                };

                pasteForm.Controls.AddRange(new Control[] { lblInput, txtInput, btnAnalyze, txtOutput });
                pasteForm.ShowDialog();
            };

            contextMenu.Items.Add(menuTraceInfo);
            contextMenu.Items.Add(menuHeaders);
            contextMenu.Items.Add(menuAnalyzeHeaders);
            contextMenu.Items.Add(menuPasteHeaders);
            gridTraffic.ContextMenuStrip = contextMenu;

            // 按钮点击事件
            btnSearch.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在'Exchange Online 百宝箱'登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                gridTraffic.Rows.Clear();

                DateTime startDate = dtpStartDate.Value;
                DateTime endDate = dtpEndDate.Value;
                string senderAddress = txtSenderAddress.Text.Trim();
                string recipientAddress = txtRecipientAddress.Text.Trim();

                lblStatus.Text = $"正在搜索邮件流量... ({startDate:yyyy-MM-dd HH:mm:ss} 至 {endDate:yyyy-MM-dd HH:mm:ss})";
                lblStatus.ForeColor = Color.Blue;

                // 验证日期范围不能超过10天
                if ((endDate - startDate).TotalDays > 10)
                {
                    MessageBox.Show("搜索时间范围不能超过10天！\n请缩小日期范围后重试。", "日期范围超限", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                var logPath = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs", "O365Online", "MailTraffic", $"MailTraffic_{DateTime.Now:yyyyMMdd}.log");
                var logDir = System.IO.Path.GetDirectoryName(logPath);
                if (!System.IO.Directory.Exists(logDir))
                    System.IO.Directory.CreateDirectory(logDir);

                void Log(string msg)
                {
                    System.IO.File.AppendAllText(logPath, $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {msg}\n");
                }

                Log($"开始搜索邮件流量. 开始日期: {startDate:yyyy-MM-dd HH:mm:ss}, 结束日期: {endDate:yyyy-MM-dd HH:mm:ss}");

                Task.Run(() =>
                {
                    try
                    {
                        string accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                        string tenantId = _exchangeOnlineService.TenantId;

                        Log($"Token长度: {accessToken?.Length ?? 0}, TenantId: {tenantId}");

                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                // 连接 Exchange Online
                                Log("正在连接 Exchange Online...");
                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    var errMsg = error.Exception?.Message ?? "连接 Exchange Online 失败";
                                    Log($"连接失败: {errMsg}");
                                    throw new Exception(errMsg);
                                }

                                Log("连接成功!");

                                // 重新添加连接命令 (Commands.Clear后会话状态会重置)
                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");

                                var connectResult = ps.Invoke();
                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    var errMsg = error.Exception?.Message ?? "重新连接失败";
                                    Log($"重新连接失败: {errMsg}");
                                    throw new Exception(errMsg);
                                }
                                ps.Commands.Clear();

                                // Get-MessageTraceV2 只支持最多10天范围，需要分批查询
                                var allMessages = new List<Dictionary<string, string>>();
                                var currentStart = startDate;
                                var maxRange = TimeSpan.FromDays(10);
                                var totalDays = (endDate - startDate).TotalDays;

                                if (totalDays > 10)
                                {
                                    Log($"警告: 日期范围 {totalDays:F0} 天超过10天限制，将自动分批查询...");
                                }

                                while (currentStart < endDate)
                                {
                                    var currentEnd = currentStart.AddDays(10);
                                    if (currentEnd > endDate)
                                        currentEnd = endDate;

                                    Log($"查询批次: {currentStart:yyyy-MM-dd} 至 {currentEnd:yyyy-MM-dd}");

                                    // 重新连接 (每个批次需要重新连接)
                                    ps.AddCommand("Connect-ExchangeOnline");
                                    ps.AddParameter("AccessToken", accessToken);
                                    ps.AddParameter("Organization", tenantId);
                                    ps.AddParameter("ShowBanner", false);
                                    ps.AddParameter("ErrorAction", "Stop");
                                    ps.Invoke();
                                    ps.Commands.Clear();

                                    // 使用 Get-MessageTraceV2 命令
                                    string script = $"Get-MessageTraceV2";
                                    script += $" -StartDate '{currentStart:yyyy-MM-dd} 00:00:00'";
                                    script += $" -EndDate '{currentEnd:yyyy-MM-dd} 23:59:59'";

                                    // 添加发件人筛选
                                    if (!string.IsNullOrEmpty(senderAddress))
                                    {
                                        script += $" -SenderAddress '{senderAddress}'";
                                    }

                                    // 添加收件人筛选
                                    if (!string.IsNullOrEmpty(recipientAddress))
                                    {
                                        script += $" -RecipientAddress '{recipientAddress}'";
                                    }

                                    script += " | Select-Object Date, Received, SenderAddress, RecipientAddress, Subject, Status, TotalBytes, MessageTraceId | ConvertTo-Json -Depth 2";

                                    Log($"执行脚本: {script}");

                                    ps.AddScript(script);
                                    var result = ps.Invoke();

                                    if (ps.HadErrors)
                                    {
                                        var error = ps.Streams.Error[0];
                                        Log($"批次查询错误: {error.Exception?.Message}");
                                    }

                                    // 解析结果
                                    if (result.Count > 0)
                                    {
                                        var jsonStr = result[0].BaseObject?.ToString();
                                        if (!string.IsNullOrEmpty(jsonStr))
                                        {
                                            try
                                            {
                                                var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                                if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                                {
                                                    foreach (var item in doc.RootElement.EnumerateArray())
                                                    {
                                                        var dict = new Dictionary<string, string>();
                                                        foreach (var prop in item.EnumerateObject())
                                                        {
                                                            dict[prop.Name] = prop.Value.ToString();
                                                        }
                                                        allMessages.Add(dict);
                                                    }
                                                }
                                            }
                                            catch (Exception ex)
                                            {
                                                Log($"解析批次结果异常: {ex.Message}");
                                            }
                                        }
                                    }

                                    Log($"批次结果数量: {result.Count}, 累计: {allMessages.Count}");

                                    // 调试: 输出第一条记录的字段
                                    if (result.Count > 0 && allMessages.Count > 0)
                                    {
                                        var first = allMessages[allMessages.Count - result.Count];
                                        var keys = string.Join(", ", first.Keys);
                                        Log($"第一条记录字段: {keys}");
                                        Log($"第一条记录内容: {string.Join(" | ", first.Select(kv => $"{kv.Key}={kv.Value}"))}");
                                    }

                                    // 断开连接
                                    ps.Commands.Clear();
                                    ps.AddCommand("Disconnect-ExchangeOnline");
                                    ps.AddParameter("Confirm", false);
                                    ps.Invoke();

                                    currentStart = currentEnd;
                                }

                                Log($"总结果数量: {allMessages.Count}");

                                // 辅助函数：解析 /Date(ticks)/ 格式
                                string ParseJsonDate(string jsonDate)
                                {
                                    if (string.IsNullOrEmpty(jsonDate)) return "";
                                    if (jsonDate.StartsWith("/Date(") && jsonDate.EndsWith(")/"))
                                    {
                                        var ticksStr = jsonDate.Substring(6, jsonDate.Length - 8);
                                        if (long.TryParse(ticksStr, out long ticks))
                                        {
                                            // ticks 是毫秒
                                            return new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc).AddMilliseconds(ticks).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss");
                                        }
                                    }
                                    return jsonDate;
                                }

                                this.Invoke(new Action(() =>
                                {
                                    foreach (var msg in allMessages)
                                    {
                                        var receivedRaw = msg.TryGetValue("Received", out var r) ? r : "";

                                        gridTraffic.Rows.Add(
                                            ParseJsonDate(receivedRaw),
                                            msg.TryGetValue("SenderAddress", out var sender) ? sender : "",
                                            msg.TryGetValue("RecipientAddress", out var recipient) ? recipient : "",
                                            msg.TryGetValue("Subject", out var subject) ? subject : "",
                                            msg.TryGetValue("Status", out var status) ? status : "",
                                            msg.TryGetValue("TotalBytes", out var size) ? size : "",
                                            msg.TryGetValue("MessageTraceId", out var traceId) ? traceId : ""
                                        );
                                    }

                                    lblStatus.Text = $"找到 {allMessages.Count} 条记录";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"搜索失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblDateRange);
            panel.Controls.Add(dtpStartDate);
            panel.Controls.Add(lblTo);
            panel.Controls.Add(dtpEndDate);
            panel.Controls.Add(lblSender);
            panel.Controls.Add(txtSenderAddress);
            panel.Controls.Add(lblRecipient);
            panel.Controls.Add(txtRecipientAddress);
            panel.Controls.Add(btnSearch);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(gridTraffic);

            return panel;
        }

        private Panel CreateMigrationPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "邮件迁移到 Office 365",
