                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold),
                ForeColor = Color.FromArgb(0, 120, 215)
            };

            var lblSourceServer = new Label { Text = "服务器地址:", Location = new Point(30, 165), AutoSize = true };
            var txtSourceServer = new TextBox { Location = new Point(130, 163), Size = new Size(250, 25), Name = "txtSourceServer" };

            var lblSourcePort = new Label { Text = "端口:", Location = new Point(400, 165), AutoSize = true };
            var numSourcePort = new NumericUpDown { Location = new Point(450, 163), Size = new Size(60, 25), Minimum = 1, Maximum = 99999, Value = 993, Name = "numSourcePort" };

            var lblSourceUseSsl = new Label { Text = "使用SSL:", Location = new Point(520, 165), AutoSize = true };
            var chkSourceSsl = new CheckBox { Location = new Point(580, 163), Size = new Size(50, 25), Checked = true, Name = "chkSourceSsl" };

            var lblSourceUsername = new Label { Text = "用户名:", Location = new Point(30, 195), AutoSize = true };
            var txtSourceUsername = new TextBox { Location = new Point(130, 193), Size = new Size(150, 25), Name = "txtSourceUsername" };

            var lblSourcePassword = new Label { Text = "密码:", Location = new Point(300, 195), AutoSize = true };
            var txtSourcePassword = new TextBox { Location = new Point(360, 193), Size = new Size(150, 25), PasswordChar = '*', Name = "txtSourcePassword" };

            // ===== 目标配置 =====
            var lblTargetConfig = new Label
            {
                Text = "目标配置:",
                Location = new Point(20, 240),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold),
                ForeColor = Color.FromArgb(0, 120, 215)
            };

            var lblTargetUserCsv = new Label { Text = "用户CSV:", Location = new Point(30, 265), AutoSize = true };
            var txtTargetCsv = new TextBox { Location = new Point(130, 263), Size = new Size(400, 25), Name = "txtTargetCsv" };
            var btnBrowseCsv = new Button { Location = new Point(540, 261), Size = new Size(80, 27), Text = "浏览...", Name = "btnBrowseCsv" };

            var lblCsvFormat = new Label
            {
                Text = "CSV格式: Email,TargetMailbox,Password (可选)",
                Location = new Point(130, 290),
                AutoSize = true,
                ForeColor = Color.Gray,
                Font = new Font("Microsoft Sans Serif", 10F)
            };

            // ===== 迁移选项 =====
            var lblOptions = new Label
            {
                Text = "迁移选项:",
                Location = new Point(20, 320),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold),
                ForeColor = Color.FromArgb(0, 120, 215)
            };

            var chkMigrateEmail = new CheckBox { Location = new Point(30, 345), Size = new Size(150, 25), Text = "迁移邮件", Checked = true, Name = "chkMigrateEmail" };
            var chkMigrateCalendar = new CheckBox { Location = new Point(180, 345), Size = new Size(150, 25), Text = "迁移日历", Checked = true, Name = "chkMigrateCalendar", Enabled = false };
            var chkMigrateContacts = new CheckBox { Location = new Point(330, 345), Size = new Size(150, 25), Text = "迁移联系人", Checked = false, Name = "chkMigrateContacts", Enabled = false };

            var lblBatchName = new Label { Text = "迁移批次:", Location = new Point(30, 375), AutoSize = true };
            var txtBatchName = new TextBox { Location = new Point(130, 373), Size = new Size(200, 25), Name = "txtBatchName" };
            txtBatchName.Text = "Migration_" + DateTime.Now.ToString("yyyyMMdd_HHmmss");

            var lblMaxConcurrent = new Label { Text = "最大并发:", Location = new Point(350, 375), AutoSize = true };
            var numMaxConcurrent = new NumericUpDown { Location = new Point(440, 373), Size = new Size(60, 25), Minimum = 1, Maximum = 100, Value = 5, Name = "numMaxConcurrent" };

            // ===== 操作按钮 =====
            var btnStartMigration = new Button
            {
                Location = new Point(30, 420),
                Size = new Size(120, 35),
                Text = "开始迁移",
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White,
                Name = "btnStartMigration"
            };

            var btnGetMigrationStatus = new Button
            {
                Location = new Point(160, 420),
                Size = new Size(120, 35),
                Text = "查看状态",
                Name = "btnGetMigrationStatus"
            };

            var btnCompleteMigration = new Button
            {
                Location = new Point(290, 420),
                Size = new Size(120, 35),
                Text = "完成迁移",
                BackColor = Color.FromArgb(0, 200, 100),
                ForeColor = Color.White,
                Name = "btnCompleteMigration"
            };

            // ===== 状态显示 =====
            var lblStatus = new Label
            {
                Location = new Point(30, 465),
                Size = new Size(500, 30),
                ForeColor = Color.Gray,
                Name = "lblMigrationStatus"
            };

            // ===== 迁移列表 =====
            var lblMigrationList = new Label
            {
                Text = "迁移批次列表:",
                Location = new Point(20, 505),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            var gridMigrationBatches = new DataGridView
            {
                Location = new Point(20, 530),
                Size = new Size(750, 250),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle,
                Name = "gridMigrationBatches"
            };

            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Identity", HeaderText = "批次ID", Width = 120 });
            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Name", HeaderText = "批次名称", Width = 150 });
            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Status", HeaderText = "状态", Width = 100 });
            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Total", HeaderText = "总数", Width = 60 });
            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Synced", HeaderText = "已同步", Width = 60 });
            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Failed", HeaderText = "失败", Width = 60 });
            gridMigrationBatches.Columns.Add(new DataGridViewTextBoxColumn { Name = "Created", HeaderText = "创建时间", Width = 140 });

            // ===== CSV浏览按钮事件 =====
            btnBrowseCsv.Click += (s, e) =>
            {
                using (var ofd = new OpenFileDialog())
                {
                    ofd.Filter = "CSV文件 (*.csv)|*.csv|所有文件 (*.*)|*.*";
                    ofd.Title = "选择用户CSV文件";
                    if (ofd.ShowDialog() == DialogResult.OK)
                    {
                        txtTargetCsv.Text = ofd.FileName;
                    }
                }
            };

            // ===== 迁移类型切换事件 =====
            cmbMigrationType.SelectedIndexChanged += (s, e) =>
            {
                if (cmbMigrationType.SelectedIndex == 0)
                {
                    // IMAP 迁移
                    lblSourceServer.Text = "IMAP服务器:";
                    lblSourcePort.Enabled = true;
                    lblSourceUseSsl.Enabled = true;
                    txtSourceServer.Text = "";
                    txtSourceUsername.Text = "";
                }
                else
                {
                    // Exchange 跨租户迁移
                    lblSourceServer.Text = "源Exchange服务器:";
                    lblSourcePort.Enabled = false;
                    lblSourceUseSsl.Enabled = false;
                    txtSourceServer.Text = "";
                    txtSourceUsername.Text = "";
                }
            };

            // ===== 开始迁移按钮事件 =====
            btnStartMigration.Click += (s, e) =>
            {
                // 验证输入
                if (string.IsNullOrWhiteSpace(txtSourceServer.Text))
                {
                    lblStatus.Text = "请输入源服务器地址";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                if (string.IsNullOrWhiteSpace(txtTargetCsv.Text))
                {
                    lblStatus.Text = "请选择用户CSV文件";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                if (!System.IO.File.Exists(txtTargetCsv.Text))
                {
                    lblStatus.Text = "CSV文件不存在";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                bool useAppToken = _isExchangeOnlineLoggedIn && _exchangeOnlineService != null;

                if (!useOAuth && !useAppToken)
                {
                    lblStatus.Text = "请先在'单用户同步（O365)'或'Exchange Online 百宝箱'登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在创建迁移批次...";
                lblStatus.ForeColor = Color.Blue;
                gridMigrationBatches.Rows.Clear();

                string migrationType = cmbMigrationType.SelectedIndex == 0 ? "IMAP" : "Exchange";
                string csvPath = txtTargetCsv.Text;
                string batchName = txtBatchName.Text;
                int maxConcurrent = (int)numMaxConcurrent.Value;
                bool migrateEmail = chkMigrateEmail.Checked;
                bool migrateCalendar = chkMigrateCalendar.Checked;
                bool migrateContacts = chkMigrateContacts.Checked;

                // 源配置
                string sourceServer = txtSourceServer.Text;
                int sourcePort = (int)numSourcePort.Value;
                bool useSsl = chkSourceSsl.Checked;
                string sourceUsername = txtSourceUsername.Text;
                string sourcePassword = txtSourcePassword.Text;

                var logPath = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs", "O365Online", "Migration", $"Migration_{DateTime.Now:yyyyMMdd}.log");
                var logDir = System.IO.Path.GetDirectoryName(logPath);
                if (!System.IO.Directory.Exists(logDir))
                    System.IO.Directory.CreateDirectory(logDir);

                void Log(string msg)
                {
                    System.IO.File.AppendAllText(logPath, $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {msg}\n");
                }

                Log($"开始{migrationType}迁移. 批次: {batchName}, CSV: {csvPath}");

                Task.Run(() =>
                {
                    try
                    {
                        string accessToken;
                        string tenantId;
                        if (useOAuth)
                        {
                            accessToken = _office365AccessToken;
                            tenantId = _exchangeOnlineService?.TenantId ?? "common";
                        }
                        else
                        {
                            tenantId = _exchangeOnlineService.TenantId;
                            accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                        }

                        Log($"Token长度: {accessToken?.Length ?? 0}, TenantId: {tenantId}");

                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                // 连接 Exchange Online
                                Log("正在连接 Exchange Online...");
                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                if (ps.HadErrors)
                                {
                                    var error = ps.Streams.Error[0];
                                    var errMsg = error.Exception?.Message ?? "连接 Exchange Online 失败";
                                    Log($"连接失败: {errMsg}");
                                    throw new Exception(errMsg);
                                }

                                Log("连接成功!");
                                ps.Commands.Clear();

                                // 读取CSV文件
                                var users = new List<(string Email, string TargetMailbox, string Password)>();
                                var csvLines = System.IO.File.ReadAllLines(csvPath);
                                foreach (var line in csvLines.Skip(1)) // 跳过标题行
                                {
                                    if (string.IsNullOrWhiteSpace(line)) continue;
                                    var parts = line.Split(',');
                                    if (parts.Length >= 2)
                                    {
                                        users.Add((parts[0].Trim(), parts[1].Trim(), parts.Length > 2 ? parts[2].Trim() : ""));
                                    }
                                }

                                Log($"读取到 {users.Count} 个用户");

                                if (cmbMigrationType.SelectedIndex == 0)
                                {
                                    // IMAP 迁移
                                    #region IMAP迁移
                                    // 创建迁移端点
                                    string endpointName = "IMAP_" + DateTime.Now.ToString("yyyyMMddHHmmss");
                                    Log($"创建IMAP迁移端点: {endpointName}");

                                    ps.AddCommand("New-MigrationEndpoint");
                                    ps.AddParameter("Name", endpointName);
                                    ps.AddParameter("IMAPServer", sourceServer);
                                    ps.AddParameter("IMAPPort", sourcePort);
                                    ps.AddParameter("IMAPUseSsl", useSsl);
                                    ps.AddParameter("Username", sourceUsername);
                                    ps.AddParameter("Password", sourcePassword);
                                    ps.AddParameter("ExchangeServer", sourceServer);
                                    ps.AddParameter("ErrorAction", "Stop");
                                    ps.Invoke();

                                    if (ps.HadErrors)
                                    {
                                        var error = ps.Streams.Error[0];
                                        Log($"创建迁移端点错误: {error.Exception?.Message}");
                                        // 尝试获取现有端点
                                        ps.Commands.Clear();
                                        ps.AddScript("Get-MigrationEndpoint | Select-Object -First 1 -ExpandProperty EndpointID");
                                        var epResult = ps.Invoke();
                                        if (epResult.Count > 0)
                                        {
                                            endpointName = epResult[0].BaseObject?.ToString();
                                            Log($"使用现有端点: {endpointName}");
                                        }
                                        else
                                        {
                                            throw new Exception("无法创建或获取迁移端点: " + error.Exception?.Message);
                                        }
                                    }
                                    else
                                    {
                                        Log("迁移端点创建成功");
                                    }

                                    ps.Commands.Clear();

                                    // 创建迁移批次
                                    Log($"创建迁移批次: {batchName}");

                                    // 构建迁移属性
                                    string migrateFolders = "";
                                    if (migrateEmail) migrateFolders += "Email";
                                    if (migrateCalendar) migrateFolders += ",Calendar";
                                    if (migrateContacts) migrateFolders += ",Contacts";
                                    migrateFolders = migrateFolders.TrimStart(',');

                                    // 创建CSV内容用于迁移
                                    var migrationCsvPath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"migration_{DateTime.Now:yyyyMMddHHmmss}.csv");
                                    var csvContent = "EmailAddress,Password\n";
                                    foreach (var user in users)
                                    {
                                        csvContent += $"{user.Email},{user.Password}\n";
                                    }
                                    System.IO.File.WriteAllText(migrationCsvPath, csvContent);
                                    Log($"临时CSV: {migrationCsvPath}");

                                    ps.AddCommand("New-MigrationBatch");
                                    ps.AddParameter("Name", batchName);
                                    ps.AddParameter("SourceEndpoint", endpointName);
                                    ps.AddParameter("CSVData", System.IO.File.ReadAllBytes(migrationCsvPath));
                                    ps.AddParameter("AutoStart", true);
                                    ps.AddParameter("MaxConcurrentMigrations", maxConcurrent);
                                    ps.AddParameter("ErrorAction", "Stop");
                                    ps.Invoke();

                                    // 清理临时文件
                                    try { System.IO.File.Delete(migrationCsvPath); } catch { }

                                    if (ps.HadErrors)
                                    {
                                        var error = ps.Streams.Error[0];
                                        Log($"创建迁移批次错误: {error.Exception?.Message}");
                                        throw new Exception("创建迁移批次失败: " + error.Exception?.Message);
                                    }

                                    Log("迁移批次创建成功!");
                                    #endregion
                                }
                                else
                                {
                                    #region Exchange跨租户迁移
                                    // 对于Exchange跨租户迁移，使用不同的方法
                                    Log("创建Exchange跨租户迁移批次");

                                    // 创建迁移端点
                                    string endpointName = "Exchange_" + DateTime.Now.ToString("yyyyMMddHHmmss");
                                    Log($"创建Exchange迁移端点: {endpointName}");

                                    ps.AddCommand("New-MigrationEndpoint");
                                    ps.AddParameter("Name", endpointName);
                                    ps.AddParameter("ExchangeRemoteMove", true);
                                    ps.AddParameter("RemoteServer", sourceServer);
                                    ps.AddParameter("Username", sourceUsername);
                                    ps.AddParameter("Password", sourcePassword);
                                    ps.AddParameter("ErrorAction", "Stop");
                                    ps.Invoke();

                                    if (ps.HadErrors)
                                    {
                                        var error = ps.Streams.Error[0];
                                        Log($"创建迁移端点错误: {error.Exception?.Message}");
                                        throw new Exception("创建迁移端点失败: " + error.Exception?.Message);
                                    }

                                    ps.Commands.Clear();

                                    // 创建迁移批次
                                    var migrationCsvPath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"migration_{DateTime.Now:yyyyMMddHHmmss}.csv");
                                    var csvContent = "EmailAddress,TargetMailbox,TargetArchive\n";
                                    foreach (var user in users)
                                    {
                                        csvContent += $"{user.Email},{user.TargetMailbox},false\n";
                                    }
                                    System.IO.File.WriteAllText(migrationCsvPath, csvContent);

                                    ps.AddCommand("New-MigrationBatch");
                                    ps.AddParameter("Name", batchName);
                                    ps.AddParameter("SourceEndpoint", endpointName);
                                    ps.AddParameter("CSVData", System.IO.File.ReadAllBytes(migrationCsvPath));
                                    ps.AddParameter("AutoStart", true);
                                    ps.AddParameter("MaxConcurrentMigrations", maxConcurrent);
                                    ps.AddParameter("ErrorAction", "Stop");
                                    ps.Invoke();

                                    try { System.IO.File.Delete(migrationCsvPath); } catch { }

                                    if (ps.HadErrors)
                                    {
                                        var error = ps.Streams.Error[0];
                                        Log($"创建迁移批次错误: {error.Exception?.Message}");
                                        throw new Exception("创建迁移批次失败: " + error.Exception?.Message);
                                    }

                                    Log("Exchange迁移批次创建成功!");
                                    #endregion
                                }

                                ps.Commands.Clear();

                                // 获取迁移批次列表
                                Log("获取迁移批次列表...");
                                ps.AddScript("Get-MigrationBatch | Select-Object Identity, Name, Status, TotalCount, SyncedCount, FailedCount, CreatedDateTime | ConvertTo-Json");
                                var result = ps.Invoke();

                                ps.Commands.Clear();

                                // 断开连接
                                ps.AddCommand("Disconnect-ExchangeOnline");
                                ps.AddParameter("Confirm", false);
                                ps.Invoke();

                                Log($"迁移批次查询结果: {result.Count}");

                                var batches = new List<Dictionary<string, string>>();
                                if (result.Count > 0)
                                {
                                    var jsonStr = result[0].BaseObject?.ToString();
                                    if (!string.IsNullOrEmpty(jsonStr))
                                    {
                                        try
                                        {
                                            var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                            {
                                                foreach (var item in doc.RootElement.EnumerateArray())
                                                {
                                                    var dict = new Dictionary<string, string>();
                                                    foreach (var prop in item.EnumerateObject())
                                                    {
                                                        dict[prop.Name] = prop.Value.ToString();
                                                    }
                                                    batches.Add(dict);
                                                }
                                            }
                                        }
                                        catch (Exception ex)
                                        {
                                            Log($"解析JSON错误: {ex.Message}");
                                        }
                                    }
                                }

                                this.Invoke(new Action(() =>
                                {
                                    foreach (var batch in batches)
                                    {
                                        gridMigrationBatches.Rows.Add(
                                            batch.TryGetValue("Identity", out var id) ? id : "",
                                            batch.TryGetValue("Name", out var name) ? name : "",
                                            batch.TryGetValue("Status", out var status) ? status : "",
                                            batch.TryGetValue("TotalCount", out var total) ? total : "0",
                                            batch.TryGetValue("SyncedCount", out var synced) ? synced : "0",
                                            batch.TryGetValue("FailedCount", out var failed) ? failed : "0",
                                            batch.TryGetValue("CreatedDateTime", out var created) ? created : ""
                                        );
                                    }

                                    lblStatus.Text = $"迁移批次已创建: {batchName}, 共 {users.Count} 个用户";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Log($"迁移错误: {ex.Message}");
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"迁移失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            // ===== 查看迁移状态按钮事件 =====
            btnGetMigrationStatus.Click += (s, e) =>
            {
                bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                bool useAppToken = _isExchangeOnlineLoggedIn && _exchangeOnlineService != null;

                if (!useOAuth && !useAppToken)
                {
                    lblStatus.Text = "请先在'单用户同步（O365)'或'Exchange Online 百宝箱'登录";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在获取迁移状态...";
                lblStatus.ForeColor = Color.Blue;
                gridMigrationBatches.Rows.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        string accessToken;
                        string tenantId;
                        if (useOAuth)
                        {
                            accessToken = _office365AccessToken;
                            tenantId = _exchangeOnlineService?.TenantId ?? "common";
                        }
                        else
                        {
                            tenantId = _exchangeOnlineService.TenantId;
                            accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                        }

                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                ps.Commands.Clear();

                                ps.AddScript("Get-MigrationBatch | Select-Object Identity, Name, Status, TotalCount, SyncedCount, FailedCount, CreatedDateTime | ConvertTo-Json");
                                var result = ps.Invoke();

                                ps.Commands.Clear();
                                ps.AddCommand("Disconnect-ExchangeOnline");
                                ps.AddParameter("Confirm", false);
                                ps.Invoke();

                                var batches = new List<Dictionary<string, string>>();
                                if (result.Count > 0)
                                {
                                    var jsonStr = result[0].BaseObject?.ToString();
                                    if (!string.IsNullOrEmpty(jsonStr))
                                    {
                                        try
                                        {
                                            var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                                            if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Array)
                                            {
                                                foreach (var item in doc.RootElement.EnumerateArray())
                                                {
                                                    var dict = new Dictionary<string, string>();
                                                    foreach (var prop in item.EnumerateObject())
                                                    {
                                                        dict[prop.Name] = prop.Value.ToString();
                                                    }
                                                    batches.Add(dict);
                                                }
                                            }
                                        }
                                        catch { }
                                    }
                                }

                                this.Invoke(new Action(() =>
                                {
                                    foreach (var batch in batches)
                                    {
                                        gridMigrationBatches.Rows.Add(
                                            batch.TryGetValue("Identity", out var id) ? id : "",
                                            batch.TryGetValue("Name", out var name) ? name : "",
                                            batch.TryGetValue("Status", out var status) ? status : "",
                                            batch.TryGetValue("TotalCount", out var total) ? total : "0",
                                            batch.TryGetValue("SyncedCount", out var synced) ? synced : "0",
                                            batch.TryGetValue("FailedCount", out var failed) ? failed : "0",
                                            batch.TryGetValue("CreatedDateTime", out var created) ? created : ""
                                        );
                                    }

                                    lblStatus.Text = $"共 {batches.Count} 个迁移批次";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"获取状态失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            // ===== 完成迁移按钮事件 =====
            btnCompleteMigration.Click += (s, e) =>
            {
                if (gridMigrationBatches.SelectedRows.Count == 0)
                {
                    lblStatus.Text = "请先选择一个迁移批次";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var selectedRow = gridMigrationBatches.SelectedRows[0];
                string batchIdentity = selectedRow.Cells["Identity"].Value?.ToString();
                string batchStatus = selectedRow.Cells["Status"].Value?.ToString();

                if (string.IsNullOrEmpty(batchIdentity))
                {
                    lblStatus.Text = "请选择一个有效的迁移批次";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                if (batchStatus != "Synced" && batchStatus != "Completed")
                {
                    lblStatus.Text = $"当前状态为 {batchStatus}，无法完成。请等待同步完成后再试。";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                lblStatus.Text = "正在完成迁移...";
                lblStatus.ForeColor = Color.Blue;

                Task.Run(() =>
                {
                    try
                    {
                        string accessToken;
                        string tenantId;
                        bool useOAuth = _isO365OAuthConnected && !string.IsNullOrEmpty(_office365AccessToken);
                        bool useAppToken = _isExchangeOnlineLoggedIn && _exchangeOnlineService != null;

                        if (useOAuth)
                        {
                            accessToken = _office365AccessToken;
                            tenantId = _exchangeOnlineService?.TenantId ?? "common";
                        }
                        else
                        {
                            tenantId = _exchangeOnlineService.TenantId;
                            accessToken = _exchangeOnlineService.AccessToken ?? _exchangeOnlineService.GraphAccessToken;
                        }

                        using (var runspace = System.Management.Automation.Runspaces.RunspaceFactory.CreateRunspace())
                        {
                            runspace.Open();

                            using (var ps = System.Management.Automation.PowerShell.Create())
                            {
                                ps.Runspace = runspace;

                                ps.AddCommand("Connect-ExchangeOnline");
                                ps.AddParameter("AccessToken", accessToken);
                                ps.AddParameter("Organization", tenantId);
                                ps.AddParameter("ShowBanner", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                ps.Commands.Clear();

                                // 完成迁移批次
                                ps.AddCommand("Complete-MigrationBatch");
                                ps.AddParameter("Identity", batchIdentity);
                                ps.AddParameter("Confirm", false);
                                ps.AddParameter("ErrorAction", "Stop");
                                ps.Invoke();

                                ps.Commands.Clear();
                                ps.AddCommand("Disconnect-ExchangeOnline");
                                ps.AddParameter("Confirm", false);
                                ps.Invoke();

                                this.Invoke(new Action(() =>
                                {
                                    lblStatus.Text = "迁移已完成!";
                                    lblStatus.ForeColor = Color.Green;
                                }));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblStatus.Text = $"完成迁移失败: {ex.Message}";
                            lblStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblMigrationType);
            panel.Controls.Add(cmbMigrationType);
            panel.Controls.Add(lblSourceConfig);
            panel.Controls.Add(lblSourceServer);
            panel.Controls.Add(txtSourceServer);
            panel.Controls.Add(lblSourcePort);
            panel.Controls.Add(numSourcePort);
            panel.Controls.Add(lblSourceUseSsl);
            panel.Controls.Add(chkSourceSsl);
            panel.Controls.Add(lblSourceUsername);
            panel.Controls.Add(txtSourceUsername);
            panel.Controls.Add(lblSourcePassword);
            panel.Controls.Add(txtSourcePassword);
            panel.Controls.Add(lblTargetConfig);
            panel.Controls.Add(lblTargetUserCsv);
            panel.Controls.Add(txtTargetCsv);
            panel.Controls.Add(btnBrowseCsv);
            panel.Controls.Add(lblCsvFormat);
            panel.Controls.Add(lblOptions);
            panel.Controls.Add(chkMigrateEmail);
            panel.Controls.Add(chkMigrateCalendar);
            panel.Controls.Add(chkMigrateContacts);
            panel.Controls.Add(lblBatchName);
            panel.Controls.Add(txtBatchName);
            panel.Controls.Add(lblMaxConcurrent);
            panel.Controls.Add(numMaxConcurrent);
            panel.Controls.Add(btnStartMigration);
            panel.Controls.Add(btnGetMigrationStatus);
            panel.Controls.Add(btnCompleteMigration);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblMigrationList);
            panel.Controls.Add(gridMigrationBatches);

            return panel;
        }

        private Panel CreateWhoisQueryPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "WHOIS 查询",
                Location = new Point(20, 20),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            var lblNote = new Label
            {
                Text = "查询域名的 WHOIS 注册信息",
                Location = new Point(20, 55),
                AutoSize = true,
                ForeColor = Color.Gray
            };

            var lblDomain = new Label { Text = "域名:", Location = new Point(20, 95), AutoSize = true };
            var txtWhoisDomain = new TextBox { Location = new Point(70, 93), Size = new Size(300, 25), Name = "txtWhoisDomain" };
            var btnWhoisQuery = new Button { Location = new Point(380, 91), Size = new Size(100, 27), Text = "查询", Name = "btnWhoisQuery" };

            var lblWhoisResult = new Label { Text = "查询结果:", Location = new Point(20, 130), AutoSize = true };
            var dgvWhoisResult = new DataGridView
            {
                Location = new Point(20, 155),
                Size = new Size(700, 400),
                ReadOnly = true,
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                Font = new Font("Microsoft Sans Serif", 9)
            };
            dgvWhoisResult.Columns.Add("key", "项目");
            dgvWhoisResult.Columns.Add("value", "值");

            btnWhoisQuery.Click += (s, e) =>
            {
                var domain = txtWhoisDomain.Text.Trim();
                if (string.IsNullOrEmpty(domain))
                {
                    MessageBox.Show("请输入域名", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                // 清理域名格式
                domain = domain.Replace("https://", "").Replace("http://", "").TrimEnd('/');

                dgvWhoisResult.Rows.Clear();

                Task.Run(async () =>
                {
                    try
                    {
                        // 使用 chinaz WHOIS 网页
                        using (var client = new System.Net.Http.HttpClient())
                        {
                            client.DefaultRequestHeaders.UserAgent.ParseAdd("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36");

                            var url = $"https://whois.chinaz.com/{Uri.EscapeUriString(domain)}";
                            var response = await client.GetStringAsync(url);

                            this.Invoke(new Action(() =>
                            {
                                dgvWhoisResult.Rows.Add("域名", domain);
                                dgvWhoisResult.Rows.Add("", "==================");

                                // 先尝试查找 WhoisBox 区域
                                var whoisMatch = System.Text.RegularExpressions.Regex.Match(response, @"WhoisBox""[\s\S]*?</div>\s*</div>", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                                var searchText = whoisMatch.Success ? whoisMatch.Value : response;

                                // 从 HTML 中提取关键信息
                                var whoisPatterns = new Dictionary<string, string>
                                {
                                    { "注册商", @"注册商</div>\s*<div[^>]*>([^<]+)" },
                                    { "注册商服务器", @"注册商服务器</div>\s*<div[^>]*>([^<]+)" },
                                    { "注册商电话", @"注册商电话</div>\s*<div[^>]*>([^<]+)" },
                                    { "注册商邮箱", @"注册商邮箱</div>\s*<div[^>]*>([^<]+)" },
                                    { "更新时间", @"更新时间</div>\s*<div[^>]*>([^<]+)" },
                                    { "注册时间", @"注册时间</div>\s*<div[^>]*>([^<]+)" },
                                    { "过期时间", @"过期时间</div>\s*<div[^>]*>([^<]+)" },
                                    { "域名年龄", @"域名年龄</div>\s*<div[^>]*>([^<]+)" },
                                    { "DNS", @"DNS</div>\s*<div[^>]*>([^<]+)" }
                                };

                                bool foundAny = false;
                                foreach (var kvp in whoisPatterns)
                                {
                                    try
                                    {
                                        var match = System.Text.RegularExpressions.Regex.Match(searchText, kvp.Value, System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                                        if (match.Success && match.Groups.Count > 1)
                                        {
                                            var value = match.Groups[1].Value.Trim();
                                            value = System.Text.RegularExpressions.Regex.Replace(value, "<[^>]+>", "");
                                            value = value.Replace("&nbsp;", " ").Replace("&amp;", "&").Trim();
                                            if (!string.IsNullOrEmpty(value))
                                            {
                                                dgvWhoisResult.Rows.Add(kvp.Key, value);
                                                foundAny = true;
                                            }
                                        }
                                    }
                                    catch { }
                                }

                                // 提取状态
                                var statusMatch = System.Text.RegularExpressions.Regex.Match(searchText, @"状态</div>\s*<div[^>]*>([\s\S]*?)</div>", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                                if (statusMatch.Success)
                                {
                                    var statusHtml = statusMatch.Groups[1].Value;
                                    var statusItems = System.Text.RegularExpressions.Regex.Matches(statusHtml, @"<[^>]+>([^<]+)<");
                                    if (statusItems.Count > 0)
                                    {
                                        dgvWhoisResult.Rows.Add("状态", "");
                                        foreach (System.Text.RegularExpressions.Match item in statusItems)
                                        {
                                            var status = item.Groups[1].Value.Trim();
                                            if (!string.IsNullOrEmpty(status))
                                                dgvWhoisResult.Rows.Add("", "  " + status);
                                        }
                                        foundAny = true;
                                    }
                                }

                                // 如果没有找到任何信息，显示原始 HTML 片段用于调试
                                if (!foundAny)
                                {
                                    dgvWhoisResult.Rows.Add("错误", "未能解析 WHOIS 数据");
                                    var sample = searchText.Length > 500 ? searchText.Substring(0, 500) : searchText;
                                    sample = System.Text.RegularExpressions.Regex.Replace(sample, "<[^>]+>", " ");
                                    sample = sample.Replace("&nbsp;", " ").Replace("&amp;", "&");
                                    dgvWhoisResult.Rows.Add("原始内容", sample);
                                }
                            }));
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() => dgvWhoisResult.Rows.Add("查询失败", ex.Message)));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblDomain);
            panel.Controls.Add(txtWhoisDomain);
            panel.Controls.Add(btnWhoisQuery);
            panel.Controls.Add(lblWhoisResult);
            panel.Controls.Add(dgvWhoisResult);

            return panel;
        }

        private Panel CreateDnsQueryPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill, AutoScroll = true };

            var lblTitle = new Label
            {
                Text = "DNS 查询",
                Location = new Point(20, 20),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            var lblNote = new Label
            {
                Text = "查询域名的 DNS 记录",
                Location = new Point(20, 55),
                AutoSize = true,
                ForeColor = Color.Gray
            };

            var lblDnsDomain = new Label { Text = "域名:", Location = new Point(20, 95), AutoSize = true };
            var txtDnsDomain = new TextBox { Location = new Point(70, 93), Size = new Size(250, 25), Name = "txtDnsDomain" };

            var lblDnsType = new Label { Text = "记录类型:", Location = new Point(330, 95), AutoSize = true };
            var cmbDnsType = new ComboBox
            {
                Location = new Point(400, 93),
                Size = new Size(100, 25),
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbDnsType.Items.AddRange(new object[] { "A", "MX", "TXT", "NS", "CNAME", "AAAA", "SOA", "SRV", "ALL" });
            cmbDnsType.SelectedIndex = 0;

            var btnDnsQuery = new Button { Location = new Point(510, 91), Size = new Size(100, 27), Text = "查询", Name = "btnDnsQuery" };

            var lblDnsResult = new Label { Text = "查询结果:", Location = new Point(20, 130), AutoSize = true };
            var dgvDnsResult = new DataGridView
            {
                Location = new Point(20, 155),
                Size = new Size(700, 400),
                ReadOnly = true,
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                Font = new Font("Microsoft Sans Serif", 9)
            };
            dgvDnsResult.Columns.Add("name", "域名");
            dgvDnsResult.Columns.Add("type", "记录类型");
            dgvDnsResult.Columns.Add("ttl", "TTL");
            dgvDnsResult.Columns.Add("data", "数据");

            btnDnsQuery.Click += (s, e) =>
            {
                var domain = txtDnsDomain.Text.Trim();
                if (string.IsNullOrEmpty(domain))
                {
                    MessageBox.Show("请输入域名", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                var recordType = cmbDnsType.SelectedItem?.ToString() ?? "A";

                dgvDnsResult.Rows.Clear();

                Task.Run(async () =>
                {
                    try
                    {
                        // 使用 DoH API
                        using (var client = new System.Net.Http.HttpClient())
                        {
                            client.DefaultRequestHeaders.UserAgent.ParseAdd("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
                            client.DefaultRequestHeaders.Accept.ParseAdd("application/dns-json");

                            var dohTypes = new Dictionary<string, string>
                            {
                                { "A", "1" }, { "MX", "15" }, { "TXT", "16" }, { "NS", "2" },
                                { "CNAME", "5" }, { "AAAA", "28" }, { "SOA", "6" }, { "SRV", "33" }
                            };

                            var typeCode = dohTypes.TryGetValue(recordType, out var tc) ? tc : "1";
                            var url = $"https://doh.pub/dns-query?name={Uri.EscapeDataString(domain)}&type={typeCode}";

                            var response = await client.GetStringAsync(url);

                            this.Invoke(new Action(() =>
                            {
                                try
                                {
                                    var doc = System.Text.Json.JsonDocument.Parse(response);
                                    if (doc.RootElement.TryGetProperty("Answer", out var answers))
                                    {
                                        foreach (var answer in answers.EnumerateArray())
                                        {
                                            ParseDnsAnswer(answer, recordType);
                                        }
                                    }
                                    else
                                    {
                                        dgvDnsResult.Rows.Add(domain, recordType, "", "未找到 DNS 记录");
                                    }
                                }
                                catch
                                {
                                    dgvDnsResult.Rows.Add(domain, recordType, "", response);
                                }
                            }));
                        }

                        string GetRecordTypeName(string typeCode)
                        {
                            var dict = new Dictionary<string, string>
                            {
                                { "1", "A" }, { "2", "NS" }, { "5", "CNAME" }, { "6", "SOA" },
                                { "12", "PTR" }, { "15", "MX" }, { "16", "TXT" }, { "28", "AAAA" },
                                { "33", "SRV" }
                            };
                            return dict.TryGetValue(typeCode, out var name) ? $"{name} ({typeCode})" : typeCode;
                        }

                        void ParseDnsAnswer(System.Text.Json.JsonElement answer, string recType)
                        {
                            var name = answer.TryGetProperty("name", out var n) ? n.GetString() : "";
                            var type = answer.TryGetProperty("type", out var t) ? t.GetInt32().ToString() : recType;
                            var ttl = answer.TryGetProperty("TTL", out var ttlVal) ? ttlVal.GetInt64().ToString() : "";
                            var data = answer.TryGetProperty("data", out var d) ? d.GetString() : "";

                            string dataDisplay = data;
                            switch (type)
                            {
                                case "1": // A
                                case "28": // AAAA
                                    dataDisplay = $"IP地址: {data}";
                                    break;
                                case "2": // NS
                                    dataDisplay = $"名称服务器: {data}";
                                    break;
                                case "5": // CNAME
                                    dataDisplay = $"主机别名: {data}";
                                    break;
                                case "15": // MX
                                    var mxParts = data.Split(' ');
                                    if (mxParts.Length >= 2)
                                        dataDisplay = $"优先级: {mxParts[0]}, 邮件服务器: {mxParts[1]}";
                                    else
                                        dataDisplay = $"邮件服务器: {data}";
                                    break;
                                case "16": // TXT
                                    dataDisplay = $"文本内容: {data}";
                                    break;
                                case "6": // SOA
                                    dataDisplay = $"SOA: {data}";
                                    break;
                                case "33": // SRV
                                    dataDisplay = $"SRV: {data}";
                                    break;
                            }

                            dgvDnsResult.Rows.Add(name, GetRecordTypeName(type), ttl, dataDisplay);
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() => dgvDnsResult.Rows.Add(domain, recordType, "", $"错误: {ex.Message}")));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblDnsDomain);
            panel.Controls.Add(txtDnsDomain);
            panel.Controls.Add(lblDnsType);
            panel.Controls.Add(cmbDnsType);
            panel.Controls.Add(btnDnsQuery);
            panel.Controls.Add(lblDnsResult);
            panel.Controls.Add(dgvDnsResult);

            return panel;
        }

        private Panel CreateMailSearchDeletePanel()
