            };

            // 说明文字 - 具体要求
            var lblNote1 = new Label
            {
                Text = "要求: 1.本地必须安装Outlook并处于开启状态",
                Location = new Point(20, 50),
                Size = new Size(400, 20),
                ForeColor = Color.FromArgb(255, 128, 0)
            };

            var lblNote2 = new Label
            {
                Text = "2.文件命名格式: 邮件地址.pst (例: raymond.xu@booming.one.pst)",
                Location = new Point(20, 72),
                Size = new Size(500, 20),
                ForeColor = Color.FromArgb(255, 128, 0)
            };

            var lblNote3 = new Label
            {
                Text = "3.请先在'登录'页签登录Exchange Online",
                Location = new Point(20, 94),
                Size = new Size(300, 20),
                ForeColor = Color.FromArgb(255, 128, 0)
            };

            // 并发线程
            var lblCalendarThreadCount = new Label { Text = "并发线程:", Location = new Point(20, 118), AutoSize = true };
            var numCalendarThreadCount = new NumericUpDown { Location = new Point(85, 115), Size = new Size(60, 25), Minimum = 1, Maximum = 10, Value = 2 };

            // 时区选择
            var lblTimeZone = new Label { Text = "时区:", Location = new Point(160, 118), AutoSize = true };
            var cmbTimeZone = new ComboBox { Location = new Point(195, 115), Size = new Size(180, 25), DropDownStyle = ComboBoxStyle.DropDownList };

            // 生成时区列表 (UTC-12 到 UTC+12) - 带代表性城市
            var timeZones = new List<KeyValuePair<string, string>>();
            var cityMap = new Dictionary<int, string>
            {
                { -12, "国际日期变更线西" },
                { -11, "萨摩亚" },
                { -10, "夏威夷" },
                { -9, "阿拉斯加" },
                { -8, "洛杉矶" },
                { -7, "丹佛" },
                { -6, "芝加哥" },
                { -5, "纽约" },
                { -4, "圣地亚哥" },
                { -3, "圣保罗" },
                { -2, "大西洋中部" },
                { -1, "亚速尔群岛" },
                { 0, "伦敦" },
                { 1, "巴黎" },
                { 2, "开罗" },
                { 3, "莫斯科" },
                { 4, "迪拜" },
                { 5, "伊斯兰堡" },
                { 6, "达卡" },
                { 7, "曼谷" },
                { 8, "北京" },
                { 9, "东京" },
                { 10, "悉尼" },
                { 11, "所罗门群岛" },
                { 12, "奥克兰" }
            };

            for (int offset = -12; offset <= 12; offset++)
            {
                string sign = offset >= 0 ? "+" : "";
                string city = cityMap.ContainsKey(offset) ? cityMap[offset] : "";
                string display = $"UTC{sign}{offset} {city}";
                string value = offset == 0 ? "UTC" : $"UTC{sign}{offset}";
                timeZones.Add(new KeyValuePair<string, string>(value, display));
            }
            // 默认选择中国时区
            cmbTimeZone.DataSource = timeZones;
            cmbTimeZone.DisplayMember = "Value";
            cmbTimeZone.ValueMember = "Key";
            cmbTimeZone.SelectedValue = "UTC+8";

            // PST文件列表DataGridView
            var lblFileList = new Label { Text = "PST文件列表:", Location = new Point(20, 145), AutoSize = true };

            var gridPstFiles = new DataGridView
            {
                Location = new Point(20, 170),
                Size = new Size(500, 220),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle
            };

            // 添加列
            var colFileName = new DataGridViewTextBoxColumn { Name = "FileName", HeaderText = "文件名", Width = 200, ReadOnly = true };
            var colEmail = new DataGridViewTextBoxColumn { Name = "Email", HeaderText = "邮箱名", Width = 180, ReadOnly = false };
            var colSelect = new DataGridViewCheckBoxColumn { Name = "Select", HeaderText = "选择", Width = 50 };

            gridPstFiles.Columns.AddRange(new DataGridViewColumn[] { colFileName, colEmail, colSelect });

            // 右侧进度状态显示区域
            var lblProgressTitle = new Label
            {
                Text = "同步状态:",
                Location = new Point(530, 145),
                Size = new Size(200, 20),
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            var lblProgressPercent = new Label
            {
                Text = "0%",
                Location = new Point(530, 165),
                Size = new Size(200, 40),
                Font = new Font("Microsoft Sans Serif", 24F, FontStyle.Bold),
                ForeColor = Color.FromArgb(0, 120, 215),
                TextAlign = ContentAlignment.MiddleLeft,
                Name = "lblCalendarProgressPercent"
            };

            var lblProgressDetail = new Label
            {
                Text = "等待开始...",
                Location = new Point(530, 210),
                Size = new Size(200, 60),
                Font = new Font("Microsoft Sans Serif", 10F),
                ForeColor = Color.Gray
            };

            // 载入文件夹按钮
            var btnLoadFolder = new Button
            {
                Text = "载入文件夹",
                Location = new Point(20, 395),
                Size = new Size(120, 30)
            };

            // 全选按钮
            var btnSelectAll = new Button
            {
                Text = "全选",
                Location = new Point(150, 395),
                Size = new Size(80, 30)
            };

            // 取消全选按钮
            var btnDeselectAll = new Button
            {
                Text = "取消全选",
                Location = new Point(240, 395),
                Size = new Size(80, 30)
            };

            // 同步按钮
            var btnSync = new Button
            {
                Text = "开始同步",
                Location = new Point(600, 395),
                Size = new Size(120, 30),
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White
            };

            // 进度条
            var progressSync = new ProgressBar
            {
                Location = new Point(20, 430),
                Size = new Size(500, 20),
                Style = ProgressBarStyle.Continuous,
                Name = "progressCalendarSync"
            };

            var lblStatus = new Label
            {
                Text = "就绪",
                Location = new Point(20, 455),
                Size = new Size(710, 20),
                ForeColor = Color.Gray
            };

            // 载入文件夹事件
            btnLoadFolder.Click += (s, e) =>
            {
                using (var fbd = new FolderBrowserDialog())
                {
                    if (fbd.ShowDialog() == DialogResult.OK)
                    {
                        gridPstFiles.Rows.Clear();
                        var files = Directory.GetFiles(fbd.SelectedPath, "*.pst");
                        foreach (var file in files)
                        {
                            var fileName = Path.GetFileNameWithoutExtension(file);
                            gridPstFiles.Rows.Add(fileName, fileName, false);
                            gridPstFiles.Rows[gridPstFiles.RowCount - 1].Tag = file;
                        }
                        lblStatus.Text = $"已载入 {files.Length} 个PST文件";
                        lblStatus.ForeColor = Color.Gray;
                    }
                }
            };

            // 全选事件
            btnSelectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridPstFiles.Rows)
                {
                    row.Cells["Select"].Value = true;
                }
            };

            // 取消全选事件
            btnDeselectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridPstFiles.Rows)
                {
                    row.Cells["Select"].Value = false;
                }
            };

            // 同步事件
            btnSync.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在'登录'页签登录Exchange Online";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var selectedFiles = new List<Tuple<string, string>>();
                foreach (DataGridViewRow row in gridPstFiles.Rows)
                {
                    if (row.Cells["Select"].Value != null && (bool)row.Cells["Select"].Value)
                    {
                        var filePath = row.Tag?.ToString();
                        var emailName = row.Cells["Email"].Value?.ToString();
                        if (!string.IsNullOrEmpty(filePath) && !string.IsNullOrEmpty(emailName))
                        {
                            selectedFiles.Add(Tuple.Create(filePath, emailName));
                        }
                    }
                }

                if (selectedFiles.Count == 0)
                {
                    lblStatus.Text = "请先选择要同步的PST文件";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                btnSync.Enabled = false;
                btnLoadFolder.Enabled = false;
                progressSync.Style = ProgressBarStyle.Marquee;
                lblStatus.Text = "正在同步日历...";
                lblStatus.ForeColor = Color.Blue;

                lblProgressPercent.Text = "0%";
                lblProgressPercent.ForeColor = Color.FromArgb(0, 120, 215);
                lblProgressDetail.Text = "正在提取PST文件...";

                var threadCount = (int)numCalendarThreadCount.Value;

                Task.Run(() =>
                {
                    int successCount = 0;
                    int failCount = 0;
                    int total = selectedFiles.Count;
                    int current = 0;
                    object lockObj = new object();

                    var tenantId = _exchangeOnlineService.TenantId;
                    var clientId = _exchangeOnlineService.AppId ?? "";
                    var clientSecret = _exchangeOnlineService.ClientSecret ?? "";

                    System.Threading.Tasks.Parallel.ForEach(selectedFiles,
                        new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = threadCount },
                        file =>
                    {
                        try
                        {
                            this.Invoke(new Action(() =>
                            {
                                progressSync.Value = (current * 100) / total;
                                lblStatus.Text = $"正在同步日历: {Path.GetFileName(file.Item1)} ({current}/{total})";
                            }));

                            // 创建临时目录
                            var tempDir = Path.Combine(Path.GetTempPath(), "PstCalendar_" + Guid.NewGuid().ToString("N"));
                            Directory.CreateDirectory(tempDir);

                            try
                            {
                                // 直接从PST提取日历到内存 (跳过ICS文件)
                                var pstExtractService = new PstExtractService();
                                var progressExtract = new Progress<int>(count =>
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        lblProgressDetail.Text = $"正在提取日历: {count} 个已提取";
                                    }));
                                });
                                var calendars = pstExtractService.ExtractCalendarFromPst(file.Item1, progressExtract);

                                this.Invoke(new Action(() =>
                                {
                                    lblProgressDetail.Text = $"正在导入日历: {file.Item2}\n共 {calendars.Count} 个日历事件";
                                }));

                                // 导入日历到目标邮箱 (使用 Client Secret 直接批量导入)
                                var o365Service = new Office365ImportService();
                                if (o365Service.ConnectWithClientSecret(tenantId, clientId, clientSecret, "PST日历导入"))
                                {
                                    // 使用新的直接批量异步导入方法 (PST内存 → Graph, 带重试和并发控制)
                                    var progressCallback = new Action<int, int, string>((idx, totalCount, status) =>
                                    {
                                        this.Invoke(new Action(() =>
                                        {
                                            if (totalCount > 0)
                                            {
                                                progressSync.Value = (idx * 100) / totalCount;
                                                lblProgressDetail.Text = status;
                                            }
                                        }));
                                    });

                                    // 直接批量导入日历 (最多10个并发)
                                    var selectedTimeZone = cmbTimeZone.SelectedValue?.ToString() ?? "UTC+8";
                                    int importedCount = o365Service.ImportCalendarBatchDirectAsync(
                                        file.Item2, calendars, progressCallback, 10, selectedTimeZone).GetAwaiter().GetResult();

                                    Serilog.Log.Information("PST日历直接批量导入完成: {Count} 个", importedCount);
                                }

                                lock (lockObj)
                                {
                                    successCount++;
                                }
                            }
                            finally
                            {
                                try { Directory.Delete(tempDir, true); } catch { }
                            }
                        }
                        catch (Exception ex)
                        {
                            lock (lockObj)
                            {
                                failCount++;
                            }
                            Serilog.Log.Error(ex, "同步日历失败: {File}", file.Item1);
                        }

                        lock (lockObj)
                        {
                            current++;
                        }
                    });

                    this.Invoke(new Action(() =>
                    {
                        btnSync.Enabled = true;
                        btnLoadFolder.Enabled = true;
                        progressSync.Style = ProgressBarStyle.Continuous;
                        progressSync.Value = 100;
                        lblProgressPercent.Text = "100%";
                        lblProgressPercent.ForeColor = failCount > 0 ? Color.Red : Color.Green;
                        lblProgressDetail.Text = $"成功: {successCount} 个\n失败: {failCount} 个";
                        lblStatus.Text = $"同步完成: 成功 {successCount}, 失败 {failCount}";
                        lblStatus.ForeColor = failCount > 0 ? Color.Red : Color.Green;
                    }));
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote1);
            panel.Controls.Add(lblNote2);
            panel.Controls.Add(lblNote3);
            panel.Controls.Add(lblCalendarThreadCount);
            panel.Controls.Add(numCalendarThreadCount);
            panel.Controls.Add(lblTimeZone);
            panel.Controls.Add(cmbTimeZone);
            panel.Controls.Add(lblFileList);
            panel.Controls.Add(gridPstFiles);
            panel.Controls.Add(btnLoadFolder);
            panel.Controls.Add(btnSelectAll);
            panel.Controls.Add(btnDeselectAll);
            panel.Controls.Add(btnSync);
            panel.Controls.Add(progressSync);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblProgressTitle);
            panel.Controls.Add(lblProgressPercent);
            panel.Controls.Add(lblProgressDetail);

            return panel;
        }

        /// <summary>
        /// CSV批量同步联系人到O365
        /// CSV格式: TargetEmail,DisplayName,FirstName,LastName,Email,Email2,Email3,Phone,MobilePhone,CompanyName,Department,JobTitle
        /// </summary>
        private Panel CreateCsvSyncContactsPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            var lblTitle = new Label
            {
                Text = "CSV同步联系人到O365",
                Location = new Point(20, 15),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 说明文字
            var lblNote1 = new Label
            {
                Text = "要求: 1.CSV文件命名规则: 邮箱地址.csv (例: zhangsan@example.com.csv)",
                Location = new Point(20, 50),
                Size = new Size(600, 20),
                ForeColor = Color.FromArgb(255, 128, 0)
            };

            var lblNote2 = new Label
            {
                Text = "2.CSV列: 显示名称,名字,姓氏,电子邮件,电话,手机,公司等",
                Location = new Point(20, 72),
                Size = new Size(600, 20),
                ForeColor = Color.FromArgb(255, 128, 0)
            };

            var lblNote3 = new Label
            {
                Text = "3.请先在'登录'页签登录Exchange Online",
                Location = new Point(20, 94),
                Size = new Size(300, 20),
                ForeColor = Color.FromArgb(255, 128, 0)
            };

            // 并发线程
            var lblContactThreadCount = new Label { Text = "并发线程:", Location = new Point(20, 118), AutoSize = true };
            var numContactThreadCount = new NumericUpDown { Location = new Point(85, 115), Size = new Size(60, 25), Minimum = 1, Maximum = 10, Value = 5 };

            // CSV文件列表DataGridView
            var lblFileList = new Label { Text = "CSV文件列表:", Location = new Point(20, 145), AutoSize = true };

            var gridCsvFiles = new DataGridView
            {
                Location = new Point(20, 170),
                Size = new Size(500, 220),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = false,
                ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                RowHeadersVisible = false,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.FixedSingle
            };

            // 添加列 - 文件名即邮箱名
            var colEmail = new DataGridViewTextBoxColumn { Name = "Email", HeaderText = "目标邮箱", Width = 300, ReadOnly = true };
            var colSelect = new DataGridViewCheckBoxColumn { Name = "Select", HeaderText = "选择", Width = 50 };

            gridCsvFiles.Columns.AddRange(new DataGridViewColumn[] { colEmail, colSelect });

            // 右侧进度状态显示区域
            var lblProgressTitle = new Label
            {
                Text = "同步状态:",
                Location = new Point(530, 145),
                Size = new Size(200, 20),
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            var lblProgressPercent = new Label
            {
                Text = "0%",
                Location = new Point(530, 165),
                Size = new Size(200, 40),
                Font = new Font("Microsoft Sans Serif", 24F, FontStyle.Bold),
                ForeColor = Color.FromArgb(0, 120, 215),
                TextAlign = ContentAlignment.MiddleLeft,
                Name = "lblCsvContactsProgressPercent"
            };

            var lblProgressDetail = new Label
            {
                Text = "等待开始...",
                Location = new Point(530, 210),
                Size = new Size(200, 60),
                Font = new Font("Microsoft Sans Serif", 10F),
                ForeColor = Color.Gray
            };

            // 载入文件夹按钮
            var btnLoadFolder = new Button
            {
                Text = "载入文件夹",
                Location = new Point(20, 395),
                Size = new Size(120, 30)
            };

            // 全选按钮
            var btnSelectAll = new Button
            {
                Text = "全选",
                Location = new Point(150, 395),
                Size = new Size(80, 30)
            };

            // 取消全选按钮
            var btnDeselectAll = new Button
            {
                Text = "取消全选",
                Location = new Point(240, 395),
                Size = new Size(80, 30)
            };

            // 下载模板按钮
            var btnDownloadTemplate = new Button
            {
                Text = "下载模板",
                Location = new Point(330, 395),
                Size = new Size(90, 30)
            };

            // 同步按钮
            var btnSync = new Button
            {
                Text = "开始同步",
                Location = new Point(600, 395),
                Size = new Size(120, 30),
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White
            };

            // 进度条
            var progressSync = new ProgressBar
            {
                Location = new Point(20, 430),
                Size = new Size(500, 20),
                Style = ProgressBarStyle.Continuous,
                Name = "progressCsvContactsSync"
            };

            var lblStatus = new Label
            {
                Text = "就绪",
                Location = new Point(20, 455),
                Size = new Size(710, 20),
                ForeColor = Color.Gray
            };

            // 载入文件夹事件
            btnLoadFolder.Click += (s, e) =>
            {
                using (var fbd = new FolderBrowserDialog())
                {
                    if (fbd.ShowDialog() == DialogResult.OK)
                    {
                        gridCsvFiles.Rows.Clear();
                        var files = Directory.GetFiles(fbd.SelectedPath, "*.csv");
                        foreach (var file in files)
                        {
                            // 文件名即邮箱名
                            var email = Path.GetFileNameWithoutExtension(file);
                            gridCsvFiles.Rows.Add(email, false);
                            gridCsvFiles.Rows[gridCsvFiles.RowCount - 1].Tag = file;
                        }
                        lblStatus.Text = $"已载入 {files.Length} 个CSV文件";
                        lblStatus.ForeColor = Color.Gray;
                    }
                }
            };

            // 全选事件
            btnSelectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridCsvFiles.Rows)
                {
                    row.Cells["Select"].Value = true;
                }
            };

            // 取消全选事件
            btnDeselectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridCsvFiles.Rows)
                {
                    row.Cells["Select"].Value = false;
                }
            };

            // 下载模板事件
            btnDownloadTemplate.Click += (s, e) =>
            {
                using (var sfd = new SaveFileDialog())
                {
                    sfd.Filter = "CSV files (*.csv)|*.csv";
                    sfd.FileName = "zhangsan@example.com.csv";
                    if (sfd.ShowDialog() == DialogResult.OK)
                    {
                        // 模板不需要TargetEmail列，邮箱从文件名获取
                        var template = "显示名称,名字,姓氏,电子邮件,电子邮件2,电子邮件3,电话,手机,公司,部门,职位,工作地址,家庭地址,备注,生日\r\n" +
                                       "张三,三,张,zhangsan@example.com,,,,北京公司,技术部,工程师,北京市朝阳区,北京市海淀区,备注内容,1990-01-01";
                        File.WriteAllText(sfd.FileName, template, Encoding.UTF8);
                        lblStatus.Text = "模板已下载";
                        lblStatus.ForeColor = Color.Green;
                    }
                }
            };

            // 同步事件
            btnSync.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在'登录'页签登录Exchange Online";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var selectedFiles = new List<string>();
                foreach (DataGridViewRow row in gridCsvFiles.Rows)
                {
                    if (row.Cells["Select"].Value != null && (bool)row.Cells["Select"].Value)
                    {
                        var filePath = row.Tag?.ToString();
                        if (!string.IsNullOrEmpty(filePath))
                        {
                            selectedFiles.Add(filePath);
                        }
                    }
                }

                if (selectedFiles.Count == 0)
                {
                    lblStatus.Text = "请先选择要同步的CSV文件";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                btnSync.Enabled = false;
                btnLoadFolder.Enabled = false;
                progressSync.Style = ProgressBarStyle.Marquee;
                lblStatus.Text = "正在解析CSV文件...";
                lblStatus.ForeColor = Color.Blue;
                lblProgressPercent.Text = "0%";

                var threadCount = (int)numContactThreadCount.Value;

                Task.Run(() =>
                {
                    int successCount = 0;
                    int failCount = 0;
                    int totalContacts = 0;
                    object lockObj = new object();

                    var tenantId = _exchangeOnlineService.TenantId;
                    var clientId = _exchangeOnlineService.AppId ?? "";
                    var clientSecret = _exchangeOnlineService.ClientSecret ?? "";

                    // 收集所有邮箱和联系人
                    var emailContacts = new Dictionary<string, List<ContactData>>();

                    foreach (var csvFile in selectedFiles)
                    {
                        try
                        {
                            // 从文件名获取目标邮箱 (文件名格式: 邮箱.csv)
                            var targetEmail = Path.GetFileNameWithoutExtension(csvFile);
                            if (string.IsNullOrWhiteSpace(targetEmail) || !targetEmail.Contains("@")) continue;

                            var lines = ReadCsvFileWithEncoding(csvFile);
                            if (lines.Length < 2) continue;

                            // 解析表头（使用CSV解析）
                            var headers = ParseCsvValues(lines[0]);

                            // 跳过空行
                            if (headers.Length == 0 || string.IsNullOrWhiteSpace(headers[0]))
                                continue;

                            for (int i = 1; i < lines.Length; i++)
                            {
                                // 跳过空行
                                if (string.IsNullOrWhiteSpace(lines[i])) continue;

                                var values = ParseCsvValues(lines[i]);
                                if (values.Length < headers.Length) continue;

                                var dict = new Dictionary<string, string>();
                                for (int j = 0; j < headers.Length && j < values.Length; j++)
                                {
                                    dict[headers[j]] = values[j];
                                }

                                // 支持中英文表头
                                var contact = new ContactData
                                {
                                    DisplayName = GetDictValue(dict, "显示名称", "DisplayName"),
                                    FirstName = GetDictValue(dict, "名字", "FirstName"),
                                    LastName = GetDictValue(dict, "姓氏", "LastName"),
                                    Email = GetDictValue(dict, "电子邮件", "Email"),
                                    Email2 = GetDictValue(dict, "电子邮件2", "Email2"),
                                    Email3 = GetDictValue(dict, "电子邮件3", "Email3"),
                                    Phone = GetDictValue(dict, "电话", "Phone"),
                                    MobilePhone = GetDictValue(dict, "手机", "MobilePhone"),
                                    CompanyName = GetDictValue(dict, "公司", "CompanyName"),
                                    Department = GetDictValue(dict, "部门", "Department"),
                                    JobTitle = GetDictValue(dict, "职位", "JobTitle"),
                                    BusinessAddress = GetDictValue(dict, "工作地址", "BusinessAddress"),
                                    HomeAddress = GetDictValue(dict, "家庭地址", "HomeAddress"),
                                    PersonalNotes = GetDictValue(dict, "备注", "PersonalNotes")
                                };

                                if (!emailContacts.ContainsKey(targetEmail))
                                    emailContacts[targetEmail] = new List<ContactData>();

                                emailContacts[targetEmail].Add(contact);
                                totalContacts++;
                            }
                        }
                        catch (Exception ex)
                        {
                            Serilog.Log.Error(ex, "解析CSV失败: {File}", csvFile);
                        }
                    }

                    if (emailContacts.Count == 0)
                    {
                        this.Invoke(new Action(() =>
                        {
                            btnSync.Enabled = true;
                            btnLoadFolder.Enabled = true;
                            progressSync.Style = ProgressBarStyle.Continuous;
                            lblStatus.Text = "未找到有效的联系人数据";
                            lblStatus.ForeColor = Color.Red;
                        }));
                        return;
                    }

                    int processedEmails = 0;
                    int totalEmails = emailContacts.Count;

                    System.Threading.Tasks.Parallel.ForEach(emailContacts,
                        new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = threadCount },
                        kvp =>
                    {
                        try
                        {
                            var targetEmail = kvp.Key;
                            var contacts = kvp.Value;

                            this.Invoke(new Action(() =>
                            {
                                lblProgressDetail.Text = $"正在导入: {targetEmail}\n{contacts.Count} 个联系人";
                            }));

                            var o365Service = new Office365ImportService();
                            if (o365Service.ConnectWithClientSecret(tenantId, clientId, clientSecret, "CSV联系人导入"))
                            {
                                var progressCallback = new Action<int, int, string>((idx, totalCount, status) =>
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        int overallProgress = (processedEmails * 100 + idx * 100 / totalCount) / totalEmails;
                                        progressSync.Value = overallProgress;
                                        lblProgressPercent.Text = $"{overallProgress}%";
                                        lblProgressDetail.Text = $"{targetEmail}: {status}";
                                    }));
                                });

                                int importedCount = o365Service.ImportContactsBatchDirectAsync(
                                    targetEmail, contacts, progressCallback, 10).GetAwaiter().GetResult();

                                Serilog.Log.Information("CSV联系人导入完成: {Email}, {Count} 个", targetEmail, importedCount);
                            }

                            lock (lockObj)
                            {
                                successCount++;
                            }
                        }
                        catch (Exception ex)
                        {
                            lock (lockObj)
                            {
                                failCount++;
                            }
                            Serilog.Log.Error(ex, "导入联系人失败");
                        }

                        lock (lockObj)
                        {
                            processedEmails++;
                        }
                    });

                    this.Invoke(new Action(() =>
                    {
                        btnSync.Enabled = true;
                        btnLoadFolder.Enabled = true;
                        progressSync.Style = ProgressBarStyle.Continuous;
                        progressSync.Value = 100;
                        lblProgressPercent.Text = "100%";
                        lblProgressPercent.ForeColor = failCount > 0 ? Color.Red : Color.Green;
                        lblProgressDetail.Text = $"成功: {successCount} 个邮箱\n失败: {failCount} 个\n共导入: {totalContacts} 个联系人";
                        lblStatus.Text = $"同步完成: 成功 {successCount}, 失败 {failCount}, 共 {totalContacts} 个联系人";
                        lblStatus.ForeColor = failCount > 0 ? Color.Red : Color.Green;
                    }));
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote1);
            panel.Controls.Add(lblNote2);
            panel.Controls.Add(lblNote3);
            panel.Controls.Add(lblContactThreadCount);
            panel.Controls.Add(numContactThreadCount);
            panel.Controls.Add(lblFileList);
            panel.Controls.Add(gridCsvFiles);
            panel.Controls.Add(btnLoadFolder);
            panel.Controls.Add(btnSelectAll);
            panel.Controls.Add(btnDeselectAll);
            panel.Controls.Add(btnDownloadTemplate);
            panel.Controls.Add(btnSync);
            panel.Controls.Add(progressSync);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblProgressTitle);
            panel.Controls.Add(lblProgressPercent);
            panel.Controls.Add(lblProgressDetail);

            return panel;
        }

        /// <summary>
        /// 智能读取CSV文件，自动检测编码（支持UTF-8和GBK/GB2312中文编码）
        /// </summary>
        private string[] ReadCsvFileWithEncoding(string filePath)
        {
            // 首先尝试UTF-8 (带BOM)
            try
            {
                var content = File.ReadAllText(filePath, new System.Text.UTF8Encoding(true));
                if (!string.IsNullOrEmpty(content))
                {
                    var lines = content.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None);
                    // 检查是否包含有效内容
                    if (lines.Length > 0 && !string.IsNullOrWhiteSpace(lines[0]))
                    {
                        // 检查是否有乱码特征（包含大量问号或乱码字符）
                        bool hasGarbled = lines[0].Contains("�") || (lines[0].Contains("?") && lines[0].Contains("="));
                        if (!hasGarbled)
                        {
                            Program.BatchToO365Logger.Debug("CSV文件 {File} 使用UTF-8编码(BOM)", filePath);
                            return lines;
                        }
                    }
                }
            }
            catch { }

            // 尝试UTF-8 (不带BOM)
            try
            {
                var content = File.ReadAllText(filePath, System.Text.Encoding.UTF8);
                if (!string.IsNullOrEmpty(content))
                {
                    var lines = content.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None);
                    if (lines.Length > 0 && !string.IsNullOrWhiteSpace(lines[0]))
                    {
                        // 检查是否有乱码特征
                        bool hasGarbled = lines[0].Contains("�");
                        if (!hasGarbled)
                        {
                            Program.BatchToO365Logger.Debug("CSV文件 {File} 使用UTF-8编码", filePath);
                            return lines;
                        }
                    }
                }
            }
            catch { }

            // 尝试GBK编码（中文Windows常用）
            try
            {
                var content = File.ReadAllText(filePath, System.Text.Encoding.GetEncoding("GBK"));
                if (!string.IsNullOrEmpty(content))
                {
                    var lines = content.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None);
                    if (lines.Length > 0 && !string.IsNullOrWhiteSpace(lines[0]))
                    {
                        Program.BatchToO365Logger.Debug("CSV文件 {File} 使用GBK编码", filePath);
                        return lines;
                    }
                }
            }
            catch { }

            // 尝试GB2312编码
            try
            {
                var content = File.ReadAllText(filePath, System.Text.Encoding.GetEncoding("GB2312"));
                if (!string.IsNullOrEmpty(content))
                {
                    var lines = content.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None);
                    if (lines.Length > 0 && !string.IsNullOrWhiteSpace(lines[0]))
                    {
                        Program.BatchToO365Logger.Debug("CSV文件 {File} 使用GB2312编码", filePath);
                        return lines;
                    }
                }
            }
            catch { }

            // 最后回退到系统默认编码
            Program.BatchToO365Logger.Warning("CSV文件 {File} 无法识别编码，使用系统默认编码", filePath);
            return File.ReadAllLines(filePath);
        }

        /// <summary>
        /// 从字典中获取值，支持中英文键名
        /// </summary>
        private string GetDictValue(Dictionary<string, string> dict, string chineseKey, string englishKey)
        {
            if (dict.ContainsKey(chineseKey) && !string.IsNullOrWhiteSpace(dict[chineseKey]))
                return dict[chineseKey];
            if (dict.ContainsKey(englishKey) && !string.IsNullOrWhiteSpace(dict[englishKey]))
                return dict[englishKey];
            return "";
        }

        /// <summary>
        /// 正确解析CSV行（处理带引号和转义字符的字段）
        /// </summary>
        private string[] ParseCsvValues(string line)
        {
            var result = new List<string>();
            var current = new StringBuilder();
            bool inQuotes = false;

            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];

                if (c == '"')
                {
                    if (inQuotes)
                    {
                        // 在引号内，检查下一个字符是否是引号（转义引号）
                        if (i + 1 < line.Length && line[i + 1] == '"')
                        {
                            current.Append('"');
                            i++; // 跳过下一个引号
                        }
                        else
                        {
                            // 结束引号
                            inQuotes = false;
                        }
                    }
                    else
                    {
                        // 开始引号
                        inQuotes = true;
                    }
                }
                else if (c == ',' && !inQuotes)
                {
                    result.Add(current.ToString().Trim().Trim('"'));
                    current.Clear();
                }
                else
                {
                    current.Append(c);
                }
            }

            // 添加最后一个字段
            result.Add(current.ToString().Trim().Trim('"'));

            return result.ToArray();
        }

