            var lblTimeZone = new Label { Text = "时区:", Location = new Point(160, 118), AutoSize = true };
            var cmbTimeZone = new ComboBox { Location = new Point(195, 115), Size = new Size(180, 25), DropDownStyle = ComboBoxStyle.DropDownList };

            var timeZones = new List<KeyValuePair<string, string>>();
            var cityMap = new Dictionary<int, string>
            {
                { -12, "国际日期变更线西" }, { -11, "萨摩亚" }, { -10, "夏威夷" },
                { -9, "阿拉斯加" }, { -8, "洛杉矶" }, { -7, "丹佛" },
                { -6, "芝加哥" }, { -5, "纽约" }, { -4, "圣地亚哥" },
                { -3, "圣保罗" }, { -2, "大西洋中部" }, { -1, "亚速尔群岛" },
                { 0, "伦敦" }, { 1, "巴黎" }, { 2, "开罗" },
                { 3, "莫斯科" }, { 4, "迪拜" }, { 5, "伊斯兰堡" },
                { 6, "达卡" }, { 7, "曼谷" }, { 8, "北京" },
                { 9, "东京" }, { 10, "悉尼" }, { 11, "所罗门群岛" },
                { 12, "奥克兰" }
            };

            for (int offset = -12; offset <= 12; offset++)
            {
                string sign = offset >= 0 ? "+" : "";
