            // 解析VCF文件并转换为联系人对象
            List<ContactData> ParseVcfToContacts(string vcfPath)
            {
                var contacts = new List<ContactData>();
                try
                {
                    var lines = File.ReadAllLines(vcfPath, Encoding.UTF8);
                    ContactData currentContact = null;
                    string currentEmail = null;

                    foreach (var line in lines)
                    {
                        var trimmedLine = line.Trim();
                        if (trimmedLine == "BEGIN:VCARD")
                        {
                            currentContact = new ContactData();
                        }
                        else if (trimmedLine == "END:VCARD" && currentContact != null)
                        {
                            if (!string.IsNullOrEmpty(currentEmail))
                            {
                                currentContact.Email = currentEmail;
                            }
                            if (!string.IsNullOrEmpty(currentContact.DisplayName) || !string.IsNullOrEmpty(currentContact.Email))
                            {
                                contacts.Add(currentContact);
                            }
                            currentContact = null;
                            currentEmail = null;
                        }
                        else if (currentContact != null)
                        {
                            if (trimmedLine.StartsWith("FN:") || trimmedLine.StartsWith("FN;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(2);
                                currentContact.DisplayName = value.Trim().Trim('"');
                            }
                            else if (trimmedLine.StartsWith("N:") || trimmedLine.StartsWith("N;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(2);
                                var parts = value.Split(';');
                                if (parts.Length >= 2)
                                {
                                    currentContact.LastName = parts[0].Trim().Trim('"');
                                    currentContact.FirstName = parts[1].Trim().Trim('"');
                                }
                            }
                            else if (trimmedLine.StartsWith("EMAIL:") || trimmedLine.StartsWith("EMAIL;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(6);
                                currentEmail = value.Trim().Trim('"');
                            }
                            else if (trimmedLine.StartsWith("TEL:") || trimmedLine.StartsWith("TEL;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(4);
                                currentContact.Phone = value.Trim().Trim('"');
                            }
                            else if (trimmedLine.StartsWith("ORG:") || trimmedLine.StartsWith("ORG;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(4);
                                currentContact.Department = value.Split(';')[0].Trim().Trim('"');
                            }
                            else if (trimmedLine.StartsWith("TITLE:") || trimmedLine.StartsWith("TITLE;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(6);
                                currentContact.JobTitle = value.Trim().Trim('"');
                            }
                            else if (trimmedLine.StartsWith("NOTE:") || trimmedLine.StartsWith("NOTE;"))
                            {
                                var value = trimmedLine.Contains(":") ? trimmedLine.Substring(trimmedLine.IndexOf(":") + 1) : trimmedLine.Substring(5);
                                currentContact.PersonalNotes = value.Trim().Trim('"');
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    Serilog.Log.Error(ex, "解析VCF失败: {Path}", vcfPath);
                }
                return contacts;
            }

            // 载入文件夹事件
            btnLoadFolder.Click += (s, e) =>
            {
                using (var fbd = new FolderBrowserDialog())
                {
                    if (fbd.ShowDialog() == DialogResult.OK)
                    {
                        gridVcfFiles.Rows.Clear();
                        var files = Directory.GetFiles(fbd.SelectedPath, "*.vcf");
                        foreach (var file in files)
                        {
                            // 文件名即邮箱名
                            var email = Path.GetFileNameWithoutExtension(file);
                            gridVcfFiles.Rows.Add(email, false);
                            gridVcfFiles.Rows[gridVcfFiles.RowCount - 1].Tag = file;
                        }
                        lblStatus.Text = $"已载入 {files.Length} 个VCF文件";
                        lblStatus.ForeColor = Color.Gray;
                    }
                }
            };

            // 全选事件
            btnSelectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridVcfFiles.Rows)
                {
                    row.Cells["Select"].Value = true;
                }
            };

            // 取消全选事件
            btnDeselectAll.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in gridVcfFiles.Rows)
                {
                    row.Cells["Select"].Value = false;
                }
            };

            // 同步事件
            btnSync.Click += (s, e) =>
            {
                if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
                {
                    lblStatus.Text = "请先在'登录'页签登录Office 365";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                var selectedFiles = new List<string>();
                foreach (DataGridViewRow row in gridVcfFiles.Rows)
                {
                    if (row.Cells["Select"].Value != null && (bool)row.Cells["Select"].Value)
                    {
                        var filePath = row.Tag?.ToString();
                        if (!string.IsNullOrEmpty(filePath))
                        {
                            selectedFiles.Add(filePath);
                        }
                    }
                }

                if (selectedFiles.Count == 0)
                {
                    lblStatus.Text = "请先选择要同步的VCF文件";
                    lblStatus.ForeColor = Color.Red;
                    return;
                }

                btnSync.Enabled = false;
                btnLoadFolder.Enabled = false;
                progressSync.Style = ProgressBarStyle.Marquee;
                lblStatus.Text = "正在解析VCF文件...";
                lblStatus.ForeColor = Color.Blue;
                lblProgressPercent.Text = "0%";

                var threadCount = (int)numThreadCount.Value;

                Task.Run(() =>
                {
                    int successCount = 0;
                    int failCount = 0;
                    int totalContacts = 0;
                    object lockObj = new object();

                    var tenantId = _exchangeOnlineService.TenantId;
                    var clientId = _exchangeOnlineService.AppId ?? "";
                    var clientSecret = _exchangeOnlineService.ClientSecret ?? "";

                    // 收集所有邮箱和联系人
                    var emailContacts = new Dictionary<string, List<ContactData>>();

                    foreach (var vcfFile in selectedFiles)
                    {
                        try
                        {
                            // 从文件名获取目标邮箱 (文件名格式: 邮箱.vcf)
                            var targetEmail = Path.GetFileNameWithoutExtension(vcfFile);
                            if (string.IsNullOrWhiteSpace(targetEmail) || !targetEmail.Contains("@")) continue;

                            var contacts = ParseVcfToContacts(vcfFile);
                            if (contacts.Count == 0) continue;

                            if (!emailContacts.ContainsKey(targetEmail))
                                emailContacts[targetEmail] = new List<ContactData>();

                            emailContacts[targetEmail].AddRange(contacts);
                            totalContacts += contacts.Count;
                        }
                        catch (Exception ex)
                        {
                            Serilog.Log.Error(ex, "解析VCF失败: {File}", vcfFile);
                        }
                    }

                    if (emailContacts.Count == 0)
                    {
                        this.Invoke(new Action(() =>
                        {
                            btnSync.Enabled = true;
                            btnLoadFolder.Enabled = true;
                            progressSync.Style = ProgressBarStyle.Continuous;
                            lblStatus.Text = "未找到有效的联系人数据";
                            lblStatus.ForeColor = Color.Red;
                        }));
                        return;
                    }

                    int processedEmails = 0;
                    int totalEmails = emailContacts.Count;

                    System.Threading.Tasks.Parallel.ForEach(emailContacts,
                        new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = threadCount },
                        kvp =>
                    {
                        try
                        {
                            var targetEmail = kvp.Key;
                            var contacts = kvp.Value;

                            this.Invoke(new Action(() =>
                            {
                                lblProgressDetail.Text = $"正在导入: {targetEmail}\n{contacts.Count} 个联系人";
                            }));

                            var o365Service = new Office365ImportService();
                            if (o365Service.ConnectWithClientSecret(tenantId, clientId, clientSecret, "VCF联系人导入"))
                            {
                                var progressCallback = new Action<int, int, string>((idx, totalCount, status) =>
                                {
                                    this.Invoke(new Action(() =>
                                    {
                                        int overallProgress = (processedEmails * 100 + idx * 100 / totalCount) / totalEmails;
                                        progressSync.Value = overallProgress;
                                        lblProgressPercent.Text = $"{overallProgress}%";
                                        lblProgressDetail.Text = $"{targetEmail}: {status}";
                                    }));
                                });

                                int importedCount = o365Service.ImportContactsBatchDirectAsync(
                                    targetEmail, contacts, progressCallback).GetAwaiter().GetResult();

                                Serilog.Log.Information("VCF联系人导入完成: {Email}, {Count} 个", targetEmail, importedCount);
                            }

                            lock (lockObj)
                            {
                                successCount++;
                            }
                        }
                        catch (Exception ex)
                        {
                            lock (lockObj)
                            {
                                failCount++;
                            }
                            Serilog.Log.Error(ex, "导入联系人失败");
                        }

                        lock (lockObj)
                        {
                            processedEmails++;
                        }
                    });

                    this.Invoke(new Action(() =>
                    {
                        btnSync.Enabled = true;
                        btnLoadFolder.Enabled = true;
                        progressSync.Style = ProgressBarStyle.Continuous;
                        progressSync.Value = 100;
                        lblProgressPercent.Text = "100%";
                        lblProgressPercent.ForeColor = failCount > 0 ? Color.Red : Color.Green;
                        lblProgressDetail.Text = $"成功: {successCount} 个邮箱\n失败: {failCount} 个\n共导入: {totalContacts} 个联系人";
                        lblStatus.Text = $"同步完成: 成功 {successCount}, 失败 {failCount}, 共 {totalContacts} 个联系人";
                        lblStatus.ForeColor = failCount > 0 ? Color.Red : Color.Green;
                    }));
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote1);
            panel.Controls.Add(lblNote2);
            panel.Controls.Add(lblNote3);
            panel.Controls.Add(lblThreadCount);
            panel.Controls.Add(numThreadCount);
            panel.Controls.Add(lblFileList);
            panel.Controls.Add(gridVcfFiles);
            panel.Controls.Add(btnLoadFolder);
            panel.Controls.Add(btnSelectAll);
            panel.Controls.Add(btnDeselectAll);
            panel.Controls.Add(btnSync);
            panel.Controls.Add(progressSync);
            panel.Controls.Add(lblStatus);
            panel.Controls.Add(lblProgressTitle);
            panel.Controls.Add(lblProgressPercent);
            panel.Controls.Add(lblProgressDetail);

            return panel;
        }

        // 导入PST到Office 365
        private bool ImportPstToOffice365(string pstFilePath, string targetEmail)
        {
            try
            {
                Serilog.Log.Information("开始导入PST到Office 365: {Path}, Target: {Email}", pstFilePath, targetEmail);

                // 创建临时目录提取EML
                var tempDir = Path.Combine(Path.GetTempPath(), "PstImport_" + Guid.NewGuid().ToString("N"));
                Directory.CreateDirectory(tempDir);

                try
                {
                    // 提取PST到EML文件
                    var pstExtractService = new PstExtractService();
                    pstExtractService.ExtractToEml(pstFilePath, tempDir);

                    // 获取提取的EML文件
                    var emlFiles = Directory.GetFiles(tempDir, "*.eml", SearchOption.AllDirectories);
                    Serilog.Log.Information("提取到 {Count} 个EML文件", emlFiles.Length);

                    // 逐个导入到Office 365
                    int successCount = 0;
                    foreach (var emlFile in emlFiles)
                    {
                        try
                        {
                            // 上传到目标邮箱
                            if (_office365Service.ImportEml(emlFile, "Inbox"))
                            {
                                successCount++;
                            }
                        }
                        catch (Exception ex)
                        {
                            Serilog.Log.Warning(ex, "上传邮件失败: {File}", emlFile);
                        }
                    }

                    Serilog.Log.Information("PST导入完成: 成功 {Count}/{Total}", successCount, emlFiles.Length);
                    return successCount > 0;
                }
                finally
                {
                    // 清理临时目录
                    try
                    {
                        Directory.Delete(tempDir, true);
                    }
                    catch { }
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Error(ex, "PST导入Office 365失败: {Path}", pstFilePath);
                return false;
            }
        }

        // 导入PST到Office 365 (带凭据) - 使用 Graph API
        // progressCallback: (currentEmail, totalEmails, statusMessage) => { }
        private bool ImportPstToOffice365WithCreds(string pstFilePath, string targetEmail, string tenantId, string clientId, string clientSecret, string accountName, Action<int, int, string> progressCallback = null)
        {
            try
            {
                // targetEmail 就是 PST 文件名（不带扩展名），即 Office 365 用户邮箱
                Serilog.Log.Information("========================================");
                Serilog.Log.Information("开始导入PST到Office 365");
                Serilog.Log.Information("PST文件: {Path}", pstFilePath);
                Serilog.Log.Information("目标邮箱: {Email}", targetEmail);
                Serilog.Log.Information("账户: {Account}", accountName);
                Serilog.Log.Information("========================================");
                Log($"[PST导入] ========== 开始导入 ==========");
                Log($"[PST导入] PST文件: {pstFilePath}");
                Log($"[PST导入] 目标邮箱: {targetEmail}");
                Log($"[PST导入] 账户: {accountName}");

                // 创建临时目录提取EML
                var tempDir = Path.Combine(Path.GetTempPath(), "PstImport_" + Guid.NewGuid().ToString("N"));
                Directory.CreateDirectory(tempDir);

                try
                {
                    // 提取PST到EML文件
                    Serilog.Log.Information("正在提取PST文件到EML...");
                    Log($"[PST导入] 正在提取PST文件到EML...");
                    var pstExtractService = new PstExtractService();
                    pstExtractService.ExtractToEml(pstFilePath, tempDir);

                    // 获取提取的EML文件
                    var emlFiles = Directory.GetFiles(tempDir, "*.eml", SearchOption.AllDirectories);
                    Serilog.Log.Information("提取完成，共 {Count} 个EML文件", emlFiles.Length);
                    Log($"[PST导入] 提取完成，共 {emlFiles.Length} 个EML文件");

                    // 创建Office 365服务并连接
                    Serilog.Log.Information("正在连接Office 365 (Tenant: {TenantId}, Client: {ClientId})...", tenantId, clientId);
                    Log($"[PST导入] 正在连接Office 365...");
                    var o365Service = new Office365ImportService();
                    if (!o365Service.ConnectWithClientSecret(tenantId, clientId, clientSecret, accountName))
                    {
                        Serilog.Log.Error("Office 365连接失败，请检查租户ID、客户端ID和客户端密钥是否正确");
                        return false;
                    }
                    Serilog.Log.Information("Office 365连接成功");

                    // 逐个导入到目标用户的邮箱（使用 Graph API）
                    int successCount = 0;
                    int totalEmails = emlFiles.Length;
                    int currentEmail = 0;

                    Serilog.Log.Information("开始导入 {Total} 封邮件到 {Email}", totalEmails, targetEmail);

                    foreach (var emlFile in emlFiles)
                    {
                        currentEmail++;
                        string statusMsg = "";
                        try
                        {
                            // 计算相对路径，获取文件夹名称
                            string relativePath = emlFile.Replace(tempDir + Path.DirectorySeparatorChar, "");
                            string folderName = "Inbox"; // 默认收件箱
                            if (relativePath.Contains(Path.DirectorySeparatorChar.ToString()))
                            {
                                // 提取第一层文件夹名（如 "Inbox", "Sent", "自定义文件夹" 等）
                                folderName = relativePath.Split(Path.DirectorySeparatorChar)[0];
                            }

                            // 获取邮件主题用于日志
                            var fileName = Path.GetFileName(emlFile);
                            Serilog.Log.Information("正在导入邮件 [{Current}/{Total}]: {File} -> {Folder}",
                                currentEmail, totalEmails, fileName, folderName);
                            Log($"[PST导入] 正在导入邮件 [{currentEmail}/{totalEmails}]: {fileName} -> {folderName}");

                            // 使用 Graph API 上传到目标用户邮箱的对应文件夹
                            // targetEmail 是 PST 文件名，即 Office 365 用户邮箱地址
                            if (o365Service.ImportEmlWithGraph(emlFile, targetEmail, folderName))
                            {
                                successCount++;
                                statusMsg = $"成功";
                                Serilog.Log.Information("邮件导入成功 [{Current}/{Total}]: {Subject}",
                                    currentEmail, totalEmails, fileName);
                                Log($"[PST导入] 成功 [{currentEmail}/{totalEmails}]: {fileName}");
                            }
                            else
                            {
                                statusMsg = $"失败";
                                Log($"[PST导入] 失败 [{currentEmail}/{totalEmails}]: {fileName}");
                                Serilog.Log.Warning("邮件导入失败 [{Current}/{Total}]: {File}",
                                    currentEmail, totalEmails, fileName);
                            }
                        }
                        catch (Exception ex)
                        {
                            statusMsg = $"异常: {ex.Message}";
                            Serilog.Log.Warning(ex, "上传邮件异常 [{Current}/{Total}]: {File}",
                                currentEmail, totalEmails, Path.GetFileName(emlFile));
                            Log($"[PST导入] 异常 [{currentEmail}/{totalEmails}]: {Path.GetFileName(emlFile)} - {ex.Message}");
                        }

                        // 调用进度回调更新UI
                        if (progressCallback != null)
                        {
                            try
                            {
                                progressCallback(currentEmail, totalEmails, statusMsg);
                            }
                            catch { }
                        }
                    }

                    Serilog.Log.Information("PST导入完成: 成功 {Count}/{Total}, 目标邮箱: {Email}",
                        successCount, totalEmails, targetEmail);
                    Log($"[PST导入] 导入完成: 成功 {successCount}/{totalEmails}, 目标邮箱: {targetEmail}");
                    return successCount > 0;
                }
                finally
                {
                    // 清理临时目录
                    try
                    {
                        Directory.Delete(tempDir, true);
                    }
                    catch { }
                }
            }
            catch (Exception ex)
            {
                Serilog.Log.Error(ex, "PST导入Office 365失败: {Path}", pstFilePath);
                return false;
            }
        }

        // 导入单个PST文件
        private bool ImportPstFile(string pstFilePath)
        {
            try
            {
                Serilog.Log.Information("开始导入PST文件: {Path}", pstFilePath);

                // 创建Outlook应用
                var outlookApp = new Microsoft.Office.Interop.Outlook.Application();
                var outlookNamespace = outlookApp.GetNamespace("MAPI");

                // 导入PST文件
                outlookNamespace.AddStore(pstFilePath);

                Serilog.Log.Information("PST文件导入成功: {Path}", pstFilePath);
                return true;
            }
            catch (Exception ex)
            {
                Serilog.Log.Error(ex, "PST文件导入失败: {Path}", pstFilePath);
                return false;
            }
        }

        private Panel CreateExchangeOnPremiseToolkitPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            // 创建嵌套TabControl
            var tabControl = new TabControl
            {
                Location = new Point(0, 0),
                Size = new Size(panel.Width - 20, panel.Height - 20),
                Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Left | AnchorStyles.Right
            };

            // 登录页
            var loginTab = new TabPage("连接设置");
            loginTab.Controls.Add(CreateOnPremiseLoginPanel());
            tabControl.TabPages.Add(loginTab);

            // 邮件导出EML页
            var emlExportTab = new TabPage("导出EML");
            emlExportTab.Controls.Add(CreateOnPremiseExportEmlPanel());
            tabControl.TabPages.Add(emlExportTab);

            // 邮件导出PST页
            var pstExportTab = new TabPage("导出PST");
            pstExportTab.Controls.Add(CreateOnPremiseExportPstPanel());
            tabControl.TabPages.Add(pstExportTab);

            // EWS投递到IMAP页
            var ewsToImapTab = new TabPage("EWS投递IMAP");
            ewsToImapTab.Controls.Add(CreateOnPremiseEwsToImapPanel());
            tabControl.TabPages.Add(ewsToImapTab);

            // 联系人导出页
            var contactExportTab = new TabPage("联系人导出");
            contactExportTab.Controls.Add(CreateOnPremiseContactExportPanel());
            tabControl.TabPages.Add(contactExportTab);

            // 日历导出页
            var calendarExportTab = new TabPage("日历导出");
            calendarExportTab.Controls.Add(CreateOnPremiseCalendarExportPanel());
            tabControl.TabPages.Add(calendarExportTab);

            // 批量导出PST页
            var batchExportPstTab = new TabPage("批量导出PST");
            batchExportPstTab.Controls.Add(CreateOnPremiseBatchExportPstPanel());
            tabControl.TabPages.Add(batchExportPstTab);

            // 批量投递到IMAP页
            var batchToImapTab = new TabPage("批量投递IMAP");
            batchToImapTab.Controls.Add(CreateOnPremiseBatchToImapPanel());
            tabControl.TabPages.Add(batchToImapTab);

            panel.Controls.Add(tabControl);

            return panel;
        }

