        /// <summary>
        /// 创建邮件导出EML面板
        /// </summary>
        private Panel CreateOnPremiseExportEmlPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            var lblTitle = new Label
            {
                Text = "邮件导出EML",
                Location = new Point(20, 15),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 说明
            var lblNote = new Label
            {
                Text = "通过EWS导出邮件为EML格式，按收件箱/发件箱分类保存",
                Location = new Point(20, 40),
                Size = new Size(450, 20),
                ForeColor = Color.Gray,
                Font = new Font("Microsoft Sans Serif", 8F)
            };

            // 导出邮箱
            var lblTargetMailbox = new Label { Text = "导出邮箱:", Location = new Point(20, 70), AutoSize = true };
            var txtExportTargetMailbox = new TextBox { Location = new Point(100, 68), Size = new Size(250, 25) };

            // 日期范围
            var lblDateRange = new Label { Text = "日期范围:", Location = new Point(20, 105), AutoSize = true };
            var dtpExportStartDate = new DateTimePicker { Location = new Point(100, 103), Size = new Size(120, 25), Format = DateTimePickerFormat.Short };
            var lblTo = new Label { Text = "至", Location = new Point(225, 107), AutoSize = true };
            var dtpExportEndDate = new DateTimePicker { Location = new Point(245, 103), Size = new Size(120, 25), Format = DateTimePickerFormat.Short };

            // 输出目录
            var lblOutputDir = new Label { Text = "输出目录:", Location = new Point(20, 140), AutoSize = true };
            var txtExportOutputDir = new TextBox { Location = new Point(100, 138), Size = new Size(280, 25) };
            var btnBrowseExportDir = new Button { Text = "浏览...", Location = new Point(385, 136), Size = new Size(70, 25) };
            btnBrowseExportDir.Click += (s, e) =>
            {
                using (var fb = new FolderBrowserDialog())
                {
                    fb.Description = "选择EML输出目录";
                    if (fb.ShowDialog() == DialogResult.OK)
                    {
                        txtExportOutputDir.Text = fb.SelectedPath;
                    }
                }
            };

            // 选项
            var chkExportReceived = new CheckBox { Text = "收件箱", Location = new Point(100, 170), AutoSize = true, Checked = true };
            var chkExportSent = new CheckBox { Text = "发件箱", Location = new Point(170, 170), AutoSize = true, Checked = false };

            // 导出按钮
            var btnExportEml = new Button
            {
                Text = "开始导出",
                Location = new Point(100, 205),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条
            var prgExportEml = new ProgressBar { Location = new Point(20, 245), Size = new Size(500, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            var lblExportProgress = new Label { Text = "", Location = new Point(20, 270), AutoSize = true, ForeColor = Color.Gray };

            btnExportEml.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtExportOutputDir.Text))
                {
                    MessageBox.Show("请选择输出目录", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (!Directory.Exists(txtExportOutputDir.Text))
                {
                    try { Directory.CreateDirectory(txtExportOutputDir.Text); }
                    catch (Exception ex)
                    {
                        MessageBox.Show("创建输出目录失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        return;
                    }
                }

                btnExportEml.Enabled = false;
                prgExportEml.Visible = true;
                prgExportEml.Value = 0;
                lblExportProgress.Text = "准备导出...";
                _logTextBox.Clear();
                _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 开始EML导出...\n");

                Task.Run(() =>
                {
                    try
                    {
                        string targetMailbox = txtExportTargetMailbox.Text.Trim();
                        DateTime startDate = dtpExportStartDate.Value.Date;
                        DateTime endDate = dtpExportEndDate.Value.Date.AddDays(1).AddSeconds(-1);
                        bool includeReceived = chkExportReceived.Checked;
                        bool includeSent = chkExportSent.Checked;

                        int totalExported = 0;
                        int totalErrors = 0;

                        // 导出收件箱
                        if (includeReceived)
                        {
                            this.Invoke(new Action(() =>
                            {
                                lblExportProgress.Text = "正在导出收件箱...";
                                _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 正在导出收件箱...\n");
                            }));
                            var (count, errors) = ExportEmailsFromFolder(
                                targetMailbox,
                                Microsoft.Exchange.WebServices.Data.WellKnownFolderName.Inbox,
                                startDate, endDate,
                                txtExportOutputDir.Text,
                                prgExportEml,
                                lblExportProgress,
                                null);
                            totalExported += count;
                            totalErrors += errors;
                        }

                        // 导出发件箱
                        if (includeSent)
                        {
                            this.Invoke(new Action(() =>
                            {
                                lblExportProgress.Text = "正在导出发件箱...";
                                _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 正在导出发件箱...\n");
                            }));
                            var (count, errors) = ExportEmailsFromFolder(
                                targetMailbox,
                                Microsoft.Exchange.WebServices.Data.WellKnownFolderName.SentItems,
                                startDate, endDate,
                                txtExportOutputDir.Text,
                                prgExportEml,
                                lblExportProgress,
                                null);
                            totalExported += count;
                            totalErrors += errors;
                        }

                        this.Invoke(new Action(() =>
                        {
                            lblExportProgress.Text = $"导出完成! 共导出 {totalExported} 封邮件，{totalErrors} 个错误";
                            lblExportProgress.ForeColor = totalErrors > 0 ? Color.Orange : Color.Green;
                            _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 导出完成! 共导出 {totalExported} 封邮件，{totalErrors} 个错误\n");
                            btnExportEml.Enabled = true;
                            prgExportEml.Value = prgExportEml.Maximum;
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblExportProgress.Text = "导出失败: " + ex.Message;
                            lblExportProgress.ForeColor = Color.Red;
                            _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 导出失败: {ex.Message}\n");
                            btnExportEml.Enabled = true;
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblTargetMailbox);
            panel.Controls.Add(txtExportTargetMailbox);
            panel.Controls.Add(lblDateRange);
            panel.Controls.Add(dtpExportStartDate);
            panel.Controls.Add(lblTo);
            panel.Controls.Add(dtpExportEndDate);
            panel.Controls.Add(lblOutputDir);
            panel.Controls.Add(txtExportOutputDir);
            panel.Controls.Add(btnBrowseExportDir);
            panel.Controls.Add(chkExportReceived);
            panel.Controls.Add(chkExportSent);
            panel.Controls.Add(btnExportEml);
            panel.Controls.Add(prgExportEml);
            panel.Controls.Add(lblExportProgress);

            return panel;
        }

        /// <summary>
        /// 从指定文件夹导出EML文件（使用服务方法）
        /// </summary>
        private (int exported, int errors) ExportEmailsFromFolder(
            string targetMailbox,
            Microsoft.Exchange.WebServices.Data.WellKnownFolderName folderName,
            DateTime startDate,
            DateTime endDate,
            string outputDir,
            ProgressBar progressBar,
            Label progressLabel,
            TextBox logTextBox)
        {
            return OnPremiseToolkitService.ExportEmailsToEml(
                targetMailbox,
                folderName,
                startDate,
                endDate,
                outputDir,
                (processed, total) =>
                {
                    this.Invoke(new Action(() =>
                    {
                        if (total > 0)
                        {
                            progressBar.Maximum = Math.Max(total, 1);
                            progressBar.Value = Math.Min(processed, progressBar.Maximum);
                            progressLabel.Text = $"已处理 {processed}/{total} 封邮件";
                        }
                        else
                        {
                            progressBar.Maximum = 1;
                            progressBar.Value = 0;
                            progressLabel.Text = "正在处理...";
                        }
                    }));
                },
                (errorMsg) =>
                {
                    this.Invoke(new Action(() =>
                    {
                        if (logTextBox != null)
                            AppendLog(logTextBox, $"[错误] {errorMsg}");
                        else
                            _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] [错误] {errorMsg}\n");
                    }));
                });
        }

        /// <summary>
        /// 向日志文本框追加内容
        /// </summary>
        private void AppendLog(TextBox textBox, string message)
        {
            if (textBox.InvokeRequired)
            {
                textBox.Invoke(new Action(() => AppendLog(textBox, message)));
                return;
            }
            textBox.AppendText(message + Environment.NewLine);
            textBox.SelectionStart = textBox.Text.Length;
            textBox.ScrollToCaret();
        }

        /// <summary>
        /// 清理文件名中的非法字符
        /// </summary>
        private string SanitizeFileName(string fileName)
        {
            if (string.IsNullOrEmpty(fileName)) return "无主题";
            var invalid = Path.GetInvalidFileNameChars();
            foreach (var c in invalid)
            {
                fileName = fileName.Replace(c, '_');
            }
            if (fileName.Length > 100) fileName = fileName.Substring(0, 100);
            return fileName;
        }

        /// <summary>
        /// 创建邮件导出PST面板
        /// </summary>
        private Panel CreateOnPremiseExportPstPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            var lblTitle = new Label
            {
                Text = "邮件导出PST",
                Location = new Point(20, 15),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 说明
            var lblNote = new Label
            {
                Text = "使用本地Outlook导出邮箱内容到PST文件",
                Location = new Point(20, 40),
                Size = new Size(400, 20),
                ForeColor = Color.Gray,
                Font = new Font("Microsoft Sans Serif", 8F)
            };

            // 账户选择
            var lblAccount = new Label { Text = "导出账户:", Location = new Point(20, 70), AutoSize = true };
            var cmbPstAccount = new ComboBox { Location = new Point(100, 68), Size = new Size(280, 25), DropDownStyle = ComboBoxStyle.DropDown };

            // 加载账户按钮
            var btnLoadPstAccounts = new Button { Text = "刷新账户", Location = new Point(385, 66), Size = new Size(80, 25) };

            // 输出文件
            var lblOutputFile = new Label { Text = "输出文件:", Location = new Point(20, 105), AutoSize = true };
            var txtExportPstOutputFile = new TextBox { Location = new Point(100, 103), Size = new Size(280, 25) };
            var btnBrowseExportPstFile = new Button { Text = "浏览...", Location = new Point(385, 101), Size = new Size(70, 25) };
            btnBrowseExportPstFile.Click += (s, e) =>
            {
                using (var sf = new SaveFileDialog())
                {
                    sf.Filter = "PST文件|*.pst";
                    sf.Title = "选择PST输出文件";
                    sf.FileName = $"Export_{DateTime.Now:yyyyMMdd}.pst";
                    if (sf.ShowDialog() == DialogResult.OK)
                    {
                        txtExportPstOutputFile.Text = sf.FileName;
                    }
                }
            };

            // 导出选项
            var lblOptions = new Label { Text = "导出选项:", Location = new Point(20, 140), AutoSize = true };
            var chkExportPstReceived = new CheckBox { Text = "收件箱", Location = new Point(100, 138), AutoSize = true, Checked = true };
            var chkExportPstSent = new CheckBox { Text = "发件箱", Location = new Point(170, 138), AutoSize = true, Checked = true };
            var chkExportPstContacts = new CheckBox { Text = "联系人", Location = new Point(240, 138), AutoSize = true, Checked = true };
            var chkExportPstCalendar = new CheckBox { Text = "日历", Location = new Point(310, 138), AutoSize = true, Checked = true };

            // 导出按钮
            var btnExportPst = new Button
            {
                Text = "开始导出",
                Location = new Point(100, 175),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条
            var prgExportPst = new ProgressBar { Location = new Point(20, 215), Size = new Size(500, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            var lblExportPstProgress = new Label { Text = "", Location = new Point(20, 240), AutoSize = true, ForeColor = Color.Gray };

            // 加载账户（异步执行，避免阻塞UI）
            Action loadAccounts = () =>
            {
                try
                {
                    cmbPstAccount.Items.Clear();

                    // PST导出使用Outlook COM，不需要连接Exchange
                    // 如果服务为null，创建一个临时实例
                    if (_onPremiseToolkitService == null)
                    {
                        this.Invoke(new Action(() => _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] [1/4] 正在初始化Outlook COM服务...\n")));
                        _onPremiseToolkitService = new ExchangeOnPremiseToolkitService();
                        this.Invoke(new Action(() => _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] [2/4] Outlook服务初始化完成\n")));
                    }

                    // 在后台线程执行COM调用，避免UI卡死
                    this.Invoke(new Action(() => _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] [3/4] 正在扫描Outlook账户...\n")));
                    var accounts = OnPremiseToolkitService.GetOutlookAccounts();

                    // 回到UI线程更新界面
                    this.Invoke(new Action(() =>
                    {
                        if (accounts == null)
                        {
                            _logTextBox.AppendText("[ERROR] GetOutlookAccounts returned null\n");
                            _logTextBox.AppendText("Possible reasons:\n");
                            _logTextBox.AppendText("  - Outlook not installed or not configured\n");
                            _logTextBox.AppendText("  - Outlook running as admin but program as normal user\n");
                            _logTextBox.AppendText("  - Try restart program as admin\n");
                            return;
                        }

                        foreach (var account in accounts)
                        {
                            cmbPstAccount.Items.Add(account);
                        }
                        if (cmbPstAccount.Items.Count > 0)
                            cmbPstAccount.SelectedIndex = 0;

                        _logTextBox.AppendText("[4/4] Scan complete, found " + cmbPstAccount.Items.Count + " accounts\n");
                        if (cmbPstAccount.Items.Count == 0)
                        {
                            _logTextBox.AppendText("[WARNING] No Outlook accounts found\n");
                            _logTextBox.AppendText("Please check:\n");
                            _logTextBox.AppendText("  - Is Outlook started?\n");
                            _logTextBox.AppendText("  - Has Outlook been configured with email accounts?\n");
                        }
                    }));
                }
                catch (Exception ex)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[ERROR] 加载账户失败: {ex.Message}\n");
                        _logTextBox.AppendText($"堆栈: {ex.StackTrace}\n");
                    }));
                }
            };

            btnLoadPstAccounts.Click += (s, e) => { Task.Run(loadAccounts); };

            btnExportPst.Click += (s, e) =>
            {
                if (cmbPstAccount.SelectedIndex < 0)
                {
                    MessageBox.Show("请先加载并选择账户", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (string.IsNullOrWhiteSpace(txtExportPstOutputFile.Text))
                {
                    MessageBox.Show("请选择输出文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (!chkExportPstReceived.Checked && !chkExportPstSent.Checked && !chkExportPstContacts.Checked && !chkExportPstCalendar.Checked)
                {
                    MessageBox.Show("请至少选择一个导出项", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnExportPst.Enabled = false;
                prgExportPst.Visible = true;
                prgExportPst.Value = 0;
                lblExportPstProgress.Text = "准备导出...";
                _logTextBox.Clear();
                _logTextBox.AppendText($"[========== PST导出开始 ==========]\n");
                _logTextBox.AppendText($"[INFO] 开始时间: {DateTime.Now:yyyy-MM-dd HH:mm:ss}\n");
                _logTextBox.AppendText($"[INFO] 程序版本: 小铭邮件百宝箱 v1.2.0\n");
                _logTextBox.AppendText($"[----------------------------------------]\n");

                Task.Run(() =>
                {
                    try
                    {
                        string targetEmail = cmbPstAccount.SelectedItem?.ToString();
                        string outputFile = txtExportPstOutputFile.Text;
                        bool includeReceived = chkExportPstReceived.Checked;
                        bool includeSent = chkExportPstSent.Checked;
                        bool includeContacts = chkExportPstContacts.Checked;
                        bool includeCalendar = chkExportPstCalendar.Checked;

                        _logTextBox.AppendText($"[STEP 1/7] 验证导出参数...\n");
                        _logTextBox.AppendText($"  - 目标邮箱: {targetEmail}\n");
                        _logTextBox.AppendText($"  - 输出文件: {outputFile}\n");
                        _logTextBox.AppendText($"  - 收件箱: {(includeReceived ? "√" : "×")}  发件箱: {(includeSent ? "√" : "×")}\n");
                        _logTextBox.AppendText($"  - 联系人: {(includeContacts ? "√" : "×")}  日历: {(includeCalendar ? "√" : "×")}\n");

                        // 确保输出目录存在
                        var outputDir = Path.GetDirectoryName(outputFile);
                        if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
                        {
                            Directory.CreateDirectory(outputDir);
                            _logTextBox.AppendText($"[STEP 2/7] 创建输出目录: {outputDir}\n");
                        }

                        _logTextBox.AppendText($"[STEP 3/7] 连接Outlook...\n");
                        _logTextBox.AppendText($"[STEP 4/7] 正在获取邮箱文件夹...\n");
                        _logTextBox.AppendText($"[STEP 5/7] 准备导出数据...\n");

                        var result = OnPremiseToolkitService.ExportToPst(
                            targetEmail,
                            outputFile,
                            includeReceived,
                            includeSent,
                            includeContacts,
                            includeCalendar,
                            (processed, total, status) =>
                            {
                                this.Invoke(new Action(() =>
                                {
                                    if (total > 0)
                                    {
                                        prgExportPst.Maximum = total;
                                        prgExportPst.Value = Math.Min(processed, total);
                                    }
                                    lblExportPstProgress.Text = $"{status} ({processed}/{total})";
                                    _logTextBox.AppendText($"[PROGRESS] {status}\n");
                                }));
                            });

                        this.Invoke(new Action(() =>
                        {
                            prgExportPst.Value = prgExportPst.Maximum;
                            if (result)
                            {
                                lblExportPstProgress.Text = "导出完成!";
                                lblExportPstProgress.ForeColor = Color.Green;
                                _logTextBox.AppendText($"[----------------------------------------]\n");
                                _logTextBox.AppendText($"[STEP 6/7] 验证输出文件...\n");
                                if (File.Exists(outputFile))
                                {
                                    var fileInfo = new FileInfo(outputFile);
                                    _logTextBox.AppendText($"[SUCCESS] 文件已创建: {outputFile}\n");
                                    _logTextBox.AppendText($"[INFO] 文件大小: {fileInfo.Length / 1024.0 / 1024.0:F2} MB\n");
                                    _logTextBox.AppendText($"[INFO] 完成时间: {DateTime.Now:yyyy-MM-dd HH:mm:ss}\n");
                                }
                                _logTextBox.AppendText($"[========== PST导出完成 ==========]\n");
                            }
                            else
                            {
                                lblExportPstProgress.Text = "导出失败";
                                lblExportPstProgress.ForeColor = Color.Red;
                                _logTextBox.AppendText($"[ERROR] PST导出失败，请查看上方日志\n");
                                _logTextBox.AppendText($"[========== PST导出失败 ==========]\n");
                            }
                            btnExportPst.Enabled = true;
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblExportPstProgress.Text = "导出失败";
                            lblExportPstProgress.ForeColor = Color.Red;
                            _logTextBox.AppendText($"[ERROR] 导出过程发生异常:\n");
                            _logTextBox.AppendText($"  {ex.Message}\n");
                            _logTextBox.AppendText($"[堆栈信息]\n{ex.StackTrace}\n");
                            _logTextBox.AppendText($"[========== PST导出失败 ==========]\n");
                            btnExportPst.Enabled = true;
                        }));
                    }
                });
            };

            // 初始加载账户（仅当服务已连接时）
            if (_onPremiseToolkitService != null)
                loadAccounts();

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblNote);
            panel.Controls.Add(lblAccount);
            panel.Controls.Add(cmbPstAccount);
            panel.Controls.Add(btnLoadPstAccounts);
            panel.Controls.Add(lblOutputFile);
            panel.Controls.Add(txtExportPstOutputFile);
            panel.Controls.Add(btnBrowseExportPstFile);
            panel.Controls.Add(lblOptions);
            panel.Controls.Add(chkExportPstReceived);
            panel.Controls.Add(chkExportPstSent);
            panel.Controls.Add(chkExportPstContacts);
            panel.Controls.Add(chkExportPstCalendar);
            panel.Controls.Add(btnExportPst);
            panel.Controls.Add(prgExportPst);
            panel.Controls.Add(lblExportPstProgress);

            return panel;
        }

        /// <summary>
        /// 创建EWS投递到IMAP面板
        /// </summary>
        private Panel CreateOnPremiseEwsToImapPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            // ===== 左列 (输入区域) =====
            int leftX = 20;
            int labelWidth = 85;
            int inputX = 110;
            int inputWidth = 200;
            int rowHeight = 28;
            int startY = 15;

            var lblTitle = new Label
            {
                Text = "EWS 投递到 IMAP",
                Location = new Point(leftX, startY),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 第1行: 已保存配置
            int y = startY + 35;
            var lblSavedConfig = new Label { Text = "已保存配置:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var cmbEwsToImapSaved = new ComboBox { Location = new Point(inputX, y), Size = new Size(inputWidth, 25), DropDownStyle = ComboBoxStyle.DropDown };
            var savedImapAccounts = RegistryService.LoadEwsToImapAccounts();
            cmbEwsToImapSaved.Items.Add("（请选择配置）");
            cmbEwsToImapSaved.Items.Add("（手动输入）");
            foreach (var acc in savedImapAccounts)
            {
                cmbEwsToImapSaved.Items.Add(acc.Name);
            }
            cmbEwsToImapSaved.SelectedIndex = 0;

            // 第2行: 源邮箱 (Exchange)
            y += rowHeight + 5;
            var lblSourceMailbox = new Label { Text = "源邮箱:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtEwsToImapSourceMailbox = new TextBox { Location = new Point(inputX, y), Size = new Size(inputWidth, 25) };

            // 第3行: 操作邮箱 (Impersonation)
            y += rowHeight + 5;
            var lblTargetMailbox = new Label { Text = "操作邮箱:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtEwsToImapTargetMailbox = new TextBox { Location = new Point(inputX, y), Size = new Size(inputWidth, 25) };
            var lblTargetHint = new Label { Text = "(Impersonation)", Location = new Point(inputX + inputWidth + 5, y + 5), AutoSize = true, ForeColor = Color.Gray };

            // 第4行: IMAP服务器和端口
            y += rowHeight + 5;
            var lblImapServer = new Label { Text = "IMAP服务器:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtEwsToImapServer = new TextBox { Location = new Point(inputX, y), Size = new Size(130, 25) };
            var lblImapPort = new Label { Text = "端口:", Location = new Point(inputX + 135, y + 3), Size = new Size(35, 20) };
            var numEwsToImapPort = new NumericUpDown { Location = new Point(inputX + 170, y), Size = new Size(60, 25), Minimum = 1, Maximum = 65535, Value = 993 };

            // 第5行: IMAP用户名和密码
            y += rowHeight + 5;
            var lblImapUser = new Label { Text = "用户名:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtEwsToImapUser = new TextBox { Location = new Point(inputX, y), Size = new Size(inputWidth, 25) };

            y += rowHeight + 5;
            var lblImapPassword = new Label { Text = "密码:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtEwsToImapPassword = new TextBox { Location = new Point(inputX, y), Size = new Size(inputWidth, 25), UseSystemPasswordChar = true };

            // 第6行: 日期范围
            y += rowHeight + 5;
            var lblDateRange = new Label { Text = "日期范围:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var dtpEwsToImapStartDate = new DateTimePicker { Location = new Point(inputX, y), Size = new Size(110, 25), Format = DateTimePickerFormat.Short };
            var lblTo = new Label { Text = "至", Location = new Point(inputX + 115, y + 3), Size = new Size(20, 20) };
            var dtpEwsToImapEndDate = new DateTimePicker { Location = new Point(inputX + 135, y), Size = new Size(110, 25), Format = DateTimePickerFormat.Short };

            // 第7行: SSL和按钮
            y += rowHeight + 5;
            var chkEwsToImapSsl = new CheckBox { Text = "使用SSL", Location = new Point(inputX, y), AutoSize = true, Checked = true };
            var btnEwsToImapDeliver = new Button
            {
                Text = "开始投递",
                Location = new Point(inputX + 100, y - 3),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条和进度标签
            y += 40;
            var prgEwsToImap = new ProgressBar { Location = new Point(leftX, y), Size = new Size(inputWidth + 50, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            y += 25;
            var lblEwsToImapProgress = new Label { Text = "", Location = new Point(leftX, y), AutoSize = true, ForeColor = Color.Gray };

            // 日志区域
            y += 25;
            var txtEwsToImapLog = new TextBox
            {
                Location = new Point(leftX, y),
                Size = new Size(inputWidth + 80, 180),
                Multiline = true,
                ReadOnly = true,
                ScrollBars = ScrollBars.Vertical,
                BackColor = Color.FromArgb(30, 30, 30),
                ForeColor = Color.LightGray
            };

            // 加载选中配置到表单
            cmbEwsToImapSaved.SelectedIndexChanged += (s, e) =>
            {
                if (cmbEwsToImapSaved.SelectedIndex <= 1) return;
                var name = cmbEwsToImapSaved.SelectedItem?.ToString();
                if (string.IsNullOrEmpty(name)) return;
                var acc = savedImapAccounts.Find(a => a.Name == name);
                if (acc != null)
                {
                    txtEwsToImapServer.Text = acc.ImapServer;
                    numEwsToImapPort.Value = acc.ImapPort > 0 ? acc.ImapPort : 993;
                    txtEwsToImapUser.Text = acc.Username;
                    txtEwsToImapPassword.Text = acc.Password;
                    chkEwsToImapSsl.Checked = acc.UseSsl;
                }
            };

            btnEwsToImapDeliver.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtEwsToImapServer.Text))
                {
                    MessageBox.Show("请输入IMAP服务器地址", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                if (_onPremiseToolkitService == null || !_onPremiseToolkitService.IsConnected)
                {
                    MessageBox.Show("请先连接Exchange服务器", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnEwsToImapDeliver.Enabled = false;
                prgEwsToImap.Visible = true;
                prgEwsToImap.Value = 0;
                lblEwsToImapProgress.Text = "准备投递...";
                txtEwsToImapLog.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        string sourceMailbox = txtEwsToImapSourceMailbox.Text.Trim();
                        string targetMailbox = txtEwsToImapTargetMailbox.Text.Trim();
                        string imapServer = txtEwsToImapServer.Text.Trim();
                        int imapPort = (int)numEwsToImapPort.Value;
                        string imapUser = txtEwsToImapUser.Text.Trim();
                        string imapPassword = txtEwsToImapPassword.Text;
                        DateTime startDate = dtpEwsToImapStartDate.Value.Date;
                        DateTime endDate = dtpEwsToImapEndDate.Value.Date.AddDays(1).AddSeconds(-1);
                        bool useSsl = chkEwsToImapSsl.Checked;

                        this.Invoke(new Action(() =>
                        {
                            AppendLog(txtEwsToImapLog, "[========== EWS投递到IMAP开始 ==========]");
                            AppendLog(txtEwsToImapLog, $"[信息] IMAP服务器: {imapServer}:{imapPort}");
                            AppendLog(txtEwsToImapLog, $"[信息] 用户名: {imapUser}");
                            AppendLog(txtEwsToImapLog, $"[信息] 日期范围: {startDate:yyyy-MM-dd} 至 {endDate:yyyy-MM-dd}");
                            AppendLog(txtEwsToImapLog, $"[信息] SSL: {(useSsl ? "是" : "否")}");
                            if (!string.IsNullOrEmpty(targetMailbox))
                            {
                                AppendLog(txtEwsToImapLog, $"[信息] 目标邮箱(Impersonation): {targetMailbox}");
                            }
                        }));

                        // 设置Impersonation用户（必须先设置，再获取文件夹）
                        if (!string.IsNullOrEmpty(targetMailbox))
                        {
                            if (!_onPremiseToolkitService.SetImpersonatedUser(targetMailbox))
                            {
                                this.Invoke(new Action(() =>
                                {
                                    AppendLog(txtEwsToImapLog, "[错误] 设置Impersonation用户失败");
                                    lblEwsToImapProgress.Text = "设置Impersonation用户失败";
                                    btnEwsToImapDeliver.Enabled = true;
                                }));
                                return;
                            }
                            AppendLog(txtEwsToImapLog, "[信息] Impersonation设置成功");
                        }

                        // 验证Impersonation是否生效：尝试绑定目标邮箱的Inbox
                        AppendLog(txtEwsToImapLog, "[调试] 验证Impersonation访问...");
                        var (inboxCount, inboxError) = _onPremiseToolkitService.TestImpersonationInbox();
                        if (!string.IsNullOrEmpty(inboxError))
                        {
                            this.Invoke(new Action(() =>
                            {
                                AppendLog(txtEwsToImapLog, $"[错误] Impersonation验证失败: {inboxError}");
                                lblEwsToImapProgress.Text = "Impersonation验证失败";
                                btnEwsToImapDeliver.Enabled = true;
                            }));
                            return;
                        }
                        AppendLog(txtEwsToImapLog, $"[调试] Impersonation验证成功，Inbox中有 {inboxCount} 封信");

                        AppendLog(txtEwsToImapLog, "[步骤1/4] 正在获取Exchange文件夹列表...");

                        // 获取所有文件夹
                        // 注意：如果已通过SetImpersonatedUser设置了Impersonation，这里传null即可使用模拟用户上下文
                        var folders = _onPremiseToolkitService.GetAllFolders();
                        int totalEmails = 0;
                        foreach (var folder in folders)
                        {
                            totalEmails += folder.TotalCount;
                        }

                        this.Invoke(new Action(() =>
                        {
                            AppendLog(txtEwsToImapLog, $"[信息] 共发现 {folders.Count} 个文件夹, 约 {totalEmails} 封邮件");
                            AppendLog(txtEwsToImapLog, "[调试] 文件夹列表:");
                            // 显示所有文件夹及其层级、类型
                            foreach (var folder in folders.Where(f => f.TotalCount > 0))
                            {
                                AppendLog(txtEwsToImapLog, $"[调试]   {folder.DisplayName} ({folder.TotalCount}封, Class:{folder.FolderClass})");
                            }
                            AppendLog(txtEwsToImapLog, "[步骤2/4] 正在连接IMAP服务器...");
                            prgEwsToImap.Maximum = 1; // 先设为1，投递时动态调整
                        }));

                        // 连接IMAP
                        using (var imapClient = new MailKit.Net.Imap.ImapClient())
                        {
                            imapClient.Connect(imapServer, imapPort, useSsl ? MailKit.Security.SecureSocketOptions.SslOnConnect : MailKit.Security.SecureSocketOptions.None);
                            imapClient.Authenticate(imapUser, imapPassword);

                            this.Invoke(new Action(() =>
                            {
                                AppendLog(txtEwsToImapLog, "[信息] IMAP服务器连接成功");
                                AppendLog(txtEwsToImapLog, "[步骤3/4] 正在投递邮件...");
                            }));

                            // 获取INBOX作为基准
                            var inbox = imapClient.Inbox;
                            int deliveredCount = 0;
                            int errorCount = 0;
                            int processedEmails = 0;

                            // 投递收件箱
                            var inboxFolder = folders.FirstOrDefault(f => f.DisplayName == "收件箱" || f.DisplayName == "Inbox");
                            if (inboxFolder != null && inboxFolder.TotalCount > 0)
                            {
                                var emails = _onPremiseToolkitService.GetFolderEmailsMime(inboxFolder.Id, startDate, endDate);
                                this.Invoke(new Action(() => AppendLog(txtEwsToImapLog, $"[投递] 收件箱: 实际匹配 {emails.Count} 封")));
                                foreach (var email in emails)
                                {
                                    try
                                    {
                                        using (var stream = new MemoryStream(email.Item2))
                                        {
                                            var message = MimeKit.MimeMessage.Load(stream);
                                            // 使用AppendRequest的InternalDate保留原始收到时间
                                            var request = new MailKit.AppendRequest(message, MailKit.MessageFlags.None) { InternalDate = new DateTimeOffset(email.Item3) };
                                            inbox.Append(request, CancellationToken.None);
                                            deliveredCount++;
                                        }
                                        processedEmails++;
                                        this.Invoke(new Action(() =>
                                        {
                                            prgEwsToImap.Value = Math.Min(processedEmails, prgEwsToImap.Maximum);
                                            lblEwsToImapProgress.Text = $"正在投递: {processedEmails} 封";
                                        }));
                                    }
                                    catch (Exception ex)
                                    {
                                        errorCount++;
                                        this.Invoke(new Action(() => AppendLog(txtEwsToImapLog, $"[错误] {email.Item1}: {ex.Message}")));
                                    }
                                }
                            }

                            // 定义非邮件系统文件夹名称（这些会被跳过）
                            string[] systemFolders = new string[] {
                                "AllContacts", "AllNotes", "AllCalendarItems",
                                "DefaultFoldersChangeHistory", "Conversation Action Settings",
                                "Calendar", "Contacts", "Tasks", "Notes", "Journal",
                                "Shortcuts", "Sync Issues", "RSS", "News",
                                "Deletions", "Purges", "Versions", "ConversationHistory"
                            };

                            // 投递其他文件夹（排除系统文件夹）
                            foreach (var folder in folders.Where(f =>
                                f.DisplayName != "收件箱" && f.DisplayName != "Inbox" &&
                                f.TotalCount > 0 &&
                                !systemFolders.Any(sf => f.DisplayName.Equals(sf, StringComparison.OrdinalIgnoreCase))))
                            {
                                try
                                {
                                    // 在IMAP上创建或获取文件夹
                                    var imapFolder = GetOrCreateImapFolder(imapClient, folder.DisplayName);

                                    var emails = _onPremiseToolkitService.GetFolderEmailsMime(folder.Id, startDate, endDate);
                                    this.Invoke(new Action(() => AppendLog(txtEwsToImapLog, $"[投递] {folder.DisplayName}: 实际匹配 {emails.Count} 封")));
                                    foreach (var email in emails)
                                    {
                                        try
                                        {
                                            using (var stream = new MemoryStream(email.Item2))
                                            {
                                                var message = MimeKit.MimeMessage.Load(stream);
                                                // 使用AppendRequest的InternalDate保留原始收到时间
                                                var request = new MailKit.AppendRequest(message, MailKit.MessageFlags.None) { InternalDate = new DateTimeOffset(email.Item3) };
                                                imapFolder.Append(request, CancellationToken.None);
                                                deliveredCount++;
                                            }
                                            processedEmails++;
                                            this.Invoke(new Action(() =>
                                            {
                                                prgEwsToImap.Value = Math.Min(processedEmails, prgEwsToImap.Maximum);
                                                lblEwsToImapProgress.Text = $"正在投递: {processedEmails} 封";
                                            }));
                                        }
                                        catch (Exception ex)
                                        {
                                            errorCount++;
                                            this.Invoke(new Action(() => AppendLog(txtEwsToImapLog, $"[错误] {email.Item1}: {ex.Message}")));
                                        }
                                    }
                                }
                                catch (Exception ex)
                                {
                                    this.Invoke(new Action(() => AppendLog(txtEwsToImapLog, $"[错误] 文件夹 {folder.DisplayName}: {ex.Message}")));
                                }
                            }

                            imapClient.Disconnect(true);

                            this.Invoke(new Action(() =>
                            {
                                AppendLog(txtEwsToImapLog, "[步骤4/4] 投递完成");
                                AppendLog(txtEwsToImapLog, $"[结果] 成功投递: {deliveredCount} 封");
                                if (errorCount > 0)
                                    AppendLog(txtEwsToImapLog, $"[结果] 失败: {errorCount} 封");
                                AppendLog(txtEwsToImapLog, "[========== EWS投递到IMAP完成 ==========]");
                                lblEwsToImapProgress.Text = $"投递完成: {deliveredCount} 封";
                                btnEwsToImapDeliver.Enabled = true;
                                prgEwsToImap.Value = prgEwsToImap.Maximum;
                            }));
                        }
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            AppendLog(txtEwsToImapLog, $"[错误] {ex.Message}");
                            AppendLog(txtEwsToImapLog, "[========== EWS投递到IMAP失败 ==========]");
                            lblEwsToImapProgress.Text = "投递失败: " + ex.Message;
                            btnEwsToImapDeliver.Enabled = true;
                        }));
                    }
                });
            };

            // 获取或创建IMAP文件夹
            MailKit.IMailFolder GetOrCreateImapFolder(MailKit.Net.Imap.ImapClient client, string folderName)
            {
                try
                {
                    // 尝试获取已存在的文件夹
                    var personalNamespace = client.PersonalNamespaces.FirstOrDefault();
                    if (personalNamespace != null)
                    {
                        foreach (var folder in client.GetFolders(personalNamespace))
                        {
                            if (folder.Name.Equals(folderName, StringComparison.OrdinalIgnoreCase))
                                return folder;
                        }
                    }
                }
                catch { }

                // 创建新文件夹 (在INBOX下创建子文件夹)
                try
                {
                    return client.Inbox.Create(folderName, true, CancellationToken.None);
                }
                catch
                {
                    // 如果创建失败，返回INBOX
                    return client.Inbox;
                }
            }

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblSavedConfig);
            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblSavedConfig);
            panel.Controls.Add(cmbEwsToImapSaved);
            panel.Controls.Add(lblSourceMailbox);
            panel.Controls.Add(txtEwsToImapSourceMailbox);
            panel.Controls.Add(lblTargetMailbox);
            panel.Controls.Add(txtEwsToImapTargetMailbox);
            panel.Controls.Add(lblTargetHint);
            panel.Controls.Add(lblImapServer);
            panel.Controls.Add(txtEwsToImapServer);
            panel.Controls.Add(lblImapPort);
            panel.Controls.Add(numEwsToImapPort);
            panel.Controls.Add(lblImapUser);
            panel.Controls.Add(txtEwsToImapUser);
            panel.Controls.Add(lblImapPassword);
            panel.Controls.Add(txtEwsToImapPassword);
            panel.Controls.Add(lblDateRange);
            panel.Controls.Add(dtpEwsToImapStartDate);
            panel.Controls.Add(lblTo);
            panel.Controls.Add(dtpEwsToImapEndDate);
            panel.Controls.Add(chkEwsToImapSsl);
