        /// <summary>
        /// 创建联系人导出面板
        /// </summary>
        private Panel CreateOnPremiseContactExportPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            var lblTitle = new Label
            {
                Text = "联系人导出",
                Location = new Point(20, 15),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 导出邮箱 (支持Impersonation)
            var lblTargetMailbox = new Label { Text = "导出邮箱:", Location = new Point(20, 50), AutoSize = true };
            var txtContactTargetMailbox = new TextBox { Location = new Point(100, 48), Size = new Size(250, 25) };
            var lblTargetMailboxTip = new Label { Text = "(Impersonation)", Location = new Point(355, 50), AutoSize = true, ForeColor = Color.Gray };

            // 输出格式
            var lblOutputFormat = new Label { Text = "输出格式:", Location = new Point(20, 85), AutoSize = true };
            var cmbContactFormat = new ComboBox
            {
                Location = new Point(100, 83),
                Size = new Size(120, 25),
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbContactFormat.Items.AddRange(new object[] { "CSV文件", "vCard文件" });
            cmbContactFormat.SelectedIndex = 0;

            // 输出文件/目录
            var lblOutputFile = new Label { Text = "输出目录:", Location = new Point(20, 120), AutoSize = true };
            var txtContactOutputFile = new TextBox { Location = new Point(100, 118), Size = new Size(280, 25) };
            var btnBrowseContactFile = new Button { Text = "浏览...", Location = new Point(385, 116), Size = new Size(70, 25) };
            btnBrowseContactFile.Click += (s, e) =>
            {
                if (cmbContactFormat.SelectedIndex == 0)
                {
                    // CSV: 选择文件
                    lblOutputFile.Text = "输出文件:";
                    using (var sf = new SaveFileDialog())
                    {
                        sf.Filter = "CSV文件|*.csv";
                        sf.Title = "选择联系人输出文件";
                        sf.FileName = $"Contacts_{DateTime.Now:yyyyMMdd}.csv";
                        if (sf.ShowDialog() == DialogResult.OK)
                        {
                            txtContactOutputFile.Text = sf.FileName;
                        }
                    }
                }
                else
                {
                    // vCard: 选择目录（每个联系人一个文件）
                    lblOutputFile.Text = "输出目录:";
                    using (var fb = new FolderBrowserDialog())
                    {
                        fb.Description = "选择联系人导出目录";
                        fb.ShowNewFolderButton = true;
                        if (fb.ShowDialog() == DialogResult.OK)
                        {
                            txtContactOutputFile.Text = fb.SelectedPath;
                        }
                    }
                }
            };

            cmbContactFormat.SelectedIndexChanged += (s, e) =>
            {
                if (!string.IsNullOrEmpty(txtContactOutputFile.Text))
                {
                    string oldExt = cmbContactFormat.SelectedIndex == 0 ? ".vcf" : ".csv";
                    string newExt = cmbContactFormat.SelectedIndex == 0 ? ".csv" : ".vcf";
                    if (txtContactOutputFile.Text.EndsWith(oldExt))
                    {
                        txtContactOutputFile.Text = txtContactOutputFile.Text.Substring(0, txtContactOutputFile.Text.Length - oldExt.Length) + newExt;
                    }
                }
            };

            // 导出按钮
            var btnExportContacts = new Button
            {
                Text = "开始导出",
                Location = new Point(100, 155),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条
            var prgExportContacts = new ProgressBar { Location = new Point(20, 195), Size = new Size(500, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            var lblExportContactsProgress = new Label { Text = "", Location = new Point(20, 220), AutoSize = true, ForeColor = Color.Gray };

            // 结果日志
            var txtExportContactsLog = new TextBox
            {
                Location = new Point(20, 250),
                Size = new Size(500, 230),
                Multiline = true,
                ReadOnly = true,
                ScrollBars = ScrollBars.Vertical,
                BackColor = Color.FromArgb(30, 30, 30),
                ForeColor = Color.LightGray
            };

            btnExportContacts.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtContactOutputFile.Text))
                {
                    MessageBox.Show("请选择输出文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnExportContacts.Enabled = false;
                prgExportContacts.Visible = true;
                prgExportContacts.Value = 0;
                lblExportContactsProgress.Text = "准备导出...";
                txtExportContactsLog.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        string targetMailbox = txtContactTargetMailbox.Text.Trim();
                        int format = cmbContactFormat.SelectedIndex;
                        string outputFile = txtContactOutputFile.Text;

                        this.Invoke(new Action(() => lblExportContactsProgress.Text = "正在获取联系人..."));

                        // 获取所有联系人（支持Impersonation）
                        var contacts = OnPremiseToolkitService.GetContacts(targetMailbox);
                        int contactCount = contacts.Count;

                        this.Invoke(new Action(() =>
                        {
                            prgExportContacts.Maximum = contactCount;
                            prgExportContacts.Value = 0;
                            AppendLog(txtExportContactsLog, $"[信息] 共有 {contactCount} 个联系人");
                        }));

                        // 导出联系人
                        bool success = false;
                        string outputPath = outputFile;
                        if (format == 0) // CSV
                        {
                            success = OnPremiseToolkitService.ExportContactsToCsv(outputFile);
                        }
                        else // vCard
                        {
                            success = OnPremiseToolkitService.ExportContactsToVcf(outputFile);
                            outputPath = System.IO.Path.Combine(outputFile, "contacts");
                        }

                        this.Invoke(new Action(() =>
                        {
                            if (success)
                            {
                                AppendLog(txtExportContactsLog, $"[完成] 成功导出 {contactCount} 个联系人");
                                AppendLog(txtExportContactsLog, $"[完成] 文件已保存到: {outputPath}");
                                lblExportContactsProgress.Text = $"导出完成! 共导出 {contactCount} 个联系人";
                            }
                            else
                            {
                                AppendLog(txtExportContactsLog, $"[错误] 导出失败");
                                lblExportContactsProgress.Text = "导出失败";
                            }
                            btnExportContacts.Enabled = true;
                            prgExportContacts.Value = contactCount;
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblExportContactsProgress.Text = "导出失败: " + ex.Message;
                            btnExportContacts.Enabled = true;
                            AppendLog(txtExportContactsLog, $"[错误] {ex.Message}");
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblTargetMailbox);
            panel.Controls.Add(txtContactTargetMailbox);
            panel.Controls.Add(lblTargetMailboxTip);
            panel.Controls.Add(lblOutputFormat);
            panel.Controls.Add(cmbContactFormat);
            panel.Controls.Add(lblOutputFile);
            panel.Controls.Add(txtContactOutputFile);
            panel.Controls.Add(btnBrowseContactFile);
            panel.Controls.Add(btnExportContacts);
            panel.Controls.Add(prgExportContacts);
            panel.Controls.Add(lblExportContactsProgress);
            panel.Controls.Add(txtExportContactsLog);

            return panel;
        }

        /// <summary>
        /// 创建日历导出面板
        /// </summary>
        private Panel CreateOnPremiseCalendarExportPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            var lblTitle = new Label
            {
                Text = "日历导出",
                Location = new Point(20, 15),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 导出邮箱 (支持Impersonation)
            var lblTargetMailbox = new Label { Text = "导出邮箱:", Location = new Point(20, 50), AutoSize = true };
            var txtCalendarTargetMailbox = new TextBox { Location = new Point(100, 48), Size = new Size(250, 25) };
            var lblTargetMailboxTip = new Label { Text = "(Impersonation)", Location = new Point(355, 50), AutoSize = true, ForeColor = Color.Gray };

            // 日期范围
            var lblDateRange = new Label { Text = "日期范围:", Location = new Point(20, 85), AutoSize = true };
            var dtpCalendarStartDate = new DateTimePicker { Location = new Point(100, 83), Size = new Size(120, 25), Format = DateTimePickerFormat.Short };
            var lblTo = new Label { Text = "至", Location = new Point(225, 87), AutoSize = true };
            var dtpCalendarEndDate = new DateTimePicker { Location = new Point(245, 83), Size = new Size(120, 25), Format = DateTimePickerFormat.Short };

            // 输出格式
            var lblOutputFormat = new Label { Text = "输出格式:", Location = new Point(20, 120), AutoSize = true };
            var cmbCalendarFormat = new ComboBox
            {
                Location = new Point(100, 118),
                Size = new Size(120, 25),
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbCalendarFormat.Items.AddRange(new object[] { "CSV文件", "iCalendar文件" });
            cmbCalendarFormat.SelectedIndex = 1;

            // 输出文件/目录
            var lblOutputFile = new Label { Text = "输出目录:", Location = new Point(20, 155), AutoSize = true };
            var txtCalendarOutputFile = new TextBox { Location = new Point(100, 153), Size = new Size(280, 25) };
            var btnBrowseCalendarFile = new Button { Text = "浏览...", Location = new Point(385, 151), Size = new Size(70, 25) };
            btnBrowseCalendarFile.Click += (s, e) =>
            {
                if (cmbCalendarFormat.SelectedIndex == 0)
                {
                    // CSV: 选择文件
                    lblOutputFile.Text = "输出文件:";
                    using (var sf = new SaveFileDialog())
                    {
                        sf.Filter = "CSV文件|*.csv";
                        sf.Title = "选择日历输出文件";
                        sf.FileName = $"Calendar_{DateTime.Now:yyyyMMdd}.csv";
                        if (sf.ShowDialog() == DialogResult.OK)
                        {
                            txtCalendarOutputFile.Text = sf.FileName;
                        }
                    }
                }
                else
                {
                    // ICS: 选择目录
                    lblOutputFile.Text = "输出目录:";
                    using (var fb = new FolderBrowserDialog())
                    {
                        fb.Description = "选择日历导出目录";
                        fb.ShowNewFolderButton = true;
                        if (fb.ShowDialog() == DialogResult.OK)
                        {
                            txtCalendarOutputFile.Text = fb.SelectedPath;
                        }
                    }
                }
            };

            cmbCalendarFormat.SelectedIndexChanged += (s, e) =>
            {
                if (cmbCalendarFormat.SelectedIndex == 0)
                    lblOutputFile.Text = "输出文件:";
                else
                    lblOutputFile.Text = "输出目录:";
            };

            // 导出按钮
            var btnExportCalendar = new Button
            {
                Text = "开始导出",
                Location = new Point(100, 190),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条
            var prgExportCalendar = new ProgressBar { Location = new Point(20, 230), Size = new Size(500, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            var lblExportCalendarProgress = new Label { Text = "", Location = new Point(20, 255), AutoSize = true, ForeColor = Color.Gray };

            // 结果日志
            var txtExportCalendarLog = new TextBox
            {
                Location = new Point(20, 285),
                Size = new Size(500, 195),
                Multiline = true,
                ReadOnly = true,
                ScrollBars = ScrollBars.Vertical,
                BackColor = Color.FromArgb(30, 30, 30),
                ForeColor = Color.LightGray
            };

            btnExportCalendar.Click += (s, e) =>
            {
                Serilog.Log.Information("日历导出按钮点击");

                if (string.IsNullOrWhiteSpace(txtCalendarOutputFile.Text))
                {
                    MessageBox.Show("请选择输出目录", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (OnPremiseToolkitService == null)
                {
                    MessageBox.Show("服务未初始化", "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }

                if (!OnPremiseToolkitService.IsConnected)
                {
                    MessageBox.Show("请先连接到 Exchange 服务器", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnExportCalendar.Enabled = false;
                prgExportCalendar.Visible = true;
                prgExportCalendar.Value = 0;
                lblExportCalendarProgress.Text = "准备导出...";
                txtExportCalendarLog.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        string targetMailbox = txtCalendarTargetMailbox.Text.Trim();
                        int format = cmbCalendarFormat.SelectedIndex;
                        string outputFile = txtCalendarOutputFile.Text;

                        // 获取UI中的日期范围
                        DateTime startDate = DateTime.MinValue;
                        DateTime endDate = DateTime.MaxValue;
                        this.Invoke(new Action(() =>
                        {
                            startDate = dtpCalendarStartDate.Value.Date;
                            endDate = dtpCalendarEndDate.Value.Date;
                            AppendLog(txtExportCalendarLog, $"[信息] 日期范围: {startDate:yyyy-MM-dd} 至 {endDate:yyyy-MM-dd}");
                        }));

                        Serilog.Log.Information("日历导出开始: targetMailbox={Target}, format={Format}, output={Output}",
                            targetMailbox, format, outputFile);

                        this.Invoke(new Action(() =>
                        {
                            AppendLog(txtExportCalendarLog, $"[信息] 目标邮箱: {(string.IsNullOrEmpty(targetMailbox) ? "当前连接用户" : targetMailbox)}");
                            AppendLog(txtExportCalendarLog, $"[信息] 输出格式: {(format == 0 ? "CSV" : "iCalendar(ICS)")}");
                        }));

                        this.Invoke(new Action(() => lblExportCalendarProgress.Text = "正在获取日历事件..."));

                        // 获取日历事件（支持Impersonation和日期范围）
                        var calendars = OnPremiseToolkitService.GetCalendars(targetMailbox, startDate, endDate);
                        int calendarCount = calendars.Count;

                        Serilog.Log.Information("获取到 {Count} 个日历事件", calendarCount);

                        this.Invoke(new Action(() =>
                        {
                            prgExportCalendar.Maximum = Math.Max(1, calendarCount);
                            prgExportCalendar.Value = 0;
                            AppendLog(txtExportCalendarLog, $"[信息] 共有 {calendarCount} 个日历事件");
                        }));

                        // 导出日历
                        bool success = false;
                        string outputPath = outputFile;
                        if (format == 0) // CSV
                        {
                            success = OnPremiseToolkitService.ExportCalendarsToCsv(outputFile, calendars);
                        }
                        else // ICS
                        {
                            outputPath = System.IO.Path.Combine(outputFile, "calendar.ics");
                            success = OnPremiseToolkitService.ExportCalendarsToIcs(outputPath, calendars);
                        }

                        Serilog.Log.Information("日历导出结果: success={Success}, count={Count}", success, calendarCount);

                        this.Invoke(new Action(() =>
                        {
                            if (success)
                            {
                                AppendLog(txtExportCalendarLog, $"[完成] 成功导出 {calendarCount} 个日历事件");
                                AppendLog(txtExportCalendarLog, $"[完成] 文件已保存到: {outputPath}");
                                lblExportCalendarProgress.Text = $"导出完成! 共导出 {calendarCount} 个日历事件";
                            }
                            else
                            {
                                AppendLog(txtExportCalendarLog, $"[错误] 导出失败(服务返回false)");
                                lblExportCalendarProgress.Text = "导出失败";
                            }
                            btnExportCalendar.Enabled = true;
                            prgExportCalendar.Value = prgExportCalendar.Maximum;
                        }));
                    }
                    catch (Exception ex)
                    {
                        Serilog.Log.Error(ex, "导出日历事件失败");
                        this.Invoke(new Action(() =>
                        {
                            lblExportCalendarProgress.Text = "导出失败: " + ex.Message;
                            btnExportCalendar.Enabled = true;
                            AppendLog(txtExportCalendarLog, $"[错误] {ex.Message}");
                            if (ex.InnerException != null)
                                AppendLog(txtExportCalendarLog, $"[错误] {ex.InnerException.Message}");
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblTargetMailbox);
            panel.Controls.Add(txtCalendarTargetMailbox);
            panel.Controls.Add(lblTargetMailboxTip);
            panel.Controls.Add(lblDateRange);
            panel.Controls.Add(dtpCalendarStartDate);
            panel.Controls.Add(lblTo);
            panel.Controls.Add(dtpCalendarEndDate);
            panel.Controls.Add(lblOutputFormat);
            panel.Controls.Add(cmbCalendarFormat);
            panel.Controls.Add(lblOutputFile);
            panel.Controls.Add(txtCalendarOutputFile);
            panel.Controls.Add(btnBrowseCalendarFile);
            panel.Controls.Add(btnExportCalendar);
            panel.Controls.Add(prgExportCalendar);
            panel.Controls.Add(lblExportCalendarProgress);
            panel.Controls.Add(txtExportCalendarLog);

            return panel;
        }

        /// <summary>
        /// 创建批量导出PST面板
        /// </summary>
        private Panel CreateOnPremiseBatchExportPstPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            var lblTitle = new Label
            {
                Text = "批量导出 PST",
                Location = new Point(20, 15),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // 邮箱列表文件
            var lblMailboxList = new Label { Text = "邮箱列表:", Location = new Point(20, 50), AutoSize = true };
            var txtBatchPstMailboxList = new TextBox { Location = new Point(100, 48), Size = new Size(280, 25) };
            var btnBrowseMailboxList = new Button { Text = "浏览...", Location = new Point(385, 46), Size = new Size(70, 25) };
            btnBrowseMailboxList.Click += (s, e) =>
            {
                using (var of = new OpenFileDialog())
                {
                    of.Filter = "Excel/CSV文件|*.xlsx;*.xls;*.csv|文本文件|*.txt";
                    of.Title = "选择邮箱列表文件";
                    if (of.ShowDialog() == DialogResult.OK)
                    {
                        txtBatchPstMailboxList.Text = of.FileName;
                    }
                }
            };

            // 下载模板按钮
            var btnDownloadTemplate = new Button
            {
                Text = "下载模板",
                Location = new Point(460, 46),
                Size = new Size(80, 25)
            };
            btnDownloadTemplate.Click += (s, e) =>
            {
                try
                {
                    var tempPath = Path.Combine(Path.GetTempPath(), "批量导出PST模板.csv");
                    var templateContent = "用户邮箱,PST文件名\nuser@example.com,user_backup\ntest@company.com,test_backup";
                    File.WriteAllText(tempPath, templateContent, System.Text.Encoding.UTF8);
                    MessageBox.Show($"模板已保存到:\n{tempPath}", "模板下载", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("模板下载失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // 输出目录
            var lblOutputDir = new Label { Text = "输出目录:", Location = new Point(20, 85), AutoSize = true };
            var txtBatchPstOutputDir = new TextBox { Location = new Point(100, 83), Size = new Size(280, 25) };
            var btnBrowseBatchPstDir = new Button { Text = "浏览...", Location = new Point(385, 81), Size = new Size(70, 25) };
            btnBrowseBatchPstDir.Click += (s, e) =>
            {
                using (var fb = new FolderBrowserDialog())
                {
                    fb.Description = "选择PST输出目录";
                    if (fb.ShowDialog() == DialogResult.OK)
                    {
                        txtBatchPstOutputDir.Text = fb.SelectedPath;
                    }
                }
            };

            // 日期范围
            var lblDateRange = new Label { Text = "日期范围:", Location = new Point(20, 120), AutoSize = true };
            var dtpBatchPstStartDate = new DateTimePicker { Location = new Point(100, 118), Size = new Size(120, 25), Format = DateTimePickerFormat.Short };
            var lblTo = new Label { Text = "至", Location = new Point(225, 122), AutoSize = true };
            var dtpBatchPstEndDate = new DateTimePicker { Location = new Point(245, 118), Size = new Size(120, 25), Format = DateTimePickerFormat.Short };

            // 线程数
            var lblThreadCount = new Label { Text = "线程数:", Location = new Point(100, 150), AutoSize = true };
            var numBatchPstThreads = new NumericUpDown
            {
                Location = new Point(160, 148),
                Size = new Size(60, 25),
                Minimum = 2,
                Maximum = 10,
                Value = 2,
                Increment = 1
            };

            // 导出内容选项
            var lblExportContent = new Label { Text = "导出内容:", Location = new Point(100, 178), AutoSize = true };
            var chkBatchEmail = new CheckBox { Text = "邮件", Location = new Point(170, 176), AutoSize = true, Checked = true };
            var chkBatchCalendar = new CheckBox { Text = "日历", Location = new Point(220, 176), AutoSize = true, Checked = false, Enabled = false };
            var chkBatchContacts = new CheckBox { Text = "联系人", Location = new Point(280, 176), AutoSize = true, Checked = false, Enabled = false };
            var chkBatchTasks = new CheckBox { Text = "任务", Location = new Point(350, 176), AutoSize = true, Checked = false };

            // 日历/联系人暂时禁用（功能开发中）

            // 开始导出按钮
            var btnBatchPstExport = new Button
            {
                Text = "开始导出",
                Location = new Point(430, 205),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条
            var prgBatchPst = new ProgressBar { Location = new Point(20, 245), Size = new Size(520, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            var lblBatchPstProgress = new Label { Text = "", Location = new Point(20, 270), AutoSize = true, ForeColor = Color.Gray };

            // 结果日志
            var txtBatchPstLog = new TextBox
            {
                Location = new Point(20, 300),
                Size = new Size(520, 200),
                Multiline = true,
                ReadOnly = true,
                ScrollBars = ScrollBars.Vertical,
                BackColor = Color.FromArgb(30, 30, 30),
                ForeColor = Color.LightGray
            };

            btnBatchPstExport.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtBatchPstMailboxList.Text))
                {
                    MessageBox.Show("请选择邮箱列表文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (string.IsNullOrWhiteSpace(txtBatchPstOutputDir.Text))
                {
                    MessageBox.Show("请选择输出目录", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnBatchPstExport.Enabled = false;
                prgBatchPst.Visible = true;
                prgBatchPst.Value = 0;
                lblBatchPstProgress.Text = "准备导出...";
                txtBatchPstLog.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        string mailboxListFile = txtBatchPstMailboxList.Text.Trim();
                        string outputDir = txtBatchPstOutputDir.Text.Trim();
                        DateTime startDate = dtpBatchPstStartDate.Value.Date;
                        DateTime endDate = dtpBatchPstEndDate.Value.Date.AddDays(1).AddSeconds(-1);
                        int threadCount = (int)numBatchPstThreads.Value;

                        bool exportEmail = chkBatchEmail.Checked;
                        bool exportCalendar = chkBatchCalendar.Checked;
                        bool exportContacts = chkBatchContacts.Checked;
                        bool exportTasks = chkBatchTasks.Checked;

                        this.Invoke(new Action(() =>
                        {
                            AppendLog(txtBatchPstLog, "[信息] 批量导出PST开始");
                            AppendLog(txtBatchPstLog, $"[信息] 邮箱列表: {mailboxListFile}");
                            AppendLog(txtBatchPstLog, $"[信息] 输出目录: {outputDir}");
                            AppendLog(txtBatchPstLog, $"[信息] 日期范围: {startDate:yyyy-MM-dd} 至 {endDate:yyyy-MM-dd}");
                            AppendLog(txtBatchPstLog, $"[信息] 线程数: {threadCount}");
                            string exportItems = "";
                            if (exportEmail) exportItems += "邮件 ";
                            if (exportCalendar) exportItems += "日历 ";
                            if (exportContacts) exportItems += "联系人 ";
                            if (exportTasks) exportItems += "任务 ";
                            AppendLog(txtBatchPstLog, $"[信息] 导出内容: {exportItems}");
                            AppendLog(txtBatchPstLog, "[信息] 方案: EWS提取 + Outlook创建PST");
                        }));

                        bool result = OnPremiseToolkitService.BatchExportPst(
                            mailboxListFile,
                            outputDir,
                            startDate,
                            endDate,
                            threadCount,
                            exportEmail,
                            exportCalendar,
                            exportContacts,
                            exportTasks,
                            (completed, total, userEmail, status) =>
                        {
                            this.Invoke(new Action(() =>
                            {
                                prgBatchPst.Maximum = total;
                                prgBatchPst.Value = completed;
                                lblBatchPstProgress.Text = $"进度: {completed}/{total} - {userEmail}";
                                AppendLog(txtBatchPstLog, $"[{completed}/{total}] {userEmail}: {status}");
                            }));
                        });

                        this.Invoke(new Action(() =>
                        {
                            if (result)
                            {
                                lblBatchPstProgress.Text = "导出完成!";
                                lblBatchPstProgress.ForeColor = Color.Green;
                                AppendLog(txtBatchPstLog, "[完成] 批量导出PST完成");
                            }
                            else
                            {
                                lblBatchPstProgress.Text = "导出完成（部分失败）";
                                lblBatchPstProgress.ForeColor = Color.Orange;
                                AppendLog(txtBatchPstLog, "[完成] 批量导出PST完成（部分失败），请查看日志");
                            }
                            btnBatchPstExport.Enabled = true;
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblBatchPstProgress.Text = "导出失败: " + ex.Message;
                            lblBatchPstProgress.ForeColor = Color.Red;
                            btnBatchPstExport.Enabled = true;
                            AppendLog(txtBatchPstLog, $"[错误] {ex.Message}");
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblMailboxList);
            panel.Controls.Add(txtBatchPstMailboxList);
            panel.Controls.Add(btnBrowseMailboxList);
            panel.Controls.Add(btnDownloadTemplate);
            panel.Controls.Add(lblOutputDir);
            panel.Controls.Add(txtBatchPstOutputDir);
            panel.Controls.Add(btnBrowseBatchPstDir);
            panel.Controls.Add(lblDateRange);
            panel.Controls.Add(dtpBatchPstStartDate);
            panel.Controls.Add(lblTo);
            panel.Controls.Add(dtpBatchPstEndDate);
            panel.Controls.Add(lblThreadCount);
            panel.Controls.Add(numBatchPstThreads);
            panel.Controls.Add(lblExportContent);
            panel.Controls.Add(chkBatchEmail);
            panel.Controls.Add(chkBatchCalendar);
            panel.Controls.Add(chkBatchContacts);
            panel.Controls.Add(chkBatchTasks);
            panel.Controls.Add(btnBatchPstExport);
            panel.Controls.Add(prgBatchPst);
            panel.Controls.Add(lblBatchPstProgress);
            panel.Controls.Add(txtBatchPstLog);

            return panel;
        }

        /// <summary>
        /// 创建批量投递到IMAP面板
        /// </summary>
        private Panel CreateOnPremiseBatchToImapPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            int leftX = 20;
            int labelWidth = 85;
            int inputX = 110;
            int inputWidth = 200;
            int rowHeight = 28;
            int startY = 15;

            // 右列配置
            int rightX = 370;
            int rightLabelWidth = 85;
            int rightInputX = 460;
            int rightInputWidth = 180;

            var lblTitle = new Label
            {
                Text = "批量投递到 IMAP",
                Location = new Point(leftX, startY),
                AutoSize = true,
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            // ===== 第1行: 账户映射文件 =====
            int y = startY + 35;
            var lblMappingFile = new Label { Text = "账户映射:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtBatchImapMapping = new TextBox { Location = new Point(inputX, y), Size = new Size(280, 25) };
            var btnBrowseMappingFile = new Button { Text = "浏览...", Location = new Point(inputX + 285, y - 2), Size = new Size(70, 25) };
            btnBrowseMappingFile.Click += (s, e) =>
            {
                using (var of = new OpenFileDialog())
                {
                    of.Filter = "Excel/CSV文件|*.xlsx;*.xls;*.csv";
                    of.Title = "选择账户映射文件";
                    if (of.ShowDialog() == DialogResult.OK)
                    {
                        txtBatchImapMapping.Text = of.FileName;
                    }
                }
            };

            var btnDownloadTemplate = new Button
            {
                Text = "下载模板",
                Location = new Point(inputX + 360, y - 2),
                Size = new Size(80, 25)
            };
            btnDownloadTemplate.Click += (s, e) =>
            {
                try
                {
                    using (var sf = new SaveFileDialog())
                    {
                        sf.Filter = "CSV文件|*.csv";
                        sf.Title = "保存模板文件";
                        sf.FileName = "批量投递IMAP模板.csv";
                        if (sf.ShowDialog() == DialogResult.OK)
                        {
                            var templateContent = "源邮箱,目标邮箱,目标密码\nuser@company.com,user@company.com,password123";
                            File.WriteAllText(sf.FileName, templateContent, System.Text.Encoding.UTF8);
                            MessageBox.Show($"模板已保存到:\n{sf.FileName}", "模板下载", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show("模板下载失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // ===== 第2行: IMAP服务器（左） + 已保存配置（右） =====
            y += rowHeight + 5;
            var lblImapServer = new Label { Text = "IMAP服务器:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var txtBatchImapServer = new TextBox { Location = new Point(inputX, y), Size = new Size(130, 25) };
            var lblImapPort = new Label { Text = "端口:", Location = new Point(inputX + 135, y + 3), Size = new Size(35, 20) };
            var numBatchImapPort = new NumericUpDown { Location = new Point(inputX + 170, y), Size = new Size(60, 25), Minimum = 1, Maximum = 65535, Value = 993 };
            var chkBatchImapSsl = new CheckBox { Text = "SSL", Location = new Point(inputX + 235, y + 2), AutoSize = true, Checked = true };

            // 右列: 已保存配置
            var lblSavedConfig = new Label { Text = "已保存配置:", Location = new Point(rightX, y + 3), Size = new Size(rightLabelWidth, 20) };
            var cmbBatchImapSaved = new ComboBox { Location = new Point(rightInputX, y), Size = new Size(rightInputWidth, 25), DropDownStyle = ComboBoxStyle.DropDown };
            var savedImapAccounts = RegistryService.LoadEwsToImapAccounts();
            cmbBatchImapSaved.Items.Add("（请选择配置）");
            cmbBatchImapSaved.Items.Add("（手动输入）");
            foreach (var acc in savedImapAccounts)
            {
                cmbBatchImapSaved.Items.Add(acc.Name);
            }
            cmbBatchImapSaved.SelectedIndex = 0;

            // ===== 第3行: 日期范围 =====
            y += rowHeight + 5;
            var lblDateRange = new Label { Text = "日期范围:", Location = new Point(leftX, y + 3), Size = new Size(labelWidth, 20) };
            var dtpBatchImapStartDate = new DateTimePicker { Location = new Point(inputX, y), Size = new Size(110, 25), Format = DateTimePickerFormat.Short };
            var lblTo = new Label { Text = "至", Location = new Point(inputX + 115, y + 3), Size = new Size(20, 20) };
            var dtpBatchImapEndDate = new DateTimePicker { Location = new Point(inputX + 135, y), Size = new Size(110, 25), Format = DateTimePickerFormat.Short };

            // ===== 第4行: 选项 =====
            y += rowHeight + 5;
            var chkBatchImapReceived = new CheckBox { Text = "包含收件箱", Location = new Point(inputX, y + 2), AutoSize = true, Checked = true };
            var chkBatchImapSent = new CheckBox { Text = "包含发件箱", Location = new Point(inputX + 90, y + 2), AutoSize = true, Checked = false };
            var lblThreads = new Label { Text = "并发线程:", Location = new Point(inputX + 190, y + 3), Size = new Size(60, 20) };
            var numBatchImapThreads = new NumericUpDown { Location = new Point(inputX + 250, y), Size = new Size(45, 25), Minimum = 1, Maximum = 10, Value = 3 };

            // ===== 第5行: 开始投递按钮 =====
            y += 35;
            var btnBatchImapDeliver = new Button
            {
                Text = "开始投递",
                Location = new Point(inputX + 100, y - 3),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 120, 215)
            };

            // 进度条
            y += 40;
            var prgBatchImap = new ProgressBar { Location = new Point(leftX, y), Size = new Size(inputWidth + 50, 20), Style = ProgressBarStyle.Continuous, Visible = false };
            y += 25;
            var lblBatchImapProgress = new Label { Text = "", Location = new Point(leftX, y), AutoSize = true, ForeColor = Color.Gray };

            // 日志区域
            y += 25;
            var txtBatchImapLog = new TextBox
            {
                Location = new Point(leftX, y),
                Size = new Size(inputWidth + 80, 180),
                Multiline = true,
                ReadOnly = true,
                ScrollBars = ScrollBars.Vertical,
                BackColor = Color.FromArgb(30, 30, 30),
                ForeColor = Color.LightGray
            };

            // 保存配置选择事件 - 填充IMAP字段
            cmbBatchImapSaved.SelectedIndexChanged += (s, e) =>
            {
                if (cmbBatchImapSaved.SelectedIndex <= 1) return;
                var name = cmbBatchImapSaved.SelectedItem?.ToString();
                if (string.IsNullOrEmpty(name)) return;
                var acc = savedImapAccounts.Find(a => a.Name == name);
                if (acc != null)
                {
                    txtBatchImapServer.Text = acc.ImapServer;
                    numBatchImapPort.Value = acc.ImapPort > 0 ? acc.ImapPort : 993;
                    chkBatchImapSsl.Checked = acc.UseSsl;
                }
            };

            btnBatchImapDeliver.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(txtBatchImapServer.Text))
                {
                    MessageBox.Show("请输入IMAP服务器地址", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                if (string.IsNullOrWhiteSpace(txtBatchImapMapping.Text))
                {
                    MessageBox.Show("请选择账户映射文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                if (_onPremiseToolkitService == null || !_onPremiseToolkitService.IsConnected)
                {
                    MessageBox.Show("请先连接Exchange服务器", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnBatchImapDeliver.Enabled = false;
                prgBatchImap.Visible = true;
                prgBatchImap.Value = 0;
                lblBatchImapProgress.Text = "准备投递...";
                txtBatchImapLog.Clear();

                Task.Run(() =>
                {
                    try
                    {
                        string imapServer = txtBatchImapServer.Text.Trim();
                        int imapPort = (int)numBatchImapPort.Value;
                        bool useSsl = chkBatchImapSsl.Checked;
                        string mappingFile = txtBatchImapMapping.Text.Trim();
                        DateTime startDate = dtpBatchImapStartDate.Value.Date;
                        DateTime endDate = dtpBatchImapEndDate.Value.Date.AddDays(1).AddSeconds(-1);
                        bool includeReceived = chkBatchImapReceived.Checked;
                        bool includeSent = chkBatchImapSent.Checked;
                        int threads = (int)numBatchImapThreads.Value;

                        this.Invoke(new Action(() =>
                        {
                            AppendLog(txtBatchImapLog, "[========== 批量投递到IMAP开始 ==========]");
                            AppendLog(txtBatchImapLog, $"[信息] IMAP服务器: {imapServer}:{imapPort} (SSL: {useSsl})");
                            AppendLog(txtBatchImapLog, $"[信息] 账户映射: {mappingFile}");
                            AppendLog(txtBatchImapLog, $"[信息] 日期范围: {startDate:yyyy-MM-dd} 至 {endDate:yyyy-MM-dd}");
                            AppendLog(txtBatchImapLog, $"[信息] 收件箱: {(includeReceived ? "是" : "否")}, 发件箱: {(includeSent ? "是" : "否")}");
                            AppendLog(txtBatchImapLog, $"[信息] 并发线程: {threads}");
                        }));

                        // 调用服务方法进行批量投递
                        _onPremiseToolkitService.BatchDeliverToImap(
                            imapServer, imapPort, useSsl,
                            mappingFile,
                            startDate, endDate,
                            includeReceived, includeSent,
                            threads,
                            (completed, total, userEmail, status) =>
                        {
                            this.Invoke(new Action(() =>
                            {
                                prgBatchImap.Maximum = total;
                                prgBatchImap.Value = completed;
                                lblBatchImapProgress.Text = $"进度: {completed}/{total} - {userEmail}";
                                AppendLog(txtBatchImapLog, $"[{completed}/{total}] {userEmail}: {status}");
                            }));
                        });

                        this.Invoke(new Action(() =>
                        {
                            lblBatchImapProgress.Text = "投递完成!";
                            lblBatchImapProgress.ForeColor = Color.Green;
                            AppendLog(txtBatchImapLog, "[========== 批量投递到IMAP结束 ==========]");
                            btnBatchImapDeliver.Enabled = true;
                            prgBatchImap.Value = prgBatchImap.Maximum;
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblBatchImapProgress.Text = "投递失败: " + ex.Message;
                            lblBatchImapProgress.ForeColor = Color.Red;
                            btnBatchImapDeliver.Enabled = true;
                            AppendLog(txtBatchImapLog, $"[错误] {ex.Message}");
                        }));
                    }
                });
            };

            panel.Controls.Add(lblTitle);
            panel.Controls.Add(lblMappingFile);
            panel.Controls.Add(txtBatchImapMapping);
            panel.Controls.Add(btnBrowseMappingFile);
            panel.Controls.Add(btnDownloadTemplate);
            panel.Controls.Add(lblSavedConfig);
            panel.Controls.Add(cmbBatchImapSaved);
            panel.Controls.Add(lblImapServer);
            panel.Controls.Add(txtBatchImapServer);
            panel.Controls.Add(lblImapPort);
            panel.Controls.Add(numBatchImapPort);
            panel.Controls.Add(chkBatchImapSsl);
            panel.Controls.Add(lblDateRange);
            panel.Controls.Add(dtpBatchImapStartDate);
            panel.Controls.Add(lblTo);
            panel.Controls.Add(dtpBatchImapEndDate);
            panel.Controls.Add(chkBatchImapReceived);
            panel.Controls.Add(chkBatchImapSent);
            panel.Controls.Add(lblThreads);
            panel.Controls.Add(numBatchImapThreads);
            panel.Controls.Add(btnBatchImapDeliver);
            panel.Controls.Add(prgBatchImap);
            panel.Controls.Add(lblBatchImapProgress);
            panel.Controls.Add(txtBatchImapLog);

            return panel;
        }

        /// <summary>
        /// 创建邮件追踪日志搜索面板
        /// </summary>
        private Panel CreateOnPremiseMailSearchPanel()
        {
            var panel = new Panel { Dock = DockStyle.Fill };

