                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbOnPremiseSource.Items.AddRange(new object[] { "全部", "EDGE", "HUB", "MAILBOX", "CALLBACK" });
            cmbOnPremiseSource.SelectedIndex = 0;
            panel.Controls.Add(lblSource);
            panel.Controls.Add(cmbOnPremiseSource);

            y += 40;

            // 搜索按钮
