                Size = new Size(400, 25),
                ForeColor = Color.Gray
            };
            panel.Controls.Add(lblOnPremisePageInfo);

            return panel;
        }

        /// <summary>
        /// 创建用户管理面板
        /// </summary>
        private Panel CreateOnPremiseUserManagementPanel(TextBox logTextBox)
        {
            var panel = new Panel { Dock = DockStyle.Fill };

            // 日志辅助方法
            Action<string, Color> AppendLog = (msg, color) =>
            {
                if (logTextBox == null) return;
                var timestamp = DateTime.Now.ToString("HH:mm:ss");
                var line = $"[{timestamp}] {msg}";
                logTextBox.AppendText(line + Environment.NewLine);
                logTextBox.SelectionStart = logTextBox.Text.Length;
                logTextBox.ScrollToCaret();
            };

            // 左侧：用户树状列表
            var pnlUserList = new Panel { Location = new Point(10, 10), Size = new Size(300, panel.Height - 70), BorderStyle = BorderStyle.FixedSingle };

            var lblUserList = new Label { Text = "用户列表", Location = new Point(10, 10), AutoSize = true, Font = new Font("Microsoft Sans Serif", 9F, FontStyle.Bold) };

            var tvUsers = new TreeView
            {
                Location = new Point(10, 35),
                Size = new Size(280, pnlUserList.Height - 80),
                Font = new Font("Microsoft Sans Serif", 9F),
                BackColor = Color.FromArgb(60, 60, 60),
                ForeColor = Color.White
            };

            var btnRefreshUsers = new Button
            {
                Text = "刷新列表",
                Location = new Point(10, pnlUserList.Height - 40),
                Size = new Size(100, 30),
                BackColor = Color.FromArgb(0, 122, 204),
                ForeColor = Color.White,
                FlatStyle = FlatStyle.Flat
            };

            pnlUserList.Controls.Add(lblUserList);
            pnlUserList.Controls.Add(tvUsers);
            pnlUserList.Controls.Add(btnRefreshUsers);

            // 右侧：用户详情
            var pnlUserDetail = new Panel { Location = new Point(320, 10), Size = new Size(panel.Width - 340, panel.Height - 70) };

            var lblUserDetailTitle = new Label { Text = "用户详情", Location = new Point(0, 0), AutoSize = true, Font = new Font("Microsoft Sans Serif", 9F, FontStyle.Bold) };

            var lblDetailName = new Label { Text = "姓名:", Location = new Point(0, 40), Size = new Size(80, 25), TextAlign = ContentAlignment.MiddleRight };
            var txtDetailName = new TextBox { Location = new Point(85, 40), Size = new Size(200, 25), ReadOnly = true, BackColor = Color.FromArgb(60, 60, 60), ForeColor = Color.White };

            var lblDetailEmail = new Label { Text = "邮箱:", Location = new Point(0, 75), Size = new Size(80, 25), TextAlign = ContentAlignment.MiddleRight };
