            btnRefreshUsers.Click += async (s, ev) =>
            {
                if (_onPremiseToolkitService == null)
                {
                    lblStatusMsg.Text = "请先连接服务器";
                    lblStatusMsg.ForeColor = Color.Yellow;
                    AppendLog("刷新用户列表失败: 服务未连接", Color.Yellow);
                    return;
                }

                btnRefreshUsers.Enabled = false;
                lblStatusMsg.Text = "正在加载用户列表...";
                lblStatusMsg.ForeColor = Color.Yellow;
                AppendLog("开始刷新用户列表...", Color.Cyan);
                tvUsers.Nodes.Clear();

                try
                {
                    var users = await System.Threading.Tasks.Task.Run(() => OnPremiseToolkitService.GetUsers());

                    // 按部门分组
                    var deptGroups = users.GroupBy(u => string.IsNullOrEmpty(u.Department) ? "未分配部门" : u.Department);

                    foreach (var dept in deptGroups.OrderBy(g => g.Key))
                    {
                        var deptNode = new TreeNode { Text = $"{dept.Key} ({dept.Count()})", Tag = "DEPT" };
                        foreach (var user in dept.OrderBy(u => u.DisplayName))
                        {
                            var userNode = new TreeNode
                            {
                                Text = $"{user.DisplayName} ({user.Email})",
                                Tag = user,
                                ForeColor = user.IsEnabled ? Color.White : Color.Gray
                            };
                            deptNode.Nodes.Add(userNode);
                        }
                        tvUsers.Nodes.Add(deptNode);
                    }

                    tvUsers.ExpandAll();
                    lblStatusMsg.Text = $"共加载 {users.Count} 个用户";
                    lblStatusMsg.ForeColor = Color.LightGreen;
                    AppendLog($"用户列表刷新成功，共 {users.Count} 个用户", Color.LightGreen);
                }
                catch (Exception ex)
                {
                    lblStatusMsg.Text = "加载失败: " + ex.Message;
                    lblStatusMsg.ForeColor = Color.Red;
                    AppendLog($"加载用户列表失败: {ex.Message}", Color.Red);
                }
                finally
                {
                    btnRefreshUsers.Enabled = true;
                }
            };

            tvUsers.AfterSelect += (s, ev) =>
            {
                if (ev.Node.Tag is ExchangeOnPremiseToolkitService.OnPremiseUserInfo user)
                {
                    selectedUserId = user.Id;
                    txtDetailName.Text = user.DisplayName;
                    txtDetailEmail.Text = user.Email;
                    txtDetailDept.Text = user.Department;
                    txtDetailTitle.Text = user.Title;
                    txtDetailStatus.Text = user.IsEnabled ? "已启用" : "已禁用";
                    txtDetailStatus.ForeColor = user.IsEnabled ? Color.LightGreen : Color.Red;
                    txtDetailType.Text = user.RecipientType;
                    btnEnableUser.Enabled = !user.IsEnabled;
                    btnDisableUser.Enabled = user.IsEnabled;
                    lblStatusMsg.Text = "";
                }
                else
                {
                    selectedUserId = "";
                    txtDetailName.Clear();
                    txtDetailEmail.Clear();
                    txtDetailDept.Clear();
                    txtDetailTitle.Clear();
                    txtDetailStatus.Clear();
                    txtDetailType.Clear();
                    btnEnableUser.Enabled = false;
