                        lblStatusMsg.ForeColor = Color.LightGreen;
                        txtDetailStatus.Text = "已启用";
                        txtDetailStatus.ForeColor = Color.LightGreen;
                        btnEnableUser.Enabled = false;
                        btnDisableUser.Enabled = true;
                        AppendLog($"用户 {txtDetailEmail.Text} 已启用成功", Color.LightGreen);
                        btnRefreshUsers.PerformClick();
                    }
                    else
                    {
                        lblStatusMsg.Text = "启用失败";
                        lblStatusMsg.ForeColor = Color.Red;
                        AppendLog($"用户 {txtDetailEmail.Text} 启用失败", Color.Red);
                        btnEnableUser.Enabled = true;
                    }
                }
                catch (Exception ex)
                {
                    lblStatusMsg.Text = "启用失败: " + ex.Message;
                    lblStatusMsg.ForeColor = Color.Red;
                    AppendLog($"启用用户异常: {ex.Message}", Color.Red);
                    btnEnableUser.Enabled = true;
                }
            };

            btnDisableUser.Click += async (s, ev) =>
            {
