                    AppendLog("重置密码失败: 请输入新密码", Color.Yellow);
                    return;
                }

                btnResetPassword.Enabled = false;
                lblStatusMsg.Text = "正在重置密码...";
                lblStatusMsg.ForeColor = Color.Yellow;
                AppendLog($"正在重置用户 {txtDetailEmail.Text} 的密码...", Color.Cyan);

                try
                {
                    var success = await System.Threading.Tasks.Task.Run(() => OnPremiseToolkitService.ResetUserPassword(selectedUserId, newPwd));
                    if (success)
                    {
                        lblStatusMsg.Text = "密码已重置成功";
                        lblStatusMsg.ForeColor = Color.LightGreen;
