        private void CmbO365SourceType_SelectedIndexChanged(object sender, EventArgs e)
        {
            // Update browse button text based on selection
            bool isPst = cmbO365SourceType.SelectedIndex == 1;

            // Show/hide PST method options using declared fields
            if (radO365PstExtract != null) radO365PstExtract.Visible = isPst;
            // EWS 直接上传模式已废弃, 永远隐藏 (统一走 EML 中转路径)
            if (radO365PstDirect != null) radO365PstDirect.Visible = false;

            // Find and toggle the label
            Control lblPstMethod = null;
            var tabControl = this.Controls.OfType<TabControl>().FirstOrDefault();
            if (tabControl != null)
            {
                foreach (TabPage tab in tabControl.TabPages)
                {
                    foreach (Control c in tab.Controls)
                    {
                        if (c.Name == "lblPstMethod")
                        {
                            lblPstMethod = c;
                            break;
                        }
                    }
                }
            }
            if (lblPstMethod != null) lblPstMethod.Visible = isPst;

            // Show/hide PST note
            Control lblPstNote = null;
            if (tabControl != null)
            {
                foreach (TabPage tab in tabControl.TabPages)
                {
                    foreach (Control c in tab.Controls)
                    {
                        if (c.Name == "lblPstNote")
                        {
                            lblPstNote = c;
                            break;
                        }
                    }
                }
            }
            if (lblPstNote != null) lblPstNote.Visible = isPst;
        }

        private Control panelFindControl(Control parent, string name)
        {
            foreach (Control c in parent.Controls)
            {
                if (c.Name == name) return c;
                var found = panelFindControl(c, name);
                if (found != null) return found;
            }
            return null;
        }

        private void BtnO365SourceBrowse_Click(object sender, EventArgs e)
        {
            // 找到按钮所在的页签
            var btn = sender as Button;
            Control current = btn;
            string panelName = null;
            while (current != null)
            {
                if (!string.IsNullOrEmpty(current.Name) &&
                    (current.Name == "EMLO365Panel" || current.Name == "PSTO365Panel"))
                {
                    panelName = current.Name;
                    break;
                }
                current = current.Parent;
            }
            if (panelName == null) return;

            var panel = this.Controls.Find(panelName, true).FirstOrDefault() as Panel;
            var cmbSourceType = panel?.Controls.Find("cmbO365SourceType", true).FirstOrDefault() as ComboBox;
            var txtSourcePath = panel?.Controls.Find("txtO365SourcePath", true).FirstOrDefault() as TextBox;

            if (cmbSourceType == null || txtSourcePath == null) return;

            if (panelName == "EMLO365Panel") // EML: 选择文件夹
            {
                using (var dialog = new FolderBrowserDialog())
                {
                    dialog.Description = "选择EML文件夹";
                    if (dialog.ShowDialog() == DialogResult.OK)
                    {
                        txtSourcePath.Text = dialog.SelectedPath;
                    }
                }
            }
            else if (panelName == "PSTO365Panel") // PST: 选择单个文件
            {
                using (var dialog = new OpenFileDialog())
                {
                    dialog.Filter = "PST文件|*.pst";
                    dialog.Title = "选择PST文件";
                    if (dialog.ShowDialog() == DialogResult.OK)
                    {
                        txtSourcePath.Text = dialog.FileName;
                    }
                }
            }
        }

        private void BtnO365Test_Click(object sender, EventArgs e)
        {
            try
            {
                _office365Service = new Office365ImportService();

                bool isOAuth = cmbO365AuthType.SelectedIndex == 0; // OAuth 2.0 is at index 0

                if (isOAuth)
                {
                    // OAuth2 登录
                    if (!_isO365OAuthConnected || string.IsNullOrEmpty(_office365AccessToken))
                    {
                        lblO365Status.Text = "请先通过 OAuth2 登录";
                        lblO365Status.ForeColor = Color.Red;
                        return;
                    }

                    if (_office365Service.ConnectWithOAuth(_office365OAuthEmail, _office365AccessToken))
                    {
                        lblO365Status.Text = "OAuth2 连接成功!";
                        lblO365Status.ForeColor = Color.Green;
                    }
                    else
                    {
                        lblO365Status.Text = "OAuth2 连接失败，请重新登录";
                        lblO365Status.ForeColor = Color.Red;
                        _isO365OAuthConnected = false;
                    }
                }
                else
                {
                    // 用户名密码登录
                    if (string.IsNullOrWhiteSpace(txtO365Email.Text) || string.IsNullOrWhiteSpace(txtO365Password.Text))
                    {
                        lblO365Status.Text = "请输入邮箱地址和密码";
                        lblO365Status.ForeColor = Color.Red;
                        return;
                    }

                    if (_office365Service.Connect(txtO365Email.Text, txtO365Password.Text, txtO365Domain.Text))
                    {
                        lblO365Status.Text = "连接成功! 正在加载文件夹...";
                        lblO365Status.ForeColor = Color.Green;

                        // 加载文件夹列表
                        LoadO365FoldersPassword(txtO365Email.Text);
                    }
                    else
                    {
                        lblO365Status.Text = "连接失败，请检查凭据";
                        lblO365Status.ForeColor = Color.Red;
                    }
                }
            }
            catch (Exception ex)
            {
                lblO365Status.Text = $"连接失败: {ex.Message}";
                lblO365Status.ForeColor = Color.Red;
            }
        }

        private void BtnSyncContacts_Click(object sender, EventArgs e)
        {
            if (!_isO365OAuthConnected || string.IsNullOrEmpty(_office365AccessToken))
            {
                lblO365Status.Text = "请先通过 OAuth2 登录";
                lblO365Status.ForeColor = Color.Red;
                return;
            }

            // 检查是否已连接服务
            if (_office365Service == null || !_office365Service.IsOAuthConnected)
            {
                _office365Service = new Office365ImportService();
                if (!_office365Service.ConnectWithOAuth(_office365OAuthEmail, _office365AccessToken))
                {
                    lblO365Status.Text = "OAuth2 连接失败，请重新登录";
                    lblO365Status.ForeColor = Color.Red;
                    return;
                }
            }

            // 打开文件对话框选择联系人文件
            using (var openFileDialog = new OpenFileDialog())
            {
                openFileDialog.Title = "选择联系人文件";
                openFileDialog.Filter = "所有支持格式|*.csv;*.vcf;*.vcard;*.msg|CSV文件|*.csv|VCF文件|*.vcf;*.vcard|MSG文件|*.msg";
                openFileDialog.FilterIndex = 1;

                if (openFileDialog.ShowDialog() == DialogResult.OK)
                {
                    var filePath = openFileDialog.FileName;
                    var extension = Path.GetExtension(filePath).ToLower();

                    try
                    {
                        lblO365Status.Text = "正在同步联系人...";
                        lblO365Status.ForeColor = Color.Blue;
                        progressO365.Style = ProgressBarStyle.Marquee;

                        // 根据文件类型处理
                        if (extension == ".csv")
                        {
                            SyncContactsFromCsv(filePath);
                        }
                        else if (extension == ".vcf" || extension == ".vcard")
                        {
                            SyncContactsFromVcf(filePath);
                        }
                        else if (extension == ".msg")
                        {
                            SyncContactsFromMsg(filePath);
                        }
                        else
                        {
                            lblO365Status.Text = "不支持的文件格式";
                            lblO365Status.ForeColor = Color.Red;
                        }

                        progressO365.Style = ProgressBarStyle.Continuous;
                    }
                    catch (Exception ex)
                    {
                        lblO365Status.Text = $"同步联系人失败: {ex.Message}";
                        lblO365Status.ForeColor = Color.Red;
                        progressO365.Style = ProgressBarStyle.Continuous;
                        Serilog.Log.Error(ex, "同步联系人失败");
                    }
                }
            }
        }

        public string SyncContactsFromCsv(string filePath)
        {
            Serilog.Log.Information("========== 开始CSV联系人同步 ==========");
            Serilog.Log.Information("文件路径: {FilePath}", filePath);

            int totalRecords = 0;
            int successCount = 0;
            int skipCount = 0;
            int errorCount = 0;
            string resultMsg = "";

            try
            {
                var encoding = System.Text.Encoding.UTF8;
                using (var reader = new StreamReader(filePath, encoding))
                {
                    reader.BaseStream.Position = 0;
                    reader.DiscardBufferedData();

                    using (var csv = new CsvHelper.CsvReader(reader, new CsvHelper.Configuration.CsvConfiguration(System.Globalization.CultureInfo.InvariantCulture)
                    {
                        HasHeaderRecord = true,
                        MissingFieldFound = null,
                        BadDataFound = null,
                        HeaderValidated = null
                    }))
                    {
                        csv.Read();
                        csv.ReadHeader();
                        var headers = csv.HeaderRecord;
                        Serilog.Log.Information("CSV表头: {Headers}", string.Join(", ", headers));

                        var records = csv.GetRecords<dynamic>().ToList();
                        totalRecords = records.Count;
                        Serilog.Log.Information("CSV总记录数: {Count}", totalRecords);

                        foreach (var record in records)
                        {
                            try
                            {
                                var dict = (IDictionary<string, object>)record;

                                // 调试：记录前3条数据
                                Serilog.Log.Information("记录数据: {Data}", string.Join(" | ", dict.Select(kvp => $"{kvp.Key}={kvp.Value}")));

                                // 尝试获取邮箱 - 支持更多列名（包括Outlook格式的"名"列）
                                string email = "";
                                // 首先检查标准邮箱列
                                foreach (var key in new[] { "电子邮件地址", "Email", "EmailAddress", "Email Address", "E-mail", "Mail", "邮箱", "Email1" })
                                {
                                    if (dict.ContainsKey(key) && dict[key] != null)
                                    {
                                        var val = dict[key]?.ToString()?.Trim();
                                        if (!string.IsNullOrEmpty(val))
                                        {
                                            email = val;
                                            break;
                                        }
                                    }
                                }
                                // 如果标准邮箱列为空，尝试使用"名"列（Outlook导出格式）
                                if (string.IsNullOrEmpty(email) && dict.ContainsKey("名") && dict["名"] != null)
                                {
                                    var nameVal = dict["名"]?.ToString()?.Trim();
                                    if (!string.IsNullOrEmpty(nameVal) && nameVal.Contains("@"))
                                    {
                                        email = nameVal;
                                    }
                                }

                                // 尝试获取显示名称
                                string displayName = "";
                                // 先尝试"电子邮件显示名称"列
                                if (dict.ContainsKey("电子邮件显示名称") && dict["电子邮件显示名称"] != null)
                                {
                                    var val = dict["电子邮件显示名称"]?.ToString()?.Trim();
                                    if (!string.IsNullOrEmpty(val))
                                    {
                                        displayName = val;
                                    }
                                }
                                // 如果没有，尝试组合名和姓
                                if (string.IsNullOrEmpty(displayName))
                                {
                                    string firstName = "", lastName = "";
                                    if (dict.ContainsKey("名") && dict["名"] != null) firstName = dict["名"]?.ToString()?.Trim();
                                    if (dict.ContainsKey("姓") && dict["姓"] != null) lastName = dict["姓"]?.ToString()?.Trim();
                                    displayName = (lastName + firstName).Trim();
                                }

                                // 验证邮箱格式
                                if (string.IsNullOrWhiteSpace(email))
                                {
                                    Serilog.Log.Warning("跳过 - 邮箱为空, Name={Name}", displayName);
                                    skipCount++;
                                    continue;
                                }

                                if (!email.Contains("@") || !email.Contains("."))
                                {
                                    Serilog.Log.Warning("跳过 - 邮箱格式无效: {Email}, Name={Name}", email, displayName);
                                    skipCount++;
                                    continue;
                                }

                                Serilog.Log.Information("正在创建联系人 - Name={Name}, Email={Email}", displayName, email);
                                bool result = _office365Service.CreateContact(displayName, email);

                                if (result)
                                {
                                    successCount++;
                                    Serilog.Log.Information("成功 - Name={Name}, Email={Email}", displayName, email);
                                }
                                else
                                {
                                    errorCount++;
                                    Serilog.Log.Warning("失败 - Name={Name}, Email={Email}", displayName, email);
                                }
                            }
                            catch (Exception ex)
                            {
                                errorCount++;
                                Serilog.Log.Error(ex, "记录处理异常: {Error}", ex.Message);
                            }
                        }
                    }
                }

                resultMsg = $"CSV同步完成: 总计{totalRecords}条, 成功{successCount}条, 跳过{skipCount}条, 失败{errorCount}条";
                Serilog.Log.Information("========== CSV联系人同步完成 ==========");
                Serilog.Log.Information(resultMsg);
            }
            catch (Exception ex)
            {
                Serilog.Log.Error(ex, "CSV同步异常: {Error}", ex.Message);
                return $"CSV同步异常: {ex.Message}";
            }

            return resultMsg;
        }

        public string SyncContactsFromVcf(string filePath)
        {
            Serilog.Log.Information("========== 开始VCF联系人同步 ==========");
            Serilog.Log.Information("文件路径: {FilePath}", filePath);

            var vcards = File.ReadAllText(filePath);
            int totalCount = 0, successCount = 0, skipCount = 0, errorCount = 0;

            // 解析 vCard
            var lines = vcards.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);
            bool inVCard = false;
            VCardData current = new VCardData();

            foreach (var line in lines)
            {
                if (line.StartsWith("BEGIN:VCARD", StringComparison.OrdinalIgnoreCase))
                {
                    inVCard = true;
                    current = new VCardData();
                }
                else if (line.StartsWith("END:VCARD", StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.IsNullOrWhiteSpace(current.Email))
                    {
                        Serilog.Log.Information("VCF联系人: Name={Name}, Email={Email}, Phone={Phone}, Company={Company}, Title={Title}",
                            current.DisplayName, current.Email, current.Phone, current.Company, current.Title);

                        bool result = _office365Service.CreateContact(
                            current.DisplayName,
                            current.Email,
                            current.Phone,
                            current.Company,
                            current.Title);

                        if (result) successCount++;
                        else errorCount++;
                        totalCount++;
                    }
                    else
                    {
                        skipCount++;
                        Serilog.Log.Warning("跳过VCF联系人: 无邮箱, Name={Name}", current.DisplayName);
                    }
                    inVCard = false;
                }
                else if (inVCard)
                {
                    ParseVCardLine(line, current);
                }
            }

            string resultMsg = $"VCF同步完成: 总计{totalCount}条, 成功{successCount}条, 跳过{skipCount}条, 失败{errorCount}条";
            Serilog.Log.Information("========== VCF联系人同步完成 ==========");
            Serilog.Log.Information(resultMsg);
            return resultMsg;
        }

        private void ParseVCardLine(string line, VCardData vcard)
        {
            // 处理带类型的字段如 TEL;TYPE=CELL:+1234567890
            string prefix = "";
            string value = "";

            if (line.Contains(":"))
            {
                int colonIndex = line.IndexOf(':');
                prefix = line.Substring(0, colonIndex);
                value = line.Substring(colonIndex + 1);
            }
            else
            {
                return;
            }

            string key = prefix.Split(';')[0].ToUpper();

            switch (key)
            {
                case "FN":
                    vcard.DisplayName = value;
                    break;
                case "N":
                    // N:姓;名;中间名;前缀;后缀
                    var parts = value.Split(';');
                    if (parts.Length >= 2)
                        vcard.DisplayName = parts[1] + parts[0]; // 名+姓
                    else if (parts.Length == 1)
                        vcard.DisplayName = parts[0];
                    break;
                case "EMAIL":
                    if (string.IsNullOrEmpty(vcard.Email))
                        vcard.Email = value;
                    break;
                case "TEL":
                    if (string.IsNullOrEmpty(vcard.Phone))
                        vcard.Phone = value;
                    break;
                case "ORG":
                    vcard.Company = value.Split(';')[0];
                    break;
                case "TITLE":
                    vcard.Title = value;
                    break;
                case "NOTE":
                    vcard.Note = value;
                    break;
                case "URL":
                    vcard.Website = value;
                    break;
                case "ADR":
                    // ADR:类型;邮箱;街道;城市;省;邮编;国家
                    var adrParts = value.Split(';');
                    if (adrParts.Length >= 3)
                        vcard.Address = string.Join(", ", adrParts.Where(s => !string.IsNullOrEmpty(s)));
                    break;
            }
        }

        private class VCardData
        {
            public string DisplayName { get; set; } = "";
            public string Email { get; set; } = "";
            public string Phone { get; set; } = "";
            public string Company { get; set; } = "";
            public string Title { get; set; } = "";
            public string Note { get; set; } = "";
            public string Website { get; set; } = "";
            public string Address { get; set; } = "";
        }

