        private void BtnSyncCalendar_Click(object sender, EventArgs e)
        {
            if (!_isO365OAuthConnected || string.IsNullOrEmpty(_office365AccessToken))
            {
                lblO365Status.Text = "请先通过 OAuth2 登录";
                lblO365Status.ForeColor = Color.Red;
                return;
            }

            // 检查是否已连接服务
            if (_office365Service == null || !_office365Service.IsOAuthConnected)
            {
                _office365Service = new Office365ImportService();
                if (!_office365Service.ConnectWithOAuth(_office365OAuthEmail, _office365AccessToken))
                {
                    lblO365Status.Text = "OAuth2 连接失败，请重新登录";
                    lblO365Status.ForeColor = Color.Red;
                    return;
                }
            }

            // 打开文件对话框选择日历文件
            using (var openFileDialog = new OpenFileDialog())
            {
                openFileDialog.Title = "选择日历文件";
                openFileDialog.Filter = "所有支持格式|*.ics;*.vcs;*.msg|ICS文件|*.ics|VCS文件|*.vcs|MSG文件|*.msg";
                openFileDialog.FilterIndex = 1;

                if (openFileDialog.ShowDialog() == DialogResult.OK)
                {
                    var filePath = openFileDialog.FileName;
                    var extension = Path.GetExtension(filePath).ToLower();

                    try
                    {
                        lblO365Status.Text = "正在同步日历...";
                        lblO365Status.ForeColor = Color.Blue;
                        progressO365.Style = ProgressBarStyle.Marquee;

                        if (extension == ".ics")
                        {
                            SyncCalendarFromIcs(filePath);
                        }
                        else if (extension == ".vcs")
                        {
                            SyncCalendarFromVcs(filePath);
                        }
                        else if (extension == ".msg")
                        {
                            SyncCalendarFromMsg(filePath);
                        }
                        else
                        {
                            lblO365Status.Text = "不支持的文件格式";
                            lblO365Status.ForeColor = Color.Red;
                        }

                        progressO365.Style = ProgressBarStyle.Continuous;
                    }
                    catch (Exception ex)
                    {
                        lblO365Status.Text = $"同步日历失败: {ex.Message}";
                        lblO365Status.ForeColor = Color.Red;
                        progressO365.Style = ProgressBarStyle.Continuous;
                        Serilog.Log.Error(ex, "同步日历失败");
                    }
                }
            }
        }

        public string SyncCalendarFromIcs(string filePath)
        {
            var icsContent = File.ReadAllText(filePath);
            int count = 0;

            var lines = icsContent.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);
            string currentSummary = "";
            DateTime currentStart = DateTime.MinValue;
            DateTime currentEnd = DateTime.MinValue;
            string currentDescription = "";
            string currentLocation = "";
            bool inEvent = false;

            foreach (var line in lines)
            {
                if (line.StartsWith("BEGIN:VEVENT", StringComparison.OrdinalIgnoreCase))
                {
                    inEvent = true;
                    currentSummary = "";
                    currentStart = DateTime.MinValue;
                    currentEnd = DateTime.MinValue;
                    currentDescription = "";
                    currentLocation = "";
                }
                else if (line.StartsWith("END:VEVENT", StringComparison.OrdinalIgnoreCase))
                {
                    if (currentStart != DateTime.MinValue)
                    {
                        _office365Service.CreateCalendarEvent(currentSummary, currentStart, currentEnd, currentDescription, currentLocation);
                        count++;
                    }
                    inEvent = false;
                }
                else if (inEvent)
                {
                    if (line.StartsWith("SUMMARY:", StringComparison.OrdinalIgnoreCase))
                        currentSummary = line.Substring(8);
                    else if (line.StartsWith("DESCRIPTION:", StringComparison.OrdinalIgnoreCase))
                        currentDescription = line.Substring(12);
                    else if (line.StartsWith("LOCATION:", StringComparison.OrdinalIgnoreCase))
                        currentLocation = line.Substring(9);
                    else if (line.StartsWith("DTSTART:", StringComparison.OrdinalIgnoreCase))
                    {
                        if (DateTime.TryParseExact(line.Substring(8), "yyyyMMddTHHmmssZ", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal, out var dt))
                            currentStart = dt;
                    }
                    else if (line.StartsWith("DTEND:", StringComparison.OrdinalIgnoreCase))
                    {
                        if (DateTime.TryParseExact(line.Substring(6), "yyyyMMddTHHmmssZ", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal, out var dt))
                            currentEnd = dt;
                    }
                }
            }

            return $"同步完成，共 {count} 个日历事件";
        }

        public string SyncCalendarFromVcs(string filePath)
        {
            // VCS 格式解析
            var vcsContent = File.ReadAllText(filePath);
            int count = 0;

            var lines = vcsContent.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);
            string currentSummary = "";
            DateTime currentStart = DateTime.MinValue;
            DateTime currentEnd = DateTime.MinValue;
            string currentDescription = "";
            string currentLocation = "";
            bool inEvent = false;

            foreach (var line in lines)
            {
                if (line.StartsWith("BEGIN:VEVENT", StringComparison.OrdinalIgnoreCase))
                {
                    inEvent = true;
                    currentSummary = "";
                    currentStart = DateTime.MinValue;
                    currentEnd = DateTime.MinValue;
                    currentDescription = "";
                    currentLocation = "";
                }
                else if (line.StartsWith("END:VEVENT", StringComparison.OrdinalIgnoreCase))
                {
                    if (currentStart != DateTime.MinValue)
                    {
                        _office365Service.CreateCalendarEvent(currentSummary, currentStart, currentEnd, currentDescription, currentLocation);
                        count++;
                    }
                    inEvent = false;
                }
                else if (inEvent)
                {
                    if (line.StartsWith("SUMMARY:", StringComparison.OrdinalIgnoreCase) || line.StartsWith("DTSTART;", StringComparison.OrdinalIgnoreCase))
                    {
                        var idx = line.IndexOf(':');
                        if (idx > 0)
                        {
                            var key = line.Substring(0, idx);
                            var value = line.Substring(idx + 1);
                            if (key == "SUMMARY")
                                currentSummary = value;
                            else if (key.Contains("DTSTART"))
                                DateTime.TryParse(value, out currentStart);
                        }
                    }
                }
            }

            return $"同步完成，共 {count} 个日历事件";
        }

