        }


        private async void BtnO365Import_Click(object sender, EventArgs e, string targetFolder)
        {
            // 根据sender的Tag确定是哪个页签
            var btn = sender as Button;
            string panelName = btn?.Tag?.ToString() == "PST" ? "PSTO365Panel" : "EMLO365Panel";
            var panel = this.Controls.Find(panelName, true).FirstOrDefault() as Panel;

            // 查找页签中的控件
            var cmbO365SourceTypePanel = panel?.Controls.Find("cmbO365SourceType", true).FirstOrDefault() as ComboBox;
            var txtO365SourcePathPanel = panel?.Controls.Find("txtO365SourcePath", true).FirstOrDefault() as TextBox;
            var cmbO365TargetFolderPanel = panel?.Controls.Find("cmbO365TargetFolder", true).FirstOrDefault() as ComboBox;
            var lblO365StatusPanel = panel?.Controls.Find("lblO365Status", true).FirstOrDefault() as Label;
            var progressO365Panel = panel?.Controls.Find("progressO365", true).FirstOrDefault() as ProgressBar;
            var lblProgressPercentPanel = panel?.Controls.Find("lblProgressPercent", true).FirstOrDefault() as Label;
            var btnO365ImportPanel = panel?.Controls.Find("btnO365Import", true).FirstOrDefault() as Button;

            // 获取实际的目标文件夹值，默认为Inbox
            string actualTargetFolder = string.IsNullOrWhiteSpace(cmbO365TargetFolderPanel?.Text) ? "Inbox" : cmbO365TargetFolderPanel.Text;

            // 检查连接状态
            bool isOAuth = cmbO365AuthType.SelectedIndex == 0; // OAuth 2.0 is at index 0

            Serilog.Log.Information("BtnO365Import_Click 开始, isOAuth={OAuth}, _isO365OAuthConnected={Connected}, panel={Panel}",
                isOAuth, _isO365OAuthConnected, panelName);

            // 检查服务是否已连接，如果未连接则创建并连接
            bool needConnect = false;
            if (_office365Service == null)
            {
                needConnect = true;
                _office365Service = new Office365ImportService();
            }
            else if (!_office365Service.IsOAuthConnected)
            {
                needConnect = true;
            }

            if (needConnect)
            {
                if (isOAuth)
                {
                    if (!_isO365OAuthConnected || string.IsNullOrEmpty(_office365AccessToken))
                    {
                        if (lblO365StatusPanel != null)
                        {
                            lblO365StatusPanel.Text = "请先通过 OAuth2 登录";
                            lblO365StatusPanel.ForeColor = Color.Red;
                        }
                        return;
                    }
                    Serilog.Log.Information("准备使用 OAuth 连接, email={Email}", _office365OAuthEmail);
                    if (!_office365Service.ConnectWithOAuth(_office365OAuthEmail, _office365AccessToken))
                    {
                        if (lblO365StatusPanel != null)
                        {
                            lblO365StatusPanel.Text = "OAuth2 连接失败，请重新登录";
                            lblO365StatusPanel.ForeColor = Color.Red;
                        }
                        return;
                    }
                    Serilog.Log.Information("OAuth 连接成功");
                }
                else
                {
                    if (!_office365Service.Connect(txtO365Email.Text, txtO365Password.Text, txtO365Domain.Text))
                    {
                        if (lblO365StatusPanel != null)
                        {
                            lblO365StatusPanel.Text = "请先测试连接";
                            lblO365StatusPanel.ForeColor = Color.Red;
                        }
                        return;
                    }
                }
            }

            // 验证源路径 (IMAP 模式无需源路径)
            int sourceTypeIndex = cmbO365SourceTypePanel?.SelectedIndex ?? 0;
            bool isPstPanel = panelName == "PSTO365Panel";
            bool isImapMode = !isPstPanel && sourceTypeIndex == 2;
            if (!isImapMode && string.IsNullOrWhiteSpace(txtO365SourcePathPanel?.Text))
            {
                if (lblO365StatusPanel != null)
                {
                    lblO365StatusPanel.Text = "请选择源路径";
                    lblO365StatusPanel.ForeColor = Color.Red;
                }
                return;
            }

            if (isO365Importing) return;
            isO365Importing = true;
            if (btnO365ImportPanel != null) btnO365ImportPanel.Enabled = false;

            var progress = new Progress<int>(count =>
            {
                if (progressO365Panel != null) progressO365Panel.Value = Math.Min(count, 100);
                if (lblO365StatusPanel != null) lblO365StatusPanel.Text = $"已导入 {count} 封邮件...";
                if (lblProgressPercentPanel != null) lblProgressPercentPanel.Text = $"{Math.Min(count, 100)}%";
            });

            // 记录日志
            Serilog.Log.Information("开始导入，源路径: {Path}, 目标文件夹: {Folder}, 类型: {Type}",
                txtO365SourcePathPanel?.Text, actualTargetFolder, sourceTypeIndex);

            await Task.Run(async () =>
            {
                try
                {
                    int imported = 0;

                    if (isPstPanel) // PST 面板 - 单文件导入
                    {
                        string pstSourcePath = txtO365SourcePathPanel?.Text ?? "";
                        string pstTargetEmail = _office365OAuthEmail ?? "";
                        var txtLog = panel?.Controls.Find("txtO365ImportLog", true).FirstOrDefault() as TextBox;

                        // PST 阶段状态更新 (顶部状态标签 + 日志框)
                        Action<string> pstUpdateStatus = (msg) => {
                            this.Invoke(new Action(() => {
                                if (lblO365StatusPanel != null) {
                                    lblO365StatusPanel.Text = msg;
                                    lblO365StatusPanel.ForeColor = Color.Black;
                                }
                            }));
                        };

                        // PST 导入专用日志回调：写入 Pstimport_日期.log 文件 + 底部日志框
                        Action<string> pstAppendLog = (msg) => {
                            if (txtLog != null)
                            {
                                txtLog.Invoke(new Action(() => {
                                    txtLog.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\r\n");
                                }));
                            }
                            // 写入 Pstimport_日期.log 并显示到主日志框 (_logTextBox)
                            this.Invoke(new Action(() => Log(msg, "PSTImport")));
                        };

                        // 阶段 1: 加载 PST 文件
                        pstUpdateStatus("正在加载 PST 文件...");
                        pstAppendLog($"开始 PST 导入: 源文件={pstSourcePath}, 目标={pstTargetEmail}/{actualTargetFolder}");

                        if (!File.Exists(pstSourcePath) || !pstSourcePath.EndsWith(".pst", StringComparison.OrdinalIgnoreCase))
                        {
                            pstAppendLog($"[错误] PST 源文件无效: {pstSourcePath}");
                            pstUpdateStatus("PST 源文件无效");
                            this.Invoke(new Action(() => {
                                if (lblO365StatusPanel != null) lblO365StatusPanel.ForeColor = Color.Red;
                            }));
                            return;
                        }

                        pstUpdateStatus($"PST 文件加载成功: {Path.GetFileName(pstSourcePath)}");
                        pstAppendLog($"PST 文件加载成功: {Path.GetFileName(pstSourcePath)}");
                        int pstImported = 0;

                        // EWS 直接上传模式已废弃, 统一走 "PST→EML→Graph" 路径
                        {
                            // 阶段 2: 解析 PST 为 EML
                            var tempDir = Path.Combine(Path.GetTempPath(), "O365Import_" + Guid.NewGuid());
                            Directory.CreateDirectory(tempDir);
                            pstAppendLog($"已创建临时目录: {tempDir}");

                            var pstService = new PstExtractService();
                            pstUpdateStatus("正在解析 PST 为 EML 文件...");
                            pstAppendLog("正在解析 PST 为 EML 文件...");

                            if (pstService.ExtractToEml(pstSourcePath, tempDir))
                            {
                                pstUpdateStatus("PST 解析完成，正在导入邮件到 Office 365...");

                                // 读取 UI 中的目标文件夹 (保留空字符串语义: 空 = 邮箱根目录)
                                string pstTargetFolder = cmbO365TargetFolderPanel?.Text?.Trim() ?? "";
                                string pstTargetDesc = string.IsNullOrEmpty(pstTargetFolder)
                                    ? "邮箱根目录"
                                    : $"目标文件夹 [{pstTargetFolder}]";
                                pstAppendLog($"PST 解析完成，开始批量导入 EML 到 {pstTargetEmail}/{pstTargetDesc}");

                                // 设置 LogCallback，让 Graph API 内部的 PstImportLogger 消息也能显示到 UI 日志框
                                _office365Service.LogCallback = pstAppendLog;

                                // 使用 UI 输入的目标文件夹; 为空则子文件夹直接放在邮箱根目录
                                pstImported = _office365Service.ImportEmlFolder(tempDir, pstTargetFolder, progress);
                                pstAppendLog($"批量导入完成，本 PST 共导入 {pstImported} 封邮件");
                                try { Directory.Delete(tempDir, true); } catch { }
                            }
                            else
                            {
                                pstAppendLog($"[错误] PST 提取失败: {pstSourcePath}");
                                pstUpdateStatus("PST 解析失败");
                                this.Invoke(new Action(() => {
                                    if (lblO365StatusPanel != null) lblO365StatusPanel.ForeColor = Color.Red;
                                }));
                            }
                        }
                        imported += pstImported;
                        pstAppendLog($"PST 导入完成: 文件={Path.GetFileName(pstSourcePath)}, 本次导入 {pstImported} 封");
                    }
                    else if (sourceTypeIndex == 0) // EML 面板 - EML 文件夹导入
                    {
                        Serilog.Log.Information("EML导入模式，源: {Source}", txtO365SourcePathPanel?.Text);
                        imported = 0;
                        if (_office365Service != null)
                        {
                            // 使用 ImportEmlWithGraph，它支持 Impersonation 和 Graph API
                            var targetEmail = _office365OAuthEmail ?? "";
                            var txtLog = panel?.Controls.Find("txtO365ImportLog", true).FirstOrDefault() as TextBox;
                            string sourceRoot = txtO365SourcePathPanel?.Text ?? "";
                            int fileCount = 0;

                            // 获取文件总数用于进度计算
                            var emlFiles = Directory.GetFiles(sourceRoot, "*.eml", SearchOption.AllDirectories);
                            fileCount = emlFiles.Length;

                            Action<string> appendLog = (msg) => {
                                if (txtLog != null)
                                {
                                    txtLog.Invoke(new Action(() => {
                                        txtLog.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\r\n");
                                    }));
                                }
                                // 同时写入主日志框 (_logTextBox) 和 SingleUserSYNCO365 日志文件
                                this.Invoke(new Action(() => Log(msg, "SingleUserSYNCO365")));
                            };

                            // 设置服务回调，使 ImportEmlWithGraph 内部的 PstImportLogger 消息也能显示到日志框
                            _office365Service.LogCallback = appendLog;

                            appendLog($"开始导入 {fileCount} 个 EML 文件到 {targetEmail}/{actualTargetFolder}");

                            // 直接走 ImportEmlFolder, 让它处理子目录层级 (target + "/" + relativeDir)
                            imported = _office365Service.ImportEmlFolder(sourceRoot, actualTargetFolder, progress);
                            appendLog($"导入完成: 成功 {imported}/{fileCount} 封");
                            Serilog.Log.Information("EML导入完成: {Count} 封", imported);
                        }
                        else
                        {
                            Serilog.Log.Warning("_office365Service 为空，无法导入EML");
                        }
                    }
                    else if (sourceTypeIndex == 2) // IMAP账户
                    {
                        var imapService = new ImapFetchService();
                        var imapEmail = "";
                        var imapPassword = "";

                        this.Invoke(new Action(() =>
                        {
                            imapEmail = txtO365ImapEmail?.Text ?? "";
                            imapPassword = txtO365ImapPassword?.Text ?? "";
                        }));

                        if (string.IsNullOrWhiteSpace(imapEmail))
                        {
                            this.Invoke(new Action(() =>
                            {
                                if (lblO365StatusPanel != null)
                                {
                                    lblO365StatusPanel.Text = "请填写IMAP邮箱信息";
                                    lblO365StatusPanel.ForeColor = Color.Red;
                                }
                            }));
                            return;
                        }

                        var tempDir = Path.Combine(Path.GetTempPath(), "O365Import_" + Guid.NewGuid());
                        Directory.CreateDirectory(tempDir);

                        bool fetchSuccess = await imapService.FetchEmailsToEmlAsync(
                            imapEmail,
                            imapPassword,
                            tempDir,
                            1000,
                            null,
                            new List<string>(),
                            null);

                        if (fetchSuccess)
                        {
                            imported = _office365Service.ImportEmlFolder(tempDir, actualTargetFolder, progress);
                            try { Directory.Delete(tempDir, true); } catch { }
                        }

                        this.Invoke(new Action(() =>
                        {
                            if (lblO365StatusPanel != null)
                                lblO365StatusPanel.Text = $"IMAP收取完成，共 {imported} 封邮件";
                        }));
                        return;
                    }

                    Serilog.Log.Information("导入完成，导入数量: {Count}", imported);

                    this.Invoke(new Action(() =>
                    {
                        if (lblO365StatusPanel != null)
                        {
                            lblO365StatusPanel.Text = $"导入完成! 共导入 {imported} 封邮件";
                            lblO365StatusPanel.ForeColor = Color.Green;
                        }
                        if (progressO365Panel != null) progressO365Panel.Value = 100;
                    }));
                }
                catch (Exception ex)
                {
                    Serilog.Log.Error(ex, "导入过程异常");
                    this.Invoke(new Action(() =>
                    {
                        if (lblO365StatusPanel != null)
                        {
                            lblO365StatusPanel.Text = $"导入失败: {ex.Message}";
                            lblO365StatusPanel.ForeColor = Color.Red;
                        }
                    }));
                }
                finally
                {
                    this.Invoke(new Action(() =>
                    {
                        isO365Importing = false;
                        if (btnO365ImportPanel != null) btnO365ImportPanel.Enabled = true;
                    }));
                }
            });
        }

        private async void LoadO365Folders(string email, string accessToken)
        {
            try
            {
                if (_office365Service == null) _office365Service = new Office365ImportService();

                // 使用 Graph API 列出文件夹 (OAuth access token 的 aud=graph.microsoft.com，EWS 无法使用)
                var folders = await Task.Run(() => _office365Service.ListGraphMailFolders(accessToken, email));

                cmbO365TargetFolder.Items.Clear();
                cmbO365TargetFolder.Items.AddRange(folders.ToArray());
                cmbO365TargetFolder.Text = "";

                lblO365Status.Text = "文件夹加载完成";
            }
            catch (Exception ex)
            {
                lblO365Status.Text = "加载文件夹失败: " + ex.Message;
                Serilog.Log.Error(ex, "加载O365文件夹失败");
            }
        }

        private async void LoadO365FoldersPassword(string email)
        {
            try
            {
                if (_office365Service == null) return;

                var serviceField = typeof(MailConverter.Office365ImportService).GetField("_service",
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                var service = serviceField?.GetValue(_office365Service) as Microsoft.Exchange.WebServices.Data.ExchangeService;

                if (service == null) return;

                var folderView = new Microsoft.Exchange.WebServices.Data.FolderView(100);
                folderView.Traversal = Microsoft.Exchange.WebServices.Data.FolderTraversal.Shallow;

                var result = service.FindFolders(Microsoft.Exchange.WebServices.Data.WellKnownFolderName.MsgFolderRoot, folderView).Result;

                var folders = new System.Collections.Generic.List<string>();
                folders.Add("Inbox");
                foreach (var folder in result)
                {
                    if (!folders.Contains(folder.DisplayName))
                        folders.Add(folder.DisplayName);
                }

                cmbO365TargetFolder.Items.Clear();
                cmbO365TargetFolder.Items.AddRange(folders.ToArray());
                cmbO365TargetFolder.Text = "";

                lblO365Status.Text = "文件夹加载完成";
            }
            catch (Exception ex)
            {
                lblO365Status.Text = "加载文件夹失败: " + ex.Message;
                Serilog.Log.Error(ex, "加载O365文件夹失败");
            }
        }

        // Exchange Online 百宝箱事件处理
        private void BtnOnlineConnect_Click(object sender, EventArgs e)
        {
            // 检查是否已登录
            if (_isExchangeOnlineLoggedIn && _exchangeOnlineService != null)
            {
                lblOnlineStatus.Text = $"已登录: {_exchangeOnlineCurrentAccount}";
                lblOnlineStatus.ForeColor = Color.Green;
                return;
            }

            // 查找账户信息
            var cmb = FindControl(this, "cmbPstAccounts") as ComboBox;
            var txtTenantId = FindControl(this, "txtTenantId") as TextBox;
            var txtClientId = FindControl(this, "txtClientId") as TextBox;
            var txtClientSecret = FindControl(this, "txtClientSecret") as TextBox;
            var lblLoginStatus = FindControl(this, "lblLoginStatus") as Label;

            if (cmb == null || cmb.SelectedItem == null || txtTenantId == null || txtClientId == null || txtClientSecret == null)
            {
                lblOnlineStatus.Text = "请选择账户";
                lblOnlineStatus.ForeColor = Color.Red;
                return;
            }

            if (string.IsNullOrWhiteSpace(txtTenantId.Text) || string.IsNullOrWhiteSpace(txtClientId.Text) || string.IsNullOrWhiteSpace(txtClientSecret.Text))
            {
                lblOnlineStatus.Text = "请填写完整账户信息";
                lblOnlineStatus.ForeColor = Color.Red;
                return;
            }

            try
            {
                var accountName = cmb.SelectedItem.ToString();
                _exchangeOnlineService = new Office365ImportService();

                if (_exchangeOnlineService.ConnectWithClientSecret(txtTenantId.Text, txtClientId.Text, txtClientSecret.Text, accountName))
                {
                    _isExchangeOnlineLoggedIn = true;
                    _exchangeOnlineCurrentAccount = accountName;
                    lblOnlineStatus.Text = $"已登录: {accountName}";
                    lblOnlineStatus.ForeColor = Color.Green;
                    if (lblLoginStatus != null)
                    {
                        lblLoginStatus.Text = $"已登录: {accountName}";
                        lblLoginStatus.ForeColor = Color.Green;
                    }
                }
                else
                {
                    lblOnlineStatus.Text = "登录失败";
                    lblOnlineStatus.ForeColor = Color.Red;
                }
            }
            catch (Exception ex)
            {
                lblOnlineStatus.Text = $"登录失败: {ex.Message}";
                lblOnlineStatus.ForeColor = Color.Red;
            }
        }

        private Control FindControl(Control parent, string name)
        {
            foreach (Control c in parent.Controls)
            {
                if (c.Name == name) return c;
                var child = FindControl(c, name);
                if (child != null) return child;
            }
            return null;
        }

        private void TabControl_SelectedIndexChanged(object sender, EventArgs e)
        {
            // 当切换到其他主Tab时，断开Exchange Online Session
            if (this.tabControl.SelectedTab != null)
            {
                var tabText = this.tabControl.SelectedTab.Text;
                if (tabText != "Exchange Online 百宝箱" && _isExchangeOnlineLoggedIn)
                {
                    // 断开Session
                    _isExchangeOnlineLoggedIn = false;
                    _exchangeOnlineService = null;
                    _exchangeOnlineCurrentAccount = null;
                    Serilog.Log.Information("已断开Exchange Online Session");
                }

                // 切换到Exchange Online 百宝箱时，刷新OAuth账户列表
                if (tabText == "Exchange Online 百宝箱")
                {
                    LoadSavedOAuthAccounts();
                }
            }
        }

        private void OnlineToolkitNestedTabControl_SelectedIndexChanged(object sender, EventArgs e)
        {
            // 子Tab切换时不断开Session，只在切换主Tab时断开
            // 但需要切换并显示对应的日志
            switch (_onlineToolkitNestedTabControl.SelectedIndex)
            {
                case 0: SwitchPstLog("O365Login"); break;
                case 1: SwitchPstLog("O365Account"); break;
                case 2: SwitchPstLog("O365Group"); break;
                case 3: SwitchPstLog("O365Mobile"); break;
                case 4: SwitchPstLog("O365Traffic"); break;
                case 5: SwitchPstLog("O365Migration"); break;
                case 6: SwitchPstLog("O365Whois"); break;
                case 7: SwitchPstLog("O365Dns"); break;
            }
        }

        private void BtnOnlineExecute_Click(object sender, EventArgs e)
        {
            if (!_isExchangeOnlineLoggedIn || _exchangeOnlineService == null)
            {
                lblOnlineStatus.Text = "请先登录";
                lblOnlineStatus.ForeColor = Color.Red;
                return;
            }

            lstOnlineResults.Items.Clear();
            lblOnlineStatus.Text = "执行中...";
            lblOnlineStatus.ForeColor = Color.Gray;

            Task.Run(() =>
            {
                try
                {
                    string tool = cmbOnlineTool.SelectedItem?.ToString() ?? "";
                    string targetEmail = txtOnlineTargetEmail.Text;

                    switch (tool)
                    {
                        case "邮箱统计":
                            // 使用Graph API获取邮箱统计
                            var mailboxStats = GetMailboxStatistics(targetEmail);
                            this.Invoke(new Action(() =>
                            {
                                lstOnlineResults.Items.Add($"邮箱: {targetEmail}");
                                lstOnlineResults.Items.Add($"总邮件数: {mailboxStats.TotalEmails}");
                                lstOnlineResults.Items.Add($"未读邮件: {mailboxStats.UnreadEmails}");
                            }));
                            break;

                        case "发送测试邮件":
                            // 使用EWS发送测试邮件
                            bool sent = _exchangeOnlineService.SendTestEmail(targetEmail, "测试邮件", "这是一封测试邮件");
                            this.Invoke(new Action(() => lstOnlineResults.Items.Add(sent ? "发送成功" : "发送失败")));
                            break;

                        default:
                            this.Invoke(new Action(() => lstOnlineResults.Items.Add("请选择工具")));
                            break;
                    }

                    this.Invoke(new Action(() => lblOnlineStatus.Text = "执行完成"));
                }
                catch (Exception ex)
                {
                    this.Invoke(new Action(() =>
                    {
                        lblOnlineStatus.Text = $"执行失败: {ex.Message}";
                        lblOnlineStatus.ForeColor = Color.Red;
                    }));
                }
            });
        }

        private class MailboxStatsResult
        {
            public int TotalEmails { get; set; }
            public int UnreadEmails { get; set; }
        }

        private MailboxStatsResult GetMailboxStatistics(string email)
        {
            try
            {
                // 使用EWS获取邮箱统计
                var service = _exchangeOnlineService.Service;
                service.ImpersonatedUserId = new Microsoft.Exchange.WebServices.Data.ImpersonatedUserId(
                    Microsoft.Exchange.WebServices.Data.ConnectingIdType.SmtpAddress, email);
                var inbox = Microsoft.Exchange.WebServices.Data.Folder.Bind(service, Microsoft.Exchange.WebServices.Data.WellKnownFolderName.Inbox).Result;
                return new MailboxStatsResult { TotalEmails = inbox.TotalCount, UnreadEmails = inbox.UnreadCount };
            }
            catch
            {
                return new MailboxStatsResult { TotalEmails = 0, UnreadEmails = 0 };
            }
        }

        // Exchange On-Premise Toolkit 事件处理
        private void BtnOnPremiseConnect_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrWhiteSpace(txtOnPremiseEmail.Text) || string.IsNullOrWhiteSpace(txtOnPremisePassword.Text))
            {
                lblOnPremiseStatus.Text = "请输入管理员邮箱和密码";
                lblOnPremiseStatus.ForeColor = Color.Red;
                return;
            }

            lblOnPremiseStatus.Text = "连接中...";
            lblOnPremiseStatus.ForeColor = Color.Gray;
            btnOnPremiseConnect.Enabled = false;

            Task.Run(() =>
            {
                try
                {
                    _onPremiseToolkitService = new ExchangeOnPremiseToolkitService();
                    bool success = OnPremiseToolkitService.Connect(
                        txtOnPremiseEmail.Text,
                        txtOnPremisePassword.Text,
                        txtOnPremiseServerUrl.Text,
                        txtOnPremiseDomain.Text);

                    this.Invoke(new Action(() =>
                    {
                        btnOnPremiseConnect.Enabled = true;
                        if (success)
                        {
                            lblOnPremiseStatus.Text = "连接成功!";
                            lblOnPremiseStatus.ForeColor = Color.Green;
                            // 加载统计信息
                            LoadOnPremiseStatistics();
                        }
                        else
                        {
                            lblOnPremiseStatus.Text = "连接失败，请检查凭据";
                            lblOnPremiseStatus.ForeColor = Color.Red;
                        }
                        // 读取并显示连接日志
                        try
                        {
                            var logPath = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "logs", "LocalExchangeServer", "connect.log");
                            if (System.IO.File.Exists(logPath))
                            {
                                var lines = System.IO.File.ReadAllLines(logPath);
                                var recentLines = lines.Length > 50 ? lines.Skip(lines.Length - 50) : lines;
                                foreach (var line in recentLines)
                                {
                                    _logTextBox.AppendText(line + Environment.NewLine);
                                }
                                _logTextBox.SelectionStart = _logTextBox.Text.Length;
                                _logTextBox.ScrollToCaret();
                            }
                        }
                        catch { }
                    }));
                }
                catch (Exception ex)
                {
                    this.Invoke(new Action(() =>
                    {
                        btnOnPremiseConnect.Enabled = true;
                        lblOnPremiseStatus.Text = $"连接失败: {ex.Message}";
                        lblOnPremiseStatus.ForeColor = Color.Red;
                    }));
                }
            });
        }

        /// <summary>
        /// 加载Exchange统计信息
        /// </summary>
        private void LoadOnPremiseStatistics()
        {
            if (_onPremiseToolkitService == null) return;

            Task.Run(() =>
            {
                try
                {
                    // 卡片1: 24小时内收到邮件
                    var receivedLast24h = OnPremiseToolkitService.SearchEmails(
                        DateTime.Now.AddHours(-24), null, null, null, true);
                    // 卡片2: 24小时内发送邮件
                    var sentLast24h = OnPremiseToolkitService.SearchEmails(
                        DateTime.Now.AddHours(-24), null, null, null, false);
                    // 卡片3: 全部收到邮件
                    var totalReceived = OnPremiseToolkitService.GetTotalMailCount(true);
                    // 卡片4: 全部发送邮件
                    var totalSent = OnPremiseToolkitService.GetTotalMailCount(false);
                    // 卡片5: 联系人数量
                    var contactCount = OnPremiseToolkitService.GetContactCount();

                    this.Invoke(new Action(() =>
                    {
                        if (_onPremiseStatCards != null && _onPremiseStatCards.Length >= 5)
                        {
                            _onPremiseStatCards[0].Text = receivedLast24h.ToString();
                            _onPremiseStatCards[1].Text = sentLast24h.ToString();
                            _onPremiseStatCards[2].Text = totalReceived.ToString();
                            _onPremiseStatCards[3].Text = totalSent.ToString();
                            _onPremiseStatCards[4].Text = contactCount.ToString();
                        }
                    }));
                }
                catch (Exception ex)
                {
                    this.Invoke(new Action(() =>
                    {
                        _logTextBox.AppendText($"[{DateTime.Now:HH:mm:ss}] 加载统计信息失败: {ex.Message}\n");
                    }));
                }
            });
        }

        /// <summary>
        /// 邮件搜索按钮点击事件
        /// </summary>
        private void BtnOnPremiseSearchExecute_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrWhiteSpace(txtOnPremiseEmail.Text) || string.IsNullOrWhiteSpace(txtOnPremisePassword.Text))
            {
                lblOnPremiseSearchStatus.Text = "请先在登录页输入管理员凭据";
                lblOnPremiseSearchStatus.ForeColor = Color.Red;
                return;
            }

            if (string.IsNullOrWhiteSpace(txtOnPremiseServerUrl.Text))
            {
                lblOnPremiseSearchStatus.Text = "请输入Exchange服务器地址";
                lblOnPremiseSearchStatus.ForeColor = Color.Red;
                return;
            }

            _currentSearchOffset = 0;
            lvOnPremiseSearchResults.Items.Clear();
            lblOnPremiseSearchStatus.Text = "搜索中... (通过PowerShell查询Exchange传输日志)";
            lblOnPremiseSearchStatus.ForeColor = Color.Gray;
            btnOnPremiseExportSelected.Enabled = false;

            Task.Run(() =>
            {
                try
                {
                    // 调用传输日志搜索
                    var results = OnPremiseToolkitService.SearchTransportLogs(
                        txtOnPremiseServerUrl.Text.Trim(),
                        txtOnPremiseEmail.Text.Trim(),
                        txtOnPremisePassword.Text.Trim(),
                        txtOnPremiseDomain.Text.Trim(),
                        dtpOnPremiseStartDate.Value,
                        dtpOnPremiseEndDate.Value,
                        txtOnPremiseSearchFrom.Text.Trim(),
                        txtOnPremiseSearchTo.Text.Trim(),
                        1000);

                    this.Invoke(new Action(() =>
                    {
                        lvOnPremiseSearchResults.Items.Clear();
                        foreach (var log in results)
                        {
                            var item = new ListViewItem(log.Status);
                            item.SubItems.Add(log.From);
                            item.SubItems.Add(log.To);
                            item.SubItems.Add(log.Subject ?? "");
                            item.SubItems.Add(log.Timestamp.ToString("yyyy-MM-dd HH:mm:ss"));
                            item.SubItems.Add(log.Source ?? "");
                            item.SubItems.Add(log.EventId ?? "");
                            item.Tag = log.MessageId;
                            lvOnPremiseSearchResults.Items.Add(item);
                        }

                        lblOnPremisePageInfo.Text = $"共找到 {results.Count} 条传输日志记录";
                        lblOnPremiseSearchStatus.Text = $"查询完成，找到 {results.Count} 条记录 (日志已保存到 logs/LocalExchangeServer/connect.log)";
                        lblOnPremiseSearchStatus.ForeColor = Color.Green;
                        btnOnPremiseExportSelected.Enabled = results.Count > 0;
                    }));
                }
                catch (Exception ex)
                {
                    this.Invoke(new Action(() =>
                    {
                        lblOnPremiseSearchStatus.Text = $"搜索失败: {ex.Message}";
                        lblOnPremiseSearchStatus.ForeColor = Color.Red;
                    }));
                    Serilog.Log.Error(ex, "传输日志搜索异常");
                }
            });
        }

        /// <summary>
        /// 导出选中的邮件
        /// </summary>
        private void BtnOnPremiseExportSelected_Click(object sender, EventArgs e)
        {
            if (lvOnPremiseSearchResults.SelectedItems.Count == 0)
            {
                MessageBox.Show("请先选择要导出的邮件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            using (var dialog = new FolderBrowserDialog { Description = "选择导出文件夹" })
            {
                if (dialog.ShowDialog() != DialogResult.OK) return;

                lblOnPremiseSearchStatus.Text = "导出中...";
                lblOnPremiseSearchStatus.ForeColor = Color.Gray;

                Task.Run(() =>
                {
                    try
                    {
                        int exported = 0;
                        foreach (ListViewItem item in lvOnPremiseSearchResults.SelectedItems)
                        {
                            string itemId = item.Tag?.ToString();
                            if (string.IsNullOrEmpty(itemId)) continue;

                            string mimeContent = OnPremiseToolkitService.GetMimeContent(itemId);
                            if (!string.IsNullOrEmpty(mimeContent))
                            {
                                string fileName = $"{item.SubItems[2].Text}_{item.SubItems[3].Text.Replace(":", "-").Replace(" ", "_")}.eml";
                                string filePath = System.IO.Path.Combine(dialog.SelectedPath, SanitizeFileName(fileName));
                                System.IO.File.WriteAllBytes(filePath, System.Text.Encoding.UTF8.GetBytes(mimeContent));
                                exported++;
                            }
                        }

                        this.Invoke(new Action(() =>
                        {
                            lblOnPremiseSearchStatus.Text = $"导出完成，已导出 {exported} 封邮件";
                            lblOnPremiseSearchStatus.ForeColor = Color.Green;
                            MessageBox.Show($"导出完成，共 {exported} 封邮件", "成功", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }));
                    }
                    catch (Exception ex)
                    {
                        this.Invoke(new Action(() =>
                        {
                            lblOnPremiseSearchStatus.Text = $"导出失败: {ex.Message}";
                            lblOnPremiseSearchStatus.ForeColor = Color.Red;
                        }));
                    }
                });
            }
        }

        /// <summary>
        /// 双击查看邮件详情
        /// </summary>
