        /// <summary>
        /// 格式化文件大小
        /// </summary>
        private string FormatFileSize(int bytes)
        {
            if (bytes < 1024) return bytes + " B";
            if (bytes < 1024 * 1024) return (bytes / 1024.0).ToString("F1") + " KB";
            return (bytes / (1024.0 * 1024.0)).ToString("F1") + " MB";
        }

        private void BtnImapEwsFile_Click(object sender, EventArgs e)
        {
            using (var dialog = new OpenFileDialog())
            {
                dialog.Filter = "Excel/CSV文件|*.xlsx;*.xls;*.csv";
                dialog.Title = "选择账户配置文件";

                if (dialog.ShowDialog() == DialogResult.OK)
                {
                    txtImapEwsFile.Text = dialog.FileName;
                    LoadImapEwsAccounts(dialog.FileName);
                }
            }
        }

        private void LoadImapEwsAccounts(string filePath)
        {
            lstImapEwsAccounts.Items.Clear();

            try
            {
                string ext = Path.GetExtension(filePath).ToLower();
                var accounts = new List<ImapToEwsAccount>();

                if (ext == ".xlsx" || ext == ".xls")
                    accounts = LoadImapEwsFromExcel(filePath);
                else
                    accounts = LoadImapEwsFromCsv(filePath);

                foreach (var account in accounts)
                {
                    lstImapEwsAccounts.Items.Add($"{account.ImapEmail} -> {account.EwsEmail}");
                }

                lblImapEwsStatus.Text = $"已加载 {accounts.Count} 个账户";
            }
            catch (Exception ex)
            {
                MessageBox.Show("加载账户失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private List<ImapToEwsAccount> LoadImapEwsFromExcel(string filePath)
        {
            var accounts = new List<ImapToEwsAccount>();

            using (var workbook = new ClosedXML.Excel.XLWorkbook(filePath))
            {
                var worksheet = workbook.Worksheets.First();
                var headerRow = worksheet.Row(1);
                var headers = new List<string>();
                foreach (var cell in headerRow.CellsUsed())
                {
                    headers.Add(cell.GetValue<string>().Trim().ToLower());
                }

                // 找列索引
                int imapEmailIdx = FindColumn(headers, new[] { "imapemail", "imap_email", "邮箱" });
                int imapPwdIdx = FindColumn(headers, new[] { "imappassword", "imap_password", "imapwd", "密码" });
                int imapHostIdx = FindColumn(headers, new[] { "imaphost", "imap_host", "imap服务器" });
                int ewsEmailIdx = FindColumn(headers, new[] { "ewsemail", "ews_email", "目标邮箱" });
                int ewsPwdIdx = FindColumn(headers, new[] { "ewspassword", "ews_password", "目标密码" });
                int ewsUrlIdx = FindColumn(headers, new[] { "ewsserverurl", "ews_server_url", "服务器" });
                int targetFolderIdx = FindColumn(headers, new[] { "targetfolder", "target_folder", "目标文件夹", "目标目录" });

                if (imapEmailIdx < 0 || imapPwdIdx < 0 || ewsEmailIdx < 0 || ewsPwdIdx < 0)
                    throw new Exception("必须包含ImapEmail, ImapPassword, EwsEmail, EwsPassword列");

                var rows = worksheet.RowsUsed().Skip(1);
                foreach (var row in rows)
                {
                    var imapEmail = row.Cell(imapEmailIdx + 1).GetValue<string>().Trim();
                    var imapPwd = row.Cell(imapPwdIdx + 1).GetValue<string>().Trim();
                    var ewsEmail = row.Cell(ewsEmailIdx + 1).GetValue<string>().Trim();
                    var ewsPwd = row.Cell(ewsPwdIdx + 1).GetValue<string>().Trim();

                    if (!string.IsNullOrWhiteSpace(imapEmail) && !string.IsNullOrWhiteSpace(ewsEmail))
                    {
                        accounts.Add(new ImapToEwsAccount
                        {
                            ImapEmail = imapEmail,
                            ImapPassword = imapPwd,
                            ImapHost = imapHostIdx >= 0 ? row.Cell(imapHostIdx + 1).GetValue<string>().Trim() : "",
                            EwsEmail = ewsEmail,
                            EwsPassword = ewsPwd,
                            EwsServerUrl = ewsUrlIdx >= 0 ? row.Cell(ewsUrlIdx + 1).GetValue<string>().Trim() : "auto",
                            TargetFolder = targetFolderIdx >= 0 ? row.Cell(targetFolderIdx + 1).GetValue<string>().Trim() : ""
                        });
                    }
                }
            }

            return accounts;
        }

        private List<ImapToEwsAccount> LoadImapEwsFromCsv(string filePath)
        {
            var accounts = new List<ImapToEwsAccount>();

            using (var reader = new System.IO.StreamReader(filePath, System.Text.Encoding.UTF8))
            {
                var config = new CsvHelper.Configuration.CsvConfiguration(System.Globalization.CultureInfo.InvariantCulture)
                {
                    HasHeaderRecord = true,
                    MissingFieldFound = null
                };

                using (var csv = new CsvHelper.CsvReader(reader, config))
                {
                    csv.Read();
                    csv.ReadHeader();
                    var headers = csv.HeaderRecord;

                    int imapEmailIdx = FindColumn(headers, new[] { "imapemail", "imap_email", "邮箱" });
                    int imapPwdIdx = FindColumn(headers, new[] { "imappassword", "imap_password", "密码" });
                    int ewsEmailIdx = FindColumn(headers, new[] { "ewsemail", "ews_email", "目标邮箱" });
                    int ewsPwdIdx = FindColumn(headers, new[] { "ewspassword", "ews_password", "目标密码" });
                    int ewsUrlIdx = FindColumn(headers, new[] { "ewsserverurl", "服务器" });
                    int targetFolderIdx = FindColumn(headers, new[] { "targetfolder", "目标文件夹" });

                    while (csv.Read())
                    {
                        var imapEmail = csv.GetField(imapEmailIdx)?.Trim() ?? "";
                        var ewsEmail = csv.GetField(ewsEmailIdx)?.Trim() ?? "";

                        if (!string.IsNullOrWhiteSpace(imapEmail) && !string.IsNullOrWhiteSpace(ewsEmail))
                        {
                            accounts.Add(new ImapToEwsAccount
                            {
                                ImapEmail = imapEmail,
                                ImapPassword = csv.GetField(imapPwdIdx)?.Trim() ?? "",
                                EwsEmail = ewsEmail,
                                EwsPassword = csv.GetField(ewsPwdIdx)?.Trim() ?? "",
                                EwsServerUrl = ewsUrlIdx >= 0 && csv.GetField(ewsUrlIdx) != null ? csv.GetField(ewsUrlIdx).Trim() : "auto",
                                TargetFolder = targetFolderIdx >= 0 && csv.GetField(targetFolderIdx) != null ? csv.GetField(targetFolderIdx).Trim() : ""
                            });
                        }
                    }
                }
            }

            return accounts;
        }

        private int FindColumn<T>(T headers, string[] possibleNames) where T : IEnumerable<string>
        {
            int idx = 0;
            foreach (var header in headers)
            {
                foreach (var name in possibleNames)
                {
                    if (header.Contains(name))
                        return idx;
                }
                idx++;
            }
            return -1;
        }

        private async void BtnImapEwsSyncStart_Click(object sender, EventArgs e)
        {
            if (lstImapEwsAccounts.Items.Count == 0)
            {
                MessageBox.Show("请先加载账户文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (isImapEwsSyncing) return;

            isImapEwsSyncing = true;
            btnImapEwsSyncStart.Enabled = false;
            btnImapEwsSyncStart.Text = "同步中...";
            lblStatus.Text = "正在同步到EWS...";
            _statusProgressBar.Minimum = 0;
            _statusProgressBar.Maximum = lstImapEwsAccounts.Items.Count;
            _statusProgressBar.Value = 0;

            try
            {
                string ext = Path.GetExtension(txtImapEwsFile.Text).ToLower();
                List<ImapToEwsAccount> accounts;

                if (ext == ".xlsx" || ext == ".xls")
                    accounts = LoadImapEwsFromExcel(txtImapEwsFile.Text);
                else
                    accounts = LoadImapEwsFromCsv(txtImapEwsFile.Text);

                _imapEwsService = new ImapToEwsService();
                _imapEwsService.SetCallbacks(
                    msg => this.Invoke(new Action(() => {
                        lblImapEwsStatus.Text = msg;
                        Log("[ImapEws] " + msg);
                    })),
                    (completed, total, email) => this.Invoke(new Action(() => {
                        _statusProgressBar.Value = completed;
                        lblStatus.Text = $"同步进度: {completed}/{total} - {email}";
                    }))
                );

                await Task.Run(() => _imapEwsService.SyncAccountsAsync(
                    accounts,
                    (int)numImapEwsParallel.Value,
                    (int)numImapEwsMaxPer.Value
                ));

                lblStatus.Text = "同步完成!";
                _statusProgressBar.Value = _statusProgressBar.Maximum;
                MessageBox.Show("全部账户同步到EWS完成！", "成功", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                lblStatus.Text = "同步失败: " + ex.Message;
                MessageBox.Show("同步失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Log("[ImapEws ERROR] " + ex.Message);
            }
            finally
            {
                isImapEwsSyncing = false;
                btnImapEwsSyncStart.Enabled = true;
                btnImapEwsSyncStart.Text = "开始同步";
            }
        }

