        private async void BtnImapTest_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrEmpty(txtImapEmail.Text))
            {
                MessageBox.Show("请输入邮箱地址", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtImapPassword.Text))
            {
                MessageBox.Show("请输入密码或授权码", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            btnImapTest.Enabled = false;
            lblImapStatus.Text = "正在测试连接...";
            lblImapStatus.ForeColor = Color.Blue;

            try
            {
                var autoDiscover = new AutoDiscoverService();

                string host = txtImapHost.Text;
                int port = (int)numImapPort.Value;
                bool useSsl = chkImapSsl.Checked;

                // 如果填写了自动发现，使用自动发现
                if (string.IsNullOrEmpty(host) || host == "自动发现")
                {
                    lblImapStatus.Text = "正在自动发现IMAP服务器...";
                    var config = await autoDiscover.AutoDiscoverAsync(txtImapEmail.Text, txtImapPassword.Text);
                    host = config.Host;
                    port = config.Port;
                    useSsl = config.UseSsl;

                    txtImapHost.Text = host;
                    numImapPort.Value = port;
                    chkImapSsl.Checked = useSsl;
                }

                var result = await autoDiscover.TestConnectionAsync(host, port, useSsl, txtImapEmail.Text, txtImapPassword.Text);

                if (result.Success)
                {
                    lblImapStatus.Text = result.Message;
                    lblImapStatus.ForeColor = Color.Green;
                }
                else
                {
                    lblImapStatus.Text = result.Message;
                    lblImapStatus.ForeColor = Color.Red;
                }
            }
            catch (Exception ex)
            {
                lblImapStatus.Text = "测试失败: " + ex.Message;
                lblImapStatus.ForeColor = Color.Red;
            }
            finally
            {
                btnImapTest.Enabled = true;
            }
        }

