        private async Task BtnYearStats_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrEmpty(txtImapEmlEmail.Text) || string.IsNullOrEmpty(txtImapEmlPassword.Text))
            {
                MessageBox.Show("请先输入邮箱和密码", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                Log("正在获取邮件年度统计...");

                // 如果没有加载文件夹，先加载
                if (lstImapFolders.Items.Count == 0)
                {
                    await LoadImapEmlFoldersAsync();
                }

                if (lstImapFolders.Items.Count == 0)
                {
                    MessageBox.Show("未能获取到文件夹，请检查邮箱配置", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                // 获取选中的文件夹
                var selectedFolders = new List<string>();
                foreach (var item in lstImapFolders.CheckedItems)
                {
                    selectedFolders.Add(item.ToString());
                }

                if (selectedFolders.Count == 0)
                {
                    MessageBox.Show("请至少选择一个文件夹", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                var service = new ImapFetchService();
                // 显示年度统计对话框
                var stats = await service.GetYearlyStatsAsync(txtImapEmlEmail.Text, txtImapEmlPassword.Text, selectedFolders);

                var result = "邮件年度统计\n\n";
                foreach (var kvp in stats.OrderByDescending(x => x.Key))
                {
                    result += $"{kvp.Key}年: {kvp.Value} 封\n";
                }
                result += $"\n总计: {stats.Values.Sum()} 封";

                MessageBox.Show(result, "年度统计", MessageBoxButtons.OK, MessageBoxIcon.Information);
                Log("年度统计完成");
            }
            catch (Exception ex)
            {
                MessageBox.Show("统计失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Log("年度统计失败: " + ex.Message);
            }
        }

        private async void BtnImapEmlFetch_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrEmpty(txtImapEmlEmail.Text))
            {
                MessageBox.Show("请输入邮箱地址", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtImapEmlPassword.Text))
            {
                MessageBox.Show("请输入密码或授权码", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtImapEmlOutputDir.Text))
            {
                MessageBox.Show("请选择输出目录", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (isImapEmlFetching) return;

            // 检查导出格式
            bool isMsgFormat = radImapMsgFormat != null && radImapMsgFormat.Checked;

            isImapEmlFetching = true;
            btnImapEmlFetch.Enabled = false;
            btnImapEmlFetch.Text = "导出中...";
            lblStatus.Text = "正在从IMAP服务器导出邮件...";
            UpdateStatusProgress(0, (int)numImapEmlMaxEmails.Value, "正在导出: 0/" + numImapEmlMaxEmails.Value);

            try
            {
                if (isMsgFormat)
                {
                    // 使用Python脚本导出MSG
                    var exeDir = AppDomain.CurrentDomain.BaseDirectory;
                    var pythonScript = Path.Combine(exeDir, "script", "imap_to_msg.py");

                    if (!File.Exists(pythonScript))
                    {
                        throw new Exception("Python脚本不存在: " + pythonScript);
                    }

                    var outputPath = txtImapEmlOutputDir.Text;
                    var maxEmails = (int)numImapEmlMaxEmails.Value;

                    // 获取选中的文件夹
                    var selectedFolders = new List<string>();
                    foreach (var item in lstImapEmlFolders.CheckedItems)
                    {
                        selectedFolders.Add(item.ToString());
                    }
                    var folderArg = selectedFolders.Count > 0 ? string.Join(",", selectedFolders) : "";

                    var threadCount = (int)numImapThreads.Value;
                    var args = $"\"{pythonScript}\" \"{txtImapEmlEmail.Text}\" \"{txtImapEmlPassword.Text}\" \"{outputPath}\" {maxEmails} {threadCount} {folderArg}";

                    Log("[IMAP->MSG] 执行: python " + args, null, "imap2eml");

                    var pythonExe = Program.GetPythonExecutable();
                    if (string.IsNullOrEmpty(pythonExe))
                    {
                        throw new Exception("Python环境未找到，请重新安装程序");
                    }

                    var startInfo = Program.CreatePythonStartInfo(pythonExe, args);

                    using (var process = System.Diagnostics.Process.Start(startInfo))
                    {
                        if (process != null)
                        {
                            // 异步读取输出和错误，避免死锁
                            var outputTask = System.Threading.Tasks.Task.Run(() => process.StandardOutput.ReadToEndAsync());
                            var errorTask = System.Threading.Tasks.Task.Run(() => process.StandardError.ReadToEndAsync());

                            // 等待进程结束
                            var completed = process.WaitForExit(600000); // 10分钟超时

                            if (!completed)
                            {
                                process.Kill();
                                Log("[IMAP->MSG] 进程超时被终止", null, "imap2eml");
                            }

                            var output = outputTask.Result;
                            var error = errorTask.Result;

                            Log("[IMAP->MSG] 输出: " + output, null, "imap2eml");
                            if (!string.IsNullOrEmpty(error))
                                Log("[IMAP->MSG] 错误: " + error, null, "imap2eml");

                            lblImapEmlStatus.Text = output;
                        }
                    }
                }
                else
                {
                    // 使用C#服务导出EML
                    var service = new ImapFetchService();
                    service.SetCallbacks(
                        msg => this.Invoke(new Action(() => {
                            lblImapEmlStatus.Text = msg;
                            Log("[IMAP->EML] " + msg, null, "imap2eml");
                        })),
                        (current, total) => this.Invoke(new Action(() => {
                            UpdateStatusProgress(current, total, $"正在导出: {current}/{total}");
                        }))
                    );

                    // 获取选中的文件夹
                    var selectedFolders = new List<string>();
                    foreach (var item in lstImapEmlFolders.CheckedItems)
                    {
                        selectedFolders.Add(item.ToString());
                    }

                    // 计算年份区间（提供默认值以防控件未初始化）
                    int startYear = numStartYear != null ? (int)numStartYear.Value : 2010;
                    int endYear = numEndYear != null ? (int)numEndYear.Value : DateTime.Now.Year;
                    var startDate = new DateTime(startYear, 1, 1);
                    var endDate = new DateTime(endYear, 12, 31, 23, 59, 59);

                    // 如果勾选了下载最近N天，则覆盖startDate
                    if (chkImapFetchDaysLimit != null && chkImapFetchDaysLimit.Checked && numImapFetchDaysBack != null)
                    {
                        int daysBack = (int)numImapFetchDaysBack.Value;
                        if (daysBack > 0)
                        {
                            startDate = DateTime.Now.AddDays(-daysBack);
                            Log($"将收取最近 {daysBack} 天的邮件 (从 {startDate:yyyy-MM-dd} 至今)...", null, "imap2eml");
                        }
                    }
                    else
                    {
                        Log($"将收取 {startYear} 年到 {endYear} 年的邮件...", null, "imap2eml");
                    }

                    await Task.Run(() => service.FetchEmailsToEmlAsync(
                        txtImapEmlEmail.Text,
                        txtImapEmlPassword.Text,
                        txtImapEmlOutputDir.Text,
                        (int)numImapEmlMaxEmails.Value,
                        startDate,
                        selectedFolders.Count > 0 ? selectedFolders : null,
                        endDate
                    ));
                }

                lblStatus.Text = "导出完成!";
                UpdateStatusProgress((int)numImapEmlMaxEmails.Value, (int)numImapEmlMaxEmails.Value, "导出完成!");
                MessageBox.Show("导出完成！", "成功", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                lblStatus.Text = "导出失败: " + ex.Message;
                HideStatusProgress();
                MessageBox.Show("导出失败: " + ex.Message, "错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Log("[IMAP->导出 ERROR] " + ex.Message, null, "imap2eml");
            }
            finally
            {
                isImapEmlFetching = false;
                btnImapEmlFetch.Enabled = true;
                btnImapEmlFetch.Text = "开始导出";
            }
        }

        private async void BtnImapFetch_Click(object sender, EventArgs e)
        {
            var dbgPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs", "debug.txt");
            File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] ENTERED\n");
            File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] isImapFetching={isImapFetching}\n");

            if (string.IsNullOrEmpty(txtImapEmail.Text))
            {
                MessageBox.Show("请输入邮箱地址", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtImapPassword.Text))
            {
                MessageBox.Show("请输入密码或授权码", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtImapOutputDir.Text))
            {
                MessageBox.Show("请选择输出目录", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (string.IsNullOrEmpty(txtImapFileName.Text))
            {
                MessageBox.Show("请输入文件名", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            string outputPath = Path.Combine(txtImapOutputDir.Text, txtImapFileName.Text);
            if (!outputPath.EndsWith(".pst", StringComparison.OrdinalIgnoreCase))
            {
                outputPath += ".pst";
            }

            if (isImapFetching) return;

            File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] creating service...\n");

            isImapFetching = true;
            btnImapFetch.Enabled = false;
            btnImapFetch.Text = "收件中...";
            lblStatus.Text = "正在从IMAP服务器收件...";
            UpdateStatusProgress(0, (int)numImapMaxEmails.Value, "正在收件: 0/" + numImapMaxEmails.Value);

            try
            {
                var service = new ImapFetchService();
                File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] service created\n");

                service.SetCallbacks(
                    msg => this.Invoke(new Action(() => {
                        lblImapStatus.Text = msg;
                        Log("[IMAP] " + msg, "IMAP2PST");
                    })),
                    (current, total) => this.Invoke(new Action(() => {
                        UpdateStatusProgress(current, total, $"正在收件: {current}/{total}");
                    }))
                );

                File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] callbacks set\n");

                var selectedFolders = new List<string>();
                foreach (var item in lstImapFolders.CheckedItems)
                {
                    selectedFolders.Add(item.ToString());
                }

                // 计算年份区间（提供默认值以防控件未初始化）
                int startYear = numStartYear != null ? (int)numStartYear.Value : 2010;
                int endYear = numEndYear != null ? (int)numEndYear.Value : DateTime.Now.Year;
                var startDate = new DateTime(startYear, 1, 1);
                var endDate = new DateTime(endYear, 12, 31, 23, 59, 59);

                File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] folders={selectedFolders.Count}, years={startYear}-{endYear}\n");

                // 如果勾选了下载最近N天，则覆盖startDate
                bool useDaysLimit = chkImapFetchDaysLimit != null && chkImapFetchDaysLimit.Checked && numImapFetchDaysBack != null && numImapFetchDaysBack.Value > 0;
                File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] useDaysLimit={useDaysLimit}, daysBack={numImapFetchDaysBack?.Value}\n");

                if (useDaysLimit)
                {
                    int daysBack = (int)numImapFetchDaysBack.Value;
                    startDate = DateTime.Now.AddDays(-daysBack);
                    Log($"将收取最近 {daysBack} 天的邮件 (从 {startDate:yyyy-MM-dd} 至今)...", "IMAP2PST");
                }
                else
                {
                    Log($"将收取 {startYear} 年到 {endYear} 年的邮件...", "IMAP2PST");
                }
                File.AppendAllText(dbgPath, $"[{DateTime.Now:HH:mm:ss.fff}] calling service.FetchEmailsToPstAsync...\n");

                await service.FetchEmailsToPstAsync(
                    txtImapEmail.Text,
                    txtImapPassword.Text,
                    outputPath,
                    (int)numImapMaxEmails.Value,
                    startDate,
                    selectedFolders.Count > 0 ? selectedFolders : null,
                    CancellationToken.None,
                    (int)(numBatchSize?.Value ?? 100),
                    endDate
                );

                lblStatus.Text = "收件完成!";
                UpdateStatusProgress((int)numImapMaxEmails.Value, (int)numImapMaxEmails.Value, "收件完成!");
