        private void ExtractEmails()
        {
            try
            {
                string sourcePath = txtExtractSourcePath.Text;
                string outputDir = txtExtractOutputDir.Text;

                // 判断方案选择
                bool useWsl = cmbExtractMethod != null && cmbExtractMethod.SelectedIndex == 1;
                bool isMsgFormat = cmbExtractFormat != null && cmbExtractFormat.SelectedIndex == 1;

                string methodName = useWsl ? "WSL" : "Outlook";
                string formatName = isMsgFormat ? "MSG" : "EML";

                if (useWsl)
                {
                    // WSL方案
                    Log($"Starting WSL extraction -> {outputDir}", null, "extract");
                    UpdateStatus("正在通过WSL提取邮件...");

                    var exeDir = AppDomain.CurrentDomain.BaseDirectory;
                    var pythonScript = Path.Combine(exeDir, "script", "extract_pst_wsl.py");

                    if (!File.Exists(pythonScript))
                    {
                        throw new Exception("Python脚本不存在: " + pythonScript);
                    }

                    var args = $"\"{pythonScript}\" \"{sourcePath}\" \"{outputDir}\"";

                    var pythonExe = Program.GetPythonExecutable();
                    if (string.IsNullOrEmpty(pythonExe))
                    {
                        throw new Exception("Python环境未找到，请重新安装程序");
                    }

                    var startInfo = Program.CreatePythonStartInfo(pythonExe, args);

                    using (var process = System.Diagnostics.Process.Start(startInfo))
                    {
                        if (process != null)
                        {
                            process.WaitForExit(600000); // 10分钟超时

                            var output = process.StandardOutput.ReadToEnd();
                            var error = process.StandardError.ReadToEnd();

                            Log("WSL输出: " + output, null, "extract");
                            if (!string.IsNullOrEmpty(error))
                                Log("WSL错误: " + error, null, "extract");

                            UpdateStatus("WSL提取完成!");
                        }
                    }
                }
                else
                {
                    // Outlook方案
                    Log($"Starting email extraction ({formatName}) -> {outputDir}", null, "extract");
                    UpdateStatus($"正在提取{formatName}邮件...");

                    if (!isMsgFormat)
                    {
                        // 使用C#提取EML
                        try
                        {
                            var pstService = new PstExtractService();
                            var progress = new Progress<int>(count =>
                            {
                                UpdateStatus($"正在提取邮件... 已处理 {count} 封");
                            });

                            bool success = pstService.ExtractToEml(sourcePath, outputDir, progress);
                            if (success)
                            {
                                UpdateStatus("提取完成!");
                            }
                            else
                            {
                                throw new Exception("C#提取失败");
                            }
                        }
                        catch (Exception ex)
                        {
                            Log($"C# extraction failed, falling back to Python: {ex.Message}", null, "extract");
                            // 如果C#失败，回退到Python
                            ExtractWithPython(sourcePath, outputDir, false);
                        }
                    }
                    else
                    {
                        // MSG格式使用Python
                        ExtractWithPython(sourcePath, outputDir, true);
                    }
                }
            }
            catch (Exception ex)
            {
                Log($"Extraction failed: {ex.Message}", null, "extract");
                throw;
            }
        }

        private void ExtractWithPython(string sourcePath, string outputDir, bool isMsgFormat)
        {
            var exeDir = AppDomain.CurrentDomain.BaseDirectory;
            var pythonScript = isMsgFormat
                ? Path.Combine(exeDir, "script", "extract_emails_to_msg.py")
                : Path.Combine(exeDir, "script", "extract_emails.py");

            if (!File.Exists(pythonScript))
            {
                throw new Exception("Python脚本不存在: " + pythonScript);
            }

            var args = $"\"{pythonScript}\" \"{outputDir}\"";
            if (!string.IsNullOrEmpty(sourcePath))
            {
                args += $" \"{sourcePath}\"";
            }

            var pythonExe = Program.GetPythonExecutable();
            if (string.IsNullOrEmpty(pythonExe))
            {
                throw new Exception("Python环境未找到，请重新安装程序");
            }

            var startInfo = Program.CreatePythonStartInfo(pythonExe, args);

            using (var process = System.Diagnostics.Process.Start(startInfo))
            {
                if (process != null)
                {
                    process.WaitForExit(600000); // 10分钟超时

                    var output = process.StandardOutput.ReadToEnd();
                    var error = process.StandardError.ReadToEnd();

                    Log("Extract Python output: " + output, null, "extract");
                    if (!string.IsNullOrEmpty(error))
                        Log("Extract Python error: " + error, null, "extract");

                    UpdateStatus("提取完成!");
                }
            }
        }

