        private void ConvertEmlToPst()
        {
            try
            {
                Log($"Starting conversion: {txtSourceDir.Text} -> {_outputPath}", "EML2PST");
                UpdateStatus($"找到文件...");

                // 获取EML文件
                var emlFiles = GetEmlFiles(txtSourceDir.Text, chkRecursive.Checked);
                int total = emlFiles.Count;

                if (total == 0)
                {
                    UpdateStatus("未找到EML文件");
                    MessageBox.Show("未找到EML文件", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                UpdateStatus($"找到 {total} 个EML文件，使用Python转换...");

                // 使用Python脚本创建PST并写入邮件
                var exeDir = AppDomain.CurrentDomain.BaseDirectory;
                var pythonScript = Path.Combine(exeDir, "script", "create_pst.py");

                Log("Python脚本路径: " + pythonScript, "EML2PST");
                Log("Python路径: " + Program.GetPythonExecutable(), "EML2PST");

                if (!File.Exists(pythonScript))
                {
                    throw new Exception("Python脚本不存在: " + pythonScript);
                }

                var pythonExe = Program.GetPythonExecutable();
                if (string.IsNullOrEmpty(pythonExe))
                {
                    throw new Exception("Python环境未找到，请重新安装程序");
                }

                Log("Python路径: " + pythonExe, "EML2PST");

                var startInfo = Program.CreatePythonStartInfo(pythonExe, $"\"{pythonScript}\" \"{_outputPath}\" \"{txtSourceDir.Text}\"");

                using (var process = System.Diagnostics.Process.Start(startInfo))
                {
                    if (process != null)
                    {
                        // 设置较长的超时时间
                        process.WaitForExit(300000); // 5分钟超时

                        var output = process.StandardOutput.ReadToEnd();
                        var error = process.StandardError.ReadToEnd();

                        Log("Python output: " + output, "EML2PST");
                        if (!string.IsNullOrEmpty(error))
                            Log("Python error: " + error, "EML2PST");

                        if (File.Exists(_outputPath))
                        {
                            var fileInfo = new FileInfo(_outputPath);
                            Log($"PST file created: {_outputPath}, Size: {fileInfo.Length} bytes", "EML2PST");
                            UpdateStatus($"转换完成! PST文件大小: {fileInfo.Length / 1024} KB");
                        }
                        else
                        {
                            Log("PST file was not created!", "EML2PST");
                            UpdateStatus("转换失败: PST文件未创建");
                        }
                    }
                }

                Log($"Conversion completed: {total} emails processed", "EML2PST");
            }
            catch (Exception ex)
            {
                Log($"Conversion failed: {ex.Message}", "EML2PST");
                UpdateStatus($"转换失败: {ex.Message}");
                throw;
            }
        }

        private List<string> GetEmlFiles(string directory, bool recursive)
        {
            var files = new List<string>();
            var searchOption = recursive ? SearchOption.AllDirectories : SearchOption.TopDirectoryOnly;

            if (Directory.Exists(directory))
            {
                files.AddRange(Directory.GetFiles(directory, "*.eml", searchOption));
                files.AddRange(Directory.GetFiles(directory, "*.EML", searchOption));
            }

            return files;
        }

        private MailItem ParseEmlFile(string filePath)
        {
            var message = MimeMessage.Load(filePath);
            var mailItem = new MailItem
            {
                MessageId = message.MessageId ?? "",
                Subject = message.Subject ?? "",
                SentDate = message.Date.DateTime,
                ReceivedDate = message.Date.DateTime,
                From = message.From != null ? message.From.ToString() : "",
                BodyText = message.TextBody ?? "",
                BodyHtml = message.HtmlBody ?? "",
                IsRead = true
            };

            if (message.To != null)
                foreach (var to in message.To)
                    mailItem.To.Add(to.ToString());

            if (message.Cc != null)
                foreach (var cc in message.Cc)
                    mailItem.Cc.Add(cc.ToString());

            if (message.Bcc != null)
                foreach (var bcc in message.Bcc)
                    mailItem.Bcc.Add(bcc.ToString());

            foreach (var attachment in message.Attachments)
            {
                mailItem.Attachments.Add(ConvertAttachment(attachment));
            }

            return mailItem;
        }

        private MailAttachment ConvertAttachment(MimeEntity entity)
        {
            var attachment = new MailAttachment
            {
                FileName = entity.ContentDisposition != null ? entity.ContentDisposition.FileName ?? "attachment" : "attachment",
                ContentType = entity.ContentType.MimeType
            };

            if (entity is MimePart mimePart)
            {
                using (var stream = new MemoryStream())
                {
                    mimePart.Content.DecodeTo(stream);
                    attachment.Content = stream.ToArray();
                    attachment.Size = attachment.Content.Length;
                }
            }

            return attachment;
        }

        private void UpdateStatus(string text)
        {
            this.Invoke(new Action(() => lblStatus.Text = text));
