        private void SetProgress(int value)
        {
            this.Invoke(new Action(() => {
                if (_statusProgressBar.Maximum > 0 && value <= _statusProgressBar.Maximum)
                    _statusProgressBar.Value = value;
            }));
        }

        private void SetProgressMax(int max)
        {
            this.Invoke(new Action(() => {
                _statusProgressBar.Minimum = 0;
                _statusProgressBar.Maximum = max > 0 ? max : 100;
            }));
        }

        private string GetRelativePath(string basePath, string fullPath)
        {
            if (string.IsNullOrEmpty(basePath) || string.IsNullOrEmpty(fullPath))
                return ".";

            basePath = basePath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            fullPath = fullPath.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);

            if (fullPath.StartsWith(basePath, StringComparison.OrdinalIgnoreCase))
            {
                string relative = fullPath.Substring(basePath.Length);
                if (relative.StartsWith(Path.DirectorySeparatorChar.ToString()) || relative.StartsWith(Path.AltDirectorySeparatorChar.ToString()))
                    relative = relative.Substring(1);
                return string.IsNullOrEmpty(relative) ? "." : relative;
            }

            return fullPath;
        }

