        private void CmbO365SavedAccounts_SelectedIndexChanged(object sender, EventArgs e)
        {
            // 使用sender而不是类字段来判断是哪个下拉框触发了事件
            var cmb = sender as ComboBox;
            if (cmb == null) return;
            if (cmb.SelectedIndex <= 0) return;

            var selectedName = cmb.SelectedItem?.ToString();
            if (string.IsNullOrEmpty(selectedName)) return;

            var settings = ConfigService.LoadAll();
            var account = settings.OAuthAccounts.Find(a => a.Name == selectedName);

            if (account != null)
            {
                // 找到cmbO365SavedAccounts所在的页签
                Control panel = null;
                Control current = cmb;
                while (current != null)
                {
                    if (!string.IsNullOrEmpty(current.Name) &&
                        (current.Name == "EMLO365Panel" || current.Name == "PSTO365Panel"))
                    {
                        panel = current;
                        break;
                    }
                    current = current.Parent;
                }

                if (panel == null) return;

                // 在对应的页签中查找并填充控件 (递归搜索)
                var clientIdBox = panel.Controls.Find("txtO365ClientId", true).FirstOrDefault() as TextBox;
                var tenantIdBox = panel.Controls.Find("txtO365TenantId", true).FirstOrDefault() as TextBox;
                var adminAccountBox = panel.Controls.Find("txtO365AdminAccount", true).FirstOrDefault() as TextBox;

                if (clientIdBox != null) clientIdBox.Text = account.ClientId;
                if (tenantIdBox != null) tenantIdBox.Text = account.TenantId;
                if (adminAccountBox != null) adminAccountBox.Text = account.Email;
            }
        }

        private void ShowServicePrincipalDialog()
        {
            // 获取已保存的 OAuth 账户列表
            var settings = ConfigService.LoadAll();
            var oauthAccounts = settings.OAuthAccounts;

            var form = new Form
            {
                Text = "注册 Service Principal",
                Size = new Size(500, 520),
                StartPosition = FormStartPosition.CenterParent,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var lblTitle = new Label
            {
                Text = "将 Azure App 注册为 Exchange Online Service Principal",
                Location = new Point(20, 15),
                Size = new Size(450, 25),
                Font = new Font("Microsoft Sans Serif", 10F, FontStyle.Bold)
            };

            var lblInfo = new Label
            {
                Text = "说明: 选择已保存的OAuth账户自动填充",
                Location = new Point(20, 45),
                Size = new Size(450, 20),
                ForeColor = Color.Gray
            };

            var lblSelectAccount = new Label { Text = "选择OAuth账户:", Location = new Point(20, 75), AutoSize = true };
            var cmbOAuthAccounts = new ComboBox
            {
                Location = new Point(20, 98),
                Size = new Size(450, 25),
                DropDownStyle = ComboBoxStyle.DropDownList
            };

            // 添加"手动输入"选项
            cmbOAuthAccounts.Items.Add("手动输入");
            foreach (var account in oauthAccounts)
            {
                cmbOAuthAccounts.Items.Add(account.Name);
            }
            if (cmbOAuthAccounts.Items.Count > 0)
                cmbOAuthAccounts.SelectedIndex = 0;

            var lblClientId = new Label { Text = "Client ID (App ID):", Location = new Point(20, 135), AutoSize = true };
            var txtClientId = new TextBox { Location = new Point(20, 158), Size = new Size(450, 25) };

            var lblTenantId = new Label { Text = "Tenant ID:", Location = new Point(20, 193), AutoSize = true };
            var txtTenantId = new TextBox { Location = new Point(20, 216), Size = new Size(450, 25) };

            var lblClientSecret = new Label { Text = "Client Secret (可选，用于应用程序权限):", Location = new Point(20, 251), AutoSize = true };
            var txtClientSecret = new TextBox { Location = new Point(20, 274), Size = new Size(450, 25) };

            var lblAdminEmail = new Label { Text = "管理员邮箱:", Location = new Point(20, 310), AutoSize = true };
            var txtAdminEmail = new TextBox { Location = new Point(20, 333), Size = new Size(450, 25) };

            var lblRoleGroup = new Label { Text = "角色组 (默认: Organization Management):", Location = new Point(20, 370), AutoSize = true };
            var txtRoleGroup = new TextBox { Location = new Point(20, 393), Size = new Size(450, 25), Text = "Organization Management" };

            // 下拉框选择事件
            cmbOAuthAccounts.SelectedIndexChanged += (s, e) =>
            {
                if (cmbOAuthAccounts.SelectedItem?.ToString() == "手动输入")
                {
                    txtClientId.Text = "";
                    txtTenantId.Text = "";
                    txtAdminEmail.Text = "";
                }
                else
                {
                    var selectedName = cmbOAuthAccounts.SelectedItem?.ToString();
                    var account = oauthAccounts.Find(a => a.Name == selectedName);
                    if (account != null)
                    {
                        txtClientId.Text = account.ClientId;
                        txtTenantId.Text = account.TenantId;
                        txtAdminEmail.Text = account.Email;
                    }
                }
            };

            var btnExecute = new Button
            {
                Text = "执行注册",
                Location = new Point(300, 375),
                Size = new Size(85, 30),
                BackColor = Color.FromArgb(0, 120, 215),
                ForeColor = Color.White
            };

            var btnCancel = new Button
            {
                Text = "关闭",
                Location = new Point(395, 375),
                Size = new Size(75, 30)
            };

            var lblStatus = new Label
            {
                Location = new Point(20, 415),
                Size = new Size(450, 25),
                ForeColor = Color.Gray
            };

            btnExecute.Click += async (s, e) =>
            {
                var clientId = txtClientId.Text.Trim();
                var tenantId = txtTenantId.Text.Trim();
                var clientSecret = txtClientSecret.Text.Trim();
                var adminEmail = txtAdminEmail.Text.Trim();
                var roleGroup = txtRoleGroup.Text.Trim();

                if (string.IsNullOrEmpty(clientId) || string.IsNullOrEmpty(tenantId) || string.IsNullOrEmpty(adminEmail))
                {
                    MessageBox.Show("请填写 Client ID、Tenant ID 和管理员邮箱", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                btnExecute.Enabled = false;
                lblStatus.Text = "正在获取访问令牌...";
                lblStatus.ForeColor = Color.Blue;
                lblStatus.Refresh();

                // 创建 RBAC 管理器（有 Client Secret 则使用应用程序权限）
                string accessToken = null;
                Services.ExchangeRbacManager rbacManager = new Services.ExchangeRbacManager(clientId, null, tenantId, adminEmail, this.Handle, clientSecret);

                lblStatus.Text = "正在使用客户端密钥获取 Token...";
                lblStatus.ForeColor = Color.Blue;
                lblStatus.Refresh();

                var (loginSuccess, loginMessage, token) = await rbacManager.GetTokenAsync();

                if (!loginSuccess || string.IsNullOrEmpty(token))
                {
                    this.Invoke(new Action(() =>
                    {
                        lblStatus.Text = "登录失败";
                        lblStatus.ForeColor = Color.Red;
                        MessageBox.Show(loginMessage, "失败", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        btnExecute.Enabled = true;
                    }));
                    return;
                }
                accessToken = token;

                // 在后台线程使用 Token 连接 Exchange Online
                lblStatus.Text = "正在配置权限...";
                lblStatus.ForeColor = Color.Blue;
                lblStatus.Refresh();

                Task.Run(async () =>
                {
                    var (success, message) = await rbacManager.EnsureExchangePermissionsAsync(accessToken);

                    this.Invoke(new Action(() =>
                    {
                        lblStatus.Text = success ? "执行完成" : "执行失败";
                        lblStatus.ForeColor = success ? Color.Green : Color.Red;
                        MessageBox.Show(message, success ? "成功" : "失败", MessageBoxButtons.OK, success ? MessageBoxIcon.Information : MessageBoxIcon.Error);
                        btnExecute.Enabled = true;
                    }));
                });
            };

            btnCancel.Click += (s, e) => form.Close();

            form.Controls.AddRange(new Control[] {
                lblTitle, lblInfo, lblSelectAccount, cmbOAuthAccounts,
                lblClientId, txtClientId, lblTenantId, txtTenantId,
                lblClientSecret, txtClientSecret,
                lblAdminEmail, txtAdminEmail, lblRoleGroup, txtRoleGroup,
                btnExecute, btnCancel, lblStatus
            });

            form.ShowDialog();
        }

        private string ExecuteExchangeOnlineCommands(string clientId, string tenantId, string adminEmail, string roleGroup)
        {
            try
            {
                // 检查并加载本地 ExchangeOnlineManagement 模块
                var checkModule = $@"
$localModulePath = Join-Path $PSScriptRoot 'PowerShellModules\ExchangeOnlineManagement\3.9.2\netFramework'
if (Test-Path $localModulePath) {{
    $env:PSModulePath = $localModulePath + ';' + $env:PSModulePath
    Import-Module (Join-Path $localModulePath 'ExchangeOnlineManagement.psm1') -ErrorAction Stop
    Write-Output 'MODULE_OK'
}} else {{
    # 回退到系统模块
    if (-not (Get-Module -ListAvailable -Name ExchangeOnlineManagement)) {{
        Write-Output 'ERROR: ExchangeOnlineManagement 模块未安装'
        exit 1
    }}
    Write-Output 'MODULE_OK'
}}
";
                var moduleCheck = ExecutePowerShellDirect(checkModule);
                if (moduleCheck.Contains("ERROR:"))
                    return moduleCheck;

                // PowerShell 脚本：连接并执行命令
                var script = $@"
$ErrorActionPreference = 'Continue'
$results = @()

# 加载本地 ExchangeOnlineManagement 模块
$localModulePath = Join-Path $PSScriptRoot 'PowerShellModules\ExchangeOnlineManagement\3.9.2\netFramework'
if (Test-Path $localModulePath) {{
    $env:PSModulePath = $localModulePath + ';' + $env:PSModulePath
    Import-Module (Join-Path $localModulePath 'ExchangeOnlineManagement.psm1') -DisableNameChecking -ErrorAction Stop
}}

try {{
    # 使用凭据对象连接（通过管理员邮箱自动弹出密码对话框）
    $securePassword = ConvertTo-SecureString 'PlaceholderPassword' -AsPlainText -Force
    $credential = New-Object System.Management.Automation.PSCredential('{adminEmail}', $securePassword)
    Connect-ExchangeOnline -Credential $credential -ShowProgress:`$true -ErrorAction Stop
    $results += 'Connected to Exchange Online'
}}

    # 1. 创建或检查 Service Principal
    try {{
        $existing = Get-ServicePrincipal -AppId '{clientId}' -ErrorAction SilentlyContinue
        if ($existing) {{
            $results += ""Service Principal 已存在: $($existing.DisplayName)""
        }} else {{
            $sp = New-ServicePrincipal -AppId '{clientId}' -ServiceId '{tenantId}' -ErrorAction Stop
            $results += ""Service Principal 创建成功: $($sp.DisplayName)""
        }}
    }} catch {{
        $results += ""创建 ServicePrincipal 警告: $($_.Exception.Message)""
    }}

    # 2. 获取 Service Principal
    $sp = Get-ServicePrincipal -AppId '{clientId}' -ErrorAction SilentlyContinue
    if ($sp) {{
        # 3. 添加到角色组
        try {{
            $currentMembers = Get-RoleGroupMember '{roleGroup}' -ErrorAction SilentlyContinue
            $exists = $currentMembers | Where-Object {{ $_.Identity -like ""*"" }}
            if ($currentMembers -and ($currentMembers | Where-Object {{ $_.RawIdentity -eq $sp.ObjectId }})) {{
                $results += '已是角色组成员'
            }} else {{
                Add-RoleGroupMember -Identity '{roleGroup}' -Member $sp.ObjectId -ErrorAction Stop
                $results += '已添加到角色组: {roleGroup}'
            }}
        }} catch {{
            $results += ""添加角色组警告: $($_.Exception.Message)""
        }}
    }} else {{
        $results += '未能获取 Service Principal'
    }}

}} catch {{
    $results += ""错误: $($_.Exception.Message)""
}} finally {{
    Disconnect-ExchangeOnline -Confirm:`$false -ErrorAction SilentlyContinue
}}

$results | Out-String
";
                return ExecutePowerShellDirect(script);
            }
            catch (Exception ex)
            {
                return "执行失败: " + ex.Message;
            }
        }

        private string ExecutePowerShellDirect(string script)
        {
            try
            {
                var tempFile = Path.GetTempFileName() + ".ps1";
                // 写入文件时使用 UTF-8 with BOM
                System.IO.File.WriteAllText(tempFile, script, new System.Text.UTF8Encoding(true));

                var psi = new System.Diagnostics.ProcessStartInfo
                {
                    FileName = "powershell.exe",
                    Arguments = $"-ExecutionPolicy Bypass -NoProfile -File \"{tempFile}\"",
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    CreateNoWindow = true
                };

                using (var process = System.Diagnostics.Process.Start(psi))
                {
                    var output = process.StandardOutput.ReadToEnd();
                    var error = process.StandardError.ReadToEnd();
                    process.WaitForExit();

                    try { File.Delete(tempFile); } catch { }

                    if (!string.IsNullOrEmpty(error))
                        return output + "\n错误: " + error;
                    return string.IsNullOrEmpty(output) ? "执行完成" : output;
                }
            }
            catch (Exception ex)
            {
                return "执行失败: " + ex.Message;
            }
        }

