            // 导航切换逻辑
            Action<string> switchPage = (pageName) =>
            {
                // 隐藏所有页面
                foreach (var page in contentPages.Values)
                    page.Visible = false;

                // 显示选中页面
                if (contentPages.ContainsKey(pageName))
                    contentPages[pageName].Visible = true;

                // 更新导航按钮样式
                foreach (var btn in navButtons)
                {
                    btn.BackColor = btn.Tag?.ToString() == pageName ? colorSelectedNav : colorSidebarBg;
                }
            };

            // 绑定导航按钮事件
            foreach (var btn in navButtons)
            {
                btn.Click += (s, ev) =>
                {
                    var pageName = (s as Button)?.Tag?.ToString();
                    if (!string.IsNullOrEmpty(pageName))
                        switchPage(pageName);
                };
            }

            // ========== 事件逻辑 ==========
            // OAuth
            void RefreshOAuthList()
            {
                lstOAuth.Items.Clear();
                foreach (var account in settings.OAuthAccounts)
                    lstOAuth.Items.Add(account.Name);
            }
            void LoadOAuthAccountToFields(string name)
            {
                var account = settings.OAuthAccounts.Find(a => a.Name == name);
                if (account != null)
                {
                    txtOAuthName.Text = account.Name;
                    txtClientId.Text = account.ClientId;
                    txtTenantId.Text = account.TenantId;
                    txtOAuthEmail.Text = account.Email;
                }
            }
            btnOAuthAdd.Click += (s, ev) =>
            {
                if (string.IsNullOrWhiteSpace(txtOAuthName.Text) || string.IsNullOrWhiteSpace(txtClientId.Text))
                { MessageBox.Show("请输入账户名称和 Client ID", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
                var account = new OAuthAccount
                {
                    Name = txtOAuthName.Text.Trim(),
                    ClientId = txtClientId.Text.Trim(),
                    TenantId = txtTenantId.Text.Trim(),
                    Email = txtOAuthEmail.Text.Trim()
                };
                ConfigService.SaveOAuthAccount(account);
                settings = ConfigService.LoadAll();
                RefreshOAuthList();
                MessageBox.Show("保存成功", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
            };
            btnOAuthDelete.Click += (s, ev) =>
            {
                if (lstOAuth.SelectedItem == null) { MessageBox.Show("请先选择要删除的账户", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
                if (MessageBox.Show($"确定要删除账户 \"{lstOAuth.SelectedItem}\" 吗?", "确认", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
                {
                    ConfigService.DeleteOAuthAccount(lstOAuth.SelectedItem.ToString());
                    settings = ConfigService.LoadAll();
                    RefreshOAuthList();
                    txtOAuthName.Clear(); txtClientId.Clear(); txtTenantId.Clear(); txtOAuthEmail.Clear();
                }
            };
            btnOAuthUse.Click += (s, ev) =>
            {
                if (lstOAuth.SelectedItem == null) { MessageBox.Show("请先选择要使用的账户", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
                var account = settings.OAuthAccounts.Find(a => a.Name == lstOAuth.SelectedItem.ToString());
                if (account != null)
                {
                    txtO365ClientId.Text = account.ClientId;
                    txtO365TenantId.Text = account.TenantId;
                    if (!string.IsNullOrEmpty(account.Email)) txtO365Email.Text = account.Email;
                    form.Close();
                    MessageBox.Show($"已加载账户 \"{account.Name}\" 的配置", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            };
            lstOAuth.SelectedIndexChanged += (s, ev) => { if (lstOAuth.SelectedItem != null) LoadOAuthAccountToFields(lstOAuth.SelectedItem.ToString()); };

            // IMAP
            void RefreshImapList()
            {
                lstImap.Items.Clear();
                foreach (var account in settings.ImapAccounts)
                    lstImap.Items.Add(account.Name);
            }
            void LoadImapAccountToFields(string name)
            {
                var account = settings.ImapAccounts.Find(a => a.Name == name);
                if (account != null)
                {
                    txtImapName.Text = account.Name;
                    txtImapHost.Text = account.Host;
                    txtImapEmail.Text = account.Email;
                    txtImapPassword.Text = account.Password;
                }
            }
            btnImapAdd.Click += (s, ev) =>
            {
                if (string.IsNullOrWhiteSpace(txtImapName.Text) || string.IsNullOrWhiteSpace(txtImapHost.Text) || string.IsNullOrWhiteSpace(txtImapEmail.Text))
                { MessageBox.Show("请输入账户名称、服务器和邮箱", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
                SettingsService.AddOrUpdateImapAccount(txtImapName.Text.Trim(), txtImapHost.Text.Trim(), 993, true, txtImapEmail.Text.Trim(), txtImapPassword.Text);
                settings = SettingsService.Load();
                RefreshImapList();
                MessageBox.Show("保存成功", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
            };
            btnImapDelete.Click += (s, ev) =>
            {
                if (lstImap.SelectedItem == null) { MessageBox.Show("请先选择要删除的账户", "提示", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
