                    case 0: serverUrl = "https://www.googleapis.com/carddav/v1/principals/" + username + "/"; break;
                    case 1: if (domain.Contains("163.com") || domain.Contains("126.com") || domain.Contains("yeah.net")) serverUrl = "https://carddav.netease.com/carddav/addressbook/" + username.Split('@')[0]; break;
                    case 2: serverUrl = "https://outlook.office.com/carddav/principals/" + Uri.EscapeDataString(username) + "/"; break;
