    /// <summary>
    /// 邮件项
    /// </summary>
    public class MailItem
    {
        public string MessageId { get; set; }
        public string Subject { get; set; }
        public DateTime SentDate { get; set; }
        public DateTime ReceivedDate { get; set; }
        public string From { get; set; }
        public string BodyText { get; set; }
        public string BodyHtml { get; set; }
        public bool IsRead { get; set; }
        public MailPriority Priority { get; set; } = MailPriority.Normal;
        public List<string> To { get; set; } = new List<string>();
        public List<string> Cc { get; set; } = new List<string>();
        public List<string> Bcc { get; set; } = new List<string>();
        public List<MailAttachment> Attachments { get; set; } = new List<MailAttachment>();
        public Dictionary<string, string> Headers { get; set; } = new Dictionary<string, string>();

        public MailItem()
        {
            MessageId = "";
            Subject = "";
            From = "";
            BodyText = "";
            BodyHtml = "";
        }
    }

    public enum MailPriority { Low, Normal, High }

    public class MailAttachment
    {
        public string FileName { get; set; }
        public string ContentType { get; set; }
        public byte[] Content { get; set; }
        public int Size { get; set; }

        public MailAttachment()
        {
            FileName = "";
            ContentType = "";
            Content = new byte[0];
        }
    }

    /// <summary>
    /// PST文件写入服务 - 使用Outlook API (动态绑定)
    /// </summary>
    public class PstWriterService
    {
        private dynamic _outlookApp;
        private dynamic _rootFolder;
        private string _pstPath;
        private List<string> _tempFiles = new List<string>();
        private int _totalMails;

        // Outlook Enums (defined locally since we don't have the interop assembly)
        private const int olFolderInbox = 6;
        private const int olMailItem = 0;
        private const int olImportanceHigh = 2;
        private const int olImportanceLow = 0;
        private const int olImportanceNormal = 1;
        private const int olEmbeddeditem = 5;

        private void Log(string message)
        {
            try
            {
                var logPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Logs", "mailconverter.log");
                File.AppendAllText(logPath, "[" + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "] " + message + "\n");
            }
            catch { }
        }

        public void CreatePstFile(string pstPath, string storeName)
        {
            Log("Creating PST: " + pstPath);
            _pstPath = pstPath;
            _totalMails = 0;

            var directory = Path.GetDirectoryName(pstPath);
            if (!string.IsNullOrEmpty(directory) && !Directory.Exists(directory))
            {
                Directory.CreateDirectory(directory);
            }

            if (File.Exists(pstPath))
            {
                try { File.Delete(pstPath); } catch { }
            }

            bool pstCreated = false;

            // Method 1: Try Python script first
            try
            {
                var exeDir = AppDomain.CurrentDomain.BaseDirectory;
                var pythonScript = Path.Combine(exeDir, "script", "create_pst.py");

                if (File.Exists(pythonScript))
                {
                    var pythonExe = Program.GetPythonExecutable();
                    if (string.IsNullOrEmpty(pythonExe))
                    {
                        throw new Exception("Python环境未找到，请重新安装程序");
                    }

                    var startInfo = Program.CreatePythonStartInfo(pythonExe, $"\"{pythonScript}\" \"{pstPath}\" \"{storeName}\"");

                    using (var process = System.Diagnostics.Process.Start(startInfo))
                    {
                        if (process != null)
                        {
                            var output = process.StandardOutput.ReadToEnd();
                            var error = process.StandardError.ReadToEnd();
                            process.WaitForExit(30000);

                            Log("Python output: " + output);
                            if (!string.IsNullOrEmpty(error))
                                Log("Python error: " + error);

                            if (File.Exists(pstPath))
                            {
                                Log("PST file created by Python script!");
                                pstCreated = true;
                            }
                        }
                    }
                }
                else
                {
                    Log("Python script not found: " + pythonScript);
                }
            }
            catch (Exception ex)
            {
                Log("Python method failed: " + ex.Message);
            }

            // If Python created the PST, connect to it and get root folder
            if (pstCreated)
            {
                try
                {
                    // Reconnect to the PST file and get the root folder
                    Type outlookType = Type.GetTypeFromProgID("Outlook.Application");
                    if (outlookType != null)
                    {
                        _outlookApp = Activator.CreateInstance(outlookType);
                        dynamic ns = _outlookApp.GetNamespace("MAPI");

                        // Find the store with our PST file
                        foreach (dynamic store in ns.Stores)
                        {
                            try
                            {
                                string filePath = store.FilePath;
                                if (!string.IsNullOrEmpty(filePath) && filePath.Equals(pstPath, StringComparison.OrdinalIgnoreCase))
                                {
                                    _rootFolder = store.RootFolder;
                                    Log("Connected to PST root folder!");
                                    break;
                                }
                            }
                            catch { }
                        }

                        // If not found, try to add the store
                        if (_rootFolder == null)
                        {
                            try
                            {
                                ns.AddStore(pstPath);
                                foreach (dynamic store in ns.Stores)
                                {
                                    try
                                    {
                                        string filePath = store.FilePath;
                                        if (!string.IsNullOrEmpty(filePath) && filePath.Equals(pstPath, StringComparison.OrdinalIgnoreCase))
                                        {
                                            _rootFolder = store.RootFolder;
                                            Log("Connected to PST via AddStore!");
                                            break;
                                        }
                                    }
                                    catch { }
                                }
                            }
                            catch (Exception ex)
                            {
                                Log("AddStore failed: " + ex.Message);
                            }
                        }

                        if (_rootFolder == null)
                        {
                            // Fallback: use default folder
                            _rootFolder = ns.GetDefaultFolder(olFolderInbox).Parent;
                            Log("Using fallback folder");
                        }
                    }
                }
                catch (Exception ex)
                {
                    Log("Failed to connect to PST: " + ex.Message);
                }
            }
            else
            {
                // Python failed, try C# methods
                Log("Trying C# methods...");
                try
                {
                    Type outlookType = Type.GetTypeFromProgID("Outlook.Application");
                    if (outlookType == null)
                    {
                        throw new Exception("无法创建Outlook应用程序对象，请确保已安装Microsoft Outlook");
                    }

                    _outlookApp = Activator.CreateInstance(outlookType);
                    dynamic ns = _outlookApp.GetNamespace("MAPI");

                    try
                    {
                        dynamic dynStores = ns.Stores;
                        _rootFolder = dynStores.Add(pstPath);
                        Log("C# dynamic Add worked!");
                        pstCreated = true;
                    }
                    catch (Exception ex)
                    {
                        Log("C# dynamic Add failed: " + ex.Message);
                    }
                }
                catch (Exception ex)
                {
                    Log("C# methods failed: " + ex.Message);
                }
            }

            if (!pstCreated)
            {
                try
                {
                    Type outlookType = Type.GetTypeFromProgID("Outlook.Application");
                    _outlookApp = Activator.CreateInstance(outlookType);
                    dynamic ns = _outlookApp.GetNamespace("MAPI");
                    _rootFolder = ns.GetDefaultFolder(olFolderInbox).Parent;
                    Log("WARNING: Using fallback folder!");
                }
                catch (Exception ex)
                {
                    Log("Fallback also failed: " + ex.Message);
                }
            }

            Log("PST setup completed, pstCreated=" + pstCreated + ", file exists=" + File.Exists(pstPath));
        }

        public void CreateFolder(string folderPath)
        {
            if (_rootFolder == null) return;

            try
            {
                var folders = folderPath.Split(new[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries);
                dynamic currentFolder = _rootFolder;

                foreach (var folderName in folders)
                {
                    bool found = false;
                    try
                    {
                        // Try to find existing folder by iterating
                        var folderCount = currentFolder.Folders.Count;
                        for (int i = 1; i <= folderCount; i++)
                        {
                            if (currentFolder.Folders[i].Name == folderName)
                            {
                                currentFolder = currentFolder.Folders[i];
                                found = true;
                                break;
                            }
                        }
                    }
                    catch { }

                    if (!found)
                    {
                        try
                        {
                            currentFolder = currentFolder.Folders.Add(folderName);
                        }
                        catch (Exception ex)
                        {
                            Log("Failed to add folder " + folderName + ": " + ex.Message);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Log("Failed to create folder " + folderPath + ": " + ex.Message);
            }
        }

        public void WriteMail(MailItem mail, string folderPath)
        {
            if (_rootFolder == null || _outlookApp == null) return;

            try
            {
                // Get or create the target folder
                var folders = folderPath.Split(new[] { '/', '\\' }, StringSplitOptions.RemoveEmptyEntries);
                dynamic targetFolder = _rootFolder;

                foreach (var folderName in folders)
                {
                    bool found = false;
                    try
                    {
                        var folderCount = targetFolder.Folders.Count;
                        for (int i = 1; i <= folderCount; i++)
                        {
                            if (targetFolder.Folders[i].Name == folderName)
                            {
                                targetFolder = targetFolder.Folders[i];
                                found = true;
                                break;
                            }
                        }
                    }
                    catch { }

                    if (!found)
                    {
                        try
                        {
                            targetFolder = targetFolder.Folders.Add(folderName);
                        }
                        catch { }
                    }
                }

                // Create mail item using Outlook Application (not folder.Items.Add)
                dynamic outlookMail = _outlookApp.CreateItem(olMailItem);

                // Set subject
                outlookMail.Subject = mail.Subject ?? "";

                // Set body - prefer HTML if available
                if (!string.IsNullOrEmpty(mail.BodyHtml))
                {
                    outlookMail.HTMLBody = mail.BodyHtml;
                }
                else
                {
                    outlookMail.Body = mail.BodyText ?? "";
                }

                // Set recipients
                if (mail.To != null && mail.To.Count > 0)
                {
                    outlookMail.To = string.Join(";", mail.To);
                }
                if (mail.Cc != null && mail.Cc.Count > 0)
                {
                    outlookMail.CC = string.Join(";", mail.Cc);
                }
                if (mail.Bcc != null && mail.Bcc.Count > 0)
                {
                    outlookMail.BCC = string.Join(";", mail.Bcc);
                }

                // Set sent date
                if (mail.SentDate != DateTime.MinValue)
                {
                    try { outlookMail.SentOn = mail.SentDate; } catch { }
                }

                // Set priority
                if (mail.Priority == MailPriority.High)
                    outlookMail.Importance = olImportanceHigh;
                else if (mail.Priority == MailPriority.Low)
                    outlookMail.Importance = olImportanceLow;
                else
                    outlookMail.Importance = olImportanceNormal;

                // Add attachments first
                foreach (var attachment in mail.Attachments)
                {
                    if (attachment.Content != null && attachment.Content.Length > 0 && !string.IsNullOrEmpty(attachment.FileName))
                    {
                        var tempPath = Path.Combine(Path.GetTempPath(), attachment.FileName);
                        File.WriteAllBytes(tempPath, attachment.Content);
                        _tempFiles.Add(tempPath);
                        outlookMail.Attachments.Add(tempPath);
                    }
                }

                // Save the mail first
                outlookMail.Save();

                // Now move to the target folder using Move method
                try
                {
                    dynamic movedMail = outlookMail.Move(targetFolder);
                    _totalMails++;
                    Log("Mail saved: " + mail.Subject);
                }
                catch (Exception ex)
                {
                    // If move fails, the mail might already be in the right place
                    Log("Mail saved (move failed): " + mail.Subject + " - " + ex.Message);
                    _totalMails++;
                }
            }
            catch (Exception ex)
            {
                Log("Failed to write mail " + mail.Subject + ": " + ex.Message);
            }
        }

        public void Close()
        {
            foreach (var tempFile in _tempFiles)
            {
                try { File.Delete(tempFile); } catch { }
            }
            _tempFiles.Clear();

            if (_rootFolder != null)
            {
                Marshal.ReleaseComObject(_rootFolder);
                _rootFolder = null;
            }

            if (_outlookApp != null)
            {
                Marshal.ReleaseComObject(_outlookApp);
                _outlookApp = null;
            }

            Log("PST saved: " + _pstPath + ", Total mails: " + _totalMails);
        }
    }
}
